class YieldRangeCalendar(QCalendarWidget):
    """良率日期选择专用日历：范围内绿色可选，范围外黑字灰底禁选。"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._range_min = QDate.currentDate()
        self._range_max = QDate.currentDate()
        self._hovered_date = QDate()
        self.setGridVisible(False)
        self.setVerticalHeaderFormat(QCalendarWidget.NoVerticalHeader)
        self.setMouseTracking(True)
        self.currentPageChanged.connect(lambda *_: self.updateCells())

        self._calendar_view = self.findChild(QTableView)
        if self._calendar_view is not None:
            self._calendar_view.setMouseTracking(True)
            self._calendar_view.viewport().installEventFilter(self)

    def setAllowedDateRange(self, min_date: QDate, max_date: QDate):
        if not min_date.isValid() or not max_date.isValid():
            return
        if min_date > max_date:
            min_date, max_date = max_date, min_date
        self._range_min = QDate(min_date)
        self._range_max = QDate(max_date)
        self.setMinimumDate(self._range_min)
        self.setMaximumDate(self._range_max)
        selected = self.selectedDate()
        if selected < self._range_min:
            self.setSelectedDate(self._range_min)
        elif selected > self._range_max:
            self.setSelectedDate(self._range_max)
        self.updateCells()

    def _page_start_date(self) -> QDate:
        first_of_month = QDate(self.yearShown(), self.monthShown(), 1)
        first_day_of_week = int(self.firstDayOfWeek())
        offset_days = (first_of_month.dayOfWeek() - first_day_of_week) % 7
        return first_of_month.addDays(-offset_days)

    def _date_from_index(self, index) -> QDate:
        if index is None or not index.isValid():
            return QDate()
        return self._page_start_date().addDays(index.row() * 7 + index.column())

    def _is_selectable(self, date: QDate) -> bool:
        return date.isValid() and self._range_min <= date <= self._range_max

    def _index_is_enabled(self, index) -> bool:
        if self._calendar_view is None or index is None or not index.isValid():
            return False
        model = self._calendar_view.model()
        if model is None:
            return False
        try:
            return bool(model.flags(index) & Qt.ItemIsEnabled)
        except Exception:
            return False

    def eventFilter(self, obj, event):
        if self._calendar_view is None or obj is not self._calendar_view.viewport():
            return super().eventFilter(obj, event)

        if event.type() == QEvent.MouseMove:
            hovered_index = self._calendar_view.indexAt(event.pos())
            hovered_date = self._date_from_index(hovered_index)
            if hovered_date != self._hovered_date:
                self._hovered_date = hovered_date if hovered_date.isValid() else QDate()
                self.updateCells()
            if hovered_date.isValid() and not self._index_is_enabled(hovered_index):
                self._calendar_view.viewport().setCursor(Qt.ForbiddenCursor)
            else:
                self._calendar_view.viewport().setCursor(Qt.ArrowCursor)
        elif event.type() == QEvent.Leave:
            self._hovered_date = QDate()
            self._calendar_view.viewport().setCursor(Qt.ArrowCursor)
            self.updateCells()
        elif event.type() in (QEvent.MouseButtonPress, QEvent.MouseButtonDblClick):
            clicked_index = self._calendar_view.indexAt(event.pos())
            if clicked_index.isValid() and not self._index_is_enabled(clicked_index):
                return True

        return super().eventFilter(obj, event)

    def paintCell(self, painter: QPainter, rect, date: QDate):
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)

        selectable = self._is_selectable(date)
        selected = date == self.selectedDate()
        hovered = date == self._hovered_date

        draw_rect = rect.adjusted(3, 3, -3, -3)
        if selectable:
            # 可选日期：淡蓝色背景，深蓝色文字
            bg_color = QColor("#D5E3F0")
            text_color = QColor("#2C3E50")
            if hovered and not selected:
                bg_color = QColor("#B8D4E8")
            if selected:
                bg_color = QColor("#5B9BD5")
                text_color = QColor("#FFFFFF")
        else:
            # 不可选日期：无背景，灰色文字
            bg_color = QColor("transparent")
            text_color = QColor("#B0B0B0")

        painter.setPen(Qt.NoPen)
        painter.setBrush(bg_color)
        painter.drawRoundedRect(draw_rect, 7, 7)

        font = painter.font()
        font.setBold(bool(selected))
        painter.setFont(font)
        painter.setPen(text_color)
        painter.drawText(draw_rect, Qt.AlignCenter, str(date.day()))
        painter.restore()


class WiBatchCalendar(YieldRangeCalendar):
    """Weekly Inspection 批次日历：仅对已导入的检测日涂色，中间无数据的日期不填充。"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._batch_date_keys: set[str] = set()

    def setAllowedBatchDates(self, date_strs: list[str] | None):
        keys: set[str] = set()
        for raw in date_strs or []:
            s = str(raw or "").strip()[:10]
            if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
                keys.add(s)
        self._batch_date_keys = keys
        if keys:
            qdates = [QDate.fromString(k, "yyyy-MM-dd") for k in sorted(keys)]
            qdates = [d for d in qdates if d.isValid()]
            if qdates:
                self.setAllowedDateRange(min(qdates), max(qdates))
        self.updateCells()

    def _is_selectable(self, date: QDate) -> bool:
        if not date.isValid():
            return False
        if self._batch_date_keys:
            return date.toString("yyyy-MM-dd") in self._batch_date_keys
        return super()._is_selectable(date)


class WiProcessDatePickerWidget(QFrame):
    """WI 检测日期选择：左侧制程列表，右侧可勾选批次日（默认最近 4 个）。"""

    def __init__(self, parent=None, ui_scale: float = 1.0, on_changed=None, on_confirm=None):
        super().__init__(parent)
        self._s = float(ui_scale) if ui_scale else 1.0
        self._on_changed = on_changed
        self._on_confirm = on_confirm
        self._process_dates: dict[str, list[str]] = {}
        self._selection_by_process: dict[str, set[str]] = {}
        self._selected_processes: set[str] = set()
        self._active_process = ""
        self._block_change = False
        self._mini_btn_style = f"""
            QPushButton {{
                background: #F5F9FF;
                border: 1px solid #B8D4E8;
                border-radius: 4px;
                padding: 2px 8px;
                font-size: {int(10*self._s)}px;
                font-weight: 600;
                color: #3A5A7A;
                text-align: center;
            }}
            QPushButton:hover {{ background: #E8F1F8; }}
        """

        self.setObjectName("wi_process_date_picker")
        self.setStyleSheet(f"""
            QFrame#wi_process_date_picker {{
                background-color: #FFFFFF;
                border: 1px solid #C5D9E8;
                border-radius: 6px;
            }}
            QListWidget {{
                border: none;
                background: transparent;
                font-size: {int(11*self._s)}px;
                color: #2C3E50;
            }}
            QListWidget::item {{
                padding: 4px 6px;
                min-height: {int(22*self._s)}px;
            }}
            QListWidget::item:selected {{
                background-color: #D5E3F0;
                color: #2C3E50;
            }}
            QListWidget::item:hover {{
                background-color: #E8F1F8;
            }}
        """)

        outer = QVBoxLayout(self)
        outer.setContentsMargins(int(4 * self._s), int(4 * self._s), int(4 * self._s), int(4 * self._s))
        outer.setSpacing(int(6 * self._s))

        root = QHBoxLayout()
        root.setSpacing(int(4 * self._s))

        proc_col = QVBoxLayout()
        proc_col.setSpacing(int(2 * self._s))
        proc_hdr = QHBoxLayout()
        proc_hdr.setContentsMargins(0, 0, 0, 0)
        proc_lbl = QLabel("制程")
        proc_lbl.setStyleSheet(
            f"font-size: {int(10*self._s)}px; font-weight: 700; color: #5A7A99; border: none;"
        )
        proc_hdr.addWidget(proc_lbl)
        proc_col.addLayout(proc_hdr)
        self.process_list = QListWidget()
        self.process_list.setMinimumWidth(int(88 * self._s))
        self.process_list.setMaximumWidth(int(120 * self._s))
        self.process_list.setMinimumHeight(int(130 * self._s))
        self.process_list.setMaximumHeight(int(200 * self._s))
        self.process_list.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        self.process_list.itemChanged.connect(self._on_process_item_changed)
        self.process_list.currentItemChanged.connect(self._on_process_changed)
        proc_col.addWidget(self.process_list)
        root.addLayout(proc_col)

        sep = QFrame()
        sep.setFrameShape(QFrame.VLine)
        sep.setStyleSheet("color: #E8F1F8;")
        sep.setFixedWidth(1)
        root.addWidget(sep)

        date_col = QVBoxLayout()
        date_col.setSpacing(int(2 * self._s))
        date_hdr = QHBoxLayout()
        date_hdr.setContentsMargins(0, 0, 0, 0)
        date_lbl = QLabel("检测日期")
        date_lbl.setStyleSheet(
            f"font-size: {int(10*self._s)}px; font-weight: 700; color: #5A7A99; border: none;"
        )
        date_hdr.addWidget(date_lbl)
        date_hdr.addStretch(1)
        mini_h = int(20 * self._s)
        mini_w = int(44 * self._s)
        self.btn_confirm = QPushButton("确定")
        self.btn_confirm.setCursor(QCursor(Qt.PointingHandCursor))
        self.btn_confirm.setFixedSize(mini_w, mini_h)
        self.btn_confirm.setStyleSheet(self._mini_btn_style)
        self.btn_confirm.clicked.connect(self._on_confirm_clicked)
        date_hdr.addWidget(self.btn_confirm)
        self.btn_select_all = QPushButton("全选")
        self.btn_select_all.setCursor(QCursor(Qt.PointingHandCursor))
        self.btn_select_all.setFixedSize(mini_w, mini_h)
        self.btn_select_all.setStyleSheet(self._mini_btn_style)
        self.btn_select_all.setToolTip("为当前制程勾选全部检测日期")
        self.btn_select_all.clicked.connect(self._select_all_dates)
        date_hdr.addWidget(self.btn_select_all)
        date_col.addLayout(date_hdr)

        self.date_list = QListWidget()
        self.date_list.setMinimumWidth(int(100 * self._s))
        self.date_list.setMinimumHeight(int(130 * self._s))
        self.date_list.setMaximumHeight(int(200 * self._s))
        self.date_list.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        self.date_list.itemChanged.connect(self._on_date_item_changed)
        date_col.addWidget(self.date_list)
        root.addLayout(date_col, 1)
        outer.addLayout(root)

    def active_process(self) -> str:
        return str(self._active_process or "").strip()

    def selected_processes(self) -> list[str]:
        order = sorted(self._process_dates.keys(), key=lambda x: x.lower())
        return [p for p in order if p in self._selected_processes]

    def set_process_date_map(
        self,
        process_dates: dict[str, list[str]],
        *,
        active_process: str | None = None,
        selected_processes: set[str] | list[str] | None = None,
        default_recent_n: int = 4,
    ):
        self._process_dates = {
            str(k).strip(): sorted({str(d).strip()[:10] for d in (v or []) if str(d).strip()})
            for k, v in (process_dates or {}).items()
            if str(k).strip()
        }
        for proc, dates in self._process_dates.items():
            prev = self._selection_by_process.get(proc)
            valid = set(dates)
            if prev is None:
                pick = dates[-default_recent_n:] if dates else []
                self._selection_by_process[proc] = set(pick)
            else:
                self._selection_by_process[proc] = {d for d in prev if d in valid}
                if not self._selection_by_process[proc] and dates:
                    self._selection_by_process[proc] = set(dates[-default_recent_n:])

        prefer_proc = str(active_process or "").strip()
        if selected_processes is not None:
            valid_prev = {str(p).strip() for p in selected_processes if str(p).strip() in self._process_dates}
        else:
            valid_prev = {p for p in self._selected_processes if p in self._process_dates}
        if not valid_prev and self._process_dates:
            first = sorted(self._process_dates.keys(), key=lambda x: x.lower())[0]
            valid_prev = {first}

        self._block_change = True
        self.process_list.blockSignals(True)
        self.process_list.clear()
        for proc in sorted(self._process_dates.keys(), key=lambda x: x.lower()):
            item = QListWidgetItem(proc)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable | Qt.ItemIsEnabled)
            item.setCheckState(Qt.Checked if proc in valid_prev else Qt.Unchecked)
            self.process_list.addItem(item)
        self.process_list.blockSignals(False)
        self._selected_processes = set(valid_prev)
        self._block_change = False

        pick_proc = prefer_proc if prefer_proc in self._process_dates else ""
        if not pick_proc and valid_prev:
            pick_proc = sorted(valid_prev, key=lambda x: x.lower())[0]
        if pick_proc:
            self._select_process_row(pick_proc)
        elif self.process_list.count() > 0:
            self.process_list.setCurrentRow(0)
        else:
            self._active_process = ""
            self._reload_date_list()

    def set_active_process(self, process_name: str):
        self._select_process_row(str(process_name or "").strip())

    def set_selected_processes(
        self, processes: set[str] | list[str], *, active_process: str | None = None,
    ):
        want = {str(p).strip() for p in (processes or []) if str(p).strip()}
        self._block_change = True
        for i in range(self.process_list.count()):
            item = self.process_list.item(i)
            if not item:
                continue
            name = str(item.text() or "").strip()
            item.setCheckState(Qt.Checked if name in want else Qt.Unchecked)
        self._selected_processes = {str(p).strip() for p in want if p in self._process_dates}
        self._block_change = False
        pick = str(active_process or "").strip()
        if pick and pick in self._process_dates:
            self._select_process_row(pick)
        elif self._selected_processes:
            self._select_process_row(sorted(self._selected_processes, key=lambda x: x.lower())[0])

    def selected_dates(self, process_name: str | None = None) -> list[str]:
        proc = str(process_name or self._active_process or "").strip()
        if not proc:
            return []
        picks = self._selection_by_process.get(proc) or set()
        order = self._process_dates.get(proc) or []
        return [d for d in order if d in picks]

    def selection_summary(self) -> str:
        """用于弹出按钮上的摘要文案。"""
        procs = self.selected_processes()
        if not procs:
            return "点击选择制程与检测日期"
        active = self.active_process()
        dates = self.selected_dates(active) if active else []
        proc_txt = procs[0] if len(procs) == 1 else f"{procs[0]} 等{len(procs)}个制程"
        if not dates and active:
            return f"{proc_txt} · 未选日期"
        if not dates:
            return f"已选 {len(procs)} 个制程 · 请勾选检测日期"
        if len(dates) <= 2:
            return f"{proc_txt} · {'、'.join(dates)}"
        return f"{proc_txt} · {dates[0]} … {dates[-1]}（{len(dates)}天）"

    def _select_process_row(self, process_name: str):
        for i in range(self.process_list.count()):
            if self.process_list.item(i).text().strip() == process_name:
                self.process_list.setCurrentRow(i)
                return
        self._active_process = process_name
        self._reload_date_list()

    def _on_process_item_changed(self, item: QListWidgetItem):
        if self._block_change or not item:
            return
        name = str(item.text() or "").strip()
        if item.checkState() == Qt.Checked:
            self._selected_processes.add(name)
        else:
            self._selected_processes.discard(name)
            if self._active_process == name:
                remain = self.selected_processes()
                if remain:
                    self._select_process_row(remain[0])

    def _on_process_changed(self, current: QListWidgetItem | None, _prev: QListWidgetItem | None):
        if self._block_change:
            return
        self._active_process = current.text().strip() if current else ""
        self._reload_date_list()

    def _reload_date_list(self):
        proc = self._active_process
        dates = self._process_dates.get(proc) or []
        picks = self._selection_by_process.setdefault(proc, set())

        self._block_change = True
        self.date_list.blockSignals(True)
        self.date_list.clear()
        for d in dates:
            item = QListWidgetItem(d)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Checked if d in picks else Qt.Unchecked)
            self.date_list.addItem(item)
        self.date_list.blockSignals(False)
        self._block_change = False

    def _on_date_item_changed(self, item: QListWidgetItem):
        if self._block_change or not self._active_process:
            return
        key = str(item.text() or "").strip()
        picks = self._selection_by_process.setdefault(self._active_process, set())
        if item.checkState() == Qt.Checked:
            picks.add(key)
        else:
            picks.discard(key)

    def _select_all_dates(self):
        if not self._active_process:
            return
        dates = self._process_dates.get(self._active_process) or []
        self._selection_by_process[self._active_process] = set(dates)
        self._block_change = True
        for i in range(self.date_list.count()):
            self.date_list.item(i).setCheckState(Qt.Checked)
        self._block_change = False

    def _on_confirm_clicked(self):
        if callable(self._on_confirm):
            self._on_confirm()
        elif callable(self._on_changed):
            self._on_changed()

    def _notify_changed(self):
        if callable(self._on_changed):
            self._on_changed()


# 良率页：可点击的配方行（整行接收鼠标；内部控件透传）
class RecipeYieldClickRow(QWidget):
    """承载一行良率条形内容，整行点击上报 view_key + payload。"""

    def __init__(self, host: QWidget, view_key: str, payload: dict, inner: QWidget, parent=None):
        super().__init__(parent)
        self._host = host
        self._view_key = str(view_key or "")
        self._payload = dict(payload or {})
        lay = QHBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        inner.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        lay.addWidget(inner, 1)
        self.setCursor(QCursor(Qt.PointingHandCursor))
        self._make_children_mouse_transparent(inner)

    @staticmethod
    def _make_children_mouse_transparent(root: QWidget):
        for ch in root.findChildren(QWidget):
            # 允许数值标签响应点击
            if ch.objectName() in ("yield_count_ng", "yield_count_alert"):
                continue
            ch.setAttribute(Qt.WA_TransparentForMouseEvents, True)

    def mouseReleaseEvent(self, ev):
        if ev.button() == Qt.LeftButton and self._host is not None:
            fn = getattr(self._host, "_on_yield_recipe_row_clicked", None)
            if callable(fn):
                fn(self._view_key, self._payload)
        super().mouseReleaseEvent(ev)


# ==================== 2-B. JMP 集成模块（内联） ====================
import tempfile
import subprocess
