# ── JMP / PPT 路径持久化（与脚本同目录，避免启动方式不同导致 cwd 变化而“记不住路径”）──
def _app_config_dir() -> str:
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    try:
        d = os.path.dirname(os.path.abspath(__file__))
        if d:
            return d
    except NameError:
        pass
    return os.getcwd()


def _app_state_path(filename: str) -> str:
    return os.path.join(_app_config_dir(), filename)


_JMP_CONFIG_FILE = os.path.join(_app_config_dir(), "jmp_config.json")
_PPT_CONFIG_FILE = os.path.join(_app_config_dir(), "powerpoint_config.json")
_STAND_YIELD_SPEC_FILE = os.path.join(_app_config_dir(), "stand_yield_specs.json")
_DEFAULT_STAND_YIELD_SPECS = {
    "Spring Rate": {"lsl": 0.705, "usl": 0.815},
    "Global Average": {"lsl": 8.5, "usl": 11.83},
}

_ORT_CORE_COL_ALIASES = {
    "project": ("项目", "項目", "project"),
    "machine_type": ("机种", "機種", "几種", "model", "machine type"),
    "component": ("组件", "組件", "component"),
    "subpart": ("小件", "subpart", "sub_part"),
    "recipe": ("配方", "recipe"),
    "time": ("检测时间", "檢測時間", "时间", "時間", "time"),
    "barcode": ("二维码", "條碼", "条码", "barcode", "sn"),
    "material_category": ("物料类别", "物料類別", "物料类型", "material category", "material_category"),
}

_MATERIAL_CATEGORY_DEFAULT = "IPQC"
_ORT_MATERIAL_CATEGORY_COL = "物料类别"


def _normalize_stand_yield_specs(raw) -> dict:
    src = raw if isinstance(raw, dict) else {}
    out: dict = {}
    for point_name, default_limits in _DEFAULT_STAND_YIELD_SPECS.items():
        row = src.get(point_name) if isinstance(src.get(point_name), dict) else {}
        try:
            lsl = float(row.get("lsl", default_limits["lsl"]))
        except (TypeError, ValueError):
            lsl = float(default_limits["lsl"])
        try:
            usl = float(row.get("usl", default_limits["usl"]))
        except (TypeError, ValueError):
            usl = float(default_limits["usl"])
        low, high = (lsl, usl) if lsl <= usl else (usl, lsl)
        out[point_name] = {"lsl": low, "usl": high}
    return out


def _load_stand_yield_specs() -> dict:
    try:
        with open(_STAND_YIELD_SPEC_FILE, "r", encoding="utf-8") as fh:
            return _normalize_stand_yield_specs(json.load(fh))
    except Exception:
        return _normalize_stand_yield_specs({})


def _save_stand_yield_specs(specs: dict) -> dict:
    payload = _normalize_stand_yield_specs(specs)
    with open(_STAND_YIELD_SPEC_FILE, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)
    return payload


def _stand_value_in_spec(value, lsl, usl) -> bool:
    try:
        v = float(value)
        l = float(lsl)
        u = float(usl)
    except (TypeError, ValueError):
        return False
    return l <= v <= u


def _is_valid_stand_serial_barcode(barcode) -> bool:
    txt = str(barcode or "").strip()
    if not txt or txt.lower() == "na":
        return False
    if txt.startswith("na_row_"):
        return False
    return True


def _dedupe_stand_long_df_by_serial(df: pd.DataFrame) -> pd.DataFrame:
    """Stand 良率统计：同一 Serial no. 仅保留 test_time 最新的一批测点记录（入库不去重）。"""
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df.iloc[0:0].copy()
    work = df.copy()
    if "barcode" not in work.columns:
        return work.iloc[0:0].copy()
    work["barcode"] = work["barcode"].fillna("").astype(str).str.strip()
    work = work[work["barcode"].map(_is_valid_stand_serial_barcode)]
    if work.empty:
        return work
    if "test_time" in work.columns:
        work["_dt"] = pd.to_datetime(work["test_time"], errors="coerce")
        work = work.sort_values(["barcode", "_dt"], kind="stable")
        latest = work.groupby("barcode", dropna=False)["_dt"].transform("max")
        work = work[work["_dt"] == latest]
    else:
        work = work.drop_duplicates(subset=["barcode", "point_name"], keep="last")
    return work.drop(columns=["_dt"], errors="ignore")


def _build_stand_yield_stats_from_long_df(
    df: pd.DataFrame,
    *,
    module_name: str,
    category: str,
    product_name: str,
    specs: dict | None = None,
) -> list[dict]:
    """Stand 良率：按 Serial no. 去重（取最新时间），Spring Rate / Global Average 分别统计。"""
    specs = specs or _load_stand_yield_specs()
    spec_items = [(name, float(v["lsl"]), float(v["usl"])) for name, v in specs.items()]
    if not spec_items or df is None or df.empty:
        return []

    work = df.copy()
    work["point_name"] = work.get("point_name", "").fillna("").astype(str).str.strip()
    core_names = {name for name, _, _ in spec_items}
    work = work[work["point_name"].isin(core_names)]
    work = _dedupe_stand_long_df_by_serial(work)
    if work.empty:
        return []

    scope_cols = ["module_name", "category", "product_name"]
    if all(c in work.columns for c in scope_cols):
        grouped = work.groupby(
            [work["module_name"].fillna("").astype(str).str.strip(),
             work["category"].fillna("").astype(str).str.strip(),
             work["product_name"].fillna("").astype(str).str.strip()],
            dropna=False,
        )
        scope_groups = [
            (mod or module_name, cat or category, prod or product_name, gdf)
            for (mod, cat, prod), gdf in grouped
        ]
    else:
        scope_groups = [(module_name, category, product_name, work)]

    yield_rows: list[dict] = []
    for mod_name, cat_name, prod_name, scope_df in scope_groups:
        barcodes = sorted(scope_df["barcode"].astype(str).unique())
        dedup_total = len(barcodes)
        if dedup_total <= 0:
            continue

        combined_ng = 0
        for bc in barcodes:
            bc_rows = scope_df[scope_df["barcode"].astype(str) == bc]
            sample_ok = True
            for point_name, lsl, usl in spec_items:
                vals = pd.to_numeric(
                    bc_rows.loc[bc_rows["point_name"] == point_name, "value"],
                    errors="coerce",
                ).dropna()
                if vals.empty or not _stand_value_in_spec(vals.iloc[-1], lsl, usl):
                    sample_ok = False
                    break
            if not sample_ok:
                combined_ng += 1

        for point_name, lsl, usl in spec_items:
            ng_count = 0
            for bc in barcodes:
                vals = pd.to_numeric(
                    scope_df.loc[
                        (scope_df["barcode"].astype(str) == bc)
                        & (scope_df["point_name"] == point_name),
                        "value",
                    ],
                    errors="coerce",
                ).dropna()
                if vals.empty or not _stand_value_in_spec(vals.iloc[-1], lsl, usl):
                    ng_count += 1
            ok_count = dedup_total - ng_count
            yield_rate = round(ok_count / dedup_total * 100, 2) if dedup_total > 0 else 0.0
            yield_rows.append({
                "module_name": mod_name,
                "category": cat_name,
                "product_name": prod_name,
                "subpart": "Stand",
                "recipe": point_name,
                "total": dedup_total,
                "ng_count": ng_count,
                "alert_count": 0,
                "yield_rate": yield_rate,
                "stand_param_yield": True,
                "stand_dedup_total": dedup_total,
                "stand_combined_ng": combined_ng,
            })

    yield_rows.sort(key=lambda x: (str(x.get("product_name", "")), str(x.get("recipe", ""))))
    return yield_rows


def _prepare_stand_daily_boxplot_df(df: pd.DataFrame, specs: dict | None = None) -> pd.DataFrame:
    """Stand 箱线图：按天汇总；同一天同一 Serial + 参数仅保留最新一笔。"""
    specs = specs or _load_stand_yield_specs()
    core_names = set(specs.keys())
    if df is None or df.empty:
        return pd.DataFrame(columns=["day", "point_name", "value", "barcode"])
    work = df.copy()
    work["point_name"] = work.get("point_name", "").fillna("").astype(str).str.strip()
    work = work[work["point_name"].isin(core_names)]
    if "barcode" not in work.columns:
        return pd.DataFrame(columns=["day", "point_name", "value", "barcode"])
    work["barcode"] = work["barcode"].fillna("").astype(str).str.strip()
    work = work[work["barcode"].map(_is_valid_stand_serial_barcode)]
    if work.empty:
        return work
    work["_dt"] = pd.to_datetime(work.get("test_time"), errors="coerce")
    work["value"] = pd.to_numeric(work.get("value"), errors="coerce")
    work = work.dropna(subset=["_dt", "value"])
    if work.empty:
        return work
    work["day"] = work["_dt"].dt.strftime("%Y-%m-%d")
    work = work.sort_values(["day", "barcode", "point_name", "_dt"], kind="stable")
    work = work.drop_duplicates(subset=["day", "barcode", "point_name"], keep="last")
    return work[["day", "point_name", "value", "barcode"]].reset_index(drop=True)


_STAND_SERIAL_UPLOAD_COL_ALIASES = (
    "serial no.", "serial no", "serial_no", "serialno", "serial number",
    "serial", "barcode", "sn", "二维码", "条码", "序列号",
)

DATA_IMPORT_EXTENSIONS = (".xlsx", ".xlsm", ".csv")
DATA_IMPORT_DIALOG_FILTER = (
    "表格文件 (*.xlsx *.xlsm *.csv);;Excel (*.xlsx *.xlsm);;CSV (*.csv)"
)
DATA_IMPORT_UNSUPPORTED_MSG = "仅支持 .xlsx、.xlsm、.csv 格式"


def _data_file_extension(path: str) -> str:
    return os.path.splitext(str(path or ""))[1].lower()


def _is_supported_data_import_file(path: str) -> bool:
    return _data_file_extension(path) in DATA_IMPORT_EXTENSIONS


def _read_tabular_dataframe(
    path: str,
    *,
    header=0,
    nrows: int | None = None,
    sheet_name: str | int | None = 0,
    dtype=str,
) -> pd.DataFrame:
    """读取 xlsx / xlsm / csv 表格（带表头行）。"""
    ext = _data_file_extension(path)
    if ext == ".csv":
        kwargs: dict = {"header": header, "dtype": dtype, "keep_default_na": False}
        if nrows is not None:
            kwargs["nrows"] = nrows
        return pd.read_csv(path, **kwargs)
    if ext in (".xlsx", ".xlsm"):
        kwargs = {"header": header, "dtype": dtype, "sheet_name": sheet_name}
        if nrows is not None:
            kwargs["nrows"] = nrows
        return pd.read_excel(path, **kwargs)
    raise ValueError(DATA_IMPORT_UNSUPPORTED_MSG)


def _read_tabular_raw(path: str, sheet_name: str | int | None = 0) -> pd.DataFrame:
    """读取 xlsx / xlsm / csv 原始矩阵（header=None，供映射/模板解析）。"""
    ext = _data_file_extension(path)
    if ext == ".csv":
        return pd.read_csv(path, header=None, dtype=str, keep_default_na=False)
    if ext in (".xlsx", ".xlsm"):
        return pd.read_excel(path, header=None, sheet_name=sheet_name)
    raise ValueError(DATA_IMPORT_UNSUPPORTED_MSG)


def _find_df_column_by_aliases(columns, aliases: tuple[str, ...]) -> str | None:
    lowered = {str(c).strip().lower(): str(c) for c in columns}
    for alias in aliases:
        hit = lowered.get(str(alias).strip().lower())
        if hit:
            return hit
    return None


def _parse_stand_serial_list_from_file(path: str) -> list[str]:
    if not _is_supported_data_import_file(path):
        raise ValueError(DATA_IMPORT_UNSUPPORTED_MSG)
    df = _read_tabular_dataframe(path, header=0, dtype=str)

    col = _find_df_column_by_aliases(df.columns, _STAND_SERIAL_UPLOAD_COL_ALIASES)
    if col is None and len(df.columns) == 1:
        col = df.columns[0]
    if col is None:
        raise ValueError("未找到 Serial no. 列，请确认表头包含 Serial no. / barcode 等字段")

    serials: list[str] = []
    seen: set[str] = set()
    for raw in df[col].tolist():
        txt = str(raw or "").strip()
        if not txt or txt.lower() in ("nan", "none", "serial no.", "serial no"):
            continue
        key = txt
        if key not in seen:
            seen.add(key)
            serials.append(key)
    if not serials:
        raise ValueError("文件中未读取到有效的 Serial no.")
    return serials


def _build_stand_serial_history_display_df(long_df: pd.DataFrame) -> pd.DataFrame:
    """Stand Serial 历史：不去重，宽表 + 同 Serial 前后变化量。"""
    specs = _load_stand_yield_specs()
    sr_name, ga_name = "Spring Rate", "Global Average"
    if long_df is None or long_df.empty:
        return pd.DataFrame()
    work = long_df.copy()
    if "barcode" not in work.columns:
        return pd.DataFrame()
    work["barcode"] = work["barcode"].fillna("").astype(str).str.strip()
    work["point_name"] = work.get("point_name", "").fillna("").astype(str).str.strip()
    work["value"] = pd.to_numeric(work.get("value"), errors="coerce")
    work["_dt"] = pd.to_datetime(work.get("test_time"), errors="coerce")
    work = work[(work["barcode"] != "") & work["point_name"].isin(specs.keys())]
    if work.empty:
        return pd.DataFrame()

    wide_rows: list[dict] = []
    for (bc, tt), grp in work.groupby(["barcode", "test_time"], sort=False):
        dt_s = grp["_dt"].dropna()
        dt_key = dt_s.iloc[0] if not dt_s.empty else pd.NaT
        row = {"barcode": bc, "test_time": tt, "_dt": dt_key}
        for pn in (sr_name, ga_name):
            if pn not in specs:
                continue
            vals = grp.loc[grp["point_name"] == pn, "value"].dropna()
            row[pn] = float(vals.iloc[0]) if not vals.empty else None
        wide_rows.append(row)

    wide = pd.DataFrame(wide_rows)
    if wide.empty:
        return wide
    wide = wide.sort_values(["barcode", "_dt", "test_time"], kind="stable", na_position="last")
    if sr_name in wide.columns:
        wide["Spring Rate Δ"] = wide.groupby("barcode")[sr_name].diff()
    if ga_name in wide.columns:
        wide["Global Average Δ"] = wide.groupby("barcode")[ga_name].diff()

    def _judge(pn: str, val) -> str:
        if val is None or (isinstance(val, float) and pd.isna(val)):
            return "NG"
        lim = specs.get(pn, {})
        return "OK" if _stand_value_in_spec(val, lim.get("lsl"), lim.get("usl")) else "NG"

    if sr_name in wide.columns:
        wide["SR判定"] = [_judge(sr_name, v) for v in wide[sr_name]]
    if ga_name in wide.columns:
        wide["GA判定"] = [_judge(ga_name, v) for v in wide[ga_name]]

    for delta_col in ("Spring Rate Δ", "Global Average Δ"):
        if delta_col in wide.columns:
            wide[delta_col] = wide[delta_col].apply(
                lambda x: "" if pd.isna(x) else f"{float(x):+.4f}"
            )

    wide.insert(0, "序号", range(1, len(wide) + 1))
    show_cols = [
        c for c in [
            "序号", "barcode", "test_time", sr_name, "Spring Rate Δ",
            ga_name, "Global Average Δ", "SR判定", "GA判定",
        ] if c in wide.columns
    ]
    out = wide[show_cols].copy()
    rename_map = {
        "barcode": "Serial no.",
        "test_time": "检测时间",
        sr_name: sr_name,
        ga_name: ga_name,
    }
    out.rename(columns=rename_map, inplace=True)
    return out.reset_index(drop=True)


def _normalize_material_category_value(value, default: str = _MATERIAL_CATEGORY_DEFAULT) -> str:
    """物料类别：源单元格为空/空白时补默认值（默认 IPQC）。"""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return default
    txt = str(value).strip()
    if not txt or txt.lower() in ("nan", "none"):
        return default
    return txt


def _detect_material_category_col_index(col_labels: list) -> int:
    """在信息列中自动识别物料类别源列（備註1 / 物料类别 等）。"""
    exact_names = (
        "備註1", "备注1", "備註 1", "备注 1", "remark1", "remark 1",
        "物料类别", "物料類別", "物料类型", "material category", "material_category",
    )
    for i, name in enumerate(col_labels or []):
        n = str(name or "").strip()
        if not n:
            continue
        nl = n.lower().replace(" ", "")
        for kw in exact_names:
            if n == kw or nl == kw.lower().replace(" ", ""):
                return i
    for i, name in enumerate(col_labels or []):
        n = str(name or "").strip().lower()
        if "備註1" in n or "备注1" in n or "remark1" in n.replace(" ", ""):
            return i
    return -1


def _resolve_material_category_col_index(config: dict, info_col_labels: list) -> int:
    """合并模板配置与列名自动识别，得到物料类别源列索引。"""
    mat_idx = config.get("material_category_col", -1)
    if isinstance(mat_idx, int) and mat_idx >= 0:
        return mat_idx
    return _detect_material_category_col_index(info_col_labels)


def _material_category_series_from_df(df: pd.DataFrame, mat_idx: int, info_col_labels: list) -> pd.Series:
    """从宽表按列索引/列名提取物料类别序列（空值补 IPQC）。"""
    if df is None or df.empty or mat_idx < 0:
        return pd.Series([_MATERIAL_CATEGORY_DEFAULT] * len(df), index=df.index)
    src_col = None
    if info_col_labels and 0 <= mat_idx < len(info_col_labels):
        src_col = info_col_labels[mat_idx]
    if src_col and src_col in df.columns:
        return df[src_col].map(_normalize_material_category_value)
    if 0 <= mat_idx < df.shape[1]:
        return df.iloc[:, mat_idx].map(_normalize_material_category_value)
    return pd.Series([_MATERIAL_CATEGORY_DEFAULT] * len(df), index=df.index)


def _material_category_for_db_row(record, df: pd.DataFrame, cfg: dict) -> str | None:
    """从宽表行解析物料类别；已映射时空值补 IPQC，未映射则返回 None。"""
    if _ORT_MATERIAL_CATEGORY_COL in df.columns:
        return _normalize_material_category_value(record.get(_ORT_MATERIAL_CATEGORY_COL))
    info_n = int(cfg.get("info_col_count", 21) or 21)
    info_labels = [str(c) for c in list(df.columns)[:info_n]]
    mat_idx = _resolve_material_category_col_index(cfg, info_labels)
    if mat_idx < 0:
        return None
    cols = list(df.columns)
    if 0 <= mat_idx < len(cols):
        return _normalize_material_category_value(record.get(cols[mat_idx]))
    return _MATERIAL_CATEGORY_DEFAULT


def _match_ort_core_col_key(col_name: str) -> str | None:
    name = str(col_name or "").strip()
    if not name:
        return None
    lowered = name.lower()
    for key, aliases in _ORT_CORE_COL_ALIASES.items():
        for alias in aliases:
            alias_lower = str(alias).lower()
            if name == alias or lowered == alias_lower:
                return key
    return None


def _ort_point_status_code(value, lsl, usl) -> int:
    """ORT 测点状态：0=NG(低于LSL)，2=Alert(介于LSL与USL)，1=合格。"""
    try:
        v = float(value)
        l = float(lsl)
    except (TypeError, ValueError):
        return 1
    if v < l:
        return 0
    try:
        u = float(usl)
    except (TypeError, ValueError):
        return 1
    if l < u and l <= v < u:
        return 2
    if u <= l and u <= v < l:
        return 2
    return 1


# ==================== 2-A. SQLite 长表存储（按 模块+大类+产品 分表）====================
class ORTDatabaseManager:
    """
    质量分析系统标准长表本地沉淀：SQLite，路径固定为
    _app_config_dir() / QualityAnalyseSystem_Storage.db。

    按 module_name + category + product_name 组合分表存储，
    表名格式：ort_{module_name}_{category}_{product_name}
    联合主键 (barcode, recipe, point_name)，INSERT OR REPLACE 新数据替换旧数据。
    """

    _TABLE_PREFIX = "ort"
    _REGISTRY_TABLE = "_ort_table_registry"
    _DEFAULT_MODULE = "ORT"
    _DB_FILE = "QualityAnalyseSystem_Storage.db"
    _LEGACY_DB_FILE = "ORT_Storage.db"
    _MODULE_ALIASES = {
        "ort": "ORT",
        "weekly inspection": "Weekly Inspection",
        "weekly_inspection": "Weekly Inspection",
        "周送检": "Weekly Inspection",
    }
    _CATEGORY_ALIASES = {
        "dh": "DH",
        "stand": "Stand",
        "fatp": "FATP",
    }
    _DATA_TABLE_COLUMNS = (
        "module_name", "category", "product_name", "project", "model", "component",
        "subpart", "recipe", "barcode", "test_time", "point_name", "value",
        "usl", "lsl", "line", "result", "shift", "test_position", "material_category",
        "nominal", "tol_max", "tol_min", "dimension_description", "dimension_type",
        "distribution_type", "special_attrs",
    )
    # Weekly Inspection：按「产品名称(分表) + 检测日期」整批覆盖，后导入覆盖先导入
    _WI_BATCH_REPLACE_KEY = ("product_name", "test_time")
    _WI_TABLE_ROW_PK = ("test_time", "barcode", "point_name")  # 表内行主键（同批内样本+测点）
    # CPK 入库：核心统计行（按列）建议 REAL 的字段名（清洗后列名）
    _WI_CPK_NUMERIC_COLUMNS = frozenset({
        "value", "nominal", "usl", "lsl", "tol_max", "tol_min",
        "std_dev", "mean", "maximum", "minimum", "cp", "cpkl", "cpku", "cpk",
        "projected_yield", "mean_drift", "changed_mean",
        "proposed_usl", "proposed_lsl", "proposed_yield",
        "Proposed_Tol", "Mean_Shift_Amount",
    })

    @classmethod
    def _wi_cpk_sql_type(cls, col_name: str) -> str:
        clean = re.sub(r"[^a-zA-Z0-9_]", "_", str(col_name or ""))
        if clean and not clean[0].isalpha():
            clean = "_" + clean
        if clean in cls._WI_CPK_NUMERIC_COLUMNS:
            return "REAL"
        return "TEXT"

    def __init__(self):
        app_dir = _app_config_dir()
        self.db_path = os.path.join(app_dir, self._DB_FILE)
        self.legacy_db_path = os.path.join(app_dir, self._LEGACY_DB_FILE)
        self._prepare_database()

    def _connect(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA synchronous=NORMAL;")
        return conn

    def _prepare_database(self) -> None:
        """初始化新库；若仅存在旧库，则复制并做架构升级。
        同时自动迁移旧格式表数据到新格式表。"""
        try:
            if not os.path.exists(self.db_path) and os.path.exists(self.legacy_db_path):
                shutil.copy2(self.legacy_db_path, self.db_path)
        except Exception as ex:
            print(f"[DB Warn] 复制旧数据库失败：{ex}")

        try:
            with self._connect() as conn:
                self._ensure_registry_table(conn)
                cur = conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE ?",
                    (f"{self._TABLE_PREFIX}_%",),
                )
                for row in cur.fetchall():
                    table_name = str(row[0]).strip() if row and row[0] is not None else ""
                    if table_name:
                        self._ensure_table_schema(conn, table_name)
                        self._ensure_table_indexes(conn, table_name)
                self._backfill_registry_from_existing_tables(conn)
                self._migrate_old_format_tables(conn)
                self._migrate_wi_flat_storage_tables(conn)
                self._backfill_registry_from_existing_tables(conn)
        except Exception as ex:
            print(f"[DB Warn] 初始化数据库结构失败：{ex}")

    def _migrate_old_format_tables(self, conn: sqlite3.Connection) -> None:
        """自动迁移旧格式表（ort_dh_x2689_dh）到新格式表（ort_ort_dh_x2689_dh）。"""
        try:
            cur = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE ?",
                (f"{self._TABLE_PREFIX}_%",),
            )
            all_tables = {str(row[0]).strip() for row in cur.fetchall() if row and row[0]}
            
            for old_table in list(all_tables):
                # 跳过注册表和新格式表
                if old_table == self._REGISTRY_TABLE:
                    continue
                if self._is_new_format_table_name(old_table):
                    continue  # 已经是新格式
                
                # 解析旧表名
                module_name, category, product_name = self._resolve_scope_for_existing_table(conn, old_table)
                
                # 生成新表名
                new_table = self._get_table_name(module_name, category, product_name)
                
                if new_table == old_table:
                    self._stamp_table_scope(conn, old_table, module_name, category, product_name)
                    self._ensure_table_indexes(conn, old_table)
                    self._upsert_table_registry(conn, old_table, module_name, category, product_name)
                    continue  # 已经是正确格式
                
                if new_table in all_tables:
                    # 新表已存在，合并数据
                    print(f"[DB Migrate] 合并 {old_table} -> {new_table}")
                    self._ensure_table_exists(conn, new_table)
                    self._copy_rows_into_table(conn, old_table, new_table, module_name, category, product_name)
                    conn.execute(f"DROP TABLE {old_table}")
                    print(f"[DB Migrate] 已删除旧表 {old_table}")
                else:
                    # 旧表结构可能与新结构不完全一致，统一走复制迁移，保证三级字段完整。
                    print(f"[DB Migrate] 迁移 {old_table} -> {new_table}")
                    self._ensure_table_exists(conn, new_table)
                    self._copy_rows_into_table(conn, old_table, new_table, module_name, category, product_name)
                    conn.execute(f"DROP TABLE {old_table}")
                
                # 更新注册表
                self._upsert_table_registry(conn, new_table, module_name, category, product_name)
                conn.execute(
                    f"DELETE FROM {self._REGISTRY_TABLE} WHERE table_name = ?",
                    (old_table,),
                )
                self._stamp_table_scope(conn, new_table, module_name, category, product_name)
                self._ensure_table_indexes(conn, new_table)
                all_tables.discard(old_table)
                all_tables.add(new_table)
                
        except Exception as ex:
            print(f"[DB Warn] 迁移旧格式表失败：{ex}")

    def _clean_table_fragment(self, name: str) -> str:
        """清理表名片段中的非法字符。"""
        if not name:
            return "unknown"
        cleaned = re.sub(r"[^a-zA-Z0-9_]", "_", str(name))
        cleaned = re.sub(r"_+", "_", cleaned).strip("_")
        if not cleaned:
            cleaned = "unknown"
        if cleaned[0].isdigit():
            cleaned = "_" + cleaned
        return cleaned.lower()

    def _known_module_names(self) -> list[str]:
        """返回已知的模块名列表（经过清理的小写格式）。"""
        return [
            self._clean_table_fragment(self._DEFAULT_MODULE),
            self._clean_table_fragment("Weekly Inspection")
        ]

    def _normalize_module_name(self, value: str | None) -> str:
        txt = str(value or "").strip()
        if not txt:
            return self._DEFAULT_MODULE
        alias_key = re.sub(r"\s+", " ", txt.replace("_", " ")).strip().lower()
        return self._MODULE_ALIASES.get(alias_key, txt)

    def _normalize_category_name(self, value: str | None) -> str:
        txt = str(value or "").strip()
        if not txt:
            return "UNKNOWN"
        return self._CATEGORY_ALIASES.get(txt.lower(), txt)

    def _normalize_product_name(self, value: str | None) -> str:
        txt = str(value or "").strip()
        return txt or "UNKNOWN_PRODUCT"

    def _normalize_scope_triplet(
        self,
        module_name: str | None,
        category: str | None,
        product_name: str | None,
    ) -> tuple[str, str, str]:
        return (
            self._normalize_module_name(module_name),
            self._normalize_category_name(category),
            self._normalize_product_name(product_name),
        )

    def _sql_text_literal(self, value: str) -> str:
        """将文本安全嵌入拼接 SQL 的字符串字面量。"""
        return "'" + str(value or "").replace("'", "''") + "'"

    @staticmethod
    def _infer_wi_category_from_process(process_name: str) -> str:
        """由制程名推断二级产品（如 X2689 DH CNC2 → X2689 DH）。"""
        name = str(process_name or "").strip()
        parts = name.split()
        if len(parts) >= 3:
            return " ".join(parts[:-1])
        return name or "UNKNOWN"

    def _get_table_name(self, module_name: str, category: str, product_name: str) -> str:
        """根据模块 / 大类(产品) / 产品(制程) 生成数据表名。
        
        格式: ort_{module}_{category}_{process}
        Weekly Inspection 与 ORT 相同三级：ort_weekly_inspection_{产品}_{制程}
        """
        module_clean = self._clean_table_fragment(module_name)
        category_clean = self._clean_table_fragment(category)
        product_clean = self._clean_table_fragment(product_name)
        if self._normalize_module_name(module_name) == "Weekly Inspection":
            if not category_clean or category_clean in ("unknown", "templates"):
                category_clean = self._clean_table_fragment(
                    self._infer_wi_category_from_process(product_name)
                )
        return f"{self._TABLE_PREFIX}_{module_clean}_{category_clean}_{product_clean}"

    def _table_columns(self, conn: sqlite3.Connection, table_name: str) -> set[str]:
        try:
            cur = conn.execute(f"PRAGMA table_info({table_name})")
            return {str(row[1]).strip() for row in cur.fetchall() if row and len(row) > 1}
        except Exception:
            return set()

    def _is_wi_storage_table(self, table_name: str) -> bool:
        prefix = f"{self._TABLE_PREFIX}_weekly_inspection_"
        return str(table_name or "").lower().startswith(prefix)

    @staticmethod
    def _normalize_wi_test_time_value(value) -> str:
        """Weekly Inspection 检测日期统一为 YYYY-MM-DD，供整批覆盖匹配使用。"""
        if value is None or (isinstance(value, float) and pd.isna(value)):
            return ""
        s = str(value).strip()
        if not s:
            return ""
        try:
            ts = pd.to_datetime(s, errors="coerce")
            if pd.notna(ts):
                return ts.strftime("%Y-%m-%d")
        except Exception:
            pass
        if len(s) >= 10 and s[4] == "-" and s[7] == "-":
            return s[:10]
        return s

    @staticmethod
    def _wi_normalized_test_time_sql(column: str = "test_time") -> str:
        """SQL 表达式：将 test_time 规范为 YYYY-MM-DD 便于按检测日期匹配。"""
        return (
            f"COALESCE("
            f"CASE WHEN date({column}) IS NOT NULL THEN date({column}) ELSE NULL END, "
            f"CASE WHEN length(trim({column})) >= 10 THEN substr(trim({column}), 1, 10) ELSE trim({column}) END, "
            f"''"
            f")"
        )

    def _purge_wi_batches_by_test_time(
        self, conn: sqlite3.Connection, table_name: str, test_times: list[str]
    ) -> int:
        """删除指定检测日期的整批旧数据（产品已对应分表）。"""
        if not self._is_wi_storage_table(table_name):
            return 0
        tt_expr = self._wi_normalized_test_time_sql("test_time")
        deleted = 0
        for raw_tt in test_times:
            norm_tt = self._normalize_wi_test_time_value(raw_tt)
            if not norm_tt:
                continue
            cur = conn.execute(
                f'DELETE FROM "{table_name}" WHERE {tt_expr} = ?',
                (norm_tt,),
            )
            deleted += int(cur.rowcount or 0)
        return deleted

    def wi_batch_exists(
        self,
        product_name: str,
        test_time: str,
        category: str = "",
    ) -> tuple[bool, int]:
        """检查 Weekly Inspection 是否已有相同「产品 + 检测日期」批次。返回 (是否存在, 行数)。"""
        product_name = str(product_name or "").strip()
        norm_tt = self._normalize_wi_test_time_value(test_time)
        if not product_name or not norm_tt:
            return False, 0
        table_name = self._get_table_name("Weekly Inspection", category, product_name)
        if not self._is_wi_storage_table(table_name):
            return False, 0
        tt_expr = self._wi_normalized_test_time_sql("test_time")
        try:
            with self._connect() as conn:
                cur = conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1",
                    (table_name,),
                )
                if not cur.fetchone():
                    return False, 0
                cur = conn.execute(
                    f'SELECT COUNT(*) FROM "{table_name}" WHERE {tt_expr} = ?',
                    (norm_tt,),
                )
                row = cur.fetchone()
                count = int(row[0]) if row and row[0] is not None else 0
                return count > 0, count
        except Exception as ex:
            print(f"[CPK Debug] 检查 WI 批次是否存在失败：{ex}")
            return False, 0

    def _wi_cpk_table_pk_columns(self, conn: sqlite3.Connection, table_name: str) -> list[str]:
        try:
            cur = conn.execute(f'PRAGMA table_info("{table_name}")')
            return [str(row[1]) for row in cur.fetchall() if row and len(row) > 5 and row[5]]
        except Exception:
            return []

    def _migrate_wi_cpk_table_pk_if_needed(self, conn: sqlite3.Connection, table_name: str) -> None:
        """将旧 WI 表主键 (barcode, point_name) 升级为 (test_time, barcode, point_name)。"""
        if not self._is_wi_storage_table(table_name):
            return
        try:
            cur = conn.execute(f'PRAGMA table_info("{table_name}")')
            info = cur.fetchall()
        except Exception:
            return
        if not info:
            return
        pk_cols = [str(r[1]) for r in info if len(r) > 5 and r[5]]
        target = list(self._WI_TABLE_ROW_PK)
        if pk_cols == target:
            return
        if pk_cols not in (["barcode", "point_name"], ["machine_id", "point_name"]):
            print(f"[CPK Debug] 跳过主键迁移（未知主键 {pk_cols}）：{table_name}")
            return

        col_names = [str(r[1]) for r in info]
        tmp = f"{table_name}__pk_upg"
        conn.execute(f'DROP TABLE IF EXISTS "{tmp}"')

        col_defs: list[str] = []
        for r in info:
            name = str(r[1])
            decl = str(r[2] or "TEXT").strip().upper() or "TEXT"
            if name in ("value", "nominal", "usl", "lsl", "tol_max", "tol_min"):
                decl = "REAL"
            col_defs.append(f'"{name}" {decl}')
        if "barcode" not in col_names:
            col_defs.append('"barcode" TEXT')
        col_defs.append("PRIMARY KEY (test_time, barcode, point_name)")
        conn.execute(f'CREATE TABLE "{tmp}" ({", ".join(col_defs)})')

        tt_expr = (
            "COALESCE("
            "CASE WHEN date(test_time) IS NOT NULL THEN date(test_time) ELSE NULL END, "
            "CASE WHEN length(trim(test_time)) >= 10 THEN substr(trim(test_time), 1, 10) ELSE trim(test_time) END, "
            "''"
            ")"
        )
        if "barcode" in col_names and "machine_id" in col_names:
            bc_expr = 'COALESCE(NULLIF(TRIM(barcode), ""), NULLIF(TRIM(machine_id), ""), "")'
        elif "barcode" in col_names:
            bc_expr = 'COALESCE(NULLIF(TRIM(barcode), ""), "")'
        else:
            bc_expr = 'COALESCE(NULLIF(TRIM(machine_id), ""), "")'

        select_parts: list[str] = []
        insert_cols: list[str] = []
        out_cols = col_names + (["barcode"] if "barcode" not in col_names else [])
        for c in out_cols:
            insert_cols.append(f'"{c}"')
            if c == "test_time":
                select_parts.append(f"{tt_expr} AS test_time")
            elif c == "barcode":
                select_parts.append(f"{bc_expr} AS barcode")
            else:
                select_parts.append(f'"{c}"')

        conn.execute(
            f'INSERT OR REPLACE INTO "{tmp}" ({", ".join(insert_cols)}) '
            f'SELECT {", ".join(select_parts)} FROM "{table_name}"'
        )
        conn.execute(f'DROP TABLE "{table_name}"')
        conn.execute(f'ALTER TABLE "{tmp}" RENAME TO "{table_name}"')
        conn.execute(f"CREATE INDEX IF NOT EXISTS idx_{table_name}_pt ON {table_name} (point_name)")
        conn.execute(f"CREATE INDEX IF NOT EXISTS idx_{table_name}_tt ON {table_name} (test_time)")
        print(f"[CPK Debug] 已迁移 WI 表主键 → {target}：{table_name}")

    def _ensure_registry_indexes(self, conn: sqlite3.Connection) -> None:
        conn.execute(
            f"""
            CREATE INDEX IF NOT EXISTS idx_{self._REGISTRY_TABLE.strip('_')}_scope
                ON {self._REGISTRY_TABLE} (module_name, category, product_name)
            """
        )

    def _ensure_table_indexes(self, conn: sqlite3.Connection, table_name: str) -> None:
        conn.execute(
            f"CREATE INDEX IF NOT EXISTS idx_{table_name}_recipe ON {table_name} (recipe)"
        )
        conn.execute(
            f"CREATE INDEX IF NOT EXISTS idx_{table_name}_test_time ON {table_name} (test_time)"
        )
        conn.execute(
            f"CREATE INDEX IF NOT EXISTS idx_{table_name}_recipe_point_time ON {table_name} (recipe, point_name, test_time)"
        )
        conn.execute(
            f"CREATE INDEX IF NOT EXISTS idx_{table_name}_subpart_recipe_time ON {table_name} (subpart, recipe, test_time)"
        )

    def _table_scope_from_rows(self, conn: sqlite3.Connection, table_name: str) -> tuple[str | None, str | None, str | None]:
        cols = self._table_columns(conn, table_name)
        if "category" not in cols or "product_name" not in cols:
            return None, None, None
        module_sql = "COALESCE(NULLIF(TRIM(module_name), ''), ?) AS module_name" if "module_name" in cols else "? AS module_name"
        row = conn.execute(
            f"""
            SELECT {module_sql}, category, product_name
              FROM {table_name}
             WHERE COALESCE(NULLIF(TRIM(category), ''), '') != ''
                OR COALESCE(NULLIF(TRIM(product_name), ''), '') != ''
             LIMIT 1
            """,
            (self._DEFAULT_MODULE,),
        ).fetchone()
        if not row:
            return None, None, None
        return self._normalize_scope_triplet(row[0], row[1], row[2])

    def _resolve_scope_for_existing_table(self, conn: sqlite3.Connection, table_name: str) -> tuple[str, str, str]:
        row_scope = self._table_scope_from_rows(conn, table_name)
        if all(row_scope):
            return row_scope
        return self._infer_scope_from_table_name(table_name)

    def _stamp_table_scope(
        self,
        conn: sqlite3.Connection,
        table_name: str,
        module_name: str,
        category: str,
        product_name: str,
    ) -> None:
        module_name, category, product_name = self._normalize_scope_triplet(module_name, category, product_name)
        conn.execute(f"UPDATE {table_name} SET module_name = ? WHERE module_name IS NULL OR TRIM(module_name) = ''", (module_name,))
        conn.execute(f"UPDATE {table_name} SET category = ? WHERE category IS NULL OR TRIM(category) = ''", (category,))
        conn.execute(f"UPDATE {table_name} SET product_name = ? WHERE product_name IS NULL OR TRIM(product_name) = ''", (product_name,))

    def _is_new_format_table_name(self, table_name: str) -> bool:
        raw = str(table_name or "").strip()
        if not raw.startswith(f"{self._TABLE_PREFIX}_"):
            return False
        suffix = raw[len(self._TABLE_PREFIX) + 1:]
        known_modules = sorted(
            {self._clean_table_fragment(name) for name in self._known_module_names()},
            key=len,
            reverse=True,
        )
        suffix_lower = suffix.lower()
        for mod_frag in known_modules:
            if suffix_lower.startswith(mod_frag.lower() + "_"):
                rest = suffix[len(mod_frag) + 1:]
                if mod_frag == self._clean_table_fragment("Weekly Inspection"):
                    cat_tok, proc_tok = self._split_wi_table_rest(rest)
                    return bool(cat_tok and proc_tok)
                return "_" in rest
        return False

    def _registry_row(self, conn: sqlite3.Connection, table_name: str) -> dict | None:
        try:
            cur = conn.execute(
                f"SELECT module_name, category, product_name FROM {self._REGISTRY_TABLE} WHERE table_name = ?",
                (table_name,),
            )
            row = cur.fetchone()
            if not row:
                return None
            return {"module_name": row[0], "category": row[1], "product_name": row[2]}
        except Exception:
            return None

    def _copy_rows_into_table(
        self,
        conn: sqlite3.Connection,
        src_table: str,
        dst_table: str,
        module_name: str,
        category: str,
        product_name: str,
    ) -> None:
        src_cols = self._table_columns(conn, src_table)
        select_exprs: list[str] = []
        for col_name in self._DATA_TABLE_COLUMNS:
            if col_name == "module_name":
                select_exprs.append(f"{self._sql_text_literal(module_name)} AS module_name")
            elif col_name == "category":
                select_exprs.append(f"{self._sql_text_literal(category)} AS category")
            elif col_name == "product_name":
                select_exprs.append(f"{self._sql_text_literal(product_name)} AS product_name")
            elif col_name in src_cols:
                select_exprs.append(col_name)
            else:
                select_exprs.append(f"NULL AS {col_name}")
        conn.execute(
            f"""
            INSERT OR REPLACE INTO {dst_table} ({', '.join(self._DATA_TABLE_COLUMNS)})
            SELECT {', '.join(select_exprs)}
              FROM {src_table}
            """
        )

    @staticmethod
    def _split_wi_table_rest(rest: str) -> tuple[str, str]:
        """解析 WI 表名后缀：{产品}_{制程}，制程 token 以产品 token 为前缀。"""
        rest = str(rest or "").strip().lower()
        if not rest:
            return "", ""
        for i in range(1, len(rest)):
            if rest[i] != "_":
                continue
            cat_part = rest[:i]
            proc_part = rest[i + 1:]
            if proc_part.startswith(cat_part + "_") or proc_part == cat_part:
                return cat_part, proc_part
        return "", rest

    def _infer_scope_from_table_name(self, table_name: str) -> tuple[str, str, str]:
        """兼容旧表名推断 module/category/product。"""
        raw = str(table_name or "").strip()
        if not raw.startswith(f"{self._TABLE_PREFIX}_"):
            return self._DEFAULT_MODULE, "", raw
        suffix = raw[len(self._TABLE_PREFIX) + 1:]
        wi_mod = self._clean_table_fragment("Weekly Inspection")
        known_modules = sorted(
            {self._clean_table_fragment(m) for m in self._known_module_names()},
            key=len,
            reverse=True,
        )
        suffix_lower = suffix.lower()
        for mod_frag in known_modules:
            prefix = mod_frag.lower() + "_"
            if not suffix_lower.startswith(prefix):
                continue
            rest = suffix[len(mod_frag) + 1:]
            if mod_frag == wi_mod:
                cat_tok, proc_tok = self._split_wi_table_rest(rest)
                if cat_tok and proc_tok:
                    category = cat_tok.replace("_", " ")
                    product_name = proc_tok.replace("_", " ")
                    return self._normalize_scope_triplet("Weekly Inspection", category, product_name)
                process_name = rest.replace("_", " ")
                category = self._infer_wi_category_from_process(process_name)
                return self._normalize_scope_triplet("Weekly Inspection", category, process_name)
            parts = [p for p in rest.split("_") if p]
            if len(parts) >= 2:
                return self._normalize_scope_triplet(mod_frag, parts[0], "_".join(parts[1:]))
            if len(parts) == 1:
                return self._normalize_scope_triplet(mod_frag, "", parts[0])
        parts = [p for p in suffix.split("_") if p]
        if len(parts) >= 2:
            return self._normalize_scope_triplet(self._DEFAULT_MODULE, parts[0], "_".join(parts[1:]))
        return self._normalize_scope_triplet(self._DEFAULT_MODULE, "", suffix or raw)

    def _migrate_wi_flat_storage_tables(self, conn: sqlite3.Connection) -> None:
        """WI 旧单级分表 ort_weekly_inspection_{制程} → ort_weekly_inspection_{产品}_{制程}。"""
        wi_mod = self._clean_table_fragment("Weekly Inspection")
        prefix = f"{self._TABLE_PREFIX}_{wi_mod}_"
        try:
            cur = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE ?",
                (f"{prefix}%",),
            )
            tables = [str(r[0]) for r in cur.fetchall() if r and r[0]]
        except Exception as ex:
            print(f"[DB Warn] 枚举 WI 表失败：{ex}")
            return
        for old_table in tables:
            suffix = old_table[len(prefix):]
            cat_tok, proc_tok = self._split_wi_table_rest(suffix)
            if cat_tok and proc_tok:
                continue
            row_scope = self._table_scope_from_rows(conn, old_table)
            if row_scope[0] and row_scope[1] and row_scope[2]:
                module_name, category, product_name = row_scope
            else:
                reg = self._registry_row(conn, old_table)
                if reg:
                    module_name = reg.get("module_name") or "Weekly Inspection"
                    category = str(reg.get("category") or "").strip()
                    product_name = str(reg.get("product_name") or "").strip()
                else:
                    module_name = "Weekly Inspection"
                    product_name = suffix.replace("_", " ")
                    category = self._infer_wi_category_from_process(product_name)
            if not category or category in ("_templates_", "UNKNOWN"):
                category = self._infer_wi_category_from_process(product_name)
            new_table = self._get_table_name(module_name, category, product_name)
            if new_table == old_table:
                self._stamp_table_scope(conn, old_table, module_name, category, product_name)
                self._upsert_table_registry(conn, old_table, module_name, category, product_name)
                continue
            print(f"[DB Migrate] WI 分层 {old_table} -> {new_table}")
            self._ensure_table_exists(conn, new_table)
            self._copy_rows_into_table(conn, old_table, new_table, module_name, category, product_name)
            conn.execute(f"DROP TABLE IF EXISTS {old_table}")
            conn.execute(
                f"DELETE FROM {self._REGISTRY_TABLE} WHERE table_name = ?",
                (old_table,),
            )
            self._upsert_table_registry(conn, new_table, module_name, category, product_name)
            self._stamp_table_scope(conn, new_table, module_name, category, product_name)
            self._ensure_table_indexes(conn, new_table)

    def _ensure_registry_table(self, conn: sqlite3.Connection) -> None:
        conn.execute(f"""
            CREATE TABLE IF NOT EXISTS {self._REGISTRY_TABLE} (
                table_name    TEXT PRIMARY KEY,
                module_name   TEXT NOT NULL DEFAULT '{self._DEFAULT_MODULE}',
                category      TEXT NOT NULL,
                product_name  TEXT NOT NULL,
                updated_at    TEXT NOT NULL
            )
        """)
        cols = self._table_columns(conn, self._REGISTRY_TABLE)
        if "module_name" not in cols:
            conn.execute(
                f"ALTER TABLE {self._REGISTRY_TABLE} ADD COLUMN module_name TEXT NOT NULL DEFAULT '{self._DEFAULT_MODULE}'"
            )
        conn.execute(
            f"""
            UPDATE {self._REGISTRY_TABLE}
               SET module_name = ?
             WHERE module_name IS NULL OR TRIM(module_name) = ''
            """,
            (self._DEFAULT_MODULE,),
        )
        self._ensure_registry_indexes(conn)

    def _upsert_table_registry(
        self,
        conn: sqlite3.Connection,
        table_name: str,
        module_name: str,
        category: str,
        product_name: str,
    ) -> None:
        self._ensure_registry_table(conn)
        module_name, category, product_name = self._normalize_scope_triplet(module_name, category, product_name)
        conn.execute(
            f"""
            INSERT OR REPLACE INTO {self._REGISTRY_TABLE}
            (table_name, module_name, category, product_name, updated_at)
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                str(table_name or "").strip(),
                module_name,
                category,
                product_name,
                pd.Timestamp.now().isoformat(),
            ),
        )

    def _ensure_table_exists(self, conn: sqlite3.Connection, table_name: str) -> None:
        """确保指定的表存在"""
        conn.execute(f"""
            CREATE TABLE IF NOT EXISTS {table_name} (
                module_name    TEXT,
                category       TEXT,
                product_name   TEXT,
                project        TEXT,
                model          TEXT,
                component      TEXT,
                subpart        TEXT,
                recipe         TEXT NOT NULL,
                barcode        TEXT NOT NULL,
                test_time      TEXT NOT NULL,
                point_name     TEXT NOT NULL,
                value          REAL,
                usl            REAL,
                lsl            REAL,
                line           TEXT,
                result         TEXT,
                shift          TEXT,
                test_position  TEXT,
                material_category TEXT,
                nominal        REAL,
                tol_max        REAL,
                tol_min        REAL,
                dimension_description TEXT,
                dimension_type TEXT,
                distribution_type TEXT,
                special_attrs  TEXT,
                PRIMARY KEY (barcode, recipe, point_name)
            )
        """)
        self._ensure_table_schema(conn, table_name)
        self._ensure_table_indexes(conn, table_name)

    def _ensure_table_schema(self, conn: sqlite3.Connection, table_name: str) -> None:
        """为旧表补齐新版本字段。"""
        cols = self._table_columns(conn, table_name)
        if "category" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN category TEXT")
        if "product_name" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN product_name TEXT")
        if "module_name" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN module_name TEXT")
        if "usl" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN usl REAL")
        if "material_category" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN material_category TEXT")
        if "nominal" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN nominal REAL")
        if "tol_max" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN tol_max REAL")
        if "tol_min" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN tol_min REAL")
        if "dimension_description" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN dimension_description TEXT")
        if "dimension_type" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN dimension_type TEXT")
        if "distribution_type" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN distribution_type TEXT")
        if "special_attrs" not in cols:
            conn.execute(f"ALTER TABLE {table_name} ADD COLUMN special_attrs TEXT")
        conn.execute(
            f"""
            UPDATE {table_name}
               SET module_name = ?
             WHERE module_name IS NULL OR TRIM(module_name) = ''
            """,
            (self._DEFAULT_MODULE,),
        )
        self._ensure_table_indexes(conn, table_name)

    def _backfill_registry_from_existing_tables(self, conn: sqlite3.Connection) -> None:
        self._ensure_registry_table(conn)
        cur = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE ?",
            (f"{self._TABLE_PREFIX}_%",),
        )
        for row in cur.fetchall():
            table_name = str(row[0]).strip() if row and row[0] is not None else ""
            if not table_name or table_name == self._REGISTRY_TABLE:
                continue
            self._ensure_table_schema(conn, table_name)
            module_name, category, product_name = self._resolve_scope_for_existing_table(conn, table_name)
            self._stamp_table_scope(conn, table_name, module_name, category, product_name)
            self._upsert_table_registry(conn, table_name, module_name, category, product_name)

    def _get_all_tables(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> list[dict]:
        """获取所有 ORT 数据表元信息，兼容旧表。"""
        try:
            with self._connect() as conn:
                self._ensure_registry_table(conn)
                self._backfill_registry_from_existing_tables(conn)
                cur = conn.execute("""
                    SELECT name FROM sqlite_master 
                    WHERE type='table' AND name LIKE ?
                """, (f"{self._TABLE_PREFIX}_%",))
                actual_names = {r[0] for r in cur.fetchall()}
                reg_rows = conn.execute(
                    f"SELECT table_name, module_name, category, product_name FROM {self._REGISTRY_TABLE}"
                ).fetchall()

                matched = []
                registered_names = set()
                wanted_module, wanted_category, wanted_product = self._normalize_scope_triplet(
                    module_name if module_name else None,
                    category if category else None,
                    product_name if product_name else None,
                )
                if not str(module_name or "").strip():
                    wanted_module = ""
                if not str(category or "").strip():
                    wanted_category = ""
                if not str(product_name or "").strip():
                    wanted_product = ""
                for table_name, mod, cat, prod in reg_rows:
                    if table_name not in actual_names:
                        continue
                    registered_names.add(table_name)
                    row_module, row_category, row_product = self._normalize_scope_triplet(mod, cat, prod)
                    if wanted_module and row_module != wanted_module:
                        continue
                    if wanted_category and row_category != wanted_category:
                        continue
                    if wanted_product and row_product != wanted_product:
                        continue
                    matched.append({
                        "table_name": table_name,
                        "module_name": row_module,
                        "category": row_category,
                        "product_name": row_product,
                        "legacy": False,
                    })

                if wanted_module or wanted_category or wanted_product:
                    return matched

                legacy_names = sorted(actual_names - registered_names)
                for table_name in legacy_names:
                    legacy_module, legacy_category, legacy_product = self._infer_scope_from_table_name(table_name)
                    matched.append({
                        "table_name": table_name,
                        "module_name": legacy_module,
                        "category": legacy_category,
                        "product_name": legacy_product,
                        "legacy": True,
                    })
                return matched
        except Exception:
            return []

    def save_long_dataframe(self, df: pd.DataFrame) -> int:
        """写入长表数据行；按 module/category/product 分组存储到不同表。返回实际写入行数。"""
        if df is None or df.empty:
            return 0
        
        # 确保必要的列存在
        cols_need = ("project", "model", "subpart", "recipe", "barcode", "test_time", "point_name", "value", "lsl")
        if any(c not in df.columns for c in cols_need):
            return 0
        
        # 确保可选列存在
        optional_cols = [
            "module_name", "category", "product_name", "component",
            "line", "result", "shift", "test_position", "material_category", "usl",
            "nominal", "tol_max", "tol_min", "dimension_description", "dimension_type",
            "distribution_type", "special_attrs",
        ]
        df = df.copy()
        for col in optional_cols:
            if col not in df.columns:
                df[col] = None
        
        def _scope_txt(cell, default_text: str) -> str:
            txt = str(cell).strip() if cell is not None and not (isinstance(cell, float) and pd.isna(cell)) else ""
            return txt or default_text

        # 按 module_name + category + product_name 分组
        df['_table_key'] = df.apply(
            lambda row: self._get_table_name(
                _scope_txt(row.get('module_name'), self._DEFAULT_MODULE),
                _scope_txt(row.get('category'), 'UNKNOWN'),
                _scope_txt(row.get('product_name'), 'UNKNOWN_PRODUCT')
            ), axis=1
        )
        
        def _txt(cell) -> str | None:
            if cell is None or (isinstance(cell, float) and pd.isna(cell)):
                return None
            return str(cell).strip()

        def _num(cell):
            if cell is None:
                return None
            x = pd.to_numeric(cell, errors="coerce")
            return float(x) if pd.notna(x) else None

        total_inserted = 0
        cols = (
            "module_name", "category", "product_name", "project", "model", "component",
            "subpart", "recipe", "barcode", "test_time", "point_name", "value",
            "usl", "lsl", "line", "result", "shift", "test_position", "material_category",
            "nominal", "tol_max", "tol_min", "dimension_description", "dimension_type",
            "distribution_type", "special_attrs",
        )
        
        try:
            with self._connect() as conn:
                self._ensure_registry_table(conn)
                for table_name, group_df in df.groupby('_table_key'):
                    # 确保表存在
                    self._ensure_table_exists(conn, table_name)
                    module_val = _scope_txt(group_df["module_name"].iloc[0] if "module_name" in group_df.columns else None, self._DEFAULT_MODULE)
                    category_val = _scope_txt(group_df["category"].iloc[0] if "category" in group_df.columns else None, "UNKNOWN")
                    product_val = _scope_txt(group_df["product_name"].iloc[0] if "product_name" in group_df.columns else None, "UNKNOWN_PRODUCT")
                    self._upsert_table_registry(conn, table_name, module_val, category_val, product_val)
                    
                    tuples = []
                    for _, rd in group_df[list(cols)].iterrows():
                        tuples.append(
                            (
                                _txt(rd["module_name"]),
                                _txt(rd["category"]),
                                _txt(rd["product_name"]),
                                _txt(rd["project"]),
                                _txt(rd["model"]),
                                _txt(rd["component"]),
                                _txt(rd["subpart"]),
                                _txt(rd["recipe"]),
                                _txt(rd["barcode"]) or "",
                                _txt(rd["test_time"]) or "",
                                _txt(rd["point_name"]) or "",
                                _num(rd["value"]),
                                _num(rd["usl"]),
                                _num(rd["lsl"]),
                                _txt(rd["line"]),
                                _txt(rd["result"]),
                                _txt(rd["shift"]),
                                _txt(rd["test_position"]),
                                _txt(rd["material_category"]),
                                _num(rd["nominal"]),
                                _num(rd["tol_max"]),
                                _num(rd["tol_min"]),
                                _txt(rd["dimension_description"]),
                                _txt(rd["dimension_type"]),
                                _txt(rd["distribution_type"]),
                                _txt(rd["special_attrs"]),
                            )
                        )
                    
                    if tuples:
                        sql = f"""
                            INSERT OR REPLACE INTO {table_name}
                            (module_name, category, product_name, project, model, component, subpart, recipe, barcode, test_time, point_name, value, usl, lsl, line, result, shift, test_position, material_category, nominal, tol_max, tol_min, dimension_description, dimension_type, distribution_type, special_attrs)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """
                        conn.executemany(sql, tuples)
                        total_inserted += len(tuples)
        except Exception as e:
            print(f"[DB Error] 保存数据失败: {e}")
            return 0
        
        return total_inserted

    def _ensure_cpk_dynamic_table_exists(self, conn: sqlite3.Connection, table_name: str, columns: list[str]) -> None:
        existing = self._table_columns(conn, table_name)
        is_wi = self._is_wi_storage_table(table_name)
        if not existing:
            col_defs = ["module_name TEXT", "category TEXT", "product_name TEXT"]
            for col in columns:
                if col in ("module_name", "category", "product_name"):
                    continue
                col_clean = re.sub(r"[^a-zA-Z0-9_]", "_", str(col))
                if col_clean and not col_clean[0].isalpha():
                    col_clean = "_" + col_clean
                col_defs.append(f"{col_clean} {self._wi_cpk_sql_type(col)}")
            if is_wi:
                col_defs.append("PRIMARY KEY (test_time, barcode, point_name)")
            else:
                key_field = "barcode" if "barcode" in columns else "machine_id"
                col_defs.append(f"PRIMARY KEY ({key_field}, point_name)")
            conn.execute(f"CREATE TABLE IF NOT EXISTS {table_name} ({', '.join(col_defs)})")
            conn.execute(f"CREATE INDEX IF NOT EXISTS idx_{table_name}_pt ON {table_name} (point_name)")
            conn.execute(f"CREATE INDEX IF NOT EXISTS idx_{table_name}_tt ON {table_name} (test_time)")
        else:
            if is_wi:
                self._migrate_wi_cpk_table_pk_if_needed(conn, table_name)
                existing = self._table_columns(conn, table_name)
                if "cpk" not in existing:
                    try:
                        conn.execute(f"ALTER TABLE {table_name} ADD COLUMN cpk REAL")
                    except Exception:
                        pass
            for col in columns:
                col_clean = re.sub(r"[^a-zA-Z0-9_]", "_", str(col))
                if col_clean and not col_clean[0].isalpha():
                    col_clean = "_" + col_clean
                if col_clean and col_clean not in existing and col not in ("module_name", "category", "product_name"):
                    try:
                        conn.execute(
                            f"ALTER TABLE {table_name} ADD COLUMN {col_clean} {self._wi_cpk_sql_type(col)}"
                        )
                    except Exception:
                        pass

    def save_cpk_dataframe(self, df: pd.DataFrame) -> int:
        if df is None or df.empty:
            print("[CPK Debug] DataFrame 为空")
            return 0
        key_field = "barcode" if "barcode" in df.columns else "machine_id"
        if key_field not in df.columns or "point_name" not in df.columns:
            print(f"[CPK Debug] 缺少必要列：{key_field}={(key_field in df.columns)}, point_name={('point_name' in df.columns)}")
            return 0
        if "test_time" not in df.columns:
            print("[CPK Debug] 缺少 test_time 列（检测日期），无法入库去重")
            return 0
        module_name = str(df["module_name"].iloc[0]).strip() if "module_name" in df.columns else "Weekly Inspection"
        category = str(df["category"].iloc[0]).strip() if "category" in df.columns else ""
        product_name = str(df["product_name"].iloc[0]).strip() if "product_name" in df.columns else "UNKNOWN_PRODUCT"
        table_name = self._get_table_name(module_name, category, product_name)
        print(f"[CPK Debug] 准备保存：module={module_name}, category={category}, product={product_name} → 表名={table_name}")
        print(f"[CPK Debug] DataFrame 列：{list(df.columns)[:10]}{'...' if len(df.columns) > 10 else ''}，共 {len(df)} 行")
        df = df.copy()
        if "test_time" in df.columns:
            df["test_time"] = df["test_time"].map(self._normalize_wi_test_time_value)
        key_field = "barcode" if "barcode" in df.columns else "machine_id"
        batch_times = sorted({str(t).strip() for t in df["test_time"].tolist() if str(t).strip()})
        row_dedupe = [c for c in ("barcode", "point_name") if c in df.columns]
        if len(row_dedupe) == 2:
            df = df.drop_duplicates(subset=row_dedupe, keep="last")
        if key_field in df.columns:
            df[key_field] = df[key_field].fillna("").astype(str).str.strip()
        if "point_name" in df.columns:
            df["point_name"] = df["point_name"].fillna("").astype(str).str.strip()
        df = df[(df[key_field] != "") & (df["point_name"] != "")]
        if "test_time" in df.columns:
            df = df[df["test_time"].astype(str).str.strip() != ""]
        if df.empty:
            print("[CPK Debug] 去重/过滤后无有效行")
            return 0
        col_map = {}
        for col in df.columns:
            col_clean = re.sub(r"[^a-zA-Z0-9_]", "_", str(col))
            if col_clean and not col_clean[0].isalpha():
                col_clean = "_" + col_clean
            col_map[col] = col_clean
        df.columns = [col_map[c] for c in df.columns]
        cols = list(df.columns)
        total_inserted = 0
        try:
            with self._connect() as conn:
                self._ensure_cpk_dynamic_table_exists(conn, table_name, cols)
                self._upsert_table_registry(conn, table_name, module_name, category, product_name)
                if self._is_wi_storage_table(table_name) and batch_times:
                    purged = self._purge_wi_batches_by_test_time(conn, table_name, batch_times)
                    print(
                        f"[CPK Debug] 整批覆盖：产品={product_name}，"
                        f"检测日期={batch_times}，已删除旧数据 {purged} 行"
                    )
                print(f"[CPK Debug] 表已创建/确认，列数={len(cols)}，准备写入 {len(df)} 行")
                placeholders = ", ".join(["?" for _ in cols])
                sql = f"INSERT OR REPLACE INTO {table_name} ({', '.join(cols)}) VALUES ({placeholders})"
                print(f"[CPK Debug] SQL: {sql[:200]}...")
                error_count = 0
                for idx, (_, row) in enumerate(df.iterrows()):
                    vals = []
                    for col in cols:
                        v = row[col]
                        if v is None or (isinstance(v, float) and pd.isna(v)):
                            vals.append(None)
                        else:
                            vals.append(str(v) if not isinstance(v, (int, float)) or pd.isna(v) else float(v))
                    try:
                        conn.execute(sql, vals)
                        total_inserted += 1
                        if idx < 3:
                            print(f"[CPK Debug] 第{idx+1}行写入成功")
                    except Exception as e:
                        error_count += 1
                        if idx < 5:
                            print(f"[CPK Debug] 第{idx+1}行写入失败：{e}")
                conn.commit()
                print(f"[CPK Debug] 写入完成：成功={total_inserted}, 失败={error_count}")
        except Exception as e:
            print(f"[DB Error] 保存 CPK 数据失败: {e}")
            return 0
        return total_inserted

    def query_violations_under_lsl(
        self,
        limit: int = 50000,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> pd.DataFrame:
        """Value < LSL 的历史记录（跨所有表查询）。"""
        lim = max(1, min(int(limit), 200000))
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        
        if not tables:
            return pd.DataFrame()
        
        # 构建 UNION ALL 查询
        union_parts = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name,
                       project, model, component, subpart, recipe, barcode, test_time, point_name, value, usl, lsl
                FROM {table}
                WHERE value IS NOT NULL AND lsl IS NOT NULL AND value < lsl
            """)
        
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time DESC
            LIMIT ?
        """
        
        try:
            with self._connect() as conn:
                return pd.read_sql_query(sql, conn, params=(lim,))
        except Exception:
            return pd.DataFrame()

    def query_ng_rows_for_recipe(
        self,
        recipe: str,
        start_date: str,
        end_date: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        subpart: str | None = None,
        limit: int = 8000,
    ) -> pd.DataFrame:
        """日期范围内指定配方下 Value<LSL 的明细（可选小件），按时间升序。"""
        if str(category or "").strip().lower() == "stand":
            return self._query_stand_ng_rows(
                start_date,
                end_date,
                module_name=module_name,
                category=category,
                product_name=product_name,
                recipe=recipe,
                subpart=subpart,
                limit=limit,
            )
        rcp = str(recipe or "").strip()
        if not rcp:
            return pd.DataFrame()
        lim = max(1, min(int(limit), 50000))
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return pd.DataFrame()
        sp = str(subpart or "").strip()
        sub_sql = ""
        if sp:
            sub_sql = " AND COALESCE(NULLIF(TRIM(subpart), ''), '未分类') = ? "
        union_parts = []
        params: list = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name,
                       project, model, component, subpart, recipe, barcode, test_time,
                       point_name, value, usl, lsl
                FROM {table}
                WHERE recipe = ?
                  AND test_time IS NOT NULL AND TRIM(test_time) != ''
                  AND date(test_time) BETWEEN date(?) AND date(?)
                  AND value IS NOT NULL AND lsl IS NOT NULL AND value < lsl
                  {sub_sql}
            """)
            params.extend([rcp, str(start_date).strip(), str(end_date).strip()])
            if sp:
                params.append(sp)
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time ASC, barcode, point_name
            LIMIT ?
        """
        params.append(lim)
        try:
            with self._connect() as conn:
                return pd.read_sql_query(sql, conn, params=tuple(params))
        except Exception:
            return pd.DataFrame()

    def query_ng_rows_in_date_range(
        self,
        start_date: str,
        end_date: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        limit: int = 80000,
    ) -> pd.DataFrame:
        """日期范围内当前 scope 下全部 Value<LSL 的明细（不按配方过滤），按时间升序。"""
        if str(category or "").strip().lower() == "stand":
            return self._query_stand_ng_rows(
                start_date,
                end_date,
                module_name=module_name,
                category=category,
                product_name=product_name,
                limit=limit,
            )
        lim = max(1, min(int(limit), 120000))
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return pd.DataFrame()
        union_parts = []
        params: list = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name,
                       project, model, component, subpart, recipe, barcode, test_time,
                       point_name, value, usl, lsl
                FROM {table}
                WHERE test_time IS NOT NULL AND TRIM(test_time) != ''
                  AND date(test_time) BETWEEN date(?) AND date(?)
                  AND value IS NOT NULL AND lsl IS NOT NULL AND value < lsl
            """)
            params.extend([str(start_date).strip(), str(end_date).strip()])
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time ASC, recipe, barcode, point_name
            LIMIT ?
        """
        params.append(lim)
        try:
            with self._connect() as conn:
                return pd.read_sql_query(sql, conn, params=tuple(params))
        except Exception:
            return pd.DataFrame()

    def query_alert_rows_in_date_range(
        self,
        start_date: str,
        end_date: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        limit: int = 80000,
    ) -> pd.DataFrame:
        """日期范围内当前 scope 下全部 Alert (lsl <= value < usl) 的明细。"""
        if str(category or "").strip().lower() == "stand":
            return pd.DataFrame()
        lim = max(1, min(int(limit), 120000))
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return pd.DataFrame()
        union_parts = []
        params: list = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name,
                       project, model, component, subpart, recipe, barcode, test_time,
                       point_name, value, usl, lsl
                FROM {table}
                WHERE test_time IS NOT NULL AND TRIM(test_time) != ''
                  AND date(test_time) BETWEEN date(?) AND date(?)
                  AND value IS NOT NULL AND lsl IS NOT NULL AND usl IS NOT NULL
                  AND (
                      (lsl < usl AND value >= lsl AND value < usl) OR
                      (usl <= lsl AND value >= usl AND value < lsl)
                  )
            """)
            params.extend([str(start_date).strip(), str(end_date).strip()])
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time ASC, recipe, barcode, point_name
            LIMIT ?
        """
        params.append(lim)
        try:
            with self._connect() as conn:
                return pd.read_sql_query(sql, conn, params=tuple(params))
        except Exception:
            return pd.DataFrame()

    def query_alert_rows_for_recipe(
        self,
        recipe: str,
        start_date: str,
        end_date: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        subpart: str | None = None,
        limit: int = 8000,
    ) -> pd.DataFrame:
        """日期范围内指定配方下 Alert 的明细。"""
        if str(category or "").strip().lower() == "stand":
            return pd.DataFrame()
        rcp = str(recipe or "").strip()
        if not rcp:
            return pd.DataFrame()
        lim = max(1, min(int(limit), 50000))
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return pd.DataFrame()
        sp = str(subpart or "").strip()
        sub_sql = ""
        if sp:
            sub_sql = " AND COALESCE(NULLIF(TRIM(subpart), ''), '未分类') = ? "
        union_parts = []
        params: list = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name,
                       project, model, component, subpart, recipe, barcode, test_time,
                       point_name, value, usl, lsl
                FROM {table}
                WHERE recipe = ?
                  AND test_time IS NOT NULL AND TRIM(test_time) != ''
                  AND date(test_time) BETWEEN date(?) AND date(?)
                  AND value IS NOT NULL AND lsl IS NOT NULL AND usl IS NOT NULL
                  AND (
                      (lsl < usl AND value >= lsl AND value < usl) OR
                      (usl <= lsl AND value >= usl AND value < lsl)
                  )
                  {sub_sql}
            """)
            params.extend([rcp, str(start_date).strip(), str(end_date).strip()])
            if sp:
                params.append(sp)
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time ASC, barcode, point_name
            LIMIT ?
        """
        params.append(lim)
        try:
            with self._connect() as conn:
                return pd.read_sql_query(sql, conn, params=tuple(params))
        except Exception:
            return pd.DataFrame()

    def list_distinct_recipes(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> list[str]:
        """获取所有配方（跨所有表查询）"""
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return []
        
        union_parts = [
            f"SELECT DISTINCT recipe FROM {t['table_name']} WHERE recipe IS NOT NULL AND trim(recipe) != ''"
            for t in tables
        ]
        sql = f"SELECT DISTINCT recipe FROM ({' UNION ALL '.join(union_parts)}) ORDER BY recipe COLLATE NOCASE"
        
        try:
            with self._connect() as conn:
                cur = conn.execute(sql)
                return [r[0] for r in cur.fetchall()]
        except Exception:
            return []

    def list_distinct_points(
        self,
        recipe: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> list[str]:
        """获取指定配方的所有测点（跨所有表查询）"""
        if not recipe or not str(recipe).strip():
            return []
        
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return []
        
        union_parts = [f"SELECT DISTINCT point_name FROM {t['table_name']} WHERE recipe = ?" for t in tables]
        sql = f"""
            SELECT DISTINCT point_name FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY point_name COLLATE NOCASE
        """
        
        try:
            with self._connect() as conn:
                cur = conn.execute(sql, (str(recipe).strip(),) * len(tables))
                return [r[0] for r in cur.fetchall()]
        except Exception:
            return []

    def fetch_recipe_point_series(
        self,
        recipe: str,
        point_name: str,
        limit_points: int = 50000,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> pd.DataFrame:
        """按检测时间排序的跨批次趋势数据（跨所有表查询）。"""
        lim = max(1, min(int(limit_points), 200000))
        if not recipe or not point_name:
            return pd.DataFrame()
        if str(category or "").strip().lower() == "stand":
            specs = _load_stand_yield_specs()
            lims = specs.get(str(point_name).strip())
            if not lims:
                return pd.DataFrame()
            tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
            if not tables:
                return pd.DataFrame()
            union_parts = []
            params: list = []
            for table_meta in tables:
                table = table_meta["table_name"]
                mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
                cat_lit = self._sql_text_literal(table_meta.get("category", ""))
                prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
                recipe_expr = f"COALESCE(NULLIF(TRIM(model), ''), COALESCE(NULLIF(TRIM(recipe), ''), {prod_lit}))"
                union_parts.append(
                    f"SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name, "
                    f"barcode, test_time, value, ? AS usl, ? AS lsl "
                    f"FROM {table} WHERE {recipe_expr} = ? AND point_name = ?"
                )
                params.extend([
                    float(lims["usl"]),
                    float(lims["lsl"]),
                    str(recipe).strip(),
                    str(point_name).strip(),
                ])
            sql = f"""
                SELECT * FROM (
                    {' UNION ALL '.join(union_parts)}
                )
                ORDER BY test_time ASC
                LIMIT ?
            """
            params.append(lim)
            try:
                with self._connect() as conn:
                    df = pd.read_sql_query(sql, conn, params=tuple(params))
                if df.empty:
                    return df
                df["dt"] = pd.to_datetime(df["test_time"], errors="coerce")
                return df.sort_values("dt", kind="stable", na_position="last").reset_index(drop=True)
            except Exception:
                return pd.DataFrame()
        
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return pd.DataFrame()
        
        union_parts = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(
                f"SELECT {mod_lit} AS module_name, {cat_lit} AS category, {prod_lit} AS product_name, "
                f"barcode, test_time, value, usl, lsl "
                f"FROM {table} WHERE recipe = ? AND point_name = ? AND value IS NOT NULL"
            )
        sql = f"""
            SELECT * FROM (
                {' UNION ALL '.join(union_parts)}
            )
            ORDER BY test_time ASC
            LIMIT ?
        """
        
        try:
            with self._connect() as conn:
                df = pd.read_sql_query(sql, conn, params=(str(recipe).strip(), str(point_name).strip()) * len(tables) + (lim,))
            if df.empty:
                return df
            df["dt"] = pd.to_datetime(df["test_time"], errors="coerce")
            return df.sort_values("dt", kind="stable", na_position="last").reset_index(drop=True)
        except Exception:
            return pd.DataFrame()

    def list_registered_scopes(
        self,
        module_name: str | None = None,
        category: str | None = None,
    ) -> list[tuple[str, str, str]]:
        """返回数据库中可用的 (module, category, product) 组合。"""
        rows: list[tuple[str, str, str]] = []
        seen: set[tuple[str, str, str]] = set()
        for meta in self._get_all_tables(module_name=module_name, category=category):
            triple = (
                str(meta.get("module_name") or self._DEFAULT_MODULE).strip() or self._DEFAULT_MODULE,
                str(meta.get("category") or "").strip(),
                str(meta.get("product_name") or "").strip(),
            )
            if triple in seen:
                continue
            seen.add(triple)
            rows.append(triple)
        return rows

    def list_wi_product_names(self) -> list[str]:
        """Weekly Inspection 已入库二级产品列表（category）。"""
        names: list[str] = []
        seen: set[str] = set()
        for _mod, cat, _proc in self.list_registered_scopes(module_name="Weekly Inspection"):
            p = str(cat or "").strip()
            if p and p not in ("_templates_", "UNKNOWN") and p not in seen:
                seen.add(p)
                names.append(p)
        return sorted(names, key=lambda x: x.lower())

    def list_wi_process_names(self, wi_product: str) -> list[str]:
        """指定 WI 产品下已入库制程列表。"""
        wi_product = str(wi_product or "").strip()
        names: list[str] = []
        seen: set[str] = set()
        for _mod, cat, proc in self.list_registered_scopes(module_name="Weekly Inspection"):
            if wi_product and str(cat or "").strip() != wi_product:
                continue
            p = str(proc or "").strip()
            if p and p not in seen:
                seen.add(p)
                names.append(p)
        return sorted(names, key=lambda x: x.lower())

    def query_wi_cpk_detail_rows(
        self,
        wi_product: str,
        process_name: str,
        start_date: str,
        end_date: str,
        batch_dates: list[str] | None = None,
    ) -> pd.DataFrame:
        """查询 WI 明细行（含 Cp/Cpku/Cpk 核心参数），供尺寸组聚合。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name:
            return pd.DataFrame()
        if not wi_product:
            wi_product = self._infer_wi_category_from_process(process_name)
        table_name = self._get_table_name("Weekly Inspection", wi_product, process_name)
        if not self._is_wi_storage_table(table_name):
            return pd.DataFrame()
        tt_expr = self._wi_normalized_test_time_sql("test_time")
        metric_cols = ("cp", "cpku", "cpk", "projected_yield")
        date_filters: list[str] = []
        date_params: list[str] = []
        for raw in batch_dates or []:
            s = str(raw or "").strip()[:10]
            if re.match(r"^\d{4}-\d{2}-\d{2}$", s) and s not in date_filters:
                date_filters.append(s)
        if date_filters:
            placeholders = ", ".join("?" for _ in date_filters)
            where_date = f"{tt_expr} IN ({placeholders})"
            date_params = list(date_filters)
        else:
            where_date = f"{tt_expr} BETWEEN date(?) AND date(?)"
            date_params = [str(start_date).strip(), str(end_date).strip()]
        try:
            with self._connect() as conn:
                cols = self._table_columns(conn, table_name)
                if "cpk" not in cols:
                    return pd.DataFrame()
                present_metrics = [m for m in metric_cols if m in cols]
                metric_sel = ", ".join(present_metrics)
                if not metric_sel:
                    return pd.DataFrame()
                spec_cols = []
                for sc in ("nominal", "tol_max", "tol_min", "distribution_type", "source_col"):
                    if sc in cols:
                        spec_cols.append(sc)
                spec_sel = ", ".join(spec_cols) if spec_cols else ""
                spec_sql = f", {spec_sel}" if spec_sel else ""
                cur = conn.execute(
                    f"""
                    SELECT
                        {tt_expr} AS test_time,
                        COALESCE(NULLIF(TRIM(component), ''), '') AS dim_no,
                        COALESCE(NULLIF(TRIM(dimension_description), ''), '') AS dimension_description,
                        COALESCE(NULLIF(TRIM(dimension_type), ''), '') AS dimension_type,
                        COALESCE(NULLIF(TRIM(point_name), ''), '') AS point_name,
                        COALESCE(NULLIF(TRIM(subpart), ''), '') AS point_number
                        {spec_sql},
                        {metric_sel}
                    FROM "{table_name}"
                    WHERE {where_date}
                      AND cpk IS NOT NULL
                    """,
                    tuple(date_params),
                )
                rows = cur.fetchall()
        except Exception as ex:
            print(f"[WI CPK] 查询失败：{ex}")
            return pd.DataFrame()
        if not rows:
            return pd.DataFrame()
        out_cols = [
            "test_time",
            "dim_no",
            "dimension_description",
            "dimension_type",
            "point_name",
            "point_number",
        ] + spec_cols + present_metrics
        df = pd.DataFrame(rows, columns=out_cols)
        for m in present_metrics:
            df[m] = pd.to_numeric(df[m], errors="coerce")
        return df.dropna(subset=["cpk"])

    def query_wi_report_measurement_rows(
        self,
        wi_product: str,
        process_name: str,
        batch_dates: list[str] | None = None,
    ) -> pd.DataFrame:
        """查询 WI 原始测量值（按样本×测点），供数据报告导出。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name:
            return pd.DataFrame()
        if not wi_product:
            wi_product = self._infer_wi_category_from_process(process_name)
        table_name = self._get_table_name("Weekly Inspection", wi_product, process_name)
        if not self._is_wi_storage_table(table_name):
            return pd.DataFrame()
        tt_expr = self._wi_normalized_test_time_sql("test_time")
        date_filters: list[str] = []
        for raw in batch_dates or []:
            s = str(raw or "").strip()[:10]
            if re.match(r"^\d{4}-\d{2}-\d{2}$", s) and s not in date_filters:
                date_filters.append(s)
        if not date_filters:
            return pd.DataFrame()
        placeholders = ", ".join("?" for _ in date_filters)
        try:
            with self._connect() as conn:
                cols = self._table_columns(conn, table_name)
                extra_cols = [
                    c for c in ("special_attrs", "line", "shift", "test_position", "material_category")
                    if c in cols
                ]
                extra_sql = ", ".join(extra_cols)
                extra_sel = f", {extra_sql}" if extra_sql else ""
                cur = conn.execute(
                    f"""
                    SELECT
                        {tt_expr} AS test_time,
                        COALESCE(NULLIF(TRIM(barcode), ''), '') AS barcode,
                        COALESCE(NULLIF(TRIM(point_name), ''), '') AS point_name,
                        value
                        {extra_sel}
                    FROM "{table_name}"
                    WHERE {tt_expr} IN ({placeholders})
                      AND value IS NOT NULL
                    ORDER BY {tt_expr}, barcode, point_name
                    """,
                    tuple(date_filters),
                )
                rows = cur.fetchall()
        except Exception as ex:
            print(f"[WI Report] 查询失败：{ex}")
            return pd.DataFrame()
        if not rows:
            return pd.DataFrame()
        out_cols = ["test_time", "barcode", "point_name", "value"] + extra_cols
        df = pd.DataFrame(rows, columns=out_cols)
        df["value"] = pd.to_numeric(df["value"], errors="coerce")
        return df.dropna(subset=["value"])

    def wi_table_storage_status(self, wi_product: str, process_name: str) -> dict:
        """Weekly Inspection 单表存储状态（行数、是否有 cpk 列、已填 cpk 行数）。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        out = {"exists": False, "table_name": "", "row_count": 0, "has_cpk_column": False, "cpk_row_count": 0}
        if not process_name:
            return out
        if not wi_product:
            wi_product = self._infer_wi_category_from_process(process_name)
        table_name = self._get_table_name("Weekly Inspection", wi_product, process_name)
        out["table_name"] = table_name
        if not self._is_wi_storage_table(table_name):
            return out
        try:
            with self._connect() as conn:
                cur = conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1",
                    (table_name,),
                )
                if not cur.fetchone():
                    return out
                out["exists"] = True
                out["row_count"] = int(
                    conn.execute(f'SELECT COUNT(*) FROM "{table_name}"').fetchone()[0] or 0
                )
                cols = self._table_columns(conn, table_name)
                out["has_cpk_column"] = "cpk" in cols
                if out["has_cpk_column"]:
                    out["cpk_row_count"] = int(
                        conn.execute(
                            f'SELECT COUNT(*) FROM "{table_name}" WHERE cpk IS NOT NULL'
                        ).fetchone()[0]
                        or 0
                    )
        except Exception as ex:
            print(f"[WI CPK] 表状态检查失败：{ex}")
        return out

    def backfill_wi_cpk_values(
        self,
        wi_product: str,
        process_name: str,
        point_cpk_rows: list[dict],
    ) -> int:
        """按测点补写 cpk（同列多样本共享同一 Cpk 值）。返回 UPDATE 影响行数合计。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name or not point_cpk_rows:
            return 0
        if not wi_product:
            wi_product = self._infer_wi_category_from_process(process_name)
        table_name = self._get_table_name("Weekly Inspection", wi_product, process_name)
        if not self._is_wi_storage_table(table_name):
            return 0
        total = 0
        try:
            with self._connect() as conn:
                cols = self._table_columns(conn, table_name)
                if "cpk" not in cols:
                    conn.execute(f"ALTER TABLE {table_name} ADD COLUMN cpk REAL")
                for item in point_cpk_rows:
                    cpk_v = pd.to_numeric(item.get("cpk"), errors="coerce")
                    if pd.isna(cpk_v):
                        continue
                    pn = str(item.get("point_name") or "").strip()
                    dim_no = str(item.get("dim_no") or "").strip()
                    if not pn:
                        continue
                    dim_desc = str(item.get("dimension_description") or "").strip()
                    dim_type = str(item.get("dimension_type") or "").strip()
                    cur = conn.execute(
                        f"""
                        UPDATE "{table_name}"
                           SET cpk = ?,
                               dimension_description = COALESCE(NULLIF(TRIM(dimension_description), ''), ?),
                               dimension_type = COALESCE(NULLIF(TRIM(dimension_type), ''), ?)
                         WHERE TRIM(point_name) = ?
                           AND TRIM(COALESCE(component, '')) = ?
                        """,
                        (float(cpk_v), dim_desc or None, dim_type or None, pn, dim_no),
                    )
                    total += int(cur.rowcount or 0)
                conn.commit()
        except Exception as ex:
            print(f"[WI CPK] 补写 cpk 失败：{ex}")
            return 0
        return total

    def list_distinct_long_values(
        self,
        field_name: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        filters: dict | None = None,
        limit: int = 5000,
    ) -> list[str]:
        """从长表中读取某个字段的去重值。"""
        field_map = {
            "project": "project",
            "machine_type": "model",
            "model": "model",
            "component": "component",
            "subpart": "subpart",
            "recipe": "recipe",
            "line": "line",
            "result": "result",
            "shift": "shift",
            "test_position": "test_position",
            "material_category": "material_category",
            "point_name": "point_name",
        }
        field = field_map.get(str(field_name or "").strip())
        if not field:
            return []
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return []
        lim = max(1, min(int(limit), 20000))
        filters = filters if isinstance(filters, dict) else {}
        union_parts: list[str] = []
        params: list = []
        for table_meta in tables:
            table = table_meta["table_name"]
            where_parts = [
                f"{field} IS NOT NULL",
                f"TRIM(COALESCE({field}, '')) != ''",
            ]
            local_params: list = []
            for flt_key, flt_vals in filters.items():
                db_col = field_map.get(str(flt_key or "").strip())
                vals = [str(v).strip() for v in (flt_vals or []) if str(v).strip()]
                if not db_col or not vals:
                    continue
                placeholders = ", ".join(["?"] * len(vals))
                where_parts.append(f"COALESCE(NULLIF(TRIM({db_col}), ''), '') IN ({placeholders})")
                local_params.extend(vals)
            union_parts.append(
                f"SELECT DISTINCT {field} AS value_text FROM {table} WHERE " + " AND ".join(where_parts)
            )
            params.extend(local_params)
        sql = f"""
            SELECT DISTINCT value_text
              FROM (
                {' UNION ALL '.join(union_parts)}
              )
             WHERE value_text IS NOT NULL AND TRIM(COALESCE(value_text, '')) != ''
             ORDER BY value_text COLLATE NOCASE
             LIMIT ?
        """
        params.append(lim)
        try:
            with self._connect() as conn:
                cur = conn.execute(sql, tuple(params))
                return [str(r[0]).strip() for r in cur.fetchall() if r and str(r[0]).strip()]
        except Exception:
            return []

