    def query_yield_data(
        self,
        start_date: str,
        end_date: str,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> list:
        """查询良率数据（跨所有表查询，一票否决制）"""
        tables = self._get_all_tables(module_name=module_name, category=category, product_name=product_name)
        if not tables:
            return []
        if str(category or "").strip().lower() == "stand":
            return self._query_stand_yield_data(start_date, end_date, tables)
        
        # 构建跨表查询
        union_parts = []
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT 
                    {mod_lit} AS module_name,
                    {cat_lit} AS category,
                    {prod_lit} AS product_name,
                    COALESCE(subpart, '未分类') as subpart,
                    recipe,
                    barcode,
                    CASE
                        WHEN SUM(CASE WHEN value IS NOT NULL AND lsl IS NOT NULL AND value < lsl THEN 1 ELSE 0 END) > 0 THEN 0
                        WHEN SUM(CASE
                            WHEN value IS NOT NULL AND lsl IS NOT NULL AND usl IS NOT NULL AND (
                                (lsl < usl AND value >= lsl AND value < usl) OR
                                (usl <= lsl AND value >= usl AND value < lsl)
                            ) THEN 1 ELSE 0 END) > 0 THEN 2
                        ELSE 1
                    END as sample_status
                FROM {table}
                WHERE date(test_time) BETWEEN ? AND ?
                  AND recipe IS NOT NULL AND trim(recipe) != ''
                  AND barcode IS NOT NULL AND trim(barcode) != ''
                GROUP BY subpart, recipe, barcode
            """)
        
        sql = f"""
            SELECT 
                module_name,
                category,
                product_name,
                subpart, 
                recipe, 
                COUNT(*) as Total_Count,
                SUM(CASE WHEN sample_status = 0 THEN 1 ELSE 0 END) as NG_Count,
                SUM(CASE WHEN sample_status = 2 THEN 1 ELSE 0 END) as Alert_Count,
                ROUND(CAST(SUM(CASE WHEN sample_status != 0 THEN 1 ELSE 0 END) AS FLOAT) / COUNT(*) * 100, 2) as Yield_Rate
            FROM (
                {' UNION ALL '.join(union_parts)}
            )
            GROUP BY module_name, category, product_name, subpart, recipe
            ORDER BY module_name, category, product_name, subpart, Yield_Rate ASC
        """
        
        try:
            with self._connect() as conn:
                cursor = conn.execute(sql, (start_date, end_date) * len(tables))
                results = cursor.fetchall()
                
                yield_data = []
                for row in results:
                    yield_data.append({
                        'module_name': row[0],
                        'category': row[1],
                        'product_name': row[2],
                        'subpart': row[3],
                        'recipe': row[4],
                        'total': row[5],
                        'ng_count': row[6],
                        'alert_count': row[7],
                        'yield_rate': row[8]
                    })
                return yield_data
        except Exception as e:
            print(f"[DB Error] 查询良率数据失败: {e}")
            return []

    def _query_stand_yield_data(self, start_date: str, end_date: str, tables: list[dict]) -> list:
        """Stand 良率：Serial no. 去重（取最新时间），Spring Rate / Global Average 分别统计。"""
        specs = _load_stand_yield_specs()
        core_names = list(specs.keys())
        if not core_names or not tables:
            return []

        union_parts = []
        params: list = []
        point_placeholders = ", ".join(["?"] * len(core_names))
        for table_meta in tables:
            table = table_meta["table_name"]
            mod_lit = self._sql_text_literal(table_meta.get("module_name", self._DEFAULT_MODULE))
            cat_lit = self._sql_text_literal(table_meta.get("category", ""))
            prod_lit = self._sql_text_literal(table_meta.get("product_name", ""))
            union_parts.append(f"""
                SELECT
                    {mod_lit} AS module_name,
                    {cat_lit} AS category,
                    {prod_lit} AS product_name,
                    barcode,
                    test_time,
                    point_name,
                    value
                FROM {table}
                WHERE test_time IS NOT NULL AND TRIM(test_time) != ''
                  AND date(test_time) BETWEEN date(?) AND date(?)
                  AND point_name IN ({point_placeholders})
                  AND barcode IS NOT NULL AND TRIM(barcode) != ''
            """)
            params.extend([str(start_date).strip(), str(end_date).strip(), *core_names])

        sql = f"""
            SELECT module_name, category, product_name, barcode, test_time, point_name, value
            FROM (
                {' UNION ALL '.join(union_parts)}
            )
        """
        try:
            with self._connect() as conn:
                raw_df = pd.read_sql_query(sql, conn, params=tuple(params))
            if raw_df.empty:
                return []
            first = tables[0]
            return _build_stand_yield_stats_from_long_df(
                raw_df,
                module_name=str(first.get("module_name", self._DEFAULT_MODULE)),
                category=str(first.get("category", "")),
                product_name=str(first.get("product_name", "")),
                specs=specs,
            )
        except Exception as ex:
            print(f"[DB Error] 查询 Stand 良率失败: {ex}")
            return []

