# JmpPathDialog — JMP 路径配置对话框
# ═══════════════════════════════════════════════════════════════════
class JmpPathDialog(QDialog):
    """首次使用或手动重设时弹出，让用户指定 jmp.exe 路径。"""

    def __init__(self, parent=None, current_path: str = ""):
        super().__init__(parent)
        self.selected_path = current_path or _load_jmp_path()
        self.setWindowTitle("JMP 路径配置")
        self.setMinimumWidth(600)
        self.setStyleSheet(_JMP_BASE_STYLE)
        self._build_ui()

    def _build_ui(self):
        lay = QVBoxLayout(self)
        lay.setContentsMargins(24, 20, 24, 20)
        lay.setSpacing(14)

        title_lbl = QLabel("配置 JMP 可执行程序路径")
        title_lbl.setStyleSheet("font-size: 18px; font-weight: 900; color: #2C3E50;")
        lay.addWidget(title_lbl)

        hint = QLabel(
            "请指定 JMP 的安装路径（jmp.exe）。\n"
            "常见路径：C:\\Program Files\\SAS\\JMP\\17\\jmp.exe"
        )
        hint.setStyleSheet("font-size: 12px; color: #5A7A99;")
        hint.setWordWrap(True)
        lay.addWidget(hint)

        path_row = QHBoxLayout()
        self.edit_path = QLineEdit(self.selected_path)
        self.edit_path.setPlaceholderText("请选择 jmp.exe ...")
        path_row.addWidget(self.edit_path, 1)

        btn_browse = QPushButton("浏览…")
        btn_browse.setStyleSheet(_JMP_BTN_SECONDARY)
        btn_browse.setCursor(QCursor(Qt.PointingHandCursor))
        btn_browse.setFixedHeight(40)
        btn_browse.clicked.connect(self._browse)
        path_row.addWidget(btn_browse)
        lay.addLayout(path_row)

        self.lbl_status = QLabel("")
        self.lbl_status.setStyleSheet("font-size: 12px; color: #10B981;")
        lay.addWidget(self.lbl_status)
        self._validate_path(self.selected_path)

        self.chk_save = QCheckBox("记住此路径（下次自动使用）")
        self.chk_save.setChecked(True)
        lay.addWidget(self.chk_save)

        lay.addStretch(1)

        btn_row = QHBoxLayout()
        btn_row.addStretch(1)
        btn_cancel = QPushButton("取消")
        btn_cancel.setStyleSheet(_JMP_BTN_SECONDARY)
        btn_cancel.setCursor(QCursor(Qt.PointingHandCursor))
        btn_cancel.clicked.connect(self.reject)
        btn_row.addWidget(btn_cancel)

        btn_ok = QPushButton("确定")
        btn_ok.setStyleSheet(_JMP_BTN_PRIMARY)
        btn_ok.setCursor(QCursor(Qt.PointingHandCursor))
        btn_ok.clicked.connect(self._accept)
        btn_row.addWidget(btn_ok)
        lay.addLayout(btn_row)

        self.edit_path.textChanged.connect(self._validate_path)

    def _browse(self):
        path, _ = QFileDialog.getOpenFileName(
            self, "选择 JMP 可执行文件", "",
            "可执行文件 (*.exe);;所有文件 (*)"
        )
        if path:
            self.edit_path.setText(path)

    def _validate_path(self, path: str = ""):
        path = path or self.edit_path.text()
        if not path:
            self.lbl_status.setText("")
            return
        if os.path.isfile(path):
            self.lbl_status.setStyleSheet("font-size: 12px; color: #10B981;")
            self.lbl_status.setText(f"✓ 文件存在：{path}")
        else:
            self.lbl_status.setStyleSheet("font-size: 12px; color: #EF4444;")
            self.lbl_status.setText("✗ 文件不存在，请重新选择")

    def _accept(self):
        path = self.edit_path.text().strip()
        if not path:
            QMessageBox.warning(self, "提示", "请先选择 JMP 可执行文件路径。")
            return
        if not os.path.isfile(path):
            reply = QMessageBox.question(
                self, "路径无效",
                f"所选路径不存在：\n{path}\n\n是否仍然保存并继续？",
                QMessageBox.Yes | QMessageBox.No
            )
            if reply != QMessageBox.Yes:
                return
        self.selected_path = path
        if self.chk_save.isChecked():
            _save_jmp_path(path)
        self.accept()


