# JmpBoxplotDialog — 箱线图参数配置对话框
# ═══════════════════════════════════════════════════════════════════
class JmpBoxplotDialog(QDialog):
    """配置 Graph Builder 风格的 JMP 箱线图。"""

    def __init__(self, parent, frames: list, core_cols: dict, point_cols: list):
        super().__init__(parent)
        self.frames = frames
        self.core_cols = core_cols
        self.point_cols = point_cols
        self.config = {}

        self._group_options = self._build_group_options()
        self._recipe_entries = []
        for sheet_title, df_r in self.frames:
            recipe_name = _jmp_frame_recipe_name(sheet_title, df_r)
            active_points = []
            families: dict[str, list[str]] = {}
            for point_name, val_col, spec_col in self.point_cols:
                col_candidates = [str(point_name), f"{point_name}_值", val_col]
                for cand in col_candidates:
                    if cand and cand in df_r.columns:
                        has_val = pd.to_numeric(df_r[cand], errors="coerce").notna().any()
                        if has_val:
                            active_points.append((point_name, val_col, spec_col))
                            families.setdefault(_jmp_point_family(point_name), []).append(str(point_name))
                            break
            self._recipe_entries.append({
                "sheet_title": str(sheet_title),
                "recipe_name": recipe_name,
                "points": active_points,
                "families": families,
            })

        self.setWindowTitle("JMP 箱线图 — 参数配置")
        self.setMinimumSize(860, 700)
        self.resize(980, 760)
        self.setStyleSheet(_JMP_BASE_STYLE)
        self._build_ui()
        self._refresh_family_preview()

