        outer = QVBoxLayout(self)
        outer.setContentsMargins(24, 20, 24, 20)
        outer.setSpacing(14)

        title_lbl = QLabel("配置数据库连接")
        title_lbl.setStyleSheet("font-size: 18px; font-weight: 900; color: #2C3E50;")
        outer.addWidget(title_lbl)

        hint = QLabel(
            "将按你选择的配方生成 JMP Graph Builder 箱线图。\n"
            "每个配方会按点位族（如 AC、USB）分别出图，X 轴固定为点位标签（如 AC1~AC6）。"
        )
        hint.setStyleSheet("font-size: 12px; color: #5A7A99;")
        hint.setWordWrap(True)
