# ---------- 3-0  LevelSelector ----------
class LevelSelector(QWidget):
    """自定义分段选择器，用于 L1/L2/L3 重要度设置。"""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.lay = QHBoxLayout(self)
        self.lay.setContentsMargins(0, 0, 0, 0)
        self.lay.setSpacing(1)
        
        self.group = QButtonGroup(self)
        self.btn_l1 = self._create_btn("L1", "#FF4D4F") # 红
        self.btn_l2 = self._create_btn("L2", "#FAAD14") # 黄/橙
        self.btn_l3 = self._create_btn("L3", "#52C41A") # 绿
        
        self.lay.addWidget(self.btn_l1)
        self.lay.addWidget(self.btn_l2)
        self.lay.addWidget(self.btn_l3)
        
        self.group.addButton(self.btn_l1)
        self.group.addButton(self.btn_l2)
        self.group.addButton(self.btn_l3)
        
    def _create_btn(self, text, color):
        btn = QPushButton(text)
        btn.setCheckable(True)
        # 重要：此处按钮总宽度必须小于外层 selector 的固定宽度，否则会溢出遮挡左侧“规则说明”
        btn.setFixedWidth(26)
        btn.setFixedHeight(22)
        btn.setCursor(QCursor(Qt.PointingHandCursor))
        btn.setAutoExclusive(True)
        # 初始样式（未选中）；这里必须直接注入 color，不能把占位符留在 QSS 里
        btn.setStyleSheet(f"""
            QPushButton {{
                background-color: #F0F7FF;
                color: #6B8299;
                border: 1px solid #B8D4E8;
                border-radius: 5px;
                font-size: 10px;
                font-weight: 800;
            }}
            QPushButton:hover {{
                border-color: #98B8D8;
            }}
            QPushButton:checked {{
                background-color: {color};
                color: white;
                border: 1px solid #98B8D8;
            }}
        """)
        return btn

    def currentText(self):
        checked = self.group.checkedButton()
        return checked.text() if checked else "L3"

    def setCurrentLevel(self, level):
        if level == "L1": self.btn_l1.setChecked(True)
        elif level == "L2": self.btn_l2.setChecked(True)
        else: self.btn_l3.setChecked(True)

# ---------- 3-1  PandasModel ----------
class PandasModel(QAbstractTableModel):
    """Adapt pandas DataFrame to QTableView."""

    def __init__(self, data, highlights=None, cell_foregrounds=None,
                 row_foregrounds=None, cell_backgrounds=None):
        super().__init__()
        self._data = data
        self.highlights = highlights or {}
        self.cell_foregrounds = cell_foregrounds or {}
        self.row_foregrounds = row_foregrounds or {}
        self.cell_backgrounds = cell_backgrounds or {}

    def rowCount(self, parent=None):
        return self._data.shape[0]

    def columnCount(self, parent=None):
        return self._data.shape[1]

    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid():
            return None
        row, col = index.row(), index.column()

        if role == Qt.DisplayRole:
            val = self._data.iloc[row, col]
            return "" if pd.isna(val) else str(val)
        elif role == Qt.TextAlignmentRole:
            return Qt.AlignCenter
        elif role == Qt.BackgroundRole:
            key = (row, col)
            if key in self.cell_backgrounds:
                return QColor(self.cell_backgrounds[key])
            if row in self.highlights:
                return QColor(self.highlights[row])
            return None
        elif role == Qt.ForegroundRole:
            key = (row, col)
            if key in self.cell_foregrounds:
                return QColor(self.cell_foregrounds[key])
            if row in self.row_foregrounds:
                return QColor(self.row_foregrounds[row])
            return None
        elif role == Qt.FontRole:
            if row in self.highlights:
                font = QFont()
                font.setBold(True)
                return font
        return None

    def headerData(self, section, orientation, role):
        if role == Qt.DisplayRole:
            if orientation == Qt.Horizontal:
                cols = getattr(self._data, "columns", None)
                if cols is not None and 0 <= section < len(cols):
                    return str(cols[section])
                return str(section)
            return str(section)
        return None


class ClickableFrame(QFrame):
    clicked = pyqtSignal()

    def mousePressEvent(self, event):
        if event and event.button() == Qt.LeftButton:
            self.clicked.emit()
        return super().mousePressEvent(event)


class NiceProgressDialog(QDialog):
    """简单但好看的进度弹窗（用于耗时作图）。"""

    def __init__(self, title: str, message: str, maximum: int, parent=None):
        super().__init__(parent)
        self._canceled = False
        self.setWindowTitle(title or "进度")
        self.setWindowModality(Qt.WindowModal)
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.Dialog)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setMinimumWidth(460)
        self.setFixedHeight(160)

        # 顶层布局：为了给阴影留出空间，需要有一定的 margins
        top_lay = QVBoxLayout(self)
        top_lay.setContentsMargins(10, 10, 10, 10)

        # 核心容器：用于实现背景色和圆角
        self.main_frame = QFrame()
        self.main_frame.setObjectName("main_frame")
        top_lay.addWidget(self.main_frame)

        self.main_frame.setStyleSheet("""
            QFrame#main_frame {
                background-color: #FFFFFF;
                border: 1px solid #C5D9E8;
                border-radius: 15px;
            }
            QLabel#np_msg {
                font-size: 13px;
                color: #5A7A99;
            }
            QProgressBar {
                border: 1px solid #B8D4E8;
                border-radius: 9px;
                background: #F5F9FF;
                height: 18px;
                text-align: center;
                color: #3A5A7A;
                font-size: 11px;
            }
            QProgressBar::chunk {
                border-radius: 9px;
                background: qlineargradient(
                    x1:0, y1:0, x2:1, y2:0,
                    stop:0 #5B9BD5,
                    stop:1 #7BB5E5
                );
            }
            QPushButton#np_cancel {
                background-color: #B8D4E8;
                color: #3A5A7A;
                border: none;
                border-radius: 8px;
                padding: 8px 14px;
                font-size: 12px;
                font-weight: 700;
            }
            QPushButton#np_cancel:hover { background-color: #A8C8E0; }
        """)

        # 容器内部布局
        inner = QVBoxLayout(self.main_frame)
        inner.setContentsMargins(20, 22, 20, 18)
        inner.setSpacing(12)

        msg_lbl = QLabel(message or "")
        msg_lbl.setObjectName("np_msg")
        msg_lbl.setWordWrap(True)
        inner.addWidget(msg_lbl)

        self.bar = QProgressBar()
        self.bar.setRange(0, max(1, int(maximum)))
        self.bar.setValue(0)
        inner.addWidget(self.bar)

        row = QHBoxLayout()
        row.addStretch(1)
        btn = QPushButton("取消")
        btn.setObjectName("np_cancel")
        btn.setCursor(QCursor(Qt.PointingHandCursor))
        btn.clicked.connect(self._on_cancel)
        row.addWidget(btn)
        inner.addLayout(row)

        # 阴影效果作用在核心容器上
        shadow = QGraphicsDropShadowEffect(self)
        shadow.setBlurRadius(15)
        shadow.setOffset(0, 4)
        shadow.setColor(QColor(0, 0, 0, 60))
        self.main_frame.setGraphicsEffect(shadow)

    def _on_cancel(self):
        self._canceled = True
        self.close()

    def wasCanceled(self) -> bool:
        return bool(self._canceled)

    def setValue(self, v: int):
        self.bar.setValue(int(v))

    def maximum(self) -> int:
        return int(self.bar.maximum())


