_ORT_FIELD_MIME = "application/x-ort-field-v1"


class _OrtFilterPopup(QDialog):
    """小件/配方多选弹出层（Popup 对话框，避免 QMenu 在 macOS 上一点击就关闭）。"""

    def __init__(self, anchor: QPushButton, panel: QWidget, parent=None):
        super().__init__(parent or anchor.window(), Qt.Popup | Qt.FramelessWindowHint)
        self._anchor = anchor
        self._panel = panel
        self._panel_host = panel.parentWidget()
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        self._panel.show()
        outer.addWidget(self._panel)
        self.setStyleSheet("""
            QDialog {
                background-color: #F5F9FF;
                border: 1px solid #B8D4E8;
                border-radius: 8px;
            }
        """)

    def show_below_anchor(self):
        self.adjustSize()
        min_w = max(int(self._anchor.width()), int(self._panel.sizeHint().width()) + 16)
        self.setMinimumWidth(min_w)
        self.adjustSize()
        pos = self._anchor.mapToGlobal(QPoint(0, self._anchor.height() + 2))
        self.move(pos)
        self.show()
        self.raise_()
        self.activateWindow()

    def closeEvent(self, event):
        if self._panel_host is not None:
            self._panel.setParent(self._panel_host)
            self._panel.hide()
        super().closeEvent(event)


class _OrtFieldList(QListWidget):
    """ORT 图形分析 — 可拖拽字段列表。"""

    def __init__(self, s: float = 1.0, horizontal: bool = False, parent=None):
        super().__init__(parent)
        self._s = s
        self._horizontal = horizontal
        self.setDragEnabled(True)
        self.setDragDropMode(QAbstractItemView.DragOnly)
        self.setSelectionMode(QAbstractItemView.SingleSelection)
        self.setSpacing(int(4 * s))
        if horizontal:
            self.setFlow(QListView.LeftToRight)
            self.setWrapping(False)
            self.setFixedHeight(int(28 * s))
            self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            self.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
            self.setStyleSheet(f"""
                QListWidget {{
                    border: none; background: transparent;
                    font-size: {int(10*s)}px;
                }}
                QListWidget::item {{
                    padding: {int(1*s)}px {int(4*s)}px;
                    border-radius: 3px;
                    color: #3A5A7A;
                    background-color: #FFFFFF;
                    border: 1px solid #B8D4E8;
                    margin: 1px;
                }}
                QListWidget::item:hover {{ background-color: #E8F1F8; }}
                QListWidget::item:selected {{ background-color: #B8D4E8; color: #2C3E50; }}
            """)
        else:
            self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            self.setStyleSheet(f"""
                QListWidget {{
                    border: none; background: transparent;
                    font-size: {int(12*s)}px;
                }}
                QListWidget::item {{
                    padding: {int(4*s)}px {int(8*s)}px;
                    border-radius: 4px;
                    color: #3A5A7A;
                }}
                QListWidget::item:hover {{ background-color: #E8F1F8; }}
                QListWidget::item:selected {{ background-color: #B8D4E8; color: #2C3E50; }}
            """)

    def startDrag(self, supported_actions):
        item = self.currentItem()
        if item is None:
            return
        field_key = str(item.data(Qt.UserRole) or "")
        field_type = str(item.data(Qt.UserRole + 1) or "dimension")
        display = item.text()

        payload = f"{field_key}|||{field_type}|||{display}"
        mime = QMimeData()
        mime.setText(display)
        mime.setData(_ORT_FIELD_MIME, payload.encode("utf-8"))

        s = self._s
        w = max(int(90*s), int(len(display) * 8 * s) + int(20*s))
        h = int(26*s)
        pm = QPixmap(w, h)
        pm.fill(QColor(0, 0, 0, 0))
        painter = QPainter(pm)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setBrush(QColor("#5B9BD5"))
        painter.setPen(Qt.NoPen)
        painter.drawRoundedRect(0, 0, w, h, int(5*s), int(5*s))
        painter.setPen(QColor("#FFFFFF"))
        f = QFont()
        f.setPixelSize(max(10, int(11*s)))
        painter.setFont(f)
        painter.drawText(pm.rect(), Qt.AlignCenter, display)
        painter.end()

        drag = QDrag(self)
        drag.setMimeData(mime)
        drag.setPixmap(pm)
        drag.setHotSpot(QPoint(w // 2, h // 2))
        drag.exec_(Qt.CopyAction)


class _OrtDropZone(QFrame):
    """ORT 图形分析 — 可接受字段的拖拽放置区。"""

    fieldChanged = pyqtSignal(str, str, str)  # zone_id, field_key, field_display

    def __init__(self, zone_id: str, label_text: str,
                 accepted_types=None, s: float = 1.0, compact: bool = False, single_line: bool = False, parent=None):
        super().__init__(parent)
        self.zone_id = zone_id
        self._accepted = set(accepted_types or ("dimension", "point"))
        self._s = s
        self._compact = compact
        self._single_line = single_line
        self._field_key = ""
        self._field_type = ""
        self._field_display = ""
        self.setAcceptDrops(True)
        self._build_ui(label_text, s, compact, single_line)

    def _build_ui(self, label_text: str, s: float, compact: bool = False, single_line: bool = False):
        if single_line:
            # 单行模式：紧凑宽度，确保标签和拖入的字段名都能显示完整
            self.setFixedSize(int(86 * s), int(30 * s))
            self.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            lay = QHBoxLayout(self)
            lay.setContentsMargins(int(3 * s), int(2 * s), int(3 * s), int(2 * s))
            lay.setSpacing(int(2 * s))
            self.lbl_name = QLabel(label_text)
            self.lbl_name.setAlignment(Qt.AlignCenter)
            self.lbl_name.setStyleSheet(
                f"font-size: {int(10 * s)}px; font-weight: 800; color: #5B9BD5;"
            )
            self.lbl_field = QLabel("")
            self.lbl_field.setAlignment(Qt.AlignCenter)
            self.lbl_field.setStyleSheet(
                f"font-size: {int(9 * s)}px; color: #3A5A7A; font-weight: 600;"
            )
            self.btn_clear = QPushButton("✕")
            self.btn_clear.setFixedSize(int(12 * s), int(12 * s))
            self.btn_clear.setVisible(False)
            self.btn_clear.setCursor(QCursor(Qt.PointingHandCursor))
            self.btn_clear.setStyleSheet(f"""
                QPushButton {{
                    background: #B8D4E8; border: none;
                    border-radius: {int(7 * s)}px; color: #3A5A7A;
                    font-size: {int(8 * s)}px;
                }}
                QPushButton:hover {{ background: #A8C8E0; }}
            """)
            self.btn_clear.clicked.connect(self.clear_field)
            lay.addWidget(self.lbl_name)
            lay.addWidget(self.lbl_field, 1)
            lay.addWidget(self.btn_clear, 0, Qt.AlignVCenter)
        elif compact:
            self.setMinimumWidth(int(58 * s))
            self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            lay = QVBoxLayout(self)
            lay.setContentsMargins(int(6 * s), int(5 * s), int(6 * s), int(5 * s))
            lay.setSpacing(int(3 * s))
            self.lbl_name = QLabel(label_text)
            self.lbl_name.setAlignment(Qt.AlignCenter)
            self.lbl_name.setStyleSheet(
                f"font-size: {int(10 * s)}px; font-weight: 800; color: #5B9BD5;"
            )
            self.lbl_field = QLabel("拖入…")
            self.lbl_field.setAlignment(Qt.AlignCenter)
            self.lbl_field.setWordWrap(True)
            self.lbl_field.setMinimumHeight(int(34 * s))
            self.lbl_field.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Minimum)
            self.lbl_field.setStyleSheet(
                f"font-size: {int(9 * s)}px; color: #A8C8E0; padding: 2px;"
            )
            self.btn_clear = QPushButton("✕")
            self.btn_clear.setFixedSize(int(16 * s), int(16 * s))
            self.btn_clear.setVisible(False)
            self.btn_clear.setCursor(QCursor(Qt.PointingHandCursor))
            self.btn_clear.setStyleSheet(f"""
                QPushButton {{
                    background: #B8D4E8; border: none;
                    border-radius: {int(8 * s)}px; color: #3A5A7A;
                    font-size: {int(9 * s)}px;
                }}
                QPushButton:hover {{ background: #A8C8E0; }}
            """)
            self.btn_clear.clicked.connect(self.clear_field)
            lay.addWidget(self.lbl_name)
            lay.addWidget(self.lbl_field, 1)
            lay.addWidget(self.btn_clear, 0, Qt.AlignCenter)
        else:
            self.setFixedHeight(int(40 * s))
            lay = QHBoxLayout(self)
            lay.setContentsMargins(int(8 * s), int(4 * s), int(8 * s), int(4 * s))
            lay.setSpacing(int(6 * s))
            self.lbl_name = QLabel(label_text)
            self.lbl_name.setFixedWidth(int(52 * s))
            self.lbl_name.setStyleSheet(
                f"font-size: {int(11 * s)}px; font-weight: 700; color: #5B9BD5;"
            )
            self.lbl_field = QLabel("拖入字段…")
            self.lbl_field.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            self.lbl_field.setStyleSheet(
                f"font-size: {int(11 * s)}px; color: #A8C8E0; padding: 1px {int(5 * s)}px;"
            )
            self.btn_clear = QPushButton("✕")
            self.btn_clear.setFixedSize(int(18 * s), int(18 * s))
            self.btn_clear.setVisible(False)
            self.btn_clear.setCursor(QCursor(Qt.PointingHandCursor))
            self.btn_clear.setStyleSheet(f"""
                QPushButton {{
                    background: #B8D4E8; border: none;
                    border-radius: {int(9 * s)}px; color: #3A5A7A;
                    font-size: {int(10 * s)}px;
                }}
                QPushButton:hover {{ background: #A8C8E0; }}
            """)
            self.btn_clear.clicked.connect(self.clear_field)
            lay.addWidget(self.lbl_name)
            lay.addWidget(self.lbl_field, 1)
            lay.addWidget(self.btn_clear)
        self._style_empty()

    def _style_empty(self):
        self.setStyleSheet("QFrame { background:#F5F9FF; border:1px dashed #B8D4E8; border-radius:8px; }")

    def _style_filled(self):
        self.setStyleSheet("QFrame { background:#E8F1F8; border:1px solid #5B9BD5; border-radius:8px; }")

    def _style_hover(self):
        self.setStyleSheet("QFrame { background:#E0E6ED; border:2px solid #5B9BD5; border-radius:8px; }")

    def _is_accepted_field(self, mime: QMimeData) -> bool:
        if not mime.hasFormat(_ORT_FIELD_MIME):
            return False
        raw = mime.data(_ORT_FIELD_MIME).data().decode("utf-8", errors="replace")
        parts = raw.split("|||", 2)
        key = parts[0] if len(parts) > 0 else ""
        ftype = parts[1] if len(parts) > 1 else "dimension"
        
        if ftype not in self._accepted:
            return False
            
        if self.zone_id == "group":
            if key not in ("part_name", "material_category"):
                return False
        elif self.zone_id == "x":
            if key not in ("shift", "line", "analysis_date", "material_category"):
                return False
        elif self.zone_id == "y":
            if key not in ("shift", "line", "material_category"):
                return False
        return True

    def dragEnterEvent(self, event):
        if self._is_accepted_field(event.mimeData()):
            self._style_hover()
            event.acceptProposedAction()
        else:
            event.ignore()

    def dragLeaveEvent(self, event):
        self._style_filled() if self._field_key else self._style_empty()
        super().dragLeaveEvent(event)

    def dropEvent(self, event):
        mime = event.mimeData()
        if self._is_accepted_field(mime):
            raw = mime.data(_ORT_FIELD_MIME).data().decode("utf-8", errors="replace")
            parts = raw.split("|||", 2)
            key = parts[0] if len(parts) > 0 else ""
            ftype = parts[1] if len(parts) > 1 else "dimension"
            display = parts[2] if len(parts) > 2 else key
            if key:
                self.set_field(key, ftype, display)
                event.acceptProposedAction()
                return
        self._style_filled() if self._field_key else self._style_empty()
        event.ignore()

    def set_field(self, key: str, ftype: str, display: str):
        self._field_key = key
        self._field_type = ftype
        self._field_display = display
        s = self._s
        if self._single_line:
            # 单行模式：显示截短的字段名
            txt = display if len(display) <= 4 else display[:3] + "…"
            self.lbl_field.setText(txt)
            self.lbl_field.setStyleSheet(
                f"font-size: {int(9 * s)}px; color: #3A5A7A; font-weight: 600;"
            )
        else:
            txt = display if len(display) <= 8 else display[:7] + "…"
            self.lbl_field.setText(txt)
            fs = int(9 * s) if self._compact else int(11 * s)
            self.lbl_field.setStyleSheet(
                f"font-size: {fs}px; color: #3A5A7A; font-weight: 600;"
                f" padding: 1px {int(3 * s)}px; background:#D5E3F0; border-radius: 4px;"
            )
        self.btn_clear.setVisible(True)
        self._style_filled()
        self.fieldChanged.emit(self.zone_id, key, display)

    def clear_field(self):
        self._field_key = ""
        self._field_type = ""
        self._field_display = ""
        s = self._s
        if self._single_line:
            self.lbl_field.setText("")
            self.lbl_field.setStyleSheet(
                f"font-size: {int(9 * s)}px; color: #3A5A7A; font-weight: 600;"
            )
        else:
            self.lbl_field.setText("拖入…" if self._compact else "拖入字段…")
            fs = int(9 * s) if self._compact else int(11 * s)
            self.lbl_field.setStyleSheet(
                f"font-size: {fs}px; color: #A8C8E0; padding: 1px {int(3 * s)}px;"
            )
        self.btn_clear.setVisible(False)
        self._style_empty()
        self.fieldChanged.emit(self.zone_id, "", "")

    @property
    def field_key(self) -> str:
        return self._field_key

    @property
    def field_type(self) -> str:
        return self._field_type

    @property
    def field_display(self) -> str:
        return self._field_display


# 导入规格表：繁简转换（可选，安装 zhconv 后启用）
_ZHCONV_CONVERT = None


def _norm_spec_match_str(s) -> str:
    """
    配方名 / 点位名匹配键：去除全部空白（含中间空格、换行、全角空格）；
    繁体转简体后比较；英文按大小写不敏感。
    未安装 zhconv 时仍可做去空白与英文折叠，但繁简需字面一致。
    """
    global _ZHCONV_CONVERT
    if s is None:
        return ""
    try:
        if pd.isna(s):
            return ""
    except Exception:
        pass
    t = re.sub(r"\s+", "", str(s).strip())
    if not t:
        return ""
    if _ZHCONV_CONVERT is not False:
        if _ZHCONV_CONVERT is None:
            try:
                import zhconv  # type: ignore[import-not-found]

                _ZHCONV_CONVERT = zhconv.convert
            except ImportError:
                _ZHCONV_CONVERT = False
        if _ZHCONV_CONVERT:
            t = _ZHCONV_CONVERT(t, "zh-cn")
    return t.casefold()


def _col_header_is_point_column(name: str) -> bool:
    """识别点位列：简体/繁体/英文 Point，兼容常见拼写 Piont。"""
    n = str(name).replace("\n", "").strip()
    nu = n.upper()
    return (
        "点位" in n
        or "點位" in n
        or "POINT" in nu
        or "PIONT" in nu
    )


def _col_header_is_recipe_column(name: str) -> bool:
    """识别配方列：含「配方」或 Recipe（中英文表头常见写法）。"""
    n = str(name).replace("\n", "").strip()
    nu = n.upper()
    return "配方" in n or "RECIPE" in nu


def _col_header_is_project_column(name: str) -> bool:
    """识别项目列：简繁体与英文 Project/Proj。"""
    n = str(name).replace("\n", "").strip()
    nu = n.upper()
    return "项目" in n or "項目" in n or "PROJECT" in nu or "PROJ" in nu


def _col_header_is_subpart_column(name: str) -> bool:
    """识别小件列：简繁体与英文 Subpart。"""
    n = str(name).replace("\n", "").strip()
    nu = n.upper()
    return "小件" in n or "小片" in n or "SUBPART" in nu or "SUB_PART" in nu


def _coerce_spec_limit_value(value) -> float | None:
    """将规格单元格规范为 float；无法解析则返回 None。"""
    if value is None:
        return None
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return None
    num = pd.to_numeric(value, errors="coerce")
    try:
        xf = float(num)
    except (TypeError, ValueError):
        return None
    return xf if np.isfinite(xf) else None


def _recipe_point_spec_map_to_rows(recipe_point_spec_map: dict) -> list[list]:
    """(recipe_key, point_name)->limits 转为 JSON 友好的行列表。"""
    rows = []
    if not isinstance(recipe_point_spec_map, dict):
        return rows
    for key, limits in recipe_point_spec_map.items():
        try:
            recipe_key, point_name = key
        except (TypeError, ValueError):
            continue
        recipe_key = str(recipe_key).strip()
        point_name = str(point_name).strip()
        if not recipe_key or not point_name or not isinstance(limits, dict):
            continue
        lsl = _coerce_spec_limit_value(limits.get("lsl"))
        usl = _coerce_spec_limit_value(limits.get("usl"))
        if lsl is None and usl is None:
            continue
        rows.append([recipe_key, point_name, lsl, usl])
    rows.sort(key=lambda x: (str(x[0]), str(x[1])))
    return rows


def _recipe_point_spec_rows_to_map(spec_rows: list | tuple | None) -> dict:
    """JSON 行列表转为 {(recipe_key, point_name): {'lsl','usl'}} 字典。"""
    spec_map = {}
    for row in spec_rows or []:
        recipe_key = None
        point_name = None
        lsl_raw = None
        usl_raw = None
        if isinstance(row, dict):
            recipe_key = row.get("recipe_key") or row.get("rkey")
            point_name = row.get("point_name") or row.get("point")
            lsl_raw = row.get("lsl")
            usl_raw = row.get("usl")
        elif isinstance(row, (list, tuple)) and len(row) >= 4:
            recipe_key, point_name, lsl_raw, usl_raw = row[0], row[1], row[2], row[3]
        if recipe_key is None or point_name is None:
            continue
        recipe_key = str(recipe_key).strip()
        point_name = str(point_name).strip()
        if not recipe_key or not point_name:
            continue
        limits = {}
        lsl = _coerce_spec_limit_value(lsl_raw)
        usl = _coerce_spec_limit_value(usl_raw)
        if lsl is not None:
            limits["lsl"] = lsl
        if usl is not None:
            limits["usl"] = usl
        if limits:
            spec_map[(recipe_key, point_name)] = limits
    return spec_map


def _build_valid_recipe_combos(df_source: pd.DataFrame, project_col, subpart_col, recipe_col) -> list[dict]:
    """从当前数据中提取有效的 项目/小件/配方 组合；项目/小件允许为空。"""
    if df_source is None or df_source.empty:
        return []
    if recipe_col is None:
        return []
    if recipe_col not in df_source.columns:
        return []

    has_project = project_col is not None and project_col in df_source.columns
    has_subpart = subpart_col is not None and subpart_col in df_source.columns

    combos = []
    seen = set()
    cols_to_read = [recipe_col]
    if has_project:
        cols_to_read.append(project_col)
    if has_subpart:
        cols_to_read.append(subpart_col)

    for _, row in df_source[cols_to_read].iterrows():
        project = str(row[project_col]).strip() if has_project and pd.notna(row[project_col]) else ""
        subpart = str(row[subpart_col]).strip() if has_subpart and pd.notna(row[subpart_col]) else ""
        recipe = str(row[recipe_col]).strip() if pd.notna(row[recipe_col]) else ""
        if not recipe:
            continue
        norm_key = (
            _norm_spec_match_str(project),
            _norm_spec_match_str(subpart),
            _norm_spec_match_str(recipe),
        )
        if not all(norm_key) or norm_key in seen:
            continue
        seen.add(norm_key)
        combos.append({"proj": project, "sub": subpart, "rec": recipe})
    return combos


def _load_recipe_point_spec_rows_from_excel(
    path: str,
    valid_combos: list[dict],
    all_points: list,
    match_mode: str = "recipe_point",
) -> tuple[list[list], int]:
    """读取规格表并按匹配规则生成规格映射行列表。"""
    if match_mode not in ("recipe_point", "project_subpart_recipe_point"):
        raise ValueError(f"暂不支持的规格匹配模式：{match_mode}")

    try:
        df_temp = _read_tabular_raw(path, sheet_name=0).head(20)
        header_row_idx = 0
        for idx, row in df_temp.iterrows():
            row_str = " ".join([str(x) for x in row.values])
            row_upper = row_str.upper()
            has_project = "项目" in row_str or "項目" in row_str or "PROJECT" in row_upper or "PROJ" in row_upper
            has_subpart = "小件" in row_str or "小片" in row_str or "SUBPART" in row_upper or "SUB_PART" in row_upper
            has_recipe = "配方" in row_str or "RECIPE" in row_upper
            has_spec = "USL" in row_upper or "LSL" in row_upper
            has_point = (
                "点位" in row_str
                or "點位" in row_str
                or "POINT" in row_upper
                or "PIONT" in row_upper
            )
            has_required_match_cols = has_recipe if match_mode == "recipe_point" else (has_project and has_subpart and has_recipe)
            if has_required_match_cols and (has_spec or has_point):
                header_row_idx = idx
                break
        df_spec = _read_tabular_dataframe(path, header=header_row_idx, sheet_name=0, dtype=object)
        df_spec.columns = [str(c).replace("\n", "").strip() for c in df_spec.columns]
    except ValueError as e:
        raise RuntimeError(str(e)) from e
    except Exception as e:
        raise RuntimeError(f"读取表格文件失败：\n{e}") from e

    cols = df_spec.columns.tolist()
    col_project = next((c for c in cols if _col_header_is_project_column(str(c))), None)
    col_subpart = next((c for c in cols if _col_header_is_subpart_column(str(c))), None)
    col_recipe = next((c for c in cols if _col_header_is_recipe_column(str(c))), None)
    col_point = next((c for c in cols if _col_header_is_point_column(str(c))), None)
    col_usl = next((c for c in cols if "USL" in str(c).upper()), None)
    col_lsl = next((c for c in cols if "LSL" in str(c).upper()), None)

    if not col_recipe:
        raise ValueError("规格表中未找到“配方 / Recipe”列。")
    if match_mode == "project_subpart_recipe_point" and not col_project:
        raise ValueError("规格表中未找到“项目 / Project”列。")
    if match_mode == "project_subpart_recipe_point" and not col_subpart:
        raise ValueError("规格表中未找到“小件 / Subpart”列。")
    if not col_usl and not col_lsl:
        raise ValueError("规格表中未找到 USL / LSL 列。")

    combo_index: dict[tuple[str, str, str], list[dict]] = {}
    recipe_index: dict[str, list[dict]] = {}
    for combo in valid_combos or []:
        proj_key = _norm_spec_match_str(combo.get("proj"))
        sub_key = _norm_spec_match_str(combo.get("sub"))
        rec_key = _norm_spec_match_str(combo.get("rec"))
        if not rec_key:
            continue
        recipe_index.setdefault(rec_key, []).append(combo)
        if proj_key and sub_key:
            combo_index.setdefault((proj_key, sub_key, rec_key), []).append(combo)

    point_index = {}
    for point_name in all_points or []:
        point_key = _norm_spec_match_str(point_name)
        if point_key and point_key not in point_index:
            point_index[point_key] = str(point_name).strip()

    matched_map = {}
    for _, row in df_spec.iterrows():
        recipe_key = _norm_spec_match_str(row.get(col_recipe))
        if not recipe_key:
            continue

        if match_mode == "project_subpart_recipe_point":
            project_key = _norm_spec_match_str(row.get(col_project))
            subpart_key = _norm_spec_match_str(row.get(col_subpart))
            if not (project_key and subpart_key):
                continue
            matched_combos = combo_index.get((project_key, subpart_key, recipe_key), [])
        else:
            matched_combos = recipe_index.get(recipe_key, [])
        if not matched_combos:
            continue

        usl = _coerce_spec_limit_value(row.get(col_usl)) if col_usl else None
        lsl = _coerce_spec_limit_value(row.get(col_lsl)) if col_lsl else None
        if usl is None and lsl is None:
            continue

        excel_point = str(row.get(col_point)).strip() if col_point and pd.notna(row.get(col_point)) else ""
        if excel_point:
            point_key = _norm_spec_match_str(excel_point)
            target_points = [point_index.get(point_key) or excel_point]
        else:
            target_points = [str(p).strip() for p in (all_points or []) if str(p).strip()]

        for combo in matched_combos:
            recipe_text = f"{combo['proj']}||{combo['sub']}||{combo['rec']}"
            for point_name in target_points:
                map_key = (recipe_text, str(point_name).strip())
                if not map_key[1]:
                    continue
                limits = matched_map.setdefault(map_key, {})
                if lsl is not None:
                    limits["lsl"] = lsl
                if usl is not None:
                    limits["usl"] = usl

    rows = _recipe_point_spec_map_to_rows(matched_map)
    return rows, len(rows)


class RecipeSpecDialog(QDialog):
    """
    规格设置（按配方）：
      - 左侧三列：项目 / 小件 / 配方（级联筛选）
      - 右侧：当前配方的 LSL/USL（可编辑）
        - LSL 默认来自源数据 Spec 聚合值（可修改）
        - USL 手动维护
    """

    def __init__(self, df_raw: pd.DataFrame, core_cols: dict, point_cols: list,
                 recipe_point_spec_map: dict,
                 on_save_template,
                 parent=None):
        super().__init__(parent)
        self.df_raw = df_raw
        self.core_cols = core_cols
        self.point_cols = point_cols
        # (recipe_key, point_name) -> {"lsl": float|None, "usl": float|None}
        # 使用深拷贝，这样修改不会影响原始数据，需要保存时才应用
        self.recipe_point_spec_map = copy.deepcopy(recipe_point_spec_map) if recipe_point_spec_map else {}
        self.original_spec_map = recipe_point_spec_map
        self.on_save_template = on_save_template
        # 打开规格设置窗口时：点位可直接加载，但 USL/LSL 默认先留空（不自动带出/不自动汇总）
        self._blank_specs_on_open = True

