# ---------- 3-3  DataMappingWizard ----------
class DataMappingWizard(QDialog):
    """
    ORT data mapping wizard.

    Layout:
      - Row 0: header (point names, info columns).
      - Row 1: sub-header row (value/spec).
      - Row 2+: data rows.
      - Left block (A-U, index 0-20): meta columns.
      - Measurement block: pairs (value, spec) per point.
      - Recipe column (col R, index 17): grouping key; only rows with that recipe have point data.
    """

    # ORT 表头固定常量（与实际 xlsx 一致）
    ORT_HEADER_ROW   = 0   # 列名所在行索引
    ORT_SUBHDR_ROW   = 1   # value/spec 副标题行索引
    ORT_DATA_START   = 2   # 数据起始行索引
    ORT_INFO_COL_END = 21  # 左侧信息列数（A-U，0-based）

    STAND_CORE_HEADERS = {
        "date", "serial no.", "status", "time", "spring rate", "global average",
    }
    STAND_IMPORTANT_HEADERS = {
        "build", "config", "unit", "cavity", "max angle", "min angle", "total angle",
        "global max", "global min", "push average", "push max", "push min",
        "pull average", "pull max", "pull min", "direction offset", "angle stroke offset",
    }

    @staticmethod
    def _stand_header_is_numeric(value) -> bool:
        if value is None or (isinstance(value, float) and pd.isna(value)):
            return False
        txt = str(value).strip()
        if not txt or txt.lower() in ("nan", "none"):
            return False
        try:
            float(txt)
            return True
        except (TypeError, ValueError):
            return False

    @staticmethod
    def _stand_point_label(value) -> str:
        if isinstance(value, (int, float)) and not (isinstance(value, float) and pd.isna(value)):
            v = float(value)
            return str(int(v)) if v.is_integer() else str(v)
        txt = str(value or "").strip()
        try:
            v = float(txt)
            return str(int(v)) if v.is_integer() else str(v)
        except (TypeError, ValueError):
            return txt or "—"

    @staticmethod
    def _col_excel_label(col_idx: int) -> str:
        n = int(col_idx) + 1
        letters = ""
        while n > 0:
            n, rem = divmod(n - 1, 26)
            letters = chr(65 + rem) + letters
        return letters

    @staticmethod
    def detect_sheet_format(raw_df: pd.DataFrame) -> str:
        """粗判 Excel 布局：stand_ort / ort_like / cpk_dimension / generic。"""
        if raw_df is None or raw_df.empty:
            return "unknown"
        head = raw_df.iloc[:min(20, len(raw_df))]
        flat = " ".join(
            str(x).lower()
            for x in head.values.ravel()
            if x is not None and str(x).strip() and str(x).lower() not in ("nan", "none")
        )
        if "dim. no" in flat or "dim.no" in flat or ("nominal" in flat and "tol" in flat):
            return "cpk_dimension"
        if len(raw_df) > 0:
            row0 = [
                str(x).strip().lower()
                for x in raw_df.iloc[0]
                if x is not None and str(x).strip() and str(x).lower() not in ("nan", "none")
            ]
            if (
                "date" in row0
                and "serial no." in row0
                and "spring rate" in row0
            ):
                row1_hits = 0
                if len(raw_df) > 1:
                    row1_hits = sum(
                        1
                        for v in raw_df.iloc[1]
                        if str(v).strip().lower() in ("value", "spec", "规格", "实测", "下限", "上限")
                    )
                if row1_hits < 2:
                    return "stand_ort"
        if len(raw_df) > 1:
            row1 = raw_df.iloc[1]
            hits = sum(
                1
                for v in row1
                if str(v).strip().lower() in ("value", "spec", "规格", "实测", "下限", "上限")
            )
            if hits >= 2:
                return "ort_like"
        return "generic"

    def __init__(self, raw_df: pd.DataFrame, parent=None, module_name: str = None, category: str = None):
        super().__init__(parent)
        self.raw_df = raw_df.copy()
        self.mapping_config = None
        self.spec_import_path = ""
        self.spec_match_mode = "recipe_point"
        self.recipe_point_spec_rows: list[list] = []
        self._s = parent._s if hasattr(parent, '_s') else 1.0
        if parent is not None and hasattr(parent, "_normalize_module_name"):
            default_mod = getattr(parent, "_active_template_module", None) or parent.DEFAULT_MODULE_NAME
            self.module_name = parent._normalize_module_name(module_name or default_mod)
        else:
            self.module_name = str(module_name or "ORT").strip() or "ORT"

        self.category_name = str(category or "").strip()
        self.sheet_format = self.detect_sheet_format(self.raw_df)
        if self.category_name.lower() == "stand" and self.sheet_format != "cpk_dimension":
            self.sheet_format = "stand_ort"
        self._stand_format = self.sheet_format == "stand_ort"
        if self._stand_format:
            self.header_row = 0
            self.subheader_row = 0
            self.data_start_row = 1
            self.info_col_end = 0
        else:
            self.header_row = self.ORT_HEADER_ROW
            self.subheader_row = self.ORT_SUBHDR_ROW
            self.data_start_row = self.ORT_DATA_START
            self.info_col_end = self.ORT_INFO_COL_END
        self._row_index_editable = (
            self.module_name == "Weekly Inspection" and not self._stand_format
        )
        self.core_param_cols: list[dict] = []
        self.important_param_cols: list[dict] = []
        self.measurement_start_col = -1

        title_mod = (
            "Stand"
            if self._stand_format
            else ("ORT" if self.module_name == "ORT" else self.module_name)
        )
        self.setWindowTitle(f"{title_mod} 数据映射向导")
        self.setMinimumSize(1400, 760)
        self.resize(1680, 920)
        self.setStyleSheet("""
            QDialog { background-color: #F0F7FF; }
            QGroupBox {
                font-size: 13px; font-weight: bold; color: #2C3E50;
                border: 1px solid #B8D4E8; border-radius: 6px;
                margin-top: 10px; background-color: #FFFFFF;
            }
            QGroupBox::title { subcontrol-origin: margin; left: 10px; padding: 0 4px; }
            QLabel { font-size: 13px; color: #3A5A7A; }
            QComboBox, QSpinBox, QLineEdit {
                padding: 4px; font-size: 13px; border: 1px solid #B8D4E8;
                border-radius: 4px; background: #F0F7FF; min-height: 22px;
            }
            QComboBox:hover, QSpinBox:hover { border-color: #5B9BD5; }
            QTableView {
                border: 1px solid #C5D9E8; background-color: #FFFFFF;
                alternate-background-color: #F0F7FF; gridline-color: #C5D9E8; font-size: 12px;
            }
            QListWidget { border: 1px solid #C5D9E8; border-radius: 4px; background: #F0F7FF; font-size: 13px; }
            QCheckBox { font-size: 13px; color: #3A5A7A; }
        """)
        if self.sheet_format == "cpk_dimension":
            QMessageBox.information(
                self,
                "表格格式提示",
                "当前文件疑似 CPK 维度表（含 Dim.No./Nominal 等），与 ORT/周送检宽表不同。\n"
                "请确认已选对 Sheet；若确为 CPK 数据，请先在 CPK 模块使用（开发中）。\n"
                "周送检若为「列名行 + value/spec 行 + 数据行」结构，可继续在本向导中调整行索引。",
            )

        if self._stand_format:
            self._parse_stand_columns()
        else:
            self._parse_ort_columns()
        self._init_ui()
        self._refresh_table_highlights()

    # --- Stand / ORT 列解析 ---

    def _parse_stand_columns(self):
        """Stand ORT：绿色=核心参数列，橙色=重要参数列，数字表头=实测角度列。"""
        df = self.raw_df
        n_cols = df.shape[1]
        row0 = df.iloc[self.header_row] if len(df) > self.header_row else pd.Series()
        self.core_param_cols = []
        self.important_param_cols = []
        self.point_cols = []
        self.measurement_start_col = -1
        self.info_col_names = []

        for i in range(n_cols):
            raw_h = row0.iloc[i] if i < len(row0) else ""
            if self._stand_header_is_numeric(raw_h):
                pname = self._stand_point_label(raw_h)
                if self.measurement_start_col < 0:
                    self.measurement_start_col = i
                self.point_cols.append((pname, i, None))
                continue
            name = str(raw_h).strip() if raw_h is not None else ""
            if not name or name.lower() in ("nan", "none"):
                continue
            entry = {
                "col_idx": i,
                "excel_col": self._col_excel_label(i),
                "name": name,
            }
            norm = name.lower()
            if norm in self.STAND_CORE_HEADERS:
                self.core_param_cols.append(entry)
            elif norm in self.STAND_IMPORTANT_HEADERS:
                self.important_param_cols.append(entry)
            elif self.measurement_start_col < 0:
                self.important_param_cols.append(entry)
            self.info_col_names.append(name)

        if self.measurement_start_col >= 0:
            self.info_col_end = self.measurement_start_col
        else:
            self.info_col_end = len(self.core_param_cols) + len(self.important_param_cols)

    def _parse_ort_columns(self):
        """
        解析 ORT 列结构：
          - 信息块：索引 0 .. info_col_end-1
          - 测点：(value_col, spec_col) 成对始于 info_col_end
        row0：列名；row1：value/spec 副标题；
        row0 有名称列为测点（value）；对应 spec 列常在 row1 标注 value/spec。
        """
        df = self.raw_df
        n_cols = df.shape[1]
        row0 = df.iloc[self.header_row] if len(df) > self.header_row else pd.Series()
        row1 = df.iloc[self.subheader_row] if len(df) > self.subheader_row else pd.Series()

        # 信息列名
        self.info_col_names = []
        for i in range(min(self.info_col_end, n_cols)):
            v = str(row0.iloc[i]).strip() if i < len(row0) else ""
            self.info_col_names.append(v if v and v.lower() != "nan" else f"列{i}")

        # value/spec 配对：从 info 列尾起扫描；row0 非空即为测点名（value），下一列为 spec（若存在）
        self.point_cols = []  # list of (point_name, value_col_idx, spec_col_idx)
        c = self.info_col_end
        while c < n_cols:
            v0 = str(row0.iloc[c]).strip() if c < len(row0) else ""
            r1_v = str(row1.iloc[c]).strip().lower() if c < len(row1) else ""
            if v0 and v0.lower() not in ("nan", "none", "") and r1_v in ("value", ""):
                # This is a measurement point's value column
                spec_col = c + 1 if (c + 1) < n_cols else None
                self.point_cols.append((v0, c, spec_col))
                c += 2  # skip spec col
            else:
                c += 1

    # --- 向导 UI ---

    _WIZARD_DARK_BTN_SIZE = QSize(380, 50)

    def _style_dark_btn(self, btn):
        w, h = self._WIZARD_DARK_BTN_SIZE.width(), self._WIZARD_DARK_BTN_SIZE.height()
        btn.setFixedSize(w, h)
        btn.setCursor(QCursor(Qt.PointingHandCursor))
        btn.setStyleSheet("""
            QPushButton {
                background-color: #000000; color: #FFFFFF; border: none;
                border-radius: 6px; padding: 8px 16px; font-weight: bold; font-size: 16px;
            }
            QPushButton:hover { background-color: #141414; }
            QPushButton:pressed { background-color: #262626; }
            QPushButton:disabled { background-color: #404040; color: #9CA3AF; }
        """)
        glow = QGraphicsDropShadowEffect(btn)
        glow.setBlurRadius(16)
        glow.setOffset(0, 0)
        glow.setColor(QColor(34, 211, 238, 120))
        btn.setGraphicsEffect(glow)

    def _configure_preview_table(self):
        """左侧预览表：显示行索引，便于和右侧行定位保持一致。"""
        fs = int(12 * self._s)
        hdr_style = (
            "QHeaderView::section {"
            f"background-color: #E8F1F8; color: #1E3A5F; font-size: {fs}px;"
            "font-weight: bold; padding: 4px 6px; border: 1px solid #C5D9E8;"
            "}"
        )
        vh = self.preview_table.verticalHeader()
        vh.setVisible(True)
        vh.setStyleSheet(hdr_style)
        vh.setMinimumWidth(int(48 * self._s))
        vh.setDefaultAlignment(Qt.AlignCenter)
        vh.setSectionResizeMode(QHeaderView.Fixed)
        vh.setDefaultSectionSize(int(24 * self._s))
        hh = self.preview_table.horizontalHeader()
        hh.setVisible(True)
        hh.setStyleSheet(hdr_style)
        hh.setDefaultAlignment(Qt.AlignCenter)
        hh.setMinimumHeight(int(28 * self._s))
        self.preview_table.setAlternatingRowColors(True)
        self.preview_table.setShowGrid(True)

    def _init_ui(self):
        main_layout = QHBoxLayout(self)
        main_layout.setContentsMargins(15, 15, 15, 15)
        self.splitter = QSplitter(Qt.Horizontal)

        # --- 左侧：原始表 ---
        left_panel = QFrame()
        left_lay = QVBoxLayout(left_panel)
        left_lay.setContentsMargins(0, 0, 10, 0)
        left_lay.addWidget(QLabel(
            "【预览】Stand：绿=核心列 | 橙=重要列 | 蓝=实测角度 | 浅绿=数据起始"
            if getattr(self, "_stand_format", False)
            else "【预览】原始表（蓝：列名 | 橙：副标题 | 绿：数据起始 | 棕：配方）",
            styleSheet="font-size: 15px; font-weight: bold; color: #0F172A;"
        ))
        self.preview_table = QTableView()
        self.table_model = PandasModel(self.raw_df.head(200))
        self.preview_table.setModel(self.table_model)
        self._configure_preview_table()
        left_lay.addWidget(self.preview_table)
        self.splitter.addWidget(left_panel)

        # --- 右侧：向导 ---
        right_panel = QFrame()
        right_panel.setMinimumWidth(420)
        right_panel.setMaximumWidth(720)
        outer_right = QVBoxLayout(right_panel)
        outer_right.setContentsMargins(0, 0, 0, 0)
        outer_right.setSpacing(8)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll_inner = QWidget()
        right_lay = QVBoxLayout(scroll_inner)
        right_lay.setContentsMargins(0, 0, 6, 0)
        right_lay.setSpacing(8)

        # Group 1：行索引
        grp1_title = (
            "1. 表格行索引（Stand / 周送检可调整）"
            if self._row_index_editable
            else "1. ORT 行索引（固定）"
        )
        grp1 = QGroupBox(grp1_title)
        g1l = QGridLayout(grp1)
        if self._row_index_editable:
            self.spin_header = QSpinBox()
            self.spin_subheader = QSpinBox()
            self.spin_data_start = QSpinBox()
            self.spin_info_cols = QSpinBox()
            for sp, val, hi in (
                (self.spin_header, self.header_row, max(0, len(self.raw_df) - 1)),
                (self.spin_subheader, self.subheader_row, max(0, len(self.raw_df) - 1)),
                (self.spin_data_start, self.data_start_row, max(0, len(self.raw_df))),
                (self.spin_info_cols, self.info_col_end, max(1, self.raw_df.shape[1])),
            ):
                sp.setRange(0, max(0, hi))
                sp.setValue(int(val))
            g1l.addWidget(QLabel("列名行索引"), 0, 0)
            g1l.addWidget(self.spin_header, 0, 1)
            g1l.addWidget(QLabel("副标题行（value/spec）"), 1, 0)
            g1l.addWidget(self.spin_subheader, 1, 1)
            g1l.addWidget(QLabel("数据起始行索引"), 2, 0)
            g1l.addWidget(self.spin_data_start, 2, 1)
            g1l.addWidget(QLabel("左侧信息列数"), 3, 0)
            g1l.addWidget(self.spin_info_cols, 3, 1)
            self.btn_reparse_rows = QPushButton("应用行索引并重新识别列")
            self.btn_reparse_rows.setCursor(QCursor(Qt.PointingHandCursor))
            self.btn_reparse_rows.clicked.connect(self._on_reparse_row_indices)
            g1l.addWidget(self.btn_reparse_rows, 4, 0, 1, 2)
        else:
            if self._stand_format:
                g1l.addWidget(QLabel("列名行索引"), 0, 0)
                g1l.addWidget(QLabel(f"<b>{self.header_row}</b>（第 {self.header_row+1} 行）"), 0, 1)
                g1l.addWidget(QLabel("数据起始行索引"), 1, 0)
                g1l.addWidget(QLabel(f"<b>{self.data_start_row}</b>（第 {self.data_start_row+1} 行）"), 1, 1)
                g1l.addWidget(QLabel("实测起始列"), 2, 0)
                meas_txt = (
                    f"<b>{self._col_excel_label(self.measurement_start_col)}</b>"
                    f"（索引 {self.measurement_start_col}）"
                    if self.measurement_start_col >= 0 else "—"
                )
                g1l.addWidget(QLabel(meas_txt), 2, 1)
            else:
                g1l.addWidget(QLabel("列名行索引"), 0, 0)
                g1l.addWidget(QLabel(f"<b>{self.header_row}</b>（第 {self.header_row+1} 行）"), 0, 1)
                g1l.addWidget(QLabel("副标题行（value/spec）"), 1, 0)
                g1l.addWidget(QLabel(f"<b>{self.subheader_row}</b>（第 {self.subheader_row+1} 行）"), 1, 1)
                g1l.addWidget(QLabel("数据起始行索引"), 2, 0)
                g1l.addWidget(QLabel(f"<b>{self.data_start_row}</b>（第 {self.data_start_row+1} 行）"), 2, 1)
                g1l.addWidget(QLabel("信息列数（A-U）"), 3, 0)
                g1l.addWidget(QLabel(f"<b>{self.info_col_end}</b> 列"), 3, 1)
        right_lay.addWidget(grp1)

        grp2_title = (
            "2. 参数列映射（核心 / 重要，英文表头）"
            if self._stand_format
            else "2. 核心信息列映射"
        )
        self.grp2 = QGroupBox(grp2_title)
        self.g2l = QVBoxLayout(self.grp2)
