        def create_combo_field(title, attr_name, parent_layout):
            field = QWidget()
            field_lay = QVBoxLayout(field)
            field_lay.setContentsMargins(0, 0, 0, 0)
            field_lay.setSpacing(int(4 * self._s))
            label = QLabel(title)
            label.setStyleSheet(f"font-size: {int(11*self._s)}px; font-weight: 700; color: #3A5A7A;")
            combo = QComboBox()
            combo.setObjectName(f"ort_db_combo_{attr_name}")
            combo.setFixedHeight(int(30 * self._s))
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            combo.setStyleSheet(_ort_combo_style)
            field_lay.addWidget(label)
            field_lay.addWidget(combo)
            parent_layout.addWidget(field)
            setattr(self, f"ort_db_combo_{attr_name}", combo)

        def create_dropdown_field(title, attr_name, parent_layout, min_h=96, max_h=132):
            field = QWidget()
            field_lay = QVBoxLayout(field)
            field_lay.setContentsMargins(0, 0, 0, 0)
            field_lay.setSpacing(int(4 * self._s))
 
            # 创建水平排列头部容器，将标题与下拉选择框置于同一行（左右排列）
