    def _migrate_ort_pages_to_tab_stack(self):
        """将ort_menu_stack的页面迁移到ort_content_stack，实现Tab切换。"""
        if not hasattr(self, "ort_content_stack") or not hasattr(self, "ort_menu_stack"):
            return

        # 页面映射：Tab索引 -> ort_menu_stack索引
        # ort_menu_stack: 0=图形分析, 1=数据与报告, 2=数据分析, 3=良率监控
        # Tab顺序: 0=良率监控, 1=图形分析, 2=数据分析, 3=数据与报告
        self._tab_to_stack_map = [3, 0, 2, 1]  # Tab0<-Stack3, Tab1<-Stack0, Tab2<-Stack2, Tab3<-Stack1

        # 先收集所有的页面，避免在将页面添加到 new stack 时因 reparenting 导致 old stack 索引动态改变
        pages = []
        for tab_idx in range(4):
            stack_idx = self._tab_to_stack_map[tab_idx]
            if stack_idx < self.ort_menu_stack.count():
                pages.append(self.ort_menu_stack.widget(stack_idx))
            else:
                pages.append(None)

        # 按Tab顺序将非空页面添加到ort_content_stack
        for page in pages:
            if page is not None:
                page.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                page.setMinimumWidth(0)
                self.ort_content_stack.addWidget(page)

        self.ort_content_stack.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.ort_content_stack.setMinimumWidth(0)
        self.ort_content_stack.setMinimumHeight(int(420 * self._s))

        # 默认显示良率监控（Tab索引0）
        self.ort_content_stack.setCurrentIndex(0)
        self._current_ort_tab_idx = 0
        self._update_ort_tab_styles()
        QTimer.singleShot(0, lambda: self._refresh_yield_dashboard("yield_menu"))
        QTimer.singleShot(50, self._ensure_yield_menu_layout)


