    @staticmethod
    def _wi_clamp_date_to_batch(cur: QDate, batch_dates: list[str], fallback: QDate) -> QDate:
        if not batch_dates:
            return cur if cur.isValid() else fallback
        key = cur.toString("yyyy-MM-dd") if cur.isValid() else ""
        if key in batch_dates:
            return cur
        qdates = [QDate.fromString(d, "yyyy-MM-dd") for d in batch_dates]
        qdates = [d for d in qdates if d.isValid()]
        if not qdates:
            return fallback
        if cur.isValid():
            before = [d for d in qdates if d <= cur]
            if before:
                return before[-1]
            return qdates[0]
        return qdates[0]

    def _on_wi_global_product_changed(self, *_args):
        self._wi_selected_processes = set()
        self._wi_view_process = ""
        self._wi_cpk_dashboard_cache = {}
        self._wi_active_process = ""
        picker = getattr(self, "wi_process_date_picker", None)
        if picker is not None:
            wi_product = self._get_selected_wi_product_line()
            empty_map = {p: [] for p in self._wi_process_names_for_ui(wi_product)}
            picker.set_process_date_map(empty_map, active_process=None, default_recent_n=4)
        self._sync_wi_overview_process_chips()
        self._update_wi_global_date_btn_text()
        self._set_wi_global_refresh_btn_success(False)
        self._refresh_wi_report_status()

    def _wi_selected_dates_display(self) -> str:
        dates = self._get_wi_selected_batch_dates()
        if not dates:
            return "未选日期"
        if len(dates) <= 3:
            return "、".join(dates)
        return f"{dates[0]} … {dates[-1]}（共 {len(dates)} 天）"

    def _extract_wi_cpk_points_from_excel(self, raw_df: pd.DataFrame, config: dict) -> list[dict]:
        """从 Excel + 映射模板提取各测点列的 Cpk（核心统计行，非左侧样本列）。"""
        meta_rows = config.get("meta_rows") or {}
        selected = config.get("selected_cols") or []
        special_core_rows = config.get("special_core_rows") or []
        label_col = int(config.get("label_col", 0))
        core_start = int(config.get("core_param_start_col", 1))
        core_end = int(config.get("core_param_end_col", raw_df.shape[1] - 1))

        cpk_row = -1
        for sr in special_core_rows:
            if sr.get("enabled") is False:
                continue
            if str(sr.get("key") or "").strip().lower() == "cpk":
                cpk_row = int(sr.get("row_idx", -1))
                break
        if cpk_row < 0:
            for r in range(len(raw_df)):
                lbl = str(raw_df.iloc[r, label_col] if label_col < raw_df.shape[1] else "").strip().lower()
                if lbl == "cpk" or lbl.startswith("cpk "):
                    cpk_row = r
                    break
        if cpk_row < 0:
            return []

        def _cell(r: int, c: int):
            if r < 0 or c < 0 or r >= len(raw_df) or c >= raw_df.shape[1]:
                return ""
            v = raw_df.iloc[r, c]
            if v is None or (isinstance(v, float) and pd.isna(v)):
                return ""
            return str(v).strip()

        def _meta(key: str, col_idx: int) -> str:
            row = int(meta_rows.get(key, -1))
            return _cell(row, col_idx) if row >= 0 else ""

        out: list[dict] = []
        for item in selected:
            col_idx = int(item[0])
            if col_idx < core_start or col_idx > core_end or col_idx >= raw_df.shape[1]:
                continue
            point_name = str(item[1] if len(item) > 1 else "").strip()
            dim_no = str(item[2] if len(item) > 2 else "").strip()
            cpk_v = pd.to_numeric(raw_df.iloc[cpk_row, col_idx], errors="coerce")
            if pd.isna(cpk_v):
                continue
            out.append({
                "point_name": point_name,
                "dim_no": dim_no,
                "dimension_description": _meta("dimension_description", col_idx),
                "dimension_type": _meta("dimension_type", col_idx),
                "cpk": float(cpk_v),
            })
        return out

    def _try_backfill_wi_cpk_from_workspace(self, wi_product: str, process_name: str) -> int:
        """库内无 cpk 时，尝试用工作区 Excel + 映射模板补写。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name:
            return 0
        cfg = self.get_template_config("Weekly Inspection", wi_product, process_name)
        if not cfg or not cfg.get("wi_cpk_format"):
            return 0
        file_path = getattr(self, "current_workspace_file", None) or ""
        if not file_path or not os.path.exists(file_path):
            try:
                ws_item = self.ws_file_list.currentItem()
                if ws_item and ws_item.flags() != Qt.NoItemFlags:
                    file_path = str(ws_item.data(Qt.UserRole) or "")
            except Exception:
                file_path = ""
        if not file_path or not os.path.exists(file_path):
            last_fp = os.path.join(_app_config_dir(), "workspace_last_file.txt")
            if os.path.exists(last_fp):
                with open(last_fp, "r", encoding="utf-8") as f:
                    file_path = str(f.read() or "").strip()
        if not file_path or not os.path.exists(file_path):
            return 0
        try:
            raw_df, _picked = self._read_source_df(file_path)
            if raw_df is None or raw_df.empty:
                return 0
            points = self._extract_wi_cpk_points_from_excel(raw_df, cfg)
            if not points:
                return 0
            mgr = getattr(self, "_ort_db", None)
            if mgr is None:
                return 0
            return mgr.backfill_wi_cpk_values(wi_product, process_name, points)
        except Exception as ex:
            print(f"[WI CPK] 从工作区补写失败：{ex}")
            return 0

    def _refresh_wi_cpk_dashboard(self, *, show_tip: bool = True):
        """刷新 Weekly Inspection 数据总览（按制程分别加载，顶部 chip 切换展示）。"""
        if not hasattr(self, "_wi_cpk_view"):
            return
        wi_product = self._get_selected_wi_product_line()
        processes = self._get_wi_picker_process_names()
        if not processes:
            self._wi_cpk_dashboard_cache = {}
            self._update_wi_cpk_bars([], None)
            self._refresh_wi_report_table()
            if show_tip:
                QMessageBox.information(self, "提示", "请在右上角至少选择一个制程。")
            return False
        picker = getattr(self, "wi_process_date_picker", None)
        has_any_dates = any(
            (picker.selected_dates(p) if picker is not None else [])
            for p in processes
        )
        if not has_any_dates:
            self._wi_cpk_dashboard_cache = {}
            self._update_wi_cpk_bars([], None)
            self._refresh_wi_report_table()
            if show_tip:
                QMessageBox.information(self, "提示", "请为所选制程至少勾选一个检测日期。")
            return False

        mgr = getattr(self, "_ort_db", None)
        if mgr is not None and show_tip:
            for process_name in processes:
                status = mgr.wi_table_storage_status(wi_product, process_name)
                if status.get("exists") and status.get("row_count", 0) > 0 and not status.get("has_cpk_column"):
                    n_bf = self._try_backfill_wi_cpk_from_workspace(wi_product, process_name)
                    if n_bf > 0:
                        QMessageBox.information(
                            self,
                            "已补写 Cpk",
                            f"制程「{process_name}」已从工作区补写 {n_bf} 行 Cpk。",
                        )
                    else:
                        QMessageBox.warning(
                            self,
                            "缺少 Cpk 数据",
                            f"制程「{process_name}」库内无 cpk 字段或数值，请检查映射模板后重新导入。",
                        )
                    break

        cache: dict[str, dict] = {}
        for process_name in processes:
            batch_dates = (
                picker.selected_dates(process_name) if picker is not None else []
            )
            if not batch_dates:
                continue
            date_slots = self._wi_cpk_date_slots(batch_dates)
            df = self._query_wi_cpk_overview_rows_for_process(process_name)
            order_map = self._wi_template_dimension_col_order(wi_product, process_name)
            groups, _ = self._aggregate_wi_cpk_groups(
                df,
                batch_dates=[d for d in date_slots if d],
                col_order_map=order_map,
            )
            cache[process_name] = {
                "groups": groups,
                "date_slots": date_slots,
            }
        self._wi_cpk_dashboard_cache = cache

        view = self._get_wi_view_process_name()
        if view not in cache:
            view = sorted(cache.keys(), key=lambda x: x.lower())[0] if cache else ""
        self._wi_view_process = view
        self._sync_wi_overview_process_chips()
        self._render_wi_cpk_from_cache()
        if hasattr(self, "wi_content_stack") and self.wi_content_stack.currentIndex() == 1:
            self._sync_wi_compare_process_chips()
            self._refresh_wi_compare_dimension_list()
        self._refresh_wi_report_table()
        return bool(cache)

