    def _on_wi_upload_report_template(self):
        wi_product = self._get_selected_wi_product_line()
        processes = self._get_wi_picker_process_names()
        if not wi_product:
            return QMessageBox.information(self, "提示", "请先在右上角选择产品。")
        if not processes:
            return QMessageBox.information(self, "提示", "请先在右上角至少选择一个制程。")

        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "上传报告模板",
            self.current_workspace_dir,
            DATA_IMPORT_DIALOG_FILTER,
        )
        if not file_path:
            return
        if not _is_supported_data_import_file(file_path):
            return QMessageBox.warning(self, "提示", DATA_IMPORT_UNSUPPORTED_MSG)

        config = self._parse_wi_report_template(file_path)
        if not config:
            return

        dest_xlsx, dest_json = self._wi_report_template_shared_paths(wi_product)[0]
        try:
            ext = _data_file_extension(file_path)
            if ext == ".csv":
                raw_df = _read_tabular_raw(file_path, sheet_name=0)
                raw_df.to_excel(dest_xlsx, index=False, header=False, engine="openpyxl")
            else:
                shutil.copy2(file_path, dest_xlsx)
            with open(dest_json, "w", encoding="utf-8") as fh:
                json.dump(config, fh, ensure_ascii=False, indent=2)
        except Exception as ex:
            return QMessageBox.critical(self, "保存失败", f"无法保存模板：\n{ex}")

        key = self._wi_report_template_store_key(wi_product)
        self._wi_report_template_store[key] = {
            "path": dest_xlsx,
            "config_path": dest_json,
            "config": config,
            "source_name": os.path.basename(file_path),
        }
        sp_row = int(config.get("start_point_row", -1)) + 1
        data_row = int(config.get("data_start_row", sp_row)) + 1
        n_pts = len(config.get("selected_cols") or [])
        QMessageBox.information(
            self, "模板已上传",
            f"产品「{wi_product}」模板已保存，适用于该产品下所有制程。\n"
            f"Start Point：第 {sp_row} 行\n"
            f"实测起始：第 {data_row} 行\n"
            f"测点列：{n_pts} 个",
        )
        self._refresh_wi_report_status()

    def _load_wi_report_template_entry(self, wi_product: str, process_name: str = "") -> dict | None:
        key = self._wi_report_template_store_key(wi_product)
        entry = (getattr(self, "_wi_report_template_store", None) or {}).get(key)
        if entry and os.path.isfile(entry.get("path", "")):
            return entry
        dest_xlsx, dest_json = "", ""
        for xlsx_path, json_path in self._wi_report_template_paths(wi_product, process_name):
            if os.path.isfile(xlsx_path):
                dest_xlsx, dest_json = xlsx_path, json_path
                break
        if not dest_xlsx:
            return None
        config = None
        if os.path.isfile(dest_json):
            try:
                with open(dest_json, "r", encoding="utf-8") as fh:
                    config = json.load(fh)
            except Exception:
                config = None
        if not config:
            config = self._parse_wi_report_template(dest_xlsx)
            if not config:
                return None
        entry = {
            "path": dest_xlsx,
            "config_path": dest_json,
            "config": config,
            "source_name": os.path.basename(dest_xlsx),
        }
        self._wi_report_template_store[key] = entry
        return entry

    def _query_wi_report_raw_rows(
        self, wi_product: str, process_name: str, batch_dates: list[str],
    ) -> pd.DataFrame:
        batch_dates = [str(d).strip()[:10] for d in (batch_dates or []) if str(d).strip()]
        if not batch_dates:
            return pd.DataFrame()
        mgr = getattr(self, "_ort_db", None)
        df = pd.DataFrame()
        if mgr is not None:
            df = mgr.query_wi_report_measurement_rows(wi_product, process_name, batch_dates)
        if df is None or df.empty:
            df = self._query_wi_report_raw_rows_from_memory(wi_product, process_name, batch_dates)
        return df if df is not None else pd.DataFrame()

    def _query_wi_report_raw_rows_from_memory(
        self, wi_product: str, process_name: str, batch_dates: list[str],
    ) -> pd.DataFrame:
        if self.current_df is None or self.current_df.empty:
            return pd.DataFrame()
        work = self.current_df.copy()
        if "value" not in work.columns or "point_name" not in work.columns:
            return pd.DataFrame()
        cfg = getattr(self, "current_mapping_config", None) or {}
        scope_process = str(cfg.get("product_name") or cfg.get("template_name") or "").strip()
        scope_product = str(cfg.get("wi_product") or cfg.get("category") or "").strip()
        if scope_process and scope_process != str(process_name).strip():
            return pd.DataFrame()
        if scope_product and wi_product and scope_product != str(wi_product).strip():
            return pd.DataFrame()
        bc_col = "barcode" if "barcode" in work.columns else ("machine_id" if "machine_id" in work.columns else None)
        if not bc_col:
            return pd.DataFrame()
        if "test_time" in work.columns:
            work["batch_date"] = work["test_time"].map(
                lambda v: ORTDatabaseManager._normalize_wi_test_time_value(v)
            )
        else:
            work["batch_date"] = ""
        keys = {str(d).strip()[:10] for d in batch_dates}
        work = work[work["batch_date"].isin(keys)].copy()
        if work.empty:
            return pd.DataFrame()
        out = pd.DataFrame({
            "test_time": work["batch_date"],
            "barcode": work[bc_col].fillna("").astype(str).str.strip(),
            "point_name": work["point_name"].fillna("").astype(str).str.strip(),
            "value": pd.to_numeric(work["value"], errors="coerce"),
        })
        if "special_attrs" in work.columns:
            out["special_attrs"] = work["special_attrs"]
        return out.dropna(subset=["value", "barcode", "point_name"])

    def _wi_export_scope_summary_text(self) -> str:
        """数据/报告导出区：仅展示当前选中的产品、制程与日期范围。"""
        wi_product = self._get_selected_wi_product_line() or "—"
        processes = self._get_wi_picker_process_names()
        if not processes:
            proc_txt = "—"
        elif len(processes) == 1:
            proc_txt = processes[0]
        elif len(processes) <= 3:
            proc_txt = "、".join(processes)
        else:
            proc_txt = f"{processes[0]} 等{len(processes)}个制程"

        picker = getattr(self, "wi_process_date_picker", None)
        all_dates: set[str] = set()
        if picker is not None:
            for proc in processes:
                for d in picker.selected_dates(proc):
                    all_dates.add(str(d).strip()[:10])
        dates = sorted(all_dates)
        if not dates:
            date_txt = "—"
        elif len(dates) <= 3:
            date_txt = "、".join(dates)
        else:
            date_txt = f"{dates[0]} … {dates[-1]}（共 {len(dates)} 天）"
        return f"已选产品：{wi_product} · 制程：{proc_txt} · 日期范围：{date_txt}"

    def _refresh_wi_report_status(self):
        """刷新数据报告页导出区状态（产品 / 制程 / 日期范围）。"""
        if not hasattr(self, "lbl_wi_report_scope_status"):
            return
        summary = self._wi_export_scope_summary_text()
        self.lbl_wi_report_scope_status.setText(summary)
        if hasattr(self, "lbl_wi_report_ppt_status"):
            self.lbl_wi_report_ppt_status.setText(summary)

    def _refresh_wi_report_table(self):
        try:
            self._refresh_wi_report_status()
        except Exception as ex:
            print(f"[WI Report] 刷新报告页状态失败：{ex}")

    @staticmethod
    def _wi_report_parse_special_attrs(raw) -> dict:
        if raw is None or (isinstance(raw, float) and pd.isna(raw)):
            return {}
        if isinstance(raw, dict):
            return raw
        text = str(raw).strip()
        if not text:
            return {}
        try:
            obj = json.loads(text)
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

    def _wi_report_build_samples(self, df: pd.DataFrame, batch_date: str, config: dict) -> list[dict]:
        if df is None or df.empty:
            return []
        date_key = str(batch_date).strip()[:10]
        sub = df[df["test_time"].astype(str).str[:10] == date_key].copy()
        if sub.empty:
            return []
        special_cols = config.get("special_attr_cols") or []
        point_names = {str(item[1]) for item in (config.get("selected_cols") or []) if len(item) > 1}
        samples: list[dict] = []
        for barcode, bdf in sub.groupby("barcode"):
            values: dict[str, float] = {}
            attrs: dict[int, object] = {}
            last_row = None
            for _, row in bdf.iterrows():
                last_row = row
                pn = str(row.get("point_name") or "").strip()
                if pn in point_names:
                    values[pn] = float(row["value"])
            if not values:
                continue
            sp_raw = self._wi_report_parse_special_attrs(
                last_row.get("special_attrs") if last_row is not None else None
            )
            for sc in special_cols:
                ci = int(sc.get("col_idx", -1))
                key = str(sc.get("key") or "")
                if ci < 0 or not key:
                    continue
                val = sp_raw.get(key)
                if val is not None and str(val).strip():
                    attrs[ci] = val
            samples.append({
                "barcode": str(barcode).strip(),
                "batch_date": date_key,
                "values": values,
                "special": attrs,
            })
        samples.sort(key=lambda x: x["barcode"])
        return samples

    def _wi_report_build_merged_samples(
        self, df: pd.DataFrame, batch_dates: list[str], config: dict,
    ) -> list[dict]:
        """合并多日期样本，按日期从旧到新、同日内按样本号排序。"""
        dates_sorted = sorted(
            {str(d).strip()[:10] for d in (batch_dates or []) if str(d).strip()},
            key=str,
        )
        merged: list[dict] = []
        for date_key in dates_sorted:
            merged.extend(self._wi_report_build_samples(df, date_key, config))
        return merged

    def _wi_report_format_cell_date(self, date_str: str) -> str:
        return self._wi_format_display_date(date_str)

    def _wi_report_insert_date_column(self, ws, config: dict) -> tuple[dict, int]:
        """在 Start Point（样本号）列左侧插入 Date 列，返回更新后的 config 与日期列 0-based 索引。"""
        insert_at = int(config.get("machine_id_col", config.get("label_col", 2)))
        ws.insert_cols(insert_at + 1)

        cfg = copy.deepcopy(config)
        cfg["date_col_idx"] = insert_at

        def _shift_col_idx(col_idx: int) -> int:
            return col_idx + 1 if col_idx >= insert_at else col_idx

        cfg["machine_id_col"] = _shift_col_idx(int(cfg.get("machine_id_col", insert_at)))
        cfg["label_col"] = _shift_col_idx(int(cfg.get("label_col", insert_at)))
        cfg["core_param_start_col"] = _shift_col_idx(int(cfg.get("core_param_start_col", insert_at + 1)))
        cfg["core_param_end_col"] = _shift_col_idx(int(cfg.get("core_param_end_col", insert_at)))

        shifted_cols: list[tuple] = []
        for item in cfg.get("selected_cols") or []:
            c = int(item[0])
            if c >= insert_at:
                c += 1
            shifted_cols.append((c, *item[1:]))
        cfg["selected_cols"] = shifted_cols

        for sc in cfg.get("special_attr_cols") or []:
            ci = int(sc.get("col_idx", -1))
            if ci >= insert_at:
                sc["col_idx"] = ci + 1

        sp_row = int(cfg.get("start_point_row", -1)) + 1
        if sp_row > 0:
            ws.cell(sp_row, insert_at + 1).value = "Date"
        self._wi_report_shift_formula_cols_after_insert(ws, insert_at)
        return cfg, insert_at

    @staticmethod
    def _wi_report_shift_formula_cols_after_insert(ws, insert_at_0: int) -> None:
        """插入日期列后，将原核心参数列及其右侧的公式列引用整体右移一列。"""
        max_col = ws.max_column
        col_map: dict[str, str] = {}
        for c in range(max_col - 2, insert_at_0 - 1, -1):
            old_letter = WeeklyInspectionMappingWizard._col_excel_label(c)
            new_letter = WeeklyInspectionMappingWizard._col_excel_label(c + 1)
            col_map[old_letter] = new_letter
        if not col_map:
            return

        def _shift_formula(formula: str) -> str:
            out = formula
            for old, new in sorted(col_map.items(), key=lambda x: -len(x[0])):
                out = re.sub(
                    rf"(?<![A-Z]){re.escape(old)}(\d+)",
                    lambda m, new_letter=new: f"{new_letter}{m.group(1)}",
                    out,
                    flags=re.IGNORECASE,
                )
            return out

        for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=max_col):
            for cell in row:
                val = cell.value
                if isinstance(val, str) and val.startswith("="):
                    shifted = _shift_formula(val)
                    if shifted != val:
                        cell.value = shifted

    @staticmethod
    def _wi_report_excel_col_letter(col_idx_0: int) -> str:
        n = int(col_idx_0) + 1
        letters = ""
        while n > 0:
            n, rem = divmod(n - 1, 26)
            letters = chr(65 + rem) + letters
        return letters

    def _wi_report_update_template_date(self, ws, report_dates) -> None:
        if isinstance(report_dates, str):
            report_dates = [report_dates]
        dates = [str(d).strip()[:10] for d in (report_dates or []) if str(d).strip()]
        if not dates:
            return
        dates_sorted = sorted(set(dates), key=str)
        if len(dates_sorted) == 1:
            display = self._wi_report_format_cell_date(dates_sorted[0])
        else:
            display = (
                f"{self._wi_report_format_cell_date(dates_sorted[0])}"
                f" - {self._wi_report_format_cell_date(dates_sorted[-1])}"
            )
        for r in range(1, 8):
            for c in range(1, min(20, ws.max_column + 1)):
                cell = ws.cell(r, c)
                val = str(cell.value or "").strip().lower()
                if val.startswith("date") or val == "date:":
                    ws.cell(r, c + 1).value = display
                    return

    def _wi_report_update_core_formulas(self, ws, config: dict, data_start_1: int, data_end_1: int) -> None:
        if data_end_1 < data_start_1:
            return
        tpl_start = int(config.get("data_start_row", data_start_1 - 1)) + 1
        core_rows = config.get("special_core_rows") or []
        point_cols = [int(item[0]) for item in (config.get("selected_cols") or []) if item]
        row_idxs = {int(sr.get("row_idx", -1)) + 1 for sr in core_rows if int(sr.get("row_idx", -1)) >= 0}
        for row_1 in sorted(row_idxs):
            for col_0 in point_cols:
                cell = ws.cell(row_1, col_0 + 1)
                val = cell.value
                if not isinstance(val, str) or not val.startswith("="):
                    continue
                col_letter = self._wi_report_excel_col_letter(col_0)
                new_val = re.sub(
                    rf"({col_letter})(\d+):({col_letter})(\d+)",
                    lambda m: (
                        f"{m.group(1)}{data_start_1}:{m.group(3)}{data_end_1}"
                        if int(m.group(2)) >= tpl_start - 5
                        else m.group(0)
                    ),
                    val,
                    flags=re.IGNORECASE,
                )
                if new_val != val:
                    cell.value = new_val

    def _wi_report_fill_template_sheet(
        self, ws, config: dict, samples: list[dict], report_dates,
    ) -> None:
        config, date_col = self._wi_report_insert_date_column(ws, config)

        data_start_0 = int(config.get("data_start_row", 40))
        data_start_1 = data_start_0 + 1
        label_col = int(config.get("machine_id_col", config.get("label_col", 0)))
        special_cols = config.get("special_attr_cols") or []
        point_cols = config.get("selected_cols") or []
        core_start = int(config.get("core_param_start_col", 1))
        core_end = int(config.get("core_param_end_col", ws.max_column - 1))

        old_end_0 = data_start_0
        for r in range(data_start_0, ws.max_row):
            r1 = r + 1
            has_val = False
            for c in range(core_start, min(core_end, ws.max_column - 1) + 1):
                if ws.cell(r1, c + 1).value not in (None, ""):
                    has_val = True
                    break
            if has_val:
                old_end_0 = r

        clear_end_1 = max(old_end_0, data_start_0 + max(len(samples), 1) - 1) + 1
        for r1 in range(data_start_1, clear_end_1 + 1):
            ws.cell(r1, date_col + 1).value = None
            for sc in special_cols:
                ws.cell(r1, int(sc["col_idx"]) + 1).value = None
            ws.cell(r1, label_col + 1).value = None
            for item in point_cols:
                ws.cell(r1, int(item[0]) + 1).value = None

        for i, samp in enumerate(samples):
            r1 = data_start_1 + i
            batch_date = samp.get("batch_date", "")
            if batch_date:
                ws.cell(r1, date_col + 1).value = self._wi_report_format_cell_date(batch_date)
            for sc in special_cols:
                ci = int(sc["col_idx"])
                if ci in samp.get("special", {}):
                    ws.cell(r1, ci + 1).value = samp["special"][ci]
            ws.cell(r1, label_col + 1).value = samp.get("barcode", "")
            for item in point_cols:
                ci = int(item[0])
                pn = str(item[1])
                if pn in samp.get("values", {}):
                    ws.cell(r1, ci + 1).value = samp["values"][pn]

        data_end_1 = data_start_1 + len(samples) - 1 if samples else data_start_1
        self._wi_report_update_template_date(ws, report_dates)
        self._wi_report_update_core_formulas(ws, config, data_start_1, data_end_1)

    def _wi_report_export_filename(self, process_name: str, dates: list[str]) -> str:
        dates_sorted = sorted({str(d).strip()[:10] for d in (dates or []) if str(d).strip()}, key=str)
        safe_proc = re.sub(r"[\\/*?:\[\]]+", "_", str(process_name or "").strip()) or "Report"
        if not dates_sorted:
            return f"{safe_proc}.xlsx"
        d0 = self._wi_format_display_date(dates_sorted[0])
        d1 = self._wi_format_display_date(dates_sorted[-1])
        range_part = d0 if d0 == d1 else f"{d0}_{d1}"
        return f"{safe_proc}_{range_part}.xlsx"

    def _wi_report_write_export_file(
        self, entry: dict, samples: list[dict], config: dict, dates: list[str], file_path: str,
    ) -> None:
        from openpyxl import load_workbook

        shutil.copy2(entry["path"], file_path)
        wb = load_workbook(file_path)
        ws = wb.active
        self._wi_report_fill_template_sheet(ws, config, samples, dates)
        wb.save(file_path)
        wb.close()

    def _export_wi_report_data(self):
        """按报告模板导出数据（保留模板格式与核心统计公式）。"""
        wi_product = self._get_selected_wi_product_line()
        processes = self._get_wi_picker_process_names()
        if not wi_product:
            return QMessageBox.warning(self, "提示", "请先在右上角选择产品。")
        if not processes:
            return QMessageBox.warning(self, "提示", "请先在右上角至少选择一个制程。")

        picker = getattr(self, "wi_process_date_picker", None)
        template_entry = self._load_wi_report_template_entry(wi_product)
        if not template_entry:
            return QMessageBox.warning(self, "缺少模板", "请先上传报告模板（同一产品下所有制程共用一份）。")

        export_jobs: list[tuple[str, list[dict], list[str]]] = []
        for proc in processes:
            dates = sorted(picker.selected_dates(proc) if picker is not None else [], key=str)
            if not dates:
                continue
            df = self._query_wi_report_raw_rows(wi_product, proc, dates)
            if df.empty:
                continue
            config = template_entry["config"]
            samples = self._wi_report_build_merged_samples(df, dates, config)
            if samples:
                export_jobs.append((proc, samples, dates))

        if not export_jobs:
            return QMessageBox.warning(
                self, "提示",
                "当前没有可导出的实测数据。请确认已选择检测日期并点击「刷新」。",
            )

        export_dir = QFileDialog.getExistingDirectory(
            self,
            "选择导出文件夹",
            self._get_desktop_dir(),
        )
        if not export_dir:
            return

        try:
            exported_files: list[str] = []
            total_rows = 0
            config = template_entry["config"]
            for proc, samples, dates in export_jobs:
                file_name = self._wi_report_export_filename(proc, dates)
                file_path = os.path.join(export_dir, file_name)
                if os.path.isfile(file_path):
                    base, ext = os.path.splitext(file_name)
                    suffix = 1
                    while os.path.isfile(file_path):
                        file_path = os.path.join(export_dir, f"{base}_{suffix}{ext}")
                        suffix += 1
                self._wi_report_write_export_file(template_entry, samples, config, dates, file_path)
                exported_files.append(file_path)
                total_rows += len(samples)

            date_count = sum(len(dates) for _, _, dates in export_jobs)
            file_lines = "\n".join(exported_files[:6])
            if len(exported_files) > 6:
                file_lines += f"\n… 共 {len(exported_files)} 个文件"
            QMessageBox.information(
                self, "导出成功",
                f"已导出 {len(exported_files)} 个 Excel 文件，共 {date_count} 个检测日期、{total_rows} 条样本：\n{file_lines}",
            )
        except Exception as ex:
            import traceback
            QMessageBox.critical(self, "导出失败", f"导出 Excel 时发生错误：\n{ex}\n{traceback.format_exc()}")

    @staticmethod
    def _wi_report_ppt_date_range_label(dates: list[str]) -> str:
        keys = sorted({str(d).strip()[:10] for d in (dates or []) if str(d).strip()}, key=str)
        if not keys:
            return ""
        d0 = ORTAnalyseSystem._wi_format_display_date(keys[0])
        d1 = ORTAnalyseSystem._wi_format_display_date(keys[-1])
        return d0 if d0 == d1 else f"{d0} ~ {d1}"

    # Weekly Inspection PPT 导出版式常量（与幻灯片 13.333×7.5 英寸一致）
    _WI_PPT_SLIDE_W = 13.333
    _WI_PPT_SLIDE_H = 7.5
    _WI_PPT_MARGIN = 0.10
    _WI_PPT_STACK_GAP = 0.06
    _WI_PPT_HALF_H = (_WI_PPT_SLIDE_H - 2 * _WI_PPT_MARGIN - _WI_PPT_STACK_GAP) / 2.0
    _WI_PPT_DIM_FIG_W = 9.2
    _WI_PPT_DIM_FIG_H = 7.35
    _WI_PPT_EXPORT_DPI = 260
    _WI_PPT_DIM_LEFT_MARGIN = 0.40
    _WI_PPT_DIM_RIGHT_MARGIN = 0.55

    @staticmethod
    def _wi_ppt_fill_slide_rect(
        *,
        slide_w_in: float = 13.333,
        slide_h_in: float = 7.5,
        margin_in: float = 0.08,
    ) -> dict:
        """整页贴图（PNG 与幻灯片同宽高比时使用）。"""
        return {
            "left": margin_in * 72,
            "top": margin_in * 72,
            "width": max(slide_w_in - 2 * margin_in, 0.5) * 72,
            "height": max(slide_h_in - 2 * margin_in, 0.5) * 72,
        }

    @staticmethod
    def _wi_ppt_stack_picture_rects(
        png_paths: list[str],
        *,
        slide_w_in: float = 13.333,
        slide_h_in: float = 7.5,
        margin_in: float = 0.10,
        gap_in: float = 0.06,
    ) -> list[dict]:
        """纵向堆叠多张图，均分可用高度并保持各自宽高比。"""
        paths = [p for p in (png_paths or []) if p and os.path.isfile(p)]
        if not paths:
            return []
        n = len(paths)
        usable_w = max(slide_w_in - 2 * margin_in, 1.0)
        slot_h = max((slide_h_in - 2 * margin_in - gap_in) / 2.0, 0.5)
        total_h = slot_h * n + gap_in * max(n - 1, 0)
        start_top = margin_in + max(0.0, (slide_h_in - 2 * margin_in - total_h) / 2.0)
        rects: list[dict] = []
        for i, png_path in enumerate(paths):
            img_w, img_h = ORTAnalyseSystem._png_pixel_size(png_path)
            if img_w > 0 and img_h > 0:
                img_aspect = img_w / img_h
                slot_aspect = usable_w / slot_h
                if slot_aspect > img_aspect:
                    height = slot_h
                    width = height * img_aspect
                else:
                    width = usable_w
                    height = width / img_aspect
            else:
                width, height = usable_w, slot_h
            left = (slide_w_in - width) / 2.0
            top = start_top + i * (slot_h + gap_in) + max(0.0, (slot_h - height) / 2.0)
            rects.append({
                "left": left * 72,
                "top": top * 72,
                "width": width * 72,
                "height": height * 72,
            })
        return rects

    @staticmethod
    def _png_pixel_size(path: str) -> tuple[int, int]:
        """读取 PNG 像素尺寸（无需 PIL）。"""
        import struct
        try:
            with open(path, "rb") as f:
                if f.read(8) != b"\x89PNG\r\n\x1a\n":
                    return 0, 0
                f.read(4)
                if f.read(4) != b"IHDR":
                    return 0, 0
                w, h = struct.unpack(">II", f.read(8))
                return int(w), int(h)
        except Exception:
            return 0, 0

    @staticmethod
    def _wi_ppt_fit_picture_rect(
        png_path: str,
        *,
        slide_w_in: float = 13.333,
        slide_h_in: float = 7.5,
        margin_in: float = 0.16,
        margin_right_in: float | None = None,
        top_in: float = 0.10,
        align: str = "center",
    ) -> dict:
        """按 PNG 原始宽高比在幻灯片上贴图（坐标单位：磅 pt）。"""
        img_w, img_h = ORTAnalyseSystem._png_pixel_size(png_path)
        margin_right = margin_in if margin_right_in is None else margin_right_in
        usable_w = max(slide_w_in - margin_in - margin_right, 1.0)
        usable_h = max(slide_h_in - top_in - margin_in, 1.0)
        if img_w > 0 and img_h > 0:
            aspect = img_w / img_h
            box_aspect = usable_w / usable_h
            if box_aspect > aspect:
                height = usable_h
                width = height * aspect
            else:
                width = usable_w
                height = width / aspect
        else:
            width, height = usable_w, usable_h
        align_key = str(align or "center").lower()
        if align_key == "left":
            left = margin_in
        elif align_key == "right":
            left = slide_w_in - margin_right - width
        else:
            left = (slide_w_in - width) / 2.0
        top = top_in + max(0.0, (usable_h - height) / 2.0)
        return {
            "left": left * 72,
            "top": top * 72,
            "width": width * 72,
            "height": height * 72,
        }

    def _wi_report_ppt_slide_title_line(self, grp: dict, date_slots: list[str | None]) -> str:
        diag = self._wi_cpk_status_diagnosis(grp, date_slots=date_slots)
        status = str(diag.get("label") or "数据不足")
        badge_letter, _ = self._wi_distribution_badge(str(grp.get("distribution_type") or ""))
        label = self._wi_cpk_row_label(grp) or "—"
        return f"{status}    {badge_letter}    {label}"

    @staticmethod
    def _wi_report_ppt_save_figure(fig, prefix: str = "wi_ppt", *, fixed_bbox: bool = False, dpi: int = 260) -> str:
        import matplotlib.pyplot as plt

        fd, path = tempfile.mkstemp(prefix=f"{prefix}_", suffix=".png")
        os.close(fd)
        try:
            if fixed_bbox:
                fig.savefig(path, dpi=dpi, bbox_inches=None, pad_inches=0, facecolor="white")
            else:
                fig.savefig(path, dpi=dpi, bbox_inches="tight", facecolor="white", pad_inches=0.06)
        finally:
            plt.close(fig)
        return path

    def _render_wi_overview_table_figure(
        self,
        process_name: str,
        groups: list[dict],
        date_slots: list[str | None],
    ):
        """01 数据总览：质量指标纵览表（供 PPT 首页，固定幻灯片宽高比）。"""
        from matplotlib.figure import Figure

        slots = list(date_slots or [])[:4]
        while len(slots) < 4:
            slots.append(None)
        valid_dates = [d for d in slots if d]
        date_range = self._wi_report_ppt_date_range_label(valid_dates)
        title = f"{process_name}  {date_range}  质量指标纵览".strip()

        n_rows = max(len(groups), 1)
        fig = Figure(
            figsize=(self._WI_PPT_SLIDE_W, self._WI_PPT_SLIDE_H),
            dpi=self._WI_PPT_EXPORT_DPI,
        )
        ax = fig.add_subplot(111)
        ax.axis("off")

        col_labels = ["Dimension"]
        for d in slots:
            disp = self._wi_format_display_date(d) if d else "—"
            col_labels.extend([f"{disp}\nCp", "Cpk", "Py"])
        col_labels.append("状态评估")

        table_rows: list[list[str]] = []
        cell_colors: list[list[str]] = []
        header_bg = "#E8F1F8"
        for grp in groups:
            dim_txt = self._wi_cpk_row_label(grp)
            badge, _ = self._wi_distribution_badge(str(grp.get("distribution_type") or ""))
            if badge and not dim_txt.startswith(badge):
                dim_txt = f"{badge}  {dim_txt}"
            row = [dim_txt]
            colors = ["#FFFFFF"]
            by_date = grp.get("by_date") or {}
            for d in slots:
                sm = by_date.get(d) if d else None
                if sm:
                    cpk_v = self._wi_cpk_display_cpk_for_slot(grp, sm)
                    cp_txt = self._wi_fmt_cpk_metric(sm.get("cp"))
                    cpk_txt = self._wi_fmt_cpk_metric(cpk_v)
                    py_txt = self._wi_fmt_projected_yield(sm.get("projected_yield_min"))
                    row.extend([cp_txt, cpk_txt, py_txt])
                    colors.extend(["#FFFFFF", "#FFFFFF", "#FFFFFF"])
                else:
                    row.extend(["—", "—", "—"])
                    colors.extend(["#FFFFFF", "#FFFFFF", "#FFFFFF"])
            status, status_bg = self._wi_cpk_status_evaluation(grp, date_slots=slots)
            row.append(status)
            colors.append(status_bg)
            table_rows.append(row)
            cell_colors.append(colors)

        metric_text_colors: list[list[str]] = []
        for grp, row in zip(groups, table_rows):
            mcolors = ["#2C3E50"]
            by_date = grp.get("by_date") or {}
            for d in slots:
                sm = by_date.get(d) if d else None
                if sm:
                    cpk_v = self._wi_cpk_display_cpk_for_slot(grp, sm)
                    mcolors.extend([
                        self._wi_cpk_index_color(sm.get("cp")),
                        self._wi_cpk_index_color(cpk_v),
                        self._wi_projected_yield_color(sm.get("projected_yield_min")),
                    ])
                else:
                    mcolors.extend(["#6B8299", "#6B8299", "#6B8299"])
            mcolors.append("#FFFFFF")
            metric_text_colors.append(mcolors)

        if not table_rows:
            table_rows = [["（暂无数据）"] + ["—"] * (len(col_labels) - 1)]
            cell_colors = [["#FFFFFF"] * len(col_labels)]

        n_cols = len(col_labels)
        metric_cols = max(n_cols - 2, 1)
        col_widths = [0.42] + [0.42 / metric_cols] * metric_cols + [0.16]
        col_widths = [w / sum(col_widths) for w in col_widths]

        tbl = ax.table(
            cellText=table_rows,
            colLabels=col_labels,
            loc="center",
            cellLoc="center",
            colWidths=col_widths,
        )
        tbl.auto_set_font_size(False)
        row_font = max(5.0, min(7.2, 7.0 - n_rows * 0.035))
        tbl.set_fontsize(row_font)

        row_h = min(0.085, max(0.028, 0.78 / max(n_rows + 1, 1)))
        for (r, c), cell in tbl.get_celld().items():
            cell.set_edgecolor("#D5E3F0")
            cell.set_linewidth(0.6)
            if r == 0:
                cell.set_facecolor(header_bg)
                cell.set_text_props(weight="bold", color="#2C3E50", fontsize=row_font)
                cell.set_height(row_h * 1.05)
            else:
                ridx = r - 1
                if ridx < len(cell_colors) and c < n_cols:
                    cell.set_facecolor(cell_colors[ridx][c])
                if ridx < len(metric_text_colors) and c < n_cols:
                    fg = metric_text_colors[ridx][c]
                    if c == n_cols - 1:
                        cell.set_text_props(color="#FFFFFF", weight="bold", fontsize=row_font)
                    elif c == 0:
                        cell.set_text_props(color="#2C3E50", fontsize=row_font, ha="left", wrap=True)
                        cell._loc = "left"
                    else:
                        cell.set_text_props(color=fg, weight="bold", fontsize=row_font)
                cell.set_height(row_h)

        fig.suptitle(title, fontsize=11, fontweight="bold", color="#2C3E50", y=0.97)
        fig.subplots_adjust(top=0.90, bottom=0.04, left=0.03, right=0.97)
        return fig

    def _render_wi_compare_charts_on_figure(
        self, fig, grp: dict, plot_df: pd.DataFrame, *, compact: bool = False, for_export: bool = False,
    ) -> bool:
        """在指定 Figure 上绘制 02 异常分析图表（箱线 / 折线 / 靶心）。"""
        from matplotlib.gridspec import GridSpec

        if grp is None or plot_df is None or plot_df.empty:
            return False

        meta = self._wi_compare_analyze_points(grp, plot_df)
        chart_title = "" if for_export else self._wi_compare_chart_title(grp)
        xy_bases = meta["xy_bases"]
        n_targets = len(xy_bases)
        line_will_show = bool(meta["multi_column"] and meta["scalar_points"])
        unique_dates = sorted(plot_df["test_time"].dropna().unique().tolist(), key=str) if "test_time" in plot_df.columns else []
        n_dates = len(unique_dates)

        # 判断是否为位置度/轮廓度尺寸（导出时只显示靶心图）
        is_positional = self._wi_compare_is_positional_tolerance(grp, meta) if for_export else False

        box_show_xlabels = True
        box_show_date_row = True
        line_show_xlabels = True
        line_show_date_row = True
        target_axes: list = []
        axes_grid: list[list] = []
        hier_gap = 0.26

        if for_export:
            if n_targets == 0:
                export_hspace = 0.82
                gs = GridSpec(2, 1, figure=fig, height_ratios=[1.08, 1.15], hspace=export_hspace)
                ax_box = fig.add_subplot(gs[0, 0])
                ax_line = fig.add_subplot(gs[1, 0])
            elif is_positional:
                # 位置度尺寸：只显示靶心图
                if n_dates > 0:
                    gs_t = GridSpec(n_targets, n_dates, figure=fig, wspace=0.20, hspace=0.28)
                    for ri in range(n_targets):
                        row_axes = []
                        for ci in range(n_dates):
                            row_axes.append(fig.add_subplot(gs_t[ri, ci]))
                        axes_grid.append(row_axes)
                else:
                    gs_t = GridSpec(1, n_targets, figure=fig, wspace=0.20)
                    for ti in range(n_targets):
                        target_axes.append(fig.add_subplot(gs_t[0, ti]))
                # 占位，不会实际绘制
                ax_box = None
                ax_line = None
            else:
                export_hspace = 0.62
                target_row_h = max(0.62, min(1.15, 0.42 + n_targets * 0.14))
                gs = GridSpec(
                    3, 1, figure=fig,
                    height_ratios=[1.0, 1.08, target_row_h],
                    hspace=export_hspace,
                )
                ax_box = fig.add_subplot(gs[0, 0])
                ax_line = fig.add_subplot(gs[1, 0])
                if n_dates > 0:
                    gs_t = gs[2, 0].subgridspec(n_targets, n_dates, wspace=0.20, hspace=0.28)
                    for ri in range(n_targets):
                        row_axes = []
                        for ci in range(n_dates):
                            row_axes.append(fig.add_subplot(gs_t[ri, ci]))
                        axes_grid.append(row_axes)
                else:
                    gs_t = gs[2, 0].subgridspec(1, n_targets, wspace=0.20)
                    for ti in range(n_targets):
                        target_axes.append(fig.add_subplot(gs_t[0, ti]))
        else:
            if compact:
                target_row_h = max(0.28, min(0.65, 0.16 + n_targets * 0.10)) if n_targets else 0.22
                row_h = 0.62
                hier_gap = 0.28 if n_targets else 0.24
            else:
                target_row_h = max(0.42, min(1.0, 0.32 + n_targets * 0.18)) if n_targets else 0.32
                row_h = 0.82
                hier_gap = 0.42 if n_targets else 0.34

            gs = GridSpec(
                3, 1, figure=fig,
                height_ratios=[row_h, row_h, target_row_h],
                hspace=hier_gap,
            )
            ax_box = fig.add_subplot(gs[0, 0])
            ax_line = fig.add_subplot(gs[1, 0])
            if n_targets > 0 and n_dates > 0:
                gs_t = gs[2, 0].subgridspec(n_targets, n_dates, wspace=0.18 if compact else 0.22, hspace=0.22 if compact else 0.30)
                for ri in range(n_targets):
                    row_axes = []
                    for ci in range(n_dates):
                        row_axes.append(fig.add_subplot(gs_t[ri, ci]))
                    axes_grid.append(row_axes)
            elif n_targets > 0:
                gs_t = gs[2, 0].subgridspec(1, n_targets, wspace=0.18 if compact else 0.22)
                for ti in range(n_targets):
                    target_axes.append(fig.add_subplot(gs_t[0, ti]))
            else:
                ax_tgt_placeholder = fig.add_subplot(gs[2, 0])
                self._wi_compare_plot_empty_panel(
                    ax_tgt_placeholder, "本尺寸无 X/Y 坐标对\n无需靶心图", title="",
                )

        # 绘制箱线图（位置度尺寸不绘制）
        if ax_box is not None:
            self._plot_wi_compare_box(
                ax_box, plot_df, grp, meta,
                show_xlabels=box_show_xlabels, show_date_row=box_show_date_row, show_title=not for_export,
            )
            if for_export:
                ax_box.text(
                    0.01, 0.98, "箱线图", transform=ax_box.transAxes,
                    fontsize=9, fontweight="bold", color="#64748B", va="top", ha="left",
                )
        
        # 绘制折线图（位置度尺寸不绘制）
        if ax_line is not None:
            if line_will_show:
                self._plot_wi_compare_line(
                    ax_line, plot_df, grp, meta,
                    show_xlabels=line_show_xlabels, show_date_row=line_show_date_row, show_title=False,
                )
                if for_export:
                    ax_line.text(
                        0.01, 0.98, "折线图", transform=ax_line.transAxes,
                        fontsize=9, fontweight="bold", color="#64748B", va="top", ha="left",
                    )
            elif meta["multi_column"]:
                self._wi_compare_plot_empty_panel(
                    ax_line, "本组仅有 X/Y 坐标对\n无标量测点折线", title="",
                )
            else:
                self._wi_compare_plot_empty_panel(
                    ax_line, "单列尺寸\n不生成折线图", title="",
                )
        
        # 绘制靶心图
        if n_targets and axes_grid:
            self._plot_wi_compare_targets(axes_grid, plot_df, grp, xy_bases, unique_dates)

        if for_export:
            if is_positional:
                # 位置度尺寸：只显示靶心图，调整布局
                try:
                    fig.subplots_adjust(
                        left=0.05, right=0.97, top=0.88, bottom=0.10, hspace=0.28,
                    )
                except Exception:
                    pass
            else:
                export_hspace = 0.82 if n_targets == 0 else 0.62
                # 增加底部边距，给 X 轴标签留出更多空间
                try:
                    fig.subplots_adjust(
                        left=0.05, right=0.97, top=0.84, bottom=0.14, hspace=export_hspace,
                    )
                except Exception:
                    pass
        elif meta["multi_column"] and line_will_show:
            bottom_margin, adj_hspace = (0.14 if compact else 0.16), hier_gap
            try:
                fig.subplots_adjust(
                    left=0.07, right=0.98, top=0.90, bottom=bottom_margin, hspace=adj_hspace,
                )
            except Exception:
                pass
        elif meta["multi_column"]:
            bottom_margin, adj_hspace = (0.14 if compact else 0.16), hier_gap
            try:
                fig.subplots_adjust(
                    left=0.07, right=0.98, top=0.90, bottom=bottom_margin, hspace=adj_hspace,
                )
            except Exception:
                pass
        else:
            bottom_margin, adj_hspace = (0.10 if compact else 0.12), 0.20 if compact else 0.24
            try:
                fig.subplots_adjust(
                    left=0.07, right=0.98, top=0.90, bottom=bottom_margin, hspace=adj_hspace,
                )
            except Exception:
                pass
        return True

    def _render_wi_compare_export_figure(
        self, grp: dict, plot_df: pd.DataFrame, date_slots: list[str | None],
    ) -> list[Figure]:
        """尺寸对比图（含图4式页眉），供 PPT 导出。返回 Figure 列表（箱线图和折线图分开）。"""
        from matplotlib.figure import Figure

        if plot_df is None or plot_df.empty:
            return []

        diag = self._wi_cpk_status_diagnosis(grp, date_slots=date_slots)
        status = str(diag.get("label") or "数据不足")
        status_bg, status_fg = self._wi_cpk_status_colors(status)
        badge_letter, badge_color = self._wi_distribution_badge(str(grp.get("distribution_type") or ""))
        title_rest = self._wi_cpk_row_label(grp) or "—"

        meta = self._wi_compare_analyze_points(grp, plot_df)
        xy_bases = meta["xy_bases"]
        n_targets = len(xy_bases)
        line_will_show = bool(meta["multi_column"] and meta["scalar_points"])
        
        # 判断是否为位置度/轮廓度尺寸
        is_positional = self._wi_compare_is_positional_tolerance(grp, meta)
        
        fig_w = self._WI_PPT_DIM_FIG_W
        fig_h = self._WI_PPT_DIM_FIG_H
        figures: list[Figure] = []
        
        # 位置度尺寸：只生成靶心图
        if is_positional and n_targets > 0:
            fig = Figure(figsize=(fig_w, fig_h), dpi=self._WI_PPT_EXPORT_DPI)
            from matplotlib.gridspec import GridSpec
            unique_dates = sorted(plot_df["test_time"].dropna().unique().tolist(), key=str) if "test_time" in plot_df.columns else []
            n_dates = len(unique_dates)
            if n_dates > 0:
                gs_t = GridSpec(n_targets, n_dates, figure=fig, wspace=0.20, hspace=0.28)
                axes_grid = []
                for ri in range(n_targets):
                    row_axes = []
                    for ci in range(n_dates):
                        row_axes.append(fig.add_subplot(gs_t[ri, ci]))
                    axes_grid.append(row_axes)
                self._plot_wi_compare_targets(axes_grid, plot_df, grp, xy_bases, unique_dates)
            else:
                gs_t = GridSpec(1, n_targets, figure=fig, wspace=0.20)
                target_axes = []
                for ti in range(n_targets):
                    target_axes.append(fig.add_subplot(gs_t[0, ti]))
                # 绘制靶心图到 target_axes
                self._plot_wi_compare_targets([target_axes], plot_df, grp, xy_bases, unique_dates)
            try:
                fig.subplots_adjust(left=0.05, right=0.97, top=0.95, bottom=0.10, hspace=0.28)
            except Exception:
                pass
            figures.append(fig)
            return figures
        
        # 非位置度尺寸：生成箱线图和折线图（合并）
        fig_combo = Figure(figsize=(fig_w, fig_h), dpi=self._WI_PPT_EXPORT_DPI)
        from matplotlib.gridspec import GridSpec
        
        if line_will_show:
            gs = GridSpec(2, 1, figure=fig_combo, height_ratios=[1.0, 1.0], hspace=0.45)
            ax_box = fig_combo.add_subplot(gs[0, 0])
            ax_line = fig_combo.add_subplot(gs[1, 0])
        else:
            gs = GridSpec(1, 1, figure=fig_combo)
            ax_box = fig_combo.add_subplot(gs[0, 0])
            ax_line = None

        self._plot_wi_compare_box(ax_box, plot_df, grp, meta, show_xlabels=True, show_date_row=True, show_title=False)
        ax_box.text(0.01, 0.98, "箱线图", transform=ax_box.transAxes,
                   fontsize=9, fontweight="bold", color="#64748B", va="top", ha="left")
        
        if ax_line is not None:
            self._plot_wi_compare_line(ax_line, plot_df, grp, meta, show_xlabels=True, show_date_row=True, show_title=False)
            ax_line.text(0.01, 0.98, "折线图", transform=ax_line.transAxes,
                        fontsize=9, fontweight="bold", color="#64748B", va="top", ha="left")

        try:
            if ax_line is not None:
                fig_combo.subplots_adjust(left=0.06, right=0.97, top=0.95, bottom=0.10)
            else:
                fig_combo.subplots_adjust(left=0.06, right=0.97, top=0.95, bottom=0.14)
        except Exception:
            pass

        figures.append(fig_combo)

        # 靶心图（如果有，作为独立一页）
        if n_targets > 0:
            fig_tgt = Figure(figsize=(fig_w, fig_h), dpi=self._WI_PPT_EXPORT_DPI)
            unique_dates = sorted(plot_df["test_time"].dropna().unique().tolist(), key=str) if "test_time" in plot_df.columns else []
            n_dates = len(unique_dates)
            if n_dates > 0:
                gs_t = GridSpec(n_targets, n_dates, figure=fig_tgt, wspace=0.20, hspace=0.28)
                axes_grid = []
                for ri in range(n_targets):
                    row_axes = []
                    for ci in range(n_dates):
                        row_axes.append(fig_tgt.add_subplot(gs_t[ri, ci]))
                    axes_grid.append(row_axes)
                self._plot_wi_compare_targets(axes_grid, plot_df, grp, xy_bases, unique_dates)
            else:
                gs_t = GridSpec(1, n_targets, figure=fig_tgt, wspace=0.20)
                target_axes = []
                for ti in range(n_targets):
                    target_axes.append(fig_tgt.add_subplot(gs_t[0, ti]))
                self._plot_wi_compare_targets([target_axes], plot_df, grp, xy_bases, unique_dates)
            try:
                fig_tgt.subplots_adjust(left=0.05, right=0.97, top=0.95, bottom=0.10, hspace=0.28)
            except Exception:
                pass
            figures.append(fig_tgt)
        
        return figures

    def _build_wi_report_ppt_slides(
        self, wi_product: str, process_name: str, groups: list[dict], date_slots: list[str | None],
    ) -> list[dict]:
        slides: list[dict] = []
        
        # 获取筛选条件
        filters = getattr(self, "_wi_dimension_filters", None) or {
            "持续优秀": True, "逐渐改善": True, "关注预警": True, "严重恶化": True,
        }
        
        # 筛选 groups
        filtered_groups = []
        for grp in groups:
            status_label, _ = self._wi_cpk_status_evaluation(grp, date_slots)
            if filters.get(status_label, True):
                filtered_groups.append(grp)
        
        # 如果没有符合条件的尺寸，使用原始 groups（避免导出空报告）
        if not filtered_groups:
            filtered_groups = groups
        
        # 1. 构建 PPT 首页：质量指标纵览（原生 PPT 表格形式，双表头合并）
        slots = list(date_slots or [])[:4]
        while len(slots) < 4:
            slots.append(None)
        valid_dates = [d for d in slots if d]
        date_range = self._wi_report_ppt_date_range_label(valid_dates)
        base_title = f"{process_name}  {date_range}  质量指标纵览".strip()

        # 将 filtered_groups 按照每页最多 20 行进行切片分页
        chunk_size = 20
        chunks = [filtered_groups[i:i + chunk_size] for i in range(0, len(filtered_groups), chunk_size)]
        if not chunks:
            chunks = [[]]

        for chunk_idx, chunk in enumerate(chunks):
            if len(chunks) > 1:
                title = f"{base_title} ({chunk_idx + 1})"
            else:
                title = base_title

            # 第一行表头：Dimension、各日期区域、状态评估
            header_row_1 = [
                {
                    "text": "Dimension",
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                }
            ]
            # 第二行表头：各个指标项 Cp, Cpk, Py
            header_row_2 = [
                {
                    "text": "",
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                }
            ]

            for d in slots:
                disp = self._wi_format_display_date(d) if d else "—"
                header_row_1.append({
                    "text": disp,
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                })
                for _ in range(2):
                    header_row_1.append({
                        "text": "",
                        "bold": True,
                        "bg_color": "#E8F1F8",
                        "color": "#2C3E50",
                        "font_size": 9,
                        "align": "center",
                    })
                header_row_2.extend([
                    {"text": "Cp", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"},
                    {"text": "Cpk", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"},
                    {"text": "Py", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"}
                ])

            header_row_1.append({
                "text": "状态评估",
                "bold": True,
                "bg_color": "#E8F1F8",
                "color": "#2C3E50",
                "font_size": 9,
                "align": "center",
            })
            header_row_2.append({
                "text": "",
                "bold": True,
                "bg_color": "#E8F1F8",
                "color": "#2C3E50",
                "font_size": 9,
                "align": "center",
            })

            table_rows = [header_row_1, header_row_2]
            
            # 单元格合并配置
            merges = [
                {"r1": 0, "c1": 0, "r2": 1, "c2": 0},  # Dimension 垂直合并
                {"r1": 0, "c1": 13, "r2": 1, "c2": 13} # 状态评估 垂直合并
            ]
            for i in range(4):
                merges.append({"r1": 0, "c1": 1 + 3 * i, "r2": 0, "c2": 3 + 3 * i}) # 日期水平合并

            for grp in chunk:
                dim_txt = self._wi_cpk_row_label(grp)
                badge, _ = self._wi_distribution_badge(str(grp.get("distribution_type") or ""))
                if badge and not dim_txt.startswith(badge):
                    dim_txt = f"{badge}  {dim_txt}"
                
                row = []
                row.append({
                    "text": dim_txt,
                    "bold": False,
                    "bg_color": "#FFFFFF",
                    "color": "#2C3E50",
                    "font_size": 8.5,
                    "align": "left",
                })
                
                by_date = grp.get("by_date") or {}
                for d in slots:
                    sm = by_date.get(d) if d else None
                    if sm:
                        cpk_v = self._wi_cpk_display_cpk_for_slot(grp, sm)
                        cp_txt = self._wi_fmt_cpk_metric(sm.get("cp"))
                        cpk_txt = self._wi_fmt_cpk_metric(cpk_v)
                        py_txt = self._wi_fmt_projected_yield(sm.get("projected_yield_min"))
                        
                        cp_color = self._wi_cpk_index_color(sm.get("cp"))
                        cpk_color = self._wi_cpk_index_color(cpk_v)
                        py_color = self._wi_projected_yield_color(sm.get("projected_yield_min"))
                        
                        row.append({"text": cp_txt, "bold": True, "bg_color": "#FFFFFF", "color": cp_color, "font_size": 8})
                        row.append({"text": cpk_txt, "bold": True, "bg_color": "#FFFFFF", "color": cpk_color, "font_size": 8})
                        row.append({"text": py_txt, "bold": True, "bg_color": "#FFFFFF", "color": py_color, "font_size": 8})
                    else:
                        for _ in range(3):
                            row.append({"text": "—", "bold": False, "bg_color": "#FFFFFF", "color": "#6B8299", "font_size": 8})
                
                status, status_bg = self._wi_cpk_status_evaluation(grp, date_slots=slots)
                row.append({
                    "text": status,
                    "bold": True,
                    "bg_color": status_bg,
                    "color": "#FFFFFF",
                    "font_size": 9,
                    "align": "center",
                })
                table_rows.append(row)

            if not chunk:
                empty_row = [{"text": "（暂无数据）", "bold": False, "bg_color": "#FFFFFF", "color": "#2C3E50", "font_size": 9}]
                for _ in range(13):
                    empty_row.append({"text": "—", "bold": False, "bg_color": "#FFFFFF", "color": "#6B8299", "font_size": 9})
                table_rows.append(empty_row)

            col_widths = [3.8] + [0.6] * 12 + [1.33]
            n_rows = len(table_rows)
            if len(chunk) > 0:
                row_height = min(0.32, max(0.18, 4.4 / len(chunk)))
                row_heights = [0.26, 0.26] + [row_height] * len(chunk)
            else:
                row_heights = [0.26, 0.26, 0.36]
            
            slides.append({
                "title": title,
                "title_left": 0.5 * 72,
                "title_top": 0.4 * 72,
                "title_width": 12.33 * 72,
                "title_height": 0.5 * 72,
                "tables": [
                    {
                        "rows": n_rows,
                        "cols": 14,
                        "left": 0.5 * 72,
                        "top": 1.1 * 72,
                        "width": 12.33 * 72,
                        "height": sum(row_heights) * 72,
                        "col_widths": col_widths,
                        "row_heights": row_heights,
                        "cells": table_rows,
                        "merges": merges,
                    }
                ]
            })

        # 2. 构建后续图表页（顶部直接放置该尺寸对应的 3 行原生 PPT 表格作为页眉，图片下移）
        for grp in filtered_groups:
            df = self._query_wi_compare_raw_data(
                wi_product, process_name, date_slots,
                grp.get("dim_no"), grp.get("dimension_description"), grp.get("dimension_type"),
            )
            if df is None or df.empty:
                continue
            fig_list = self._render_wi_compare_export_figure(grp, df, date_slots)
            if not fig_list:
                continue

            # 为该单页构建 3 行的原生 PPT 表格表头
            header_row_1 = [
                {
                    "text": "Dimension",
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                }
            ]
            header_row_2 = [
                {
                    "text": "",
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                }
            ]

            for d in slots:
                disp = self._wi_format_display_date(d) if d else "—"
                header_row_1.append({
                    "text": disp,
                    "bold": True,
                    "bg_color": "#E8F1F8",
                    "color": "#2C3E50",
                    "font_size": 9,
                    "align": "center",
                })
                for _ in range(2):
                    header_row_1.append({
                        "text": "",
                        "bold": True,
                        "bg_color": "#E8F1F8",
                        "color": "#2C3E50",
                        "font_size": 9,
                        "align": "center",
                    })
                header_row_2.extend([
                    {"text": "Cp", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"},
                    {"text": "Cpk", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"},
                    {"text": "Py", "bold": True, "bg_color": "#E8F1F8", "color": "#2C3E50", "font_size": 9, "align": "center"}
                ])

            header_row_1.append({
                "text": "状态评估",
                "bold": True,
                "bg_color": "#E8F1F8",
                "color": "#2C3E50",
                "font_size": 9,
                "align": "center",
            })
            header_row_2.append({
                "text": "",
                "bold": True,
                "bg_color": "#E8F1F8",
                "color": "#2C3E50",
                "font_size": 9,
                "align": "center",
            })

            # 单元格合并配置
            merges = [
                {"r1": 0, "c1": 0, "r2": 1, "c2": 0},  # Dimension 垂直合并
                {"r1": 0, "c1": 13, "r2": 1, "c2": 13} # 状态评估 垂直合并
            ]
            for i in range(4):
                merges.append({"r1": 0, "c1": 1 + 3 * i, "r2": 0, "c2": 3 + 3 * i}) # 日期水平合并

            dim_txt = self._wi_cpk_row_label(grp)
            badge, _ = self._wi_distribution_badge(str(grp.get("distribution_type") or ""))
            if badge and not dim_txt.startswith(badge):
                dim_txt = f"{badge}  {dim_txt}"
            
            row = []
            row.append({
                "text": dim_txt,
                "bold": False,
                "bg_color": "#FFFFFF",
                "color": "#2C3E50",
                "font_size": 8.5,
                "align": "left",
            })
            
            by_date = grp.get("by_date") or {}
            for d in slots:
                sm = by_date.get(d) if d else None
                if sm:
                    cpk_v = self._wi_cpk_display_cpk_for_slot(grp, sm)
                    cp_txt = self._wi_fmt_cpk_metric(sm.get("cp"))
                    cpk_txt = self._wi_fmt_cpk_metric(cpk_v)
                    py_txt = self._wi_fmt_projected_yield(sm.get("projected_yield_min"))
                    
                    cp_color = self._wi_cpk_index_color(sm.get("cp"))
                    cpk_color = self._wi_cpk_index_color(cpk_v)
                    py_color = self._wi_projected_yield_color(sm.get("projected_yield_min"))
                    
                    row.append({"text": cp_txt, "bold": True, "bg_color": "#FFFFFF", "color": cp_color, "font_size": 8})
                    row.append({"text": cpk_txt, "bold": True, "bg_color": "#FFFFFF", "color": cpk_color, "font_size": 8})
                    row.append({"text": py_txt, "bold": True, "bg_color": "#FFFFFF", "color": py_color, "font_size": 8})
                else:
                    for _ in range(3):
                        row.append({"text": "—", "bold": False, "bg_color": "#FFFFFF", "color": "#6B8299", "font_size": 8})
            
            status, status_bg = self._wi_cpk_status_evaluation(grp, date_slots=slots)
            row.append({
                "text": status,
                "bold": True,
                "bg_color": status_bg,
                "color": "#FFFFFF",
                "font_size": 9,
                "align": "center",
            })

            col_widths = [3.8] + [0.6] * 12 + [1.33]

            for fig_idx, fig in enumerate(fig_list):
                png_cmp = self._wi_report_ppt_save_figure(
                    fig, prefix=f"wi_dim_{grp.get('dim_no', 'unknown')}_{fig_idx}", fixed_bbox=True, dpi=self._WI_PPT_EXPORT_DPI,
                )
                # 顶部空出 1.1 英寸放置原生表格作为页眉
                rect = self._wi_ppt_fit_picture_rect(
                    png_cmp,
                    slide_w_in=self._WI_PPT_SLIDE_W,
                    slide_h_in=self._WI_PPT_SLIDE_H,
                    margin_in=self._WI_PPT_DIM_LEFT_MARGIN,
                    margin_right_in=self._WI_PPT_DIM_RIGHT_MARGIN,
                    top_in=1.1,
                    align="left",
                )
                
                slides.append({
                    "tables": [
                        {
                            "rows": 3,
                            "cols": 14,
                            "left": 0.5 * 72,
                            "top": 0.22 * 72,
                            "width": 12.33 * 72,
                            "height": (0.26 + 0.26 + 0.32) * 72,
                            "col_widths": col_widths,
                            "row_heights": [0.26, 0.26, 0.32],
                            "cells": [header_row_1, header_row_2, row],
                            "merges": merges,
                        }
                    ],
                    "pictures": [{"path": png_cmp, **rect}],
                })
        return slides

    def _export_wi_anomaly_data(self):
        """筛选符合选中规则的测点数据，并将其导出到 Excel 文件。"""
        wi_product = self._get_selected_wi_product_line()
        processes = self._get_wi_picker_process_names()
        if not wi_product:
            return QMessageBox.warning(self, "提示", "请先在右上角选择产品。")
        if not processes:
            return QMessageBox.warning(self, "提示", "请先在右上角至少选择一个制程。")
        
        # 获取规则筛选状态
        if not hasattr(self, "_wi_rule_filters"):
            self._wi_rule_filters: dict[str, bool] = {
                "规则1(4次升降)": True,
                "规则2(波动>0.05)": True,
                "规则3(90%外)": True,
                "规则4(60%外)": True,
            }
            
        chk_r1 = self._wi_rule_filters.get("规则1(4次升降)", True)
        chk_r2 = self._wi_rule_filters.get("规则2(波动>0.05)", True)
        chk_r3 = self._wi_rule_filters.get("规则3(90%外)", True)
        chk_r4 = self._wi_rule_filters.get("规则4(60%外)", True)
        
        if not (chk_r1 or chk_r2 or chk_r3 or chk_r4):
            QMessageBox.warning(self, "提示", "请至少选择一条异常规则（点击「规则筛选」按钮进行选择）。")
            return
            
        cache = getattr(self, "_wi_cpk_dashboard_cache", None) or {}
        export_jobs = []
        for proc in processes:
            entry = cache.get(proc) or {}
            groups = entry.get("groups") or []
            date_slots = entry.get("date_slots") or []
            if groups and any(d for d in date_slots):
                export_jobs.append((proc, groups, date_slots))
                
        if not export_jobs:
            return QMessageBox.warning(
                self, "提示",
                "当前没有可分析的检测数据。请确认已选择检测日期并点击「刷新」。",
            )
            
        anomalies = []
        
        try:
            QApplication.setOverrideCursor(Qt.WaitCursor)
            for proc, groups, date_slots in export_jobs:
                raw_df = self._query_all_wi_raw_data_for_dates(wi_product, proc, date_slots)
                if raw_df.empty:
                    continue
                    
                slots = [d for d in date_slots if d]
                if not slots:
                    continue
                    
                raw_df["point_display"] = raw_df.apply(
                    lambda r: ORTAnalyseSystem._wi_compare_point_display(r["point_name"], r["point_number"]), axis=1
                )
                
                # Fetch spec limits helper
                def get_specs(row):
                    usl = row.get("usl")
                    lsl = row.get("lsl")
                    dim_t = str(row.get("dimension_type") or "").strip().lower()
                    dim_no_val = str(row.get("dim_no") or row.get("component") or "").strip()
                    is_single_t = False
                    for g in groups:
                        if str(g.get("dim_no") or "").strip() == dim_no_val:
                            if str(g.get("distribution_type") or "").strip().lower() == "singleside-usl":
                                is_single_t = True
                            break
                    if not is_single_t:
                        is_single_t = (
                            "singleside-usl" in dim_t or
                            "profile" in dim_t or
                            "flatness" in dim_t or
                            "profile" in str(row.get("dimension_description") or "").strip().lower() or
                            "flatness" in str(row.get("dimension_description") or "").strip().lower()
                        )
                    if is_single_t:
                        lsl = 0.0
                    if pd.notna(usl) and pd.notna(lsl):
                        return float(usl), float(lsl)
                    nominal = row.get("nominal")
                    tol_max = row.get("tol_max")
                    tol_min = row.get("tol_min")
                    if pd.notna(nominal) and pd.notna(tol_max) and pd.notna(tol_min):
                        u = float(nominal) + abs(float(tol_max))
                        l = float(nominal) - abs(float(tol_min))
                        if is_single_t:
                            l = 0.0
                        return u, l
                    return None, None
                
                # Rule 2 evaluation (on mean of each date slot)
                if chk_r2:
                    dim_groups = raw_df.groupby(["dim_no", "dimension_description", "dimension_type"])
                    for dim_tuple, dim_df in dim_groups:
                        dim_no, dim_desc, dim_type = dim_tuple
                        means_by_date = {}
                        for t_time, date_df in dim_df.groupby("test_time"):
                            means_by_date[t_time] = date_df["value"].mean()
                        for i in range(1, len(slots)):
                            d_prev = slots[i-1]
                            d_curr = slots[i]
                            if d_prev in means_by_date and d_curr in means_by_date:
                                m_prev = means_by_date[d_prev]
                                m_curr = means_by_date[d_curr]
                                diff = abs(m_curr - m_prev)
                                if diff > 0.05:
                                    anomalies.append({
                                        "process": proc,
                                        "dim_no": dim_no,
                                        "dim_desc": dim_desc,
                                        "dim_type": dim_type,
                                        "machine": "—",
                                        "point": "—",
                                        "rule": "规则2",
                                        "rule_desc": "相邻日期均值波动 > 0.05",
                                        "details": f"均值波动: {d_prev}({m_prev:.4f}) → {d_curr}({m_curr:.4f}), 差值: {diff:.4f}"
                                    })
                                    
                # Point-level evaluations: Rules 1, 3, 4
                pt_groups = raw_df.groupby(["dim_no", "dimension_description", "dimension_type", "machine", "point_display"])
                for name_tuple, group_df in pt_groups:
                    dim_no, dim_desc, dim_type, machine, point_display = name_tuple
                    val_by_date = {}
                    for _, r in group_df.iterrows():
                        val_by_date[r["test_time"]] = r["value"]
                        
                    first_row = group_df.iloc[0]
                    usl, lsl = get_specs(first_row)
                    
                    is_single_usl = False
                    for g in groups:
                        if str(g.get("dim_no") or "").strip() == dim_no:
                            if str(g.get("distribution_type") or "").strip().lower() == "singleside-usl":
                                is_single_usl = True
                            break
                    if not is_single_usl:
                        is_single_usl = (
                            "singleside-usl" in str(dim_type).strip().lower() or
                            "profile" in str(dim_type).strip().lower() or
                            "flatness" in str(dim_type).strip().lower() or
                            "profile" in str(dim_desc).strip().lower() or
                            "flatness" in str(dim_desc).strip().lower()
                        )
                        
                    if chk_r1:
                        if len(slots) == 4 and all(s in val_by_date for s in slots):
                            v0 = val_by_date[slots[0]]
                            v1 = val_by_date[slots[1]]
                            v2 = val_by_date[slots[2]]
                            v3 = val_by_date[slots[3]]
                            if (v0 < v1 < v2 < v3) or (v0 > v1 > v2 > v3):
                                anomalies.append({
                                    "process": proc,
                                    "dim_no": dim_no,
                                    "dim_desc": dim_desc,
                                    "dim_type": dim_type,
                                    "machine": machine,
                                    "point": point_display,
                                    "rule": "规则1",
                                    "rule_desc": "连续4次数据上升" if v0 < v1 < v2 < v3 else "连续4次数据下降",
                                    "details": f"变动趋势: {v0:.4f} → {v1:.4f} → {v2:.4f} → {v3:.4f}"
                                })
                                
                    if chk_r3:
                        latest_date_with_data = None
                        for s in reversed(slots):
                            if s in val_by_date:
                                latest_date_with_data = s
                                break
                        if latest_date_with_data is not None and usl is not None and lsl is not None:
                            v = val_by_date[latest_date_with_data]
                            T = usl - lsl
                            if T > 0:
                                if is_single_usl:
                                    triggered = (v > usl - 0.10 * T)
                                else:
                                    triggered = (v < lsl + 0.05 * T or v > usl - 0.05 * T)
                                    
                                if triggered:
                                    anomalies.append({
                                        "process": proc,
                                        "dim_no": dim_no,
                                        "dim_desc": dim_desc,
                                        "dim_type": dim_type,
                                        "machine": machine,
                                        "point": point_display,
                                        "rule": "规则3",
                                        "rule_desc": "最新日期值在公差带90%以外",
                                        "details": f"最新日期: {latest_date_with_data}, 值: {v:.4f} (公差上限: {usl:.4f})" if is_single_usl else f"最新日期: {latest_date_with_data}, 值: {v:.4f} (公差带: [{lsl:.4f}, {usl:.4f}])"
                                    })
                                    
                    if chk_r4:
                        if len(slots) == 4 and all(s in val_by_date for s in slots) and usl is not None and lsl is not None:
                            T = usl - lsl
                            if T > 0:
                                v0 = val_by_date[slots[0]]
                                v1 = val_by_date[slots[1]]
                                v2 = val_by_date[slots[2]]
                                v3 = val_by_date[slots[3]]
                                if is_single_usl:
                                    all_outside = all(v > usl - 0.40 * T for v in (v0, v1, v2, v3))
                                else:
                                    all_outside = all((v < lsl + 0.20 * T or v > usl - 0.20 * T) for v in (v0, v1, v2, v3))
                                    
                                if all_outside:
                                    anomalies.append({
                                        "process": proc,
                                        "dim_no": dim_no,
                                        "dim_desc": dim_desc,
                                        "dim_type": dim_type,
                                        "machine": machine,
                                        "point": point_display,
                                        "rule": "规则4",
                                        "rule_desc": "连续4次值都在公差带60%以外",
                                        "details": f"各期数值: [{v0:.4f}, {v1:.4f}, {v2:.4f}, {v3:.4f}] (公差上限: {usl:.4f})" if is_single_usl else f"各期数值: [{v0:.4f}, {v1:.4f}, {v2:.4f}, {v3:.4f}] (公差带: [{lsl:.4f}, {usl:.4f}])"
                                    })
        except Exception as ex:
            QApplication.restoreOverrideCursor()
            import traceback
            QMessageBox.critical(self, "错误", f"分析失败：\n{ex}\n{traceback.format_exc()}")
            return
        finally:
            QApplication.restoreOverrideCursor()

        if not anomalies:
            QMessageBox.information(self, "提示", "根据选中的规则，未筛选到任何异常测点数据。")
            return
            
        records = []
        for idx, item in enumerate(anomalies):
            dim_no = item["dim_no"]
            dim_desc = item["dim_desc"]
            dim_type = item["dim_type"]
            proc = item["process"]
            
            # Retrieve date slots for this specific process
            entry = cache.get(proc) or {}
            groups = entry.get("groups") or []
            proc_slots = entry.get("date_slots") or []
            
            # Find matching group
            grp = None
            for g in groups:
                if (str(g.get("dim_no") or "").strip() == dim_no and 
                    str(g.get("dimension_description") or "").strip() == dim_desc and 
                    str(g.get("dimension_type") or "").strip() == dim_type):
                    grp = g
                    break
            
            status = "严重恶化"
            if grp:
                status, _ = self._wi_cpk_status_evaluation(grp, proc_slots)
            
            records.append({
                "序号": idx + 1,
                "制程": proc,
                "尺寸编号": dim_no,
                "尺寸描述": dim_desc,
                "分布类型": dim_type,
                "评估状态": status,
                "机台": item["machine"],
                "点位": item["point"],
                "触发规则": f"{item['rule']} ({item['rule_desc']})",
                "异常值/变动明细": item["details"]
            })
            
        export_df = pd.DataFrame(records)
        
        # Save file dialog
        default_name = f"{wi_product}_异常数据明细.xlsx"
        desktop = os.path.join(os.path.expanduser("~"), "Desktop")
        default_path = os.path.join(desktop, default_name)
        
        save_path, _ = QFileDialog.getSaveFileName(
            self, "保存异常数据明细", default_path, "Excel Files (*.xlsx)"
        )
        if not save_path:
            return
            
        try:
            QApplication.setOverrideCursor(Qt.WaitCursor)
            with pd.ExcelWriter(save_path, engine="openpyxl") as writer:
                export_df.to_excel(writer, sheet_name="异常测点明细", index=False)
                
                # Apply professional styling to the sheet
                workbook = writer.book
                worksheet = writer.sheets["异常测点明细"]
                
                # Column widths auto-fit
                for col in worksheet.columns:
                    max_len = max(len(str(cell.value or '')) for cell in col)
                    col_letter = col[0].column_letter
                    worksheet.column_dimensions[col_letter].width = max(max_len + 3, 10)
                    
                # Header formatting
                from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
                header_font = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
                header_fill = PatternFill(start_color="1F497D", end_color="1F497D", fill_type="solid")
                center_align = Alignment(horizontal="center", vertical="center")
                left_align = Alignment(horizontal="left", vertical="center")
                
                thin_side = Side(border_style="thin", color="D9D9D9")
                thin_border = Border(left=thin_side, right=thin_side, top=thin_side, bottom=thin_side)
                
                for col_idx in range(1, len(export_df.columns) + 1):
                    cell = worksheet.cell(row=1, column=col_idx)
                    cell.font = header_font
                    cell.fill = header_fill
                    cell.alignment = center_align
                    cell.border = thin_border
                    
                # Body formatting
                body_font = Font(name="Calibri", size=10)
                for r_idx in range(2, len(export_df) + 2):
                    for c_idx in range(1, len(export_df.columns) + 1):
                        cell = worksheet.cell(row=r_idx, column=c_idx)
                        cell.font = body_font
                        cell.border = thin_border
                        if c_idx in (1, 2, 3, 7, 8, 9): # No, process, dim_no, machine, point, rule
                            cell.alignment = center_align
                        else:
                            cell.alignment = left_align
                            
            QApplication.restoreOverrideCursor()
            QMessageBox.information(self, "成功", f"异常数据明细已成功导出至：\n{save_path}")
        except Exception as e:
            QApplication.restoreOverrideCursor()
            QMessageBox.critical(self, "错误", f"导出失败：\n{e}")

    def _export_wi_report_ppt(self):
        """合并 01/02 板块导出 Weekly Inspection PPT 质量报告。"""
        wi_product = self._get_selected_wi_product_line()
        processes = self._get_wi_picker_process_names()
        if not wi_product:
            return QMessageBox.warning(self, "提示", "请先在右上角选择产品。")
        if not processes:
            return QMessageBox.warning(self, "提示", "请先在右上角至少选择一个制程。")

        if not _ensure_ppt_export_capability(self):
            return

        cache = getattr(self, "_wi_cpk_dashboard_cache", None) or {}
        export_jobs: list[tuple[str, list[dict], list[str | None]]] = []
        for proc in processes:
            entry = cache.get(proc) or {}
            groups = entry.get("groups") or []
            date_slots = entry.get("date_slots") or []
            if groups and any(d for d in date_slots):
                export_jobs.append((proc, groups, date_slots))

        if not export_jobs:
            return QMessageBox.warning(
                self, "提示",
                "当前没有可导出的报告数据。请确认已选择检测日期并点击「刷新」。",
            )

        export_dir = QFileDialog.getExistingDirectory(
            self, "选择 PPT 导出文件夹", self._get_desktop_dir(),
        )
        if not export_dir:
            return

        temp_pngs: list[str] = []
        exported_files: list[str] = []
        try:
            QApplication.setOverrideCursor(Qt.WaitCursor)
            for proc, groups, date_slots in export_jobs:
                valid_dates = [d for d in date_slots if d]
                date_range = self._wi_report_ppt_date_range_label(valid_dates)
                safe_proc = re.sub(r"[\\/*?:\[\]]+", "_", str(proc)).strip() or "Report"
                range_part = date_range.replace(" ~ ", "_").replace(" ", "")
                file_path = os.path.join(export_dir, f"{safe_proc}_{range_part}_质量报告.pptx")
                if os.path.isfile(file_path):
                    base, ext = os.path.splitext(os.path.basename(file_path))
                    suffix = 1
                    while os.path.isfile(file_path):
                        file_path = os.path.join(export_dir, f"{base}_{suffix}{ext}")
                        suffix += 1

                slides = self._build_wi_report_ppt_slides(wi_product, proc, groups, date_slots)
                for sl in slides:
                    for pic in sl.get("pictures") or []:
                        p = pic.get("path")
                        if p:
                            temp_pngs.append(p)
                if len(slides) < 2:
                    QMessageBox.warning(
                        self, "提示",
                        f"制程「{proc}」除首页外无可用尺寸图表，已跳过。",
                    )
                    continue
                if _save_ppt_via_powerpoint_payload(slides, file_path, parent=self):
                    exported_files.append(file_path)
        except Exception as ex:
            import traceback
            QMessageBox.critical(
                self, "导出失败",
                f"导出 PPT 时发生错误：\n{ex}\n{traceback.format_exc()}",
            )
            return
        finally:
            QApplication.restoreOverrideCursor()
            for p in temp_pngs:
                try:
                    if os.path.isfile(p):
                        os.remove(p)
                except Exception:
                    pass

        if not exported_files:
            return QMessageBox.warning(self, "提示", "未能生成任何 PPT 文件。")
        file_lines = "\n".join(exported_files[:6])
        if len(exported_files) > 6:
            file_lines += f"\n… 共 {len(exported_files)} 个文件"
        QMessageBox.information(
            self, "导出成功",
            f"已导出 {len(exported_files)} 个 PPT 质量报告：\n{file_lines}",
        )

    def _query_wi_compare_raw_data(self, wi_product, process_name, date_slots, dim_no, dim_desc, dim_type):
        """查询指定制程、时间和尺寸组的原始测量数据。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name:
            return pd.DataFrame()
        
        valid_dates = [d for d in date_slots if d]
        if not valid_dates:
            return pd.DataFrame()
            
        dim_no = str(dim_no or "").strip()
        dim_desc = str(dim_desc or "").strip()
        dim_type = str(dim_type or "").strip()
        
        df = pd.DataFrame()
        mgr = getattr(self, "_ort_db", None)
        if mgr is not None:
            table_name = mgr._get_table_name("Weekly Inspection", wi_product, process_name)
            if mgr._is_wi_storage_table(table_name):
                tt_expr = mgr._wi_normalized_test_time_sql("test_time")
                placeholders = ", ".join("?" for _ in valid_dates)
                sql = f"""
                    SELECT 
                        {tt_expr} AS test_time,
                        COALESCE(NULLIF(TRIM(component), ''), '') AS dim_no,
                        COALESCE(NULLIF(TRIM(dimension_description), ''), '') AS dimension_description,
                        COALESCE(NULLIF(TRIM(dimension_type), ''), '') AS dimension_type,
                        COALESCE(NULLIF(TRIM(point_name), ''), '') AS point_name,
                        COALESCE(NULLIF(TRIM(subpart), ''), '') AS point_number,
                        value,
                        usl,
                        lsl,
                        nominal,
                        tol_max,
                        tol_min,
                        COALESCE(NULLIF(TRIM(line), ''), NULLIF(TRIM(barcode), ''), '') AS machine,
                        barcode
                    FROM "{table_name}"
                    WHERE COALESCE(NULLIF(TRIM(component), ''), '') = ?
                      AND COALESCE(NULLIF(TRIM(dimension_description), ''), '') = ?
                      AND COALESCE(NULLIF(TRIM(dimension_type), ''), '') = ?
                      AND {tt_expr} IN ({placeholders})
                """
                params = [dim_no, dim_desc, dim_type] + valid_dates
                try:
                    with mgr._connect() as conn:
                        df = pd.read_sql_query(sql, conn, params=tuple(params))
                except Exception as ex:
                    print(f"[WI Compare] DB query failed: {ex}")
                    df = pd.DataFrame()

        # Fallback to current_df in memory
        if (df is None or df.empty) and hasattr(self, "current_df") and self.current_df is not None and not self.current_df.empty:
            work = self.current_df.copy()
            # Normalize columns
            for col in ("dim_no", "component", "dimension_description", "dimension_type", "point_name", "line", "barcode"):
                if col not in work.columns:
                    work[col] = ""
                work[col] = work[col].fillna("").astype(str).str.strip()
            
            # Map columns to match DB select fields
            work["dim_no_norm"] = work["dim_no"].where(work["dim_no"] != "", work["component"])
            work["machine"] = work["line"].where(work["line"] != "", work["barcode"])
            
            if "test_time" in work.columns:
                if "batch_date" not in work.columns:
                    work["batch_date"] = work["test_time"].map(
                        lambda v: ORTDatabaseManager._normalize_wi_test_time_value(v)
                    )
            else:
                work["batch_date"] = ""
                
            # Filter
            mask = (
                (work["dim_no_norm"] == dim_no) &
                (work["dimension_description"] == dim_desc) &
                (work["dimension_type"] == dim_type) &
                (work["batch_date"].isin(valid_dates))
            )
            sub = work[mask].copy()
            if not sub.empty:
                if "subpart" in sub.columns:
                    point_number = sub["subpart"].fillna("").astype(str).str.strip()
                else:
                    point_number = pd.Series([""] * len(sub), index=sub.index)
                df = pd.DataFrame({
                    "test_time": sub["batch_date"],
                    "dim_no": sub["dim_no_norm"],
                    "dimension_description": sub["dimension_description"],
                    "dimension_type": sub["dimension_type"],
                    "point_name": sub["point_name"],
                    "point_number": point_number,
                    "value": pd.to_numeric(sub["value"], errors="coerce"),
                    "usl": pd.to_numeric(sub.get("usl"), errors="coerce") if "usl" in sub.columns else None,
                    "lsl": pd.to_numeric(sub.get("lsl"), errors="coerce") if "lsl" in sub.columns else None,
                    "nominal": pd.to_numeric(sub.get("nominal"), errors="coerce") if "nominal" in sub.columns else None,
                    "tol_max": pd.to_numeric(sub.get("tol_max"), errors="coerce") if "tol_max" in sub.columns else None,
                    "tol_min": pd.to_numeric(sub.get("tol_min"), errors="coerce") if "tol_min" in sub.columns else None,
                    "machine": sub["machine"],
                    "barcode": sub["barcode"],
                })
        
        # Clean value column
        if not df.empty:
            if "point_number" not in df.columns:
                df["point_number"] = ""
            df["value"] = pd.to_numeric(df["value"], errors="coerce")
            df = df.dropna(subset=["value"])
            # Ensure sort order
            df = df.sort_values(by=["test_time", "barcode", "point_name"])
        return df

    def _query_all_wi_raw_data_for_dates(self, wi_product, process_name, date_slots):
        """查询指定制程和时间范围内所有尺寸的所有原始数据。"""
        wi_product = str(wi_product or "").strip()
        process_name = str(process_name or "").strip()
        if not process_name:
            return pd.DataFrame()
        
        valid_dates = [d for d in date_slots if d]
        if not valid_dates:
            return pd.DataFrame()
            
        df = pd.DataFrame()
        mgr = getattr(self, "_ort_db", None)
        if mgr is not None:
            table_name = mgr._get_table_name("Weekly Inspection", wi_product, process_name)
            if mgr._is_wi_storage_table(table_name):
                tt_expr = mgr._wi_normalized_test_time_sql("test_time")
                placeholders = ", ".join("?" for _ in valid_dates)
                sql = f"""
                    SELECT 
                        {tt_expr} AS test_time,
                        COALESCE(NULLIF(TRIM(component), ''), '') AS dim_no,
                        COALESCE(NULLIF(TRIM(dimension_description), ''), '') AS dimension_description,
                        COALESCE(NULLIF(TRIM(dimension_type), ''), '') AS dimension_type,
                        COALESCE(NULLIF(TRIM(point_name), ''), '') AS point_name,
                        COALESCE(NULLIF(TRIM(subpart), ''), '') AS point_number,
                        value,
                        usl,
                        lsl,
                        nominal,
                        tol_max,
                        tol_min,
                        COALESCE(NULLIF(TRIM(line), ''), NULLIF(TRIM(barcode), ''), '') AS machine,
                        barcode
                    FROM "{table_name}"
                    WHERE {tt_expr} IN ({placeholders})
                """
                try:
                    with mgr._connect() as conn:
                        df = pd.read_sql_query(sql, conn, params=tuple(valid_dates))
                except Exception as ex:
                    print(f"[WI Anomaly] DB query failed: {ex}")
                    df = pd.DataFrame()

        # Fallback to current_df in memory
        if (df is None or df.empty) and hasattr(self, "current_df") and self.current_df is not None and not self.current_df.empty:
            work = self.current_df.copy()
            for col in ("dim_no", "component", "dimension_description", "dimension_type", "point_name", "line", "barcode"):
                if col not in work.columns:
                    work[col] = ""
                work[col] = work[col].fillna("").astype(str).str.strip()
            
            work["dim_no_norm"] = work["dim_no"].where(work["dim_no"] != "", work["component"])
            work["machine"] = work["line"].where(work["line"] != "", work["barcode"])
            
            if "test_time" in work.columns:
                if "batch_date" not in work.columns:
                    work["batch_date"] = work["test_time"].map(
                        lambda v: ORTDatabaseManager._normalize_wi_test_time_value(v)
                    )
            else:
                work["batch_date"] = ""
                
            mask = work["batch_date"].isin(valid_dates)
            sub = work[mask].copy()
            if not sub.empty:
                if "subpart" in sub.columns:
                    point_number = sub["subpart"].fillna("").astype(str).str.strip()
                else:
                    point_number = pd.Series([""] * len(sub), index=sub.index)
                df = pd.DataFrame({
                    "test_time": sub["batch_date"],
                    "dim_no": sub["dim_no_norm"],
                    "dimension_description": sub["dimension_description"],
                    "dimension_type": sub["dimension_type"],
                    "point_name": sub["point_name"],
                    "point_number": point_number,
                    "value": pd.to_numeric(sub["value"], errors="coerce"),
                    "usl": pd.to_numeric(sub.get("usl"), errors="coerce") if "usl" in sub.columns else None,
                    "lsl": pd.to_numeric(sub.get("lsl"), errors="coerce") if "lsl" in sub.columns else None,
                    "nominal": pd.to_numeric(sub.get("nominal"), errors="coerce") if "nominal" in sub.columns else None,
                    "tol_max": pd.to_numeric(sub.get("tol_max"), errors="coerce") if "tol_max" in sub.columns else None,
                    "tol_min": pd.to_numeric(sub.get("tol_min"), errors="coerce") if "tol_min" in sub.columns else None,
                    "machine": sub["machine"],
                    "barcode": sub["barcode"],
                })

        if not df.empty:
            if "point_number" not in df.columns:
                df["point_number"] = ""
            df["value"] = pd.to_numeric(df["value"], errors="coerce")
            df = df.dropna(subset=["value"])
            df = df.sort_values(by=["test_time", "barcode", "point_name"])
            
        return df

    def _on_wi_compare_abnormal_overview_clicked(self):
        """打开异常数据概览面板。"""
        process_name = self._get_selected_wi_process_name()
        wi_product = self._get_selected_wi_product_line()
        if not process_name or not wi_product:
            QMessageBox.warning(self, "提示", "请先在右上角选择产品与制程。")
            return
            
        date_slots = getattr(self, "_wi_compare_date_slots", [])
        if not date_slots or not any(date_slots):
            QMessageBox.warning(self, "提示", "当前没有有效的检测日期，请确认已选择日期并点击刷新。")
            return
            
        try:
            QApplication.setOverrideCursor(Qt.WaitCursor)
            raw_df = self._query_all_wi_raw_data_for_dates(wi_product, process_name, date_slots)
        except Exception as ex:
            import traceback
            QMessageBox.critical(self, "错误", f"查询原始数据失败：\n{ex}\n{traceback.format_exc()}")
            return
        finally:
            QApplication.restoreOverrideCursor()
            
        if raw_df.empty:
            QMessageBox.information(self, "提示", f"未查询到该制程「{process_name}」在所选日期的任何测量数据。")
            return
            
        dlg = WiAnomalyOverviewDialog(self, wi_product, process_name, date_slots, raw_df)
        dlg.exec_()

    def _on_wi_compare_item_double_clicked(self, list_item):
        """双击尺寸项，弹出该尺寸归属的所有满足规则的测点与趋势图。"""
        grp = list_item.data(Qt.UserRole)
        if not grp:
            return
            
        dim_no = str(grp.get("dim_no") or "").strip()
        dim_desc = str(grp.get("dimension_description") or "").strip()
        
        process_name = self._get_selected_wi_process_name()
        wi_product = self._get_selected_wi_product_line()
        if not process_name or not wi_product:
            QMessageBox.warning(self, "提示", "请先在右上角选择产品与制程。")
            return
            
        date_slots = getattr(self, "_wi_compare_date_slots", [])
        if not date_slots or not any(date_slots):
            QMessageBox.warning(self, "提示", "当前没有有效的检测日期，请确认已选择日期并点击刷新。")
            return
            
        try:
            QApplication.setOverrideCursor(Qt.WaitCursor)
            raw_df = self._query_all_wi_raw_data_for_dates(wi_product, process_name, date_slots)
        except Exception as ex:
            import traceback
            QMessageBox.critical(self, "错误", f"查询原始数据失败：\n{ex}\n{traceback.format_exc()}")
            return
        finally:
            QApplication.restoreOverrideCursor()
            
        if raw_df.empty:
            QMessageBox.information(self, "提示", f"未查询到该制程「{process_name}」在所选日期的任何测量数据。")
            return
            
        # 仅筛选出属于当前双击尺寸的数据
        filtered_df = raw_df[raw_df.dim_no == dim_no]
        if filtered_df.empty:
            QMessageBox.information(self, "提示", f"未查询到该尺寸「{dim_no}」在所选日期的测量数据。")
            return
            
        # 弹出异常概览窗口，窗口标题显示为该尺寸
        title_info = f"尺寸 {dim_no} — {dim_desc}"
        dlg = WiAnomalyOverviewDialog(self, wi_product, title_info, date_slots, filtered_df)
        dlg.exec_()

    def _refresh_wi_compare_dimension_list(self):
        """根据当前选择的制程，从 CPK 缓存中加载尺寸组，并刷新左侧列表。"""
        prev_key = None
        cur_item = self.wi_compare_list.currentItem()
        if cur_item is not None:
            prev_grp = cur_item.data(Qt.UserRole)
            if prev_grp:
                prev_key = self._wi_compare_dimension_key(prev_grp)

        self.wi_compare_list.clear()
        self.wi_compare_dimensions = []
        self.wi_compare_active_grp = None
        self.wi_compare_active_df = None
        self._wi_compare_plot_df = None
        
        self.wi_compare_fig.clf()
        self.wi_compare_canvas.draw()
        
        self._sync_wi_compare_process_chips()
        process_name = self._get_selected_wi_process_name()
        if not process_name:
            self._wi_compare_set_info_hint("提示：请先在右上角选择产品与日期，并点击「刷新」加载数据。")
            return
            
        cache_data = self._wi_cpk_dashboard_cache.get(process_name, {})
        groups = cache_data.get("groups", [])
        date_slots = [d for d in (cache_data.get("date_slots") or []) if d]
        self._wi_compare_date_slots = date_slots
        dates_txt = "、".join(date_slots) if date_slots else "未选日期"
        
        if not groups:
            self._wi_compare_set_info_hint(
                f"提示：制程「{process_name}」暂无已加载数据（{dates_txt}）。请确认右上角日期并点击「刷新」。"
            )
            return
            
        self._wi_compare_set_info_hint(
            f"制程「{process_name}」· 对比日期 {dates_txt} · 共 {len(groups)} 个尺寸组。请在左侧选择尺寸。"
        )
        
        restore_row = -1
        for grp in groups:
            pt_meta = self._wi_compare_analyze_points(grp, None)
            item = self._add_wi_compare_list_item(grp, date_slots)
            self.wi_compare_dimensions.append((item, grp, bool(pt_meta["xy_bases"])))
            if prev_key and self._wi_compare_dimension_key(grp) == prev_key:
                restore_row = self.wi_compare_list.count() - 1

        if restore_row >= 0:
            self.wi_compare_list.setCurrentRow(restore_row)
        elif self.wi_compare_list.count() > 0:
            self.wi_compare_list.setCurrentRow(0)
        cur = self.wi_compare_list.currentItem()
        self._apply_wi_compare_list_selection_styles(cur, None)

    def _on_wi_compare_selection_changed(self, current, previous):
        """当左侧列表的尺寸项发生改变时触发，加载机台列表并重绘图表。"""
        self._apply_wi_compare_list_selection_styles(current, previous)
        if not current:
            self.wi_compare_active_grp = None
            self.wi_compare_active_df = None
            self.wi_compare_fig.clf()
            self.wi_compare_canvas.draw()
            return
            
        grp = current.data(Qt.UserRole)
        self.wi_compare_active_grp = grp
        
        process_name = self._get_selected_wi_process_name()
        wi_product = self._get_selected_wi_product_line()
        cache_data = self._wi_cpk_dashboard_cache.get(process_name, {})
        date_slots = cache_data.get("date_slots", [])
        
        # Query raw data
        df = self._query_wi_compare_raw_data(
            wi_product, process_name, date_slots,
            grp.get("dim_no"), grp.get("dimension_description"), grp.get("dimension_type")
        )
        self.wi_compare_active_df = df
        
        self._draw_wi_compare_chart()

    def _draw_wi_compare_chart(self):
        """三列布局：折线图 | 箱线图 | 靶心图（按日期拆分网格排列）。"""
        from matplotlib.gridspec import GridSpec

        self.wi_compare_fig.clf()
        self._wi_compare_group_keys = []
        self._wi_compare_target_pivoted = None
        self._wi_compare_point_meta = {}

        grp = getattr(self, "wi_compare_active_grp", None)
        df = getattr(self, "wi_compare_active_df", None)

        if grp is None or df is None or df.empty:
            self.wi_compare_fig.set_figheight(6.0 * float(getattr(self, "_s", 1.0)))
            ax = self.wi_compare_fig.add_subplot(1, 1, 1)
            ax.axis("off")
            ax.text(0.5, 0.5, "暂无对应原始数据",
                    ha="center", va="center", transform=ax.transAxes,
                    color="#6B8299", fontsize=11, fontweight="600")
            self.wi_compare_canvas.draw()
            self._wi_compare_set_info_hint("提示：该尺寸在所选日期内暂无原始测量数据。")
            return

        machine_sel = self._wi_compare_machine_filter_text()
        plot_df = self._wi_compare_filter_df_by_machine(df, machine_sel)
        self._wi_compare_plot_df = plot_df

        if plot_df.empty:
            self.wi_compare_fig.set_figheight(6.0 * float(getattr(self, "_s", 1.0)))
            ax = self.wi_compare_fig.add_subplot(1, 1, 1)
            ax.axis("off")
            ax.text(0.5, 0.5, f"机台「{machine_sel}」无数据",
                    ha="center", va="center", transform=ax.transAxes,
                    color="#6B8299", fontsize=11, fontweight="600")
            self.wi_compare_canvas.draw()
            self._wi_compare_set_info_hint(
                f"提示：机台「{machine_sel}」在所选日期内无测量记录，请切换机台或选择「所有机台」。"
            )
            return

        meta = self._wi_compare_analyze_points(grp, plot_df)
        chart_title = self._wi_compare_chart_title(grp)
        xy_bases = meta["xy_bases"]
        n_targets = len(xy_bases)
        
        unique_dates = sorted(plot_df["test_time"].dropna().unique().tolist(), key=str)
        n_dates = len(unique_dates)

        # ── 双重认证：位置度描述 + X/Y 配对 → 仅靶心图 ──
        is_positional_only = (
            n_targets > 0
            and self._wi_compare_is_positional_tolerance(grp, meta)
        )

        hints: list[str] = []
        axes_grid = []

        if is_positional_only:
            # ── 位置度专属布局：靶心图横向/纵向网格铺满，不绘制箱线/折线 ──
            _fig_rows = max(n_targets, 1)
            _fig_cols = max(n_dates, 1)
            gs_tgt = GridSpec(_fig_rows, _fig_cols, figure=self.wi_compare_fig, wspace=0.30, hspace=0.35)
            
            for ri in range(_fig_rows):
                row_axes = []
                for ci in range(_fig_cols):
                    ax = self.wi_compare_fig.add_subplot(gs_tgt[ri, ci])
                    row_axes.append(ax)
                axes_grid.append(row_axes)

            self._plot_wi_compare_targets(axes_grid, plot_df, grp, xy_bases, unique_dates)
            hints.append(f"靶心{n_targets}×{n_dates}")
            line_will_show = False
            
            # 动态调整画布高度
            dynamic_height = max(4.0, _fig_rows * 2.6 * float(getattr(self, "_s", 1.0)))
            self.wi_compare_fig.set_figheight(dynamic_height)
            
            try:
                self.wi_compare_fig.subplots_adjust(
                    left=0.08, right=0.97, top=0.92, bottom=0.15,
                )
            except Exception:
                pass
        else:
            # ── 标准布局：箱线（上）+ 折线（中）+ 靶心（下） ──
            base_height = 5.8 * float(getattr(self, "_s", 1.0))
            target_height = (max(2.2, n_targets * 2.2) if n_targets else 2.2) * float(getattr(self, "_s", 1.0))
            dynamic_height = base_height + target_height
            self.wi_compare_fig.set_figheight(dynamic_height)

            target_row_h = (target_height / base_height) * 0.82
            line_will_show = bool(meta["multi_column"] and meta["scalar_points"])
            
            if line_will_show and n_targets:
                hier_gap = 0.42
            elif line_will_show:
                hier_gap = 0.38
            else:
                hier_gap = 0.32
            
            gs = GridSpec(
                3, 1, figure=self.wi_compare_fig,
                height_ratios=[0.82, 0.82, target_row_h],
                hspace=hier_gap,
            )

            ax_box = self.wi_compare_fig.add_subplot(gs[0, 0])
            ax_line = self.wi_compare_fig.add_subplot(gs[1, 0])
            
            if n_targets > 0:
                gs_t = gs[2, 0].subgridspec(n_targets, n_dates, wspace=0.22, hspace=0.30)
                for ri in range(n_targets):
                    row_axes = []
                    for ci in range(n_dates):
                        ax = self.wi_compare_fig.add_subplot(gs_t[ri, ci])
                        row_axes.append(ax)
                    axes_grid.append(row_axes)
            else:
                ax_tgt_placeholder = self.wi_compare_fig.add_subplot(gs[2, 0])
                self._wi_compare_plot_empty_panel(
                    ax_tgt_placeholder, "本尺寸无 X/Y 坐标对\n无需靶心图", title="",
                )

            self._plot_wi_compare_box(
                ax_box, plot_df, grp, meta, show_xlabels=True, show_date_row=True,
            )
            hints.append("箱线")
            if line_will_show:
                self._plot_wi_compare_line(
                    ax_line, plot_df, grp, meta, show_xlabels=True, show_date_row=True, show_title=False,
                )
                hints.append("折线")
            elif meta["multi_column"]:
                self._wi_compare_plot_empty_panel(
                    ax_line, "本组仅有 X/Y 坐标对\n无标量测点折线", title="",
                )
            else:
                self._wi_compare_plot_empty_panel(
                    ax_line, "单列尺寸\n不生成折线图", title="",
                )
                
            if n_targets:
                self._plot_wi_compare_targets(axes_grid, plot_df, grp, xy_bases, unique_dates)
                hints.append(f"靶心{n_targets}×{n_dates}")

            if meta["multi_column"] and line_will_show:
                bottom_margin, adj_hspace = 0.16, hier_gap
            elif meta["multi_column"]:
                bottom_margin, adj_hspace = 0.16, hier_gap
            else:
                bottom_margin, adj_hspace = 0.12, 0.24
            try:
                self.wi_compare_fig.subplots_adjust(
                    left=0.07, right=0.98, top=0.96, bottom=bottom_margin, hspace=adj_hspace,
                )
            except Exception:
                pass

        # ── 底部信息栏（公共） ──
        n_dates_lbl = plot_df["test_time"].nunique() if "test_time" in plot_df.columns else 0
        n_pts = int(plot_df["value"].notna().sum()) if "value" in plot_df.columns else 0
        proc = self._get_selected_wi_process_name()
        col_txt = f"{meta['n_columns']} 列测点"
        pos_hint = "（位置度·仅靶心）" if is_positional_only else ""
        base_info = (
            f"【{grp.get('dim_no')}】{grp.get('dimension_description')}{pos_hint} · 制程 {proc} · "
            f"{col_txt} · {n_dates_lbl} 个批次 / {n_pts} 条测量 · {' + '.join(hints)}"
        )
        if machine_sel and machine_sel != "所有机台":
            base_info += f" · 机台 {machine_sel}"
        self._wi_compare_set_info_hint(base_info + "。单击图表数据点可查看明细。")

        dpi = getattr(self, "_wi_compare_fig_dpi", 100)
        self.wi_compare_canvas.setMinimumHeight(int(self.wi_compare_fig.get_figheight() * dpi))
        self.wi_compare_canvas.draw()

    def _plot_wi_compare_line(
        self, ax, df, grp, meta: dict, *, show_xlabels: bool = True, show_date_row: bool = True,
        show_title: bool = True,
    ):
        """折线图：同日内按测点连线，不同日期间断开（参考 ORT 均值折线）。"""
        ax.set_label("ax_wi_line")
        title = self._wi_compare_chart_title(grp)
        points = meta["scalar_points"]
        if not points:
            self._wi_compare_plot_empty_panel(ax, "无可用测点数据", title=title)
            return

        group_keys, hier_info = self._wi_compare_prepare_scalar_axis(df, grp, meta)
        self._wi_compare_group_keys = group_keys
        n_groups = len(group_keys)
        if n_groups == 0:
            self._wi_compare_plot_empty_panel(ax, "无可用测点数据", title=title)
            return

        usl, lsl, nominal = self._wi_compare_resolve_spec(df, grp)
        pos_map = {gk: gi for gi, gk in enumerate(group_keys)}
        sample_colors = plt.cm.tab10(np.linspace(0, 1, max(df["barcode"].nunique(), 1)))

        for si, (barcode, bdf) in enumerate(df.groupby("barcode")):
            color = sample_colors[si % len(sample_colors)]
            import collections
            seg_by_date = collections.OrderedDict()
            for _, row in bdf.iterrows():
                if group_keys and len(group_keys[0]) == 2:
                    key = (row["test_time"], row["point_name"])
                else:
                    key = (row["test_time"],)
                if key not in pos_map:
                    continue
                d = row["test_time"]
                if d not in seg_by_date:
                    seg_by_date[d] = {"xs": [], "ys": []}
                seg_by_date[d]["xs"].append(pos_map[key])
                seg_by_date[d]["ys"].append(float(row["value"]))
            for d, seg in seg_by_date.items():
                if len(seg["xs"]) >= 2:
                    order = np.argsort(seg["xs"])
                    xs = [seg["xs"][i] for i in order]
                    ys = [seg["ys"][i] for i in order]
                    ax.plot(xs, ys, color=color, marker="o", markersize=4,
                            linewidth=1.3, alpha=0.82, zorder=3)

        ax.set_facecolor("#FAFAFA")
        ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.45, color="#C5D9E8")
        if show_title:
            ax.set_title(title, fontsize=9, fontweight="bold", color="#2C3E50", pad=8)
        ax.set_ylabel("测量值", fontsize=8, color="#2C3E50")
        ax.set_xticks(range(n_groups))
        self._wi_compare_apply_spec_lines(ax, usl, lsl, nominal, float(n_groups))
        self._wi_compare_set_y_limits(ax, df["value"], usl, lsl)
        if show_xlabels:
            self._wi_compare_apply_hierarchical_xlabels(
                ax, group_keys, hier_info, show_date_row=show_date_row,
            )
        else:
            ax.set_xticklabels([])
            ax.tick_params(axis="x", length=0, labelbottom=False)

    def _plot_wi_compare_box(
        self, ax, df, grp, meta: dict, *, show_xlabels: bool = True, show_date_row: bool = True,
        show_title: bool = True,
    ):
        """箱线图：按日期×测点分组，含批次间均值连线（参考 ORT 箱线图）。"""
        ax.set_label("ax_wi_box")
        title = self._wi_compare_chart_title(grp)
        if meta["multi_column"]:
            points = meta["scalar_points"] or meta["all_points"]
            if not points:
                self._wi_compare_plot_empty_panel(ax, "无可用测点", title=title)
                return
            group_keys, hier_info = self._wi_compare_prepare_scalar_axis(df, grp, meta)
            use_hier = hier_info.get("use_hier", len(points) > 1)
        else:
            group_keys, hier_info = self._wi_compare_prepare_scalar_axis(
                df, grp, meta, single_column=True,
            )
            use_hier = False

        self._wi_compare_group_keys = group_keys
        n_groups = len(group_keys)
        if n_groups == 0:
            self._wi_compare_plot_empty_panel(ax, "无可用数据", title=title)
            return

        usl, lsl, nominal = self._wi_compare_resolve_spec(df, grp)
        data_per_group = []
        valid_pos = []
        mean_items = []
        rng = np.random.default_rng(42)

        for gi, gk in enumerate(group_keys):
            if use_hier:
                d, pt = gk
                subset = df[(df["test_time"] == d) & (df["point_name"] == pt)]["value"].dropna().tolist()
            else:
                d = gk[0]
                subset = df[df["test_time"] == d]["value"].dropna().tolist()
            if subset:
                data_per_group.append(subset)
                valid_pos.append(gi)
                mean_items.append((gi, float(np.mean(subset)), str(gk[-1]), d if use_hier else d))

        if data_per_group:
            bp = ax.boxplot(
                data_per_group, positions=valid_pos,
                widths=max(0.28, min(0.55, 3.8 / max(len(valid_pos), 1))),
                patch_artist=True, showmeans=True,
                boxprops=dict(facecolor="#A8C8E0", alpha=0.82, linewidth=0.9),
                medianprops=dict(color="#3A5A7A", linewidth=1.8),
                whiskerprops=dict(linewidth=0.8, color="#5B9BD5"),
                capprops=dict(linewidth=0.8, color="#5B9BD5"),
                meanprops=dict(marker="D", markerfacecolor="#2F80ED", markeredgecolor="#2F80ED", markersize=4),
                flierprops=dict(marker=".", markersize=3.5, alpha=0.45, color="#5B9BD5"),
            )
            for gi, d_idx in enumerate(valid_pos):
                if use_hier:
                    d = group_keys[d_idx][0]
                else:
                    d = group_keys[d_idx][0]
                sub = df[df["test_time"] == d] if not use_hier else df[
                    (df["test_time"] == group_keys[d_idx][0]) & (df["point_name"] == group_keys[d_idx][1])
                ]
                yv = sub["value"].dropna().values
                xj = rng.normal(d_idx, 0.05, size=len(yv))
                ax.scatter(xj, yv, color="#5B9BD5", alpha=0.35, s=10, zorder=2)

        if use_hier:
            self._ort_plot_mean_line_segments(
                ax, mean_items, color="#2F80ED", linestyle="--", linewidth=1.5,
                marker="o", markersize=4, break_by_key=True,
            )
        elif len(mean_items) >= 2:
            flat = [(p, v, lb, None) for p, v, lb, _ in mean_items]
            self._ort_plot_mean_line_segments(ax, flat, color="#2F80ED", linestyle="--", linewidth=1.5)

        ax.set_facecolor("#FAFAFA")
        ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.45, color="#C5D9E8")
        if show_title:
            ax.set_title(title, fontsize=9, fontweight="bold", color="#2C3E50", pad=8)
        ax.set_xticks(range(n_groups))
        self._wi_compare_apply_spec_lines(ax, usl, lsl, nominal, float(max(n_groups - 1, 1)))
        self._wi_compare_set_y_limits(ax, df["value"], usl, lsl)
        if show_xlabels:
            self._wi_compare_apply_hierarchical_xlabels(
                ax, group_keys, hier_info, show_date_row=show_date_row,
            )
        else:
            ax.set_xticklabels([])
            ax.tick_params(axis="x", length=0, labelbottom=False)

    def _plot_wi_compare_targets(self, axes_grid, df, grp, xy_bases: list[str], unique_dates: list[str]):
        """靶心图：每个 X/Y 坐标对一张，按日期拆分（横向按日期排列，纵向按坐标对排列）。"""
        work = df.copy()
        bases, coords = [], []
        for p in work["point_name"]:
            b, c = self._wi_compare_parse_point_coord(p)
            bases.append(b)
            coords.append(c)
        work["base_name"] = bases
        work["coord"] = coords
        work = work.dropna(subset=["coord"])
        all_pivoted = []

        for ti, base in enumerate(xy_bases):
            sub = work[work["base_name"] == base]
            if sub.empty:
                for di, d in enumerate(unique_dates):
                    ax = axes_grid[ti][di]
                    self._wi_compare_plot_empty_panel(ax, f"{base}\n无数据", title=base)
                continue

            pivoted_vals = sub.pivot_table(
                index=["test_time", "barcode", "machine"],
                columns="coord",
                values=["value", "nominal", "tol_max", "tol_min"],
                aggfunc="first",
            ).reset_index()
            if ("value", "X") not in pivoted_vals.columns or ("value", "Y") not in pivoted_vals.columns:
                for di, d in enumerate(unique_dates):
                    ax = axes_grid[ti][di]
                    self._wi_compare_plot_empty_panel(ax, f"{base}\n缺少 X/Y", title=base)
                continue

            pivoted = pd.DataFrame({
                "test_time": pivoted_vals["test_time"],
                "barcode": pivoted_vals["barcode"],
                "machine": pivoted_vals["machine"],
                "base_name": base,
                "val_x": pivoted_vals[("value", "X")],
                "val_y": pivoted_vals[("value", "Y")],
                "nom_x": pivoted_vals[("nominal", "X")].fillna(0) if ("nominal", "X") in pivoted_vals.columns else 0,
                "nom_y": pivoted_vals[("nominal", "Y")].fillna(0) if ("nominal", "Y") in pivoted_vals.columns else 0,
            })
            pivoted["dx"] = pivoted["val_x"] - pivoted["nom_x"]
            pivoted["dy"] = pivoted["val_y"] - pivoted["nom_y"]
            all_pivoted.append(pivoted)

            tol_max = None
            if ("tol_max", "X") in pivoted_vals.columns:
                s = pivoted_vals[("tol_max", "X")].dropna()
                if not s.empty:
                    tol_max = float(s.iloc[0])
            if tol_max is None and ("tol_max", "Y") in pivoted_vals.columns:
                s = pivoted_vals[("tol_max", "Y")].dropna()
                if not s.empty:
                    tol_max = float(s.iloc[0])

            tol_min = None
            if ("tol_min", "X") in pivoted_vals.columns:
                s = pivoted_vals[("tol_min", "X")].dropna()
                if not s.empty:
                    tol_min = float(s.iloc[0])
            if tol_min is None and ("tol_min", "Y") in pivoted_vals.columns:
                s = pivoted_vals[("tol_min", "Y")].dropna()
                if not s.empty:
                    tol_min = float(s.iloc[0])

            if tol_max is not None and tol_min is not None:
                tol_radius = (abs(tol_max) + abs(tol_min)) / 2.0
            else:
                tol_radius = max(float(pivoted["dx"].abs().max()), float(pivoted["dy"].abs().max()), 0.1)

            import matplotlib.patches as mpatches
            colors = ["#93C5FD", "#3B82F6", "#1D4ED8", "#312E81"]
            
            for di, d in enumerate(unique_dates):
                ax = axes_grid[ti][di]
                ax.set_label(f"ax_wi_target_{ti}_{di}")
                sub_d = pivoted[pivoted["test_time"] == d]
                
                ax.set_aspect("equal", adjustable="box")
                ax.set_facecolor("#FEF2F2")
                ax.add_patch(mpatches.Circle((0, 0), tol_radius, facecolor="#F0FDF4", edgecolor="#10B981", linewidth=1.0, zorder=1))
                ax.add_patch(mpatches.Circle((0, 0), tol_radius * 0.5, fill=False, edgecolor="#34D399", linestyle="--", linewidth=0.9, zorder=1))
                ax.axhline(0, color="#94A3B8", linestyle="--", linewidth=0.7, zorder=2)
                ax.axvline(0, color="#94A3B8", linestyle="--", linewidth=0.7, zorder=2)

                color = colors[di % len(colors)]
                if not sub_d.empty:
                    ax.scatter(sub_d["dx"], sub_d["dy"], color=color, alpha=0.88, s=28, zorder=4)

                lim = tol_radius * 1.2
                if not sub_d.empty:
                    lim = max(float(sub_d["dx"].abs().max()), float(sub_d["dy"].abs().max()), tol_radius) * 1.18
                ax.set_xlim(-lim, lim)
                ax.set_ylim(-lim, lim)
                ax.grid(True, linestyle=":", alpha=0.35, color="#94A3B8")
                ax.set_title(f"{base}", fontsize=9, fontweight="bold", color="#2C3E50")
                ax.set_xlabel(str(d), fontsize=9, color="#2C3E50", fontweight="bold")
                if di == 0:
                    ax.set_ylabel("dy", fontsize=7)
                ax.tick_params(labelsize=6)

        if all_pivoted:
            self._wi_compare_target_pivoted = pd.concat(all_pivoted, ignore_index=True)

    def _on_wi_compare_canvas_click(self, event):
        """在图表上点击时，计算并显示最近的数据点明细信息。"""
        if event.inaxes is None or event.xdata is None or event.ydata is None:
            return
        
        df = getattr(self, "_wi_compare_plot_df", None)
        if df is None or df.empty:
            df = getattr(self, "wi_compare_active_df", None)
        grp = getattr(self, "wi_compare_active_grp", None)
        if df is None or df.empty or grp is None:
            return
            
        x_click, y_click = float(event.xdata), float(event.ydata)
        ax = event.inaxes
        closest_row = None
        min_dist = float("inf")
        pick_threshold = 0.35
        
        ax_lbl = ax.get_label() or ""
        group_keys = getattr(self, "_wi_compare_group_keys", []) or []

        if ax_lbl == "ax_wi_line":
            for gi, gk in enumerate(group_keys):
                if len(gk) != 2:
                    continue
                d, pt = gk
                for _, row in df[(df["test_time"] == d) & (df["point_name"] == pt)].iterrows():
                    dx = float(gi) - x_click
                    dy = float(row["value"]) - y_click
                    dist = (dx * dx + dy * dy) ** 0.5
                    if dist < min_dist:
                        min_dist = dist
                        closest_row = row
        elif ax_lbl == "ax_wi_box":
            for gi, gk in enumerate(group_keys):
                if len(gk) == 2:
                    d, pt = gk
                    sub = df[(df["test_time"] == d) & (df["point_name"] == pt)]
                else:
                    d = gk[0]
                    sub = df[df["test_time"] == d]
                for _, row in sub.iterrows():
                    dx = float(gi) - x_click
                    dy = float(row["value"]) - y_click
                    dist = (dx * dx + dy * dy) ** 0.5
                    if dist < min_dist:
                        min_dist = dist
                        closest_row = row
        elif ax_lbl.startswith("ax_wi_target"):
            pivoted = getattr(self, "_wi_compare_target_pivoted", None)
            if pivoted is not None and not pivoted.empty:
                m = re.match(r"^ax_wi_target_(\d+)_(\d+)", ax_lbl)
                if m:
                    ti, di = int(m.group(1)), int(m.group(2))
                    xy_bases = self._wi_compare_xy_bases(grp)
                    unique_dates = sorted(df["test_time"].dropna().unique().tolist(), key=str)
                    if ti < len(xy_bases) and di < len(unique_dates):
                        clicked_base = xy_bases[ti]
                        clicked_date = unique_dates[di]
                        pivoted_sub = pivoted[(pivoted["base_name"] == clicked_base) & (pivoted["test_time"] == clicked_date)]
                    else:
                        pivoted_sub = pivoted
                else:
                    pivoted_sub = pivoted

                for _, row in pivoted_sub.iterrows():
                    dx = row["dx"] - x_click
                    dy = row["dy"] - y_click
                    dist = (dx * dx + dy * dy) ** 0.5
                    if dist < min_dist:
                        min_dist = dist
                        closest_row = row
                
                if closest_row is not None and min_dist <= pick_threshold * 2:
                    mch = closest_row.get("machine") or closest_row.get("barcode") or "N/A"
                    info = (
                        f"【打靶点明细】检测时间: {closest_row['test_time']} | "
                        f"机台号: {mch} | "
                        f"X测量值: {closest_row['val_x']} (偏差: {closest_row['dx']:+.4f}) | "
                        f"Y测量值: {closest_row['val_y']} (偏差: {closest_row['dy']:+.4f})"
                    )
                    self.wi_compare_info_lbl.setText(info)
                    self.wi_compare_info_lbl.setStyleSheet(f"""
                        font-size: {int(12 * self._s)}px;
                        color: #0F4C81;
                        background-color: #EBF3FC;
                        border: 1px solid #B8D4E8;
                        border-radius: 4px;
                        padding: {int(6 * self._s)}px;
                        font-weight: bold;
                    """)
                    return

        if closest_row is not None and min_dist <= pick_threshold:
            if isinstance(closest_row, dict):
                mch = closest_row.get("machine") or "批次均值"
                val_txt = f"{closest_row['value']:.4f}" if closest_row.get("_is_mean") else str(closest_row.get("value"))
                info = (
                    f"【{'批次均值' if closest_row.get('_is_mean') else '选定点'}】"
                    f"检测时间: {closest_row['test_time']} | 测点: {closest_row['point_name']} | "
                    f"{'均值' if closest_row.get('_is_mean') else '测量值'}: {val_txt} mm"
                )
            else:
                mch = closest_row.get("machine") or closest_row.get("barcode") or "N/A"
                info = (
                    f"【选定点明细】检测时间: {closest_row['test_time']} | "
                    f"测点: {closest_row['point_name']} | "
                    f"机台号: {mch} | "
                    f"测量值: {closest_row['value']} mm"
                )
                nom = closest_row.get("nominal")
                if nom is not None and not pd.isna(nom):
                    dev = closest_row["value"] - nom
                    info += f" | 公称值: {nom} mm (偏差: {dev:+.4f} mm)"
                
            self.wi_compare_info_lbl.setText(info)
            self.wi_compare_info_lbl.setStyleSheet(f"""
                font-size: {int(12 * self._s)}px;
                color: #0F4C81;
                background-color: #EBF3FC;
                border: 1px solid #B8D4E8;
                border-radius: 4px;
                padding: {int(6 * self._s)}px;
                font-weight: bold;
            """)

    def _create_wi_global_filter_controls(self, parent_layout):
        """创建 Weekly Inspection 全局筛选控件（模板选择 + 时间范围）- 与 ORT 样式保持一致。"""
        controls = QFrame()
        controls.setObjectName("wi_global_filter_controls")
        controls.setStyleSheet(f"""
            QFrame#wi_global_filter_controls {{
                background-color: #F5F9FF;
                border: 1px solid #C5D9E8;
                border-radius: 8px;
            }}
        """)
        toolbar_lay = QHBoxLayout(controls)
        toolbar_lay.setContentsMargins(int(8 * self._s), int(4 * self._s), int(8 * self._s), int(4 * self._s))
        toolbar_lay.setSpacing(int(6 * self._s))

        combo_style = f"""
            QComboBox {{
                background-color: #FFFFFF;
                border: 1px solid #C5D9E8;
                border-radius: 6px;
                padding: {int(4*self._s)}px {int(8*self._s)}px;
                font-size: {int(13*self._s)}px;
                color: #2C3E50;
            }}
            QComboBox:hover {{ border-color: #5B9BD5; }}
            QComboBox::drop-down {{ border: none; width: 20px; }}
        """

        prod_lbl = QLabel("产品:")
        prod_lbl.setStyleSheet(f"font-size: {int(13*self._s)}px; font-weight: 600; color: #3A5A7A;")
        toolbar_lay.addWidget(prod_lbl)

        self.wi_global_product_combo = QComboBox()
        self.wi_global_product_combo.setObjectName("wi_global_product_combo")
        self.wi_global_product_combo.setFixedWidth(int(120 * self._s))
        self.wi_global_product_combo.setStyleSheet(combo_style)
        toolbar_lay.addWidget(self.wi_global_product_combo)

        sep = QFrame()
        sep.setFrameShape(QFrame.VLine)
        sep.setStyleSheet("color: #C5D9E8;")
        sep.setFixedWidth(1)
        toolbar_lay.addWidget(sep)

        date_lbl = QLabel("检测日期:")
        date_lbl.setStyleSheet(f"font-size: {int(13*self._s)}px; font-weight: 600; color: #3A5A7A;")
        toolbar_lay.addWidget(date_lbl)

        self.wi_global_date_btn = QPushButton("点击选择制程与检测日期")
        self.wi_global_date_btn.setObjectName("wi_global_date_btn")
        self.wi_global_date_btn.setCursor(QCursor(Qt.PointingHandCursor))
        self.wi_global_date_btn.setMinimumWidth(int(200 * self._s))
        self.wi_global_date_btn.setMaximumWidth(int(280 * self._s))
        wi_ctrl_h = self._wi_toolbar_control_height()
        self.wi_global_date_btn.setFixedHeight(wi_ctrl_h)
        self.wi_global_date_btn.setStyleSheet(f"""
            QPushButton {{
                background: #FFFFFF;
                border: 1px solid #B8D4E8;
                border-radius: 6px;
                padding: 0px 10px;
                font-size: {int(12*self._s)}px;
                color: #3A5A7A;
                text-align: left;
            }}
            QPushButton:hover {{ border-color: #5B9BD5; background: #F5F9FF; }}
        """)
        toolbar_lay.addWidget(self.wi_global_date_btn)

        self.wi_global_date_menu = QMenu(self.wi_global_date_btn)
        self.wi_global_date_menu.setObjectName("wi_global_date_menu")
        self.wi_global_date_menu.setStyleSheet(f"""
            QMenu {{
                background-color: #FFFFFF;
                border: 1px solid #B8D4E8;
                border-radius: 8px;
                padding: {int(6*self._s)}px;
            }}
        """)
        menu_host = QWidget()
        menu_lay = QVBoxLayout(menu_host)
        menu_lay.setContentsMargins(4, 4, 4, 4)
        menu_lay.setSpacing(4)
        self.wi_process_date_picker = WiProcessDatePickerWidget(
            menu_host,
            ui_scale=self._s,
            on_confirm=self._on_wi_process_date_picker_confirm,
        )
        menu_lay.addWidget(self.wi_process_date_picker)
        menu_action = QWidgetAction(self.wi_global_date_menu)
        menu_action.setDefaultWidget(menu_host)
        self.wi_global_date_menu.addAction(menu_action)

        def _show_wi_date_menu():
            self._sync_wi_process_date_picker()
            self.wi_global_date_menu.exec_(
                self.wi_global_date_btn.mapToGlobal(
                    QPoint(0, self.wi_global_date_btn.height())
                )
            )

        self.wi_global_date_btn.clicked.connect(_show_wi_date_menu)

        # 刷新按钮
        refresh_btn = QPushButton("刷新")
        refresh_btn.setObjectName("wi_global_refresh_btn")
