        """Weekly Inspection 全局刷新：先同步制程/日期，再加载并渲染总览。"""
        self._sync_wi_process_date_picker()
        picker = getattr(self, "wi_process_date_picker", None)
        if picker is not None:
            self._wi_selected_processes = set(picker.selected_processes())
        self._sync_wi_overview_process_chips()
        if self._refresh_wi_cpk_dashboard(show_tip=True):
            self._set_wi_global_refresh_btn_success(True)
        else:
            self._set_wi_global_refresh_btn_success(False)

