    def _init_ort_global_type_selector(self):
        """初始化 ORT 顶部类型筛选与批次日历（跟随模板树中的大类）。"""
        if not hasattr(self, "_global_type_product_map"):
            self._global_type_product_map = {}
            self._load_global_type_product_map()

        categories = self._category_names_for_module(self.DEFAULT_MODULE_NAME)
        current_type = self._get_current_global_type()
        if not current_type or current_type not in categories:
            current_type = categories[0] if categories else "—"
        if hasattr(self, "ort_global_type_btn"):
            self.ort_global_type_btn.setText(current_type)

        if hasattr(self, "ort_global_product_list"):
            _m, _c, product_name = self._ensure_yield_scope_state()
            prefer = product_name if str(_c or "").strip() == str(current_type or "").strip() else None
            self._load_global_products_by_type(current_type, select_first=True, prefer_product=prefer)
            selected = self._get_selected_global_product()
            if selected:
                self._set_yield_scope(category=current_type, product_name=selected, refresh_views=False)
            self._sync_ort_global_date_range_by_selection()
        else:
            self._sync_ort_global_date_range_by_type()

    def _refresh_ort_global_type_menu(self):
        """根据 ORT 模板树中的大类刷新顶部类型菜单。"""
        if not hasattr(self, "ort_global_type_menu"):
            return
        self.ort_global_type_menu.clear()
        for type_name in self._category_names_for_module(self.DEFAULT_MODULE_NAME):
            action = self.ort_global_type_menu.addAction(type_name)
            action.triggered.connect(lambda checked=False, t=type_name: self._on_global_type_selected(t))

    def _load_global_type_product_map(self):
        """从模板树与数据库加载类型-产品映射关系。"""
        categories = self._category_names_for_module(self.DEFAULT_MODULE_NAME)
        self._global_type_product_map = {cat: [] for cat in categories}
        template_map = self._get_yield_category_product_map().get(self.DEFAULT_MODULE_NAME, {})

        for type_name in categories:
            merged: set[str] = set()
            for name in template_map.get(type_name, []) or []:
                val = str(name or "").strip()
                if val:
                    merged.add(val)
            if hasattr(self, '_ort_db') and self._ort_db is not None:
                try:
                    for name in self._ort_db.get_products_by_category(
                        type_name, module_name=self.DEFAULT_MODULE_NAME
                    ) or []:
                        val = str(name or "").strip()
                        if val:
                            merged.add(val)
                except Exception as e:
                    print(f"加载类型-产品映射失败: {e}")
            self._global_type_product_map[type_name] = sorted(merged, key=lambda x: x.lower())

        if hasattr(self, "ort_global_product_list"):
            self._load_global_products_by_type(
                self._get_current_global_type(),
                select_first=False,
                prefer_product=self._get_selected_global_product(),
            )

    def _load_global_products_by_type(
        self,
        type_name: str,
        select_first: bool = False,
        prefer_product: str | None = None,
    ):
        """根据类型加载产品列表到顶部选择器（单选）。"""
        if not hasattr(self, "ort_global_product_list"):
            return

        product_list = self.ort_global_product_list
        if not hasattr(self, "_global_type_product_map"):
            self._load_global_type_product_map()
        products = (getattr(self, "_global_type_product_map", {}) or {}).get(type_name, [])

        product_list.blockSignals(True)
        try:
            product_list.clear()
            for product in products:
                product_list.addItem(QListWidgetItem(str(product)))

            pick_idx = -1
            prefer = str(prefer_product or "").strip()
            if prefer:
                for i in range(product_list.count()):
                    if product_list.item(i).text().strip() == prefer:
                        pick_idx = i
                        break
            if pick_idx < 0 and select_first and product_list.count() > 0:
                pick_idx = 0
            if pick_idx >= 0:
                product_list.setCurrentRow(pick_idx)
            else:
                product_list.clearSelection()
        finally:
            product_list.blockSignals(False)

        self._update_global_product_button_text()

    def _update_global_product_button_text(self):
        """更新顶部产品选择按钮的显示文本。"""
        if not hasattr(self, "ort_global_product_btn"):
            return
        product_name = self._get_selected_global_product()
        self.ort_global_product_btn.setText(product_name or "请选择产品")

    def _sync_global_product_selector_to_scope(self, product_name: str | None = None):
        """良率页切换产品时，同步顶部产品选择器。"""
        if not hasattr(self, "ort_global_product_list"):
            return
        name = str(product_name or "").strip()
        if not name:
            _m, _c, name = self._ensure_yield_scope_state()
            name = str(name or "").strip()
        if not name:
            return
        product_list = self.ort_global_product_list
        for i in range(product_list.count()):
            if product_list.item(i).text().strip() == name:
                product_list.blockSignals(True)
                try:
                    product_list.setCurrentRow(i)
                finally:
                    product_list.blockSignals(False)
                self._update_global_product_button_text()
                break

    def _on_global_product_item_selected(self, item: QListWidgetItem):
        """顶部产品单选：同步作用域、批次日历并关闭下拉。"""
        if item is None:
            return
        self._update_global_product_button_text()
        product_name = self._get_selected_global_product()
        category = self._get_current_global_type()
        self._sync_ort_global_date_range_by_selection(clamp_dates=True)
        self._set_yield_scope(category=category, product_name=product_name or None, refresh_views=False)
        if getattr(self, "_current_ort_tab_idx", -1) == 0:
            self._refresh_yield_dashboard("yield_menu")
        self._on_ort_global_scope_inputs_changed()
        menu = getattr(self, "ort_global_product_menu", None)
        if menu is not None:
            menu.close()

    def _get_global_type_products(self) -> list[str]:
        """当前类型（DH/Stand/FATP）下的全部产品列表。"""
        type_name = self._get_current_global_type()
        products = (getattr(self, "_global_type_product_map", {}) or {}).get(type_name, [])
        return [str(p).strip() for p in products if str(p).strip()]

    def _get_selected_global_product(self) -> str:
        """获取当前选中的单个产品名称。"""
        if hasattr(self, "ort_global_product_list"):
            item = self.ort_global_product_list.currentItem()
            if item is not None:
                return str(item.text() or "").strip()
        products = self._get_global_type_products()
        return products[0] if products else ""

    def _get_selected_global_products(self) -> list[str]:
        """当前选中的产品（0 或 1 个）。"""
        product = self._get_selected_global_product()
        return [product] if product else []

    def _collect_global_type_batch_dates(self) -> list[str]:
        """汇总当前类型下所有产品（及内存导入）已有数据的检测日期。"""
        category = self._get_current_global_type()
        dates: set[str] = set()
        module_name = self.DEFAULT_MODULE_NAME

        if self._is_yield_memory_mode():
            for raw in self._get_memory_yield_date_strings(
                module_name=module_name,
                category=category,
                product_name=None,
            ):
                dates.add(raw)

        mgr = getattr(self, "_ort_db", None)
        if mgr is not None:
            try:
                for raw in mgr.get_test_dates(
                    module_name=module_name,
                    category=category,
                    product_name=None,
                ):
                    dates.add(str(raw).strip()[:10])
            except Exception:
                pass

        return sorted(dates)

    def _collect_global_product_batch_dates(self, category: str, product_name: str) -> list[str]:
        """汇总当前类型下单个产品已有数据的检测日期。"""
        dates: set[str] = set()
        module_name = self.DEFAULT_MODULE_NAME
        cat = str(category or "").strip()
        prod = str(product_name or "").strip()
        if not cat or not prod:
            return []

        if self._is_yield_memory_mode():
            for raw in self._get_memory_yield_date_strings(
                module_name=module_name,
                category=cat,
                product_name=prod,
            ):
                dates.add(raw)

        mgr = getattr(self, "_ort_db", None)
        if mgr is not None:
            try:
                for raw in mgr.get_test_dates(
                    module_name=module_name,
                    category=cat,
                    product_name=prod,
                ):
                    dates.add(str(raw).strip()[:10])
            except Exception:
                pass

        return sorted(dates)

    def _collect_global_product_batch_dates(self, category: str, product_name: str) -> list[str]:
        """汇总当前类型下单个产品已有数据的检测日期。"""
        dates: set[str] = set()
        module_name = self.DEFAULT_MODULE_NAME
        cat = str(category or "").strip()
        prod = str(product_name or "").strip()
        if not cat or not prod:
            return []

        if self._is_yield_memory_mode():
            for raw in self._get_memory_yield_date_strings(
                module_name=module_name,
                category=cat,
                product_name=prod,
            ):
                dates.add(raw)

        mgr = getattr(self, "_ort_db", None)
        if mgr is not None:
            try:
                for raw in mgr.get_test_dates(
                    module_name=module_name,
                    category=cat,
                    product_name=prod,
                ):
                    dates.add(str(raw).strip()[:10])
            except Exception:
                pass

        return sorted(dates)

    def _apply_ort_global_batch_dates(self, batch_dates: list[str], *, clamp_dates: bool = True):
        """ORT 顶部日历：仅批次日淡蓝可选，首尾批次日作为 QDateEdit 边界。"""
        from PyQt5.QtCore import QDate

        batch_dates = sorted({str(d).strip()[:10] for d in (batch_dates or []) if str(d).strip()})
        if batch_dates:
            qdates = [QDate.fromString(d, "yyyy-MM-dd") for d in batch_dates]
            qdates = [d for d in qdates if d.isValid()]
            if qdates:
                min_date, max_date = min(qdates), max(qdates)
            else:
                min_date = QDate.currentDate().addYears(-1)
                max_date = QDate.currentDate()
        else:
            min_date = QDate.currentDate().addYears(-1)
            max_date = QDate.currentDate()

        for cal in (getattr(self, "ort_global_cal_start", None), getattr(self, "ort_global_cal_end", None)):
            if cal is None:
                continue
            if isinstance(cal, WiBatchCalendar):
                cal.setAllowedBatchDates(batch_dates)
            elif hasattr(cal, "setAllowedDateRange"):
                cal.setAllowedDateRange(min_date, max_date)
                cal.updateCells()

        for date_edit in (getattr(self, "ort_global_date_start", None), getattr(self, "ort_global_date_end", None)):
            if date_edit is None:
                continue
            date_edit.setMinimumDate(min_date)
            date_edit.setMaximumDate(max_date)
            if not clamp_dates:
                continue
            cur = date_edit.date()
            if batch_dates:
                pick = self._wi_clamp_date_to_batch(cur, batch_dates, max_date)
                if pick != cur:
                    date_edit.setDate(pick)
            elif cur < min_date:
                date_edit.setDate(min_date)
            elif cur > max_date:
                date_edit.setDate(max_date)

    def _sync_ort_global_date_range_by_type(self, *, clamp_dates: bool = True):
        """根据当前类型汇总全部产品的可选批次日。"""
        self._apply_ort_global_batch_dates(
            self._collect_global_type_batch_dates(),
            clamp_dates=clamp_dates,
        )

    def _sync_ort_global_date_range_by_selection(self, *, clamp_dates: bool = True):
        """根据当前选中的类型+产品同步批次日历。为了使用户选择时间范围后能任意选择产品，不再将批次日历限制在单个产品，而是采用该大类下全部产品的批次日并集。"""
        batch_dates = self._collect_global_type_batch_dates()
        return self._apply_ort_global_batch_dates(batch_dates, clamp_dates=clamp_dates)


    def _on_global_type_selected(self, type_name: str):
        """类型变化：刷新产品列表、批次日历并同步各板块。"""
        if hasattr(self, "ort_global_type_btn"):
            self.ort_global_type_btn.setText(type_name)
        prev_product = self._get_selected_global_product()
        self._load_global_products_by_type(
            type_name,
            select_first=True,
            prefer_product=prev_product,
        )
        selected = self._get_selected_global_product()
        self._sync_ort_global_date_range_by_selection(clamp_dates=True)
        self._set_yield_scope(category=type_name, product_name=selected or None, refresh_views=False)
        if getattr(self, "_current_ort_tab_idx", -1) == 0:
            self._refresh_yield_dashboard("yield_menu")
        self._on_ort_global_scope_inputs_changed()

    def _get_current_global_type(self) -> str:
        """获取当前选中的类型。"""
        if hasattr(self, 'ort_global_type_btn'):
            txt = str(self.ort_global_type_btn.text() or "").strip()
            if txt in ("", "—", "–", "-"):
                return ""
            return txt
        return ""

    def _resolve_multi_product_date_range(self, category: str, product_names: list[str]) -> tuple[QDate, QDate]:
        """计算多个产品的日期范围交集。"""
        from PyQt5.QtCore import QDate

        if not product_names:
            return QDate.currentDate().addYears(-1), QDate.currentDate()

        # 获取每个产品的日期范围
        all_ranges = []
        for product in product_names:
            min_date, max_date = self._resolve_yield_date_range(
                module_name=None,
                category=category,
                product_name=product
            )
            all_ranges.append((min_date, max_date))

        # 计算交集：最大开始日期，最小结束日期
        intersection_min = max(r[0] for r in all_ranges)
        intersection_max = min(r[1] for r in all_ranges)

        # 如果交集无效（没有重叠），返回第一个产品的范围作为默认值
        if intersection_min > intersection_max:
            return all_ranges[0]

        return intersection_min, intersection_max

    def _sync_ort_global_date_range(self):
        """同步全局时间选择器（优先按顶部类型批次日）。"""
        if hasattr(self, "ort_global_type_btn"):
            self._sync_ort_global_date_range_by_type(clamp_dates=False)
            return
        module_name, category, product_name = self._ensure_yield_scope_state()
        min_date, max_date = self._resolve_yield_date_range(
            module_name=module_name,
            category=category,
            product_name=product_name,
        )
        self._apply_ort_global_batch_dates([], clamp_dates=False)
        for cal in (getattr(self, "ort_global_cal_start", None), getattr(self, "ort_global_cal_end", None)):
            if cal is not None and hasattr(cal, "setAllowedDateRange"):
                cal.setAllowedDateRange(min_date, max_date)
                cal.updateCells()

    def _refresh_all_ort_sections_from_global(self) -> bool:
        """顶部「刷新/当天」：按当前类型、时间范围同步 ORT 全部板块。"""
        category = self._get_current_global_type()
        if not category:
            QMessageBox.information(self, "提示", "请先选择类型。")
            return False

        start_date, end_date = self._ort_global_date_range_strings()
        if start_date > end_date:
            QMessageBox.information(self, "提示", "开始日期不能晚于结束日期。")
            return False

        if hasattr(self, "ort_global_date_start") and hasattr(self, "ort_global_date_end"):
            q_start = self.ort_global_date_start.date()
            q_end = self.ort_global_date_end.date()
            if hasattr(self, "_yield_views"):
                for refs in self._yield_views.values():
                    if not refs:
                        continue
                    if refs.get("date_start"):
                        refs["date_start"].setDate(q_start)
                    if refs.get("date_end"):
                        refs["date_end"].setDate(q_end)

        self._set_yield_stats_mode("db_range")
        self._set_yield_scope(
            category=category,
            product_name=self._get_selected_global_product() or None,
            refresh_views=False,
        )
        self._refresh_yield_dashboard("yield_menu")

        had_chart = bool((getattr(self, "_ort_fig_cache", {}) or {}).get("generated"))
        spc_result = getattr(self, "spc_result_table", None)
        spc_stat = getattr(self, "spc_stat_table", None)
        had_spc = bool(
            (spc_result is not None and spc_result.rowCount() > 0)
            or (spc_stat is not None and spc_stat.rowCount() > 0)
        )

        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            self._initialize_ort_db_analysis_ui(update_placeholder=False)
            self._sync_ort_db_scope_from_global()
            self._refresh_ort_db_filter_lists()
            self._schedule_ort_update(delay_ms=80, do_plot=had_chart)
            self._refresh_ort_report_table()
            if had_spc:
                self._run_spc_analysis()
        else:
            if hasattr(self, "_ort_raw_df") and self._ort_raw_df is not None:
                self._schedule_ort_update(delay_ms=80, do_plot=had_chart)
            report_df = getattr(self, "_ort_report_df", None)
            if report_df is not None and not getattr(report_df, "empty", True):
                self._update_ort_report_table(report_df)
            if had_spc:
                self._run_spc_analysis()

        return True

    def _on_ort_global_date_refresh(self):
        """全局刷新按钮：根据选择的产品和时间范围刷新 ORT 全部板块。"""
        if not self._refresh_all_ort_sections_from_global():
            return

        # 刷新成功后，按钮变为绿色背景
        if hasattr(self, 'ort_global_btn_refresh'):
            self.ort_global_btn_refresh.setStyleSheet(f"""
                QPushButton {{
                    background-color: #4CAF50;
                    color: #FFFFFF;
                    border: 1px solid #388E3C;
                    border-radius: 6px;
                    padding: 4px 10px;
                    font-size: {int(11*self._s)}px;
                    font-weight: 600;
                }}
                QPushButton:hover {{
                    background-color: #45A049;
                    border-color: #2E7D32;
                }}
            """)

    def _query_yield_data_from_memory(self, start_date: str, end_date: str, category: str, product_name: str) -> list:
        """从内存数据查询良率数据。"""
        if not hasattr(self, 'current_df') or self.current_df is None or self.current_df.empty:
            return []

        df = self.current_df.copy()

        # 过滤产品
        if 'Product' in df.columns:
            df = df[df['Product'].astype(str).str.contains(product_name, case=False, na=False)]
        elif 'product' in df.columns:
            df = df[df['product'].astype(str).str.contains(product_name, case=False, na=False)]

        # 过滤日期
        date_col = None
        for col in df.columns:
            if 'date' in col.lower() or '时间' in col or '日期' in col:
                date_col = col
                break

        if date_col:
            df[date_col] = pd.to_datetime(df[date_col], errors='coerce')
            start_dt = pd.to_datetime(start_date)
            end_dt = pd.to_datetime(end_date)
            df = df[(df[date_col] >= start_dt) & (df[date_col] <= end_dt)]

        # 转换为良率数据格式
        yield_data = []
        if not df.empty:
            # 按测试项分组统计
            test_item_col = None
            for col in df.columns:
                if 'item' in col.lower() or '项目' in col or '测试项' in col:
                    test_item_col = col
                    break

            if test_item_col:
                for item_name, group in df.groupby(test_item_col):
                    total = len(group)
                    ng_count = 0
                    # 查找NG标记列
                    for col in group.columns:
                        if 'result' in col.lower() or '结果' in col or '判定' in col:
                            ng_count = len(group[group[col].astype(str).str.contains('NG|Fail|不合格', case=False, na=False)])
                            break
                    yield_rate = ((total - ng_count) / total * 100) if total > 0 else 0
                    yield_data.append({
                        'test_item': item_name,
                        'total': total,
                        'ng': ng_count,
                        'ok': total - ng_count,
                        'yield_rate': yield_rate,
                        'product_name': product_name,
                    })

        return yield_data

    def _update_yield_bars_for_global_view(self, yield_data: list, product_names: list[str], category: str, start_date: str, end_date: str):
        """更新全局视图的良率显示。"""
        # 聚合数据：按测试项汇总
        aggregated = {}
        for item in yield_data:
            key = item.get('test_item', 'Unknown')
            if key not in aggregated:
                aggregated[key] = {
                    'test_item': key,
                    'total': 0,
                    'ng': 0,
                    'ok': 0,
                    'products': set(),
                }
            aggregated[key]['total'] += item.get('total', 0)
            aggregated[key]['ng'] += item.get('ng', 0)
            aggregated[key]['ok'] += item.get('ok', 0)
            aggregated[key]['products'].add(item.get('product_name', ''))

        # 计算良率并转换为图表需要的格式
        result = []
        for key, data in aggregated.items():
            total = data['total']
            ng = data['ng']
            ok = data['ok']
            yield_rate = (ok / total * 100) if total > 0 else 0
            result.append({
                'recipe': key,
                'subpart': '默认',
                'total': total,
                'ng_count': ng,
                'alert_count': 0,
                'ok_count': ok,
                'yield_rate': yield_rate,
            })

        # 更新良率图表显示
        # 找到良率监控页面的视图并更新
        if hasattr(self, '_yield_views'):
            for view_key, refs in self._yield_views.items():
                if refs and 'yield_container' in refs:
                    self._update_yield_bars(result, view_key)
                    break

        # 显示统计信息
        total_items = len(result)
        avg_yield = sum(r['yield_rate'] for r in result) / total_items if total_items > 0 else 0
        print(f"良率统计: {category} 类别, 产品 {product_names}, 时间 {start_date} 至 {end_date}")
        print(f"共 {total_items} 个测试项, 平均良率 {avg_yield:.2f}%")

    def _on_ort_global_date_latest(self):
        """全局当天数据按钮：取当前类型下全部产品中最新的检测日并刷新。"""
        from PyQt5.QtCore import QDate

        category = self._get_current_global_type()
        if not category:
            QMessageBox.information(self, "提示", "请先选择类型。")
            return

        latest_dates: list[QDate] = []
        selected_product = self._get_selected_global_product()
        if selected_product:
            latest_date = self._resolve_yield_latest_date(
                module_name=None,
                category=category,
                product_name=selected_product,
            )
            if latest_date.isValid():
                latest_dates.append(latest_date)
        else:
            for product_name in self._get_global_type_products():
                latest_date = self._resolve_yield_latest_date(
                    module_name=None,
                    category=category,
                    product_name=product_name,
                )
                if latest_date.isValid():
                    latest_dates.append(latest_date)

        latest_date = self._resolve_yield_latest_date(
            module_name=None,
            category=category,
            product_name=None,
        )
        if latest_date.isValid():
            latest_dates.append(latest_date)

        if not latest_dates:
            QMessageBox.information(self, "提示", "当前类型下暂无可用的检测日期。")
            return

        latest_date = max(latest_dates)

        # 设置全局日期控件
        if hasattr(self, 'ort_global_date_start') and latest_date.isValid():
            self.ort_global_date_start.setDate(latest_date)
        if hasattr(self, 'ort_global_date_end') and latest_date.isValid():
            self.ort_global_date_end.setDate(latest_date)

        # 更新所有良率监控视图的日期控件
        if hasattr(self, '_yield_views'):
            for view_key, refs in self._yield_views.items():
                if refs:
                    if 'date_start' in refs and refs['date_start']:
                        refs['date_start'].setDate(latest_date)
                    if 'date_end' in refs and refs['date_end']:
                        refs['date_end'].setDate(latest_date)

        self._refresh_all_ort_sections_from_global()

    def _resolve_yield_latest_date(self, module_name=None, category=None, product_name=None):
        """获取当前作用域下的最新日期。"""
        from PyQt5.QtCore import QDate

        category_val = str(category or "").strip()
        product_val = str(product_name or "").strip()
        latest_date_str = ""

        mem_ok = self._is_yield_memory_mode()
        if mem_ok:
            memory_dates = self._get_memory_yield_date_strings(
                module_name=self._normalize_module_name(module_name),
                category=category_val,
                product_name=product_val,
            )
            if memory_dates:
                latest_date_str = memory_dates[-1]

        if not latest_date_str and hasattr(self, "_ort_db") and self._ort_db is not None:
            _, max_date_str = self._ort_db.get_test_date_range(
                module_name=self._normalize_module_name(module_name) or None,
                category=category_val or None,
                product_name=product_val or None,
            )
            latest_date_str = max_date_str

        if latest_date_str:
            qd = QDate.fromString(latest_date_str, "yyyy-MM-dd")
            if qd.isValid():
                return qd

        # 默认返回当前日期
        return QDate.currentDate()

    def _refresh_ort_analysis_data(self):
        """刷新图形分析页面数据。"""
        # 触发图形分析的数据刷新
        if hasattr(self, '_schedule_ort_update'):
            self._schedule_ort_update(delay_ms=100, do_plot=True)

