    def _sync_module_page(self, module_name: str):
        """根据模块名同步切换主内容区页面和导航状态（用于模板树点击联动）。"""
        module_names = ["ORT", "Weekly Inspection"]
        if module_name not in module_names:
            return
        nav_idx = module_names.index(module_name)
        self._active_module_nav_idx = nav_idx
        self._active_template_module = module_name
        page_idx = nav_idx + 1
        if hasattr(self, "module_content_stack"):
            self.module_content_stack.setCurrentIndex(page_idx)
        if hasattr(self, "module_nav_row"):
            self.module_nav_row.setVisible(False)
        self._update_module_nav_styles()

    def _on_module_nav_clicked(self, idx: int):
        """点击模块导航卡片时切换内容页面。"""
        self._active_module_nav_idx = idx
        module_names = ["ORT", "Weekly Inspection", "IPQC", "CPK"]
        if 0 <= idx < len(module_names):
            self._active_template_module = module_names[idx]
        # 页面索引：0=欢迎页，1=ORT, 2=Weekly Inspection
        page_idx = idx + 1
        if hasattr(self, "module_content_stack"):
            self.module_content_stack.setCurrentIndex(page_idx)
        # 选中模块时隐藏顶部导航卡片
        if hasattr(self, "module_nav_row"):
            self.module_nav_row.setVisible(False)
        self._update_module_nav_styles()

        # 如果切换到ORT模块，重置Tab到良率监控
        if idx == 0 and hasattr(self, "ort_content_stack"):
            self._init_ort_yield_scope(refresh_views=False)
            self._current_ort_tab_idx = 0
            self.ort_content_stack.setCurrentIndex(0)
            self._update_ort_tab_styles()
        elif idx == 1:
            self._load_wi_global_product_combo()
            self._sync_wi_overview_process_chips()
            if hasattr(self, "wi_content_stack") and self.wi_content_stack.currentIndex() == 0:
                self._show_wi_cpk_idle_hint()

