    def eventFilter(self, obj, event):
        """首页预览区随窗口缩放同步表格可视高度。"""
        if event.type() == QEvent.Resize:
            if obj == getattr(self, "home_preview_card", None):
                self._sync_home_preview_table_height()
        return super().eventFilter(obj, event)

    def keyPressEvent(self, event):
        """按 ESC 返回上一层，或按 F5 刷新/重置。"""
        if event.key() == Qt.Key_Escape:
            # 如果在首页且当前选中了某个模块，先返回欢迎页
            if self.stacked_widget.currentWidget() == getattr(self, "p_home", None):
                if hasattr(self, "_active_module_nav_idx") and self._active_module_nav_idx >= 0:
                    self._active_module_nav_idx = -1
                    if hasattr(self, "module_content_stack"):
                        self.module_content_stack.setCurrentIndex(0)
                    # 返回欢迎页时显示顶部导航卡片
                    if hasattr(self, "module_nav_row"):
                        self.module_nav_row.setVisible(True)
                    self._update_module_nav_styles()
                    event.accept()
                    return
            # 否则使用导航历史返回
            self._nav_back()
            event.accept()
        elif event.key() == Qt.Key_F5:
            self.reset_and_show_home()
            event.accept()
        else:
            super().keyPressEvent(event)

    def _sync_home_preview_table_height(self):
        """根据卡片剩余高度拉伸数据预览表格。"""
        card = getattr(self, "home_preview_card", None)
        tv = getattr(self, "table_view", None)
        if not card or not tv:
            return
        lay = card.layout()
        if lay is None:
            return
        m = lay.contentsMargins()
        inner_h = card.height() - m.top() - m.bottom()
        if inner_h < 160:
            return
        gap = lay.spacing()
        head_it = lay.itemAt(0)
        head_h = 72
        if head_it is not None and head_it.layout() is not None:
            head_h = max(head_it.layout().sizeHint().height(), 48)
        want = int(round(inner_h * 0.80))
        max_table = max(120, inner_h - head_h - gap)
        tv.setFixedHeight(min(want, max_table))

    def _apply_card_shadow(self, widget, blur_radius=28, offset_y=10):
        """给卡片控件添加轻微投影。"""
        effect = QGraphicsDropShadowEffect(self)
        effect.setBlurRadius(22)
        effect.setOffset(0, 6)
        effect.setColor(QColor(0, 0, 0, 40))
        widget.setGraphicsEffect(effect)

    def _get_yield_category_product_map(self) -> dict[str, dict[str, list[str]]]:
        """基于 ORT 映射模板树构建良率页 大类-产品 导航（与左侧模板归属一致）。"""
        nav_map: dict[str, dict[str, list[str]]] = {}
        for module_name, category_name, category_bucket in self._iter_template_nodes():
            mod = self._normalize_module_name(module_name)
            if mod != self.DEFAULT_MODULE_NAME:
                continue
            nav_map.setdefault(mod, {})[category_name] = sorted(category_bucket.keys())
        if self.DEFAULT_MODULE_NAME not in nav_map:
            nav_map.setdefault(self.DEFAULT_MODULE_NAME, {})
        return nav_map

    def _init_ort_yield_scope(self, refresh_views: bool = True, refresh_view_key: str | None = None):
        """初始化 ORT 良率作用域（优先顶部全局类型，不受左侧当前选中模板影响）。"""
        category_map = self._get_yield_category_product_map()
        module_name = self.DEFAULT_MODULE_NAME
        global_cat = self._get_current_global_type() if hasattr(self, "ort_global_type_btn") else ""
        ort_cats = category_map.get(module_name, {})
        if global_cat and global_cat in ort_cats:
            category = global_cat
        else:
            category = next(iter(ort_cats.keys()), None) or ""
        products = list(ort_cats.get(category, []))
        product_name = products[0] if products else ""
        self._yield_scope_state = {
            "module_name": module_name,
            "category": category,
            "product_name": product_name,
        }
        self._ensure_yield_scope_state()
        if refresh_views:
            self._refresh_yield_dashboard(refresh_view_key)

    def _ensure_yield_scope_state(self) -> tuple[str, str, str]:
        """确保 ORT 良率监控作用域有效（大类/产品来自映射模板树）。"""
        category_map = self._get_yield_category_product_map()
        if not hasattr(self, "_yield_scope_state") or not isinstance(self._yield_scope_state, dict):
            self._yield_scope_state = {"module_name": "", "category": "", "product_name": ""}

        module_name = self._normalize_module_name(self._yield_scope_state.get("module_name"))
        if module_name != self.DEFAULT_MODULE_NAME or module_name not in category_map:
            module_name = self.DEFAULT_MODULE_NAME

        category = str(self._yield_scope_state.get("category") or "").strip()
        if not category or category not in category_map.get(module_name, {}):
            categories = list(category_map.get(module_name, {}).keys())
            category = categories[0] if categories else ""

        products = list(category_map.get(module_name, {}).get(category, []))
        product_name = str(self._yield_scope_state.get("product_name") or "").strip()
        if product_name not in products:
            product_name = products[0] if products else ""

        self._yield_scope_state["module_name"] = module_name
        self._yield_scope_state["category"] = category
        self._yield_scope_state["product_name"] = product_name
        return module_name, category, product_name

    def _set_yield_scope(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
        refresh_views: bool = True,
        refresh_view_key: str | None = None,
    ):
        """设置当前良率查看作用域，并同步所有良率页面。"""
        self._ensure_yield_scope_state()
        category_map = self._get_yield_category_product_map()
        prev_module = self._normalize_module_name(self._yield_scope_state.get("module_name"))
        prev_category = str(self._yield_scope_state.get("category") or "").strip()
        prev_product = str(self._yield_scope_state.get("product_name") or "").strip()

        module_val = self._normalize_module_name(
            module_name if module_name is not None else self._yield_scope_state.get("module_name")
        )
        if module_val != self.DEFAULT_MODULE_NAME or module_val not in category_map:
            module_val = self.DEFAULT_MODULE_NAME

        category_val = str(category if category is not None else self._yield_scope_state.get("category") or "").strip()
        if not category_val or category_val not in category_map.get(module_val, {}):
            category_val = self._ensure_yield_scope_state()[1]

        products = list(category_map.get(module_val, {}).get(category_val, []))
        product_val = str(product_name if product_name is not None else self._yield_scope_state.get("product_name") or "").strip()
        if product_val not in products:
            product_val = products[0] if products else ""

        if module_val == prev_module and category_val == prev_category and product_val == prev_product:
            return

        only_product_changed = (
            module_val == prev_module
            and category_val == prev_category
            and product_val != prev_product
        )

        self._yield_scope_state["module_name"] = module_val
        self._yield_scope_state["category"] = category_val
        self._yield_scope_state["product_name"] = product_val
        # 仅切换产品时保留用户已选日期；切换模块/大类时才重新同步日期控件
        if not only_product_changed:
            self._mark_yield_date_reset_pending()

        # 同步全局 ORT 时间选择器的批次日历
        if hasattr(self, "ort_global_type_btn"):
            if hasattr(self, "ort_global_product_list"):
                self._sync_ort_global_date_range_by_selection(clamp_dates=not only_product_changed)
            else:
                self._sync_ort_global_date_range_by_type(clamp_dates=not only_product_changed)
        else:
            self._sync_ort_global_date_range()

        if refresh_views:
            self._refresh_yield_dashboard(refresh_view_key)

    def _set_yield_stats_mode(self, mode: str):
        """切换良率统计数据源模式。"""
        mode_val = str(mode or "").strip().lower()
        if mode_val not in {"memory", "db_latest_day", "db_range"}:
            mode_val = "db_range"
        self._yield_stats_mode = mode_val
        self._yield_session_memory_active = (mode_val == "memory")

    def _is_yield_memory_mode(self) -> bool:
        """当前是否使用导入会话内存数据做良率统计。"""
        return (
            str(getattr(self, "_yield_stats_mode", "")).strip().lower() == "memory"
            and self.current_df is not None
            and not self.current_df.empty
        )

    def _get_cached_yield_memory_long_df(self) -> pd.DataFrame | None:
        """返回当前导入数据对应的长表缓存，避免重复转换。"""
        if self.current_df is None or self.current_df.empty:
            self._yield_memory_long_df_cache = None
            self._yield_memory_long_df_cache_version = -1
            return None

        cur_ver = int(getattr(self, "_data_version", 0))
        if (
            self._yield_memory_long_df_cache is not None
            and self._yield_memory_long_df_cache_version == cur_ver
        ):
            return self._yield_memory_long_df_cache

        long_df = self._convert_current_df_to_long_format()
        self._yield_memory_long_df_cache = long_df.copy() if isinstance(long_df, pd.DataFrame) else None
        self._yield_memory_long_df_cache_version = cur_ver
        return self._yield_memory_long_df_cache

    def _mark_yield_date_reset_pending(self):
        """标记良率页日期控件需要按当前数据范围重新同步。"""
        for refs in (getattr(self, "_yield_views", {}) or {}).values():
            refs["date_needs_reset"] = True

    def _resolve_yield_date_range(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ):
        """解析当前数据源下的最早/最迟检测日期。"""
        from PyQt5.QtCore import QDate

        category_val = str(category or "").strip()
        product_val = str(product_name or "").strip()
        min_date_str = ""
        max_date_str = ""

        mem_ok = self._is_yield_memory_mode()
        if mem_ok:
            memory_dates = self._get_memory_yield_date_strings(
                module_name=self._normalize_module_name(module_name),
                category=category_val,
                product_name=product_val,
            )
            if memory_dates:
                min_date_str = memory_dates[0]
                max_date_str = memory_dates[-1]

        if (not min_date_str or not max_date_str) and hasattr(self, "_ort_db") and self._ort_db is not None:
            min_date_str, max_date_str = self._ort_db.get_test_date_range(
                module_name=self._normalize_module_name(module_name) or None,
                category=category_val or None,
                product_name=product_val or None,
            )

        if not min_date_str and max_date_str:
            min_date_str = max_date_str
        if not max_date_str and min_date_str:
            max_date_str = min_date_str

        min_date = QDate.fromString(min_date_str, "yyyy-MM-dd") if min_date_str else QDate.currentDate()
        max_date = QDate.fromString(max_date_str, "yyyy-MM-dd") if max_date_str else QDate.currentDate()
        if not min_date.isValid():
            min_date = QDate.currentDate()
        if not max_date.isValid():
            max_date = min_date
        if min_date > max_date:
            min_date, max_date = max_date, min_date
        return min_date, max_date

    def _get_memory_yield_date_strings(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ) -> list[str]:
        """从当前导入数据中提取存在数据的检测日期集合。"""
        if self.current_df is None or self.current_df.empty:
            return []

        long_df = self._get_cached_yield_memory_long_df()
        if long_df is None or long_df.empty:
            return []

        df = long_df
        if module_name and "module_name" in df.columns:
            df = df[df["module_name"].astype(str).str.strip() == self._normalize_module_name(module_name)]
        if category and "category" in df.columns:
            df = df[df["category"].astype(str).str.strip() == str(category).strip()]
        if product_name and "product_name" in df.columns:
            df = df[df["product_name"].astype(str).str.strip() == str(product_name).strip()]
        if df.empty or "test_time" not in df.columns:
            return []

        try:
            dt_series = pd.to_datetime(df["test_time"], errors="coerce").dropna()
            if dt_series.empty:
                return []
            return sorted({dt.strftime("%Y-%m-%d") for dt in dt_series})
        except Exception:
            return []

    def _apply_yield_calendar_formats(self, view_key: str, min_date, max_date):
        """将日历切换为统一的范围选择视觉。"""
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return

        date_edits = [refs.get("date_start"), refs.get("date_end")]
        weekday_fmt = QTextCharFormat()
        weekday_fmt.setForeground(QColor("#2F2A24"))
        weekday_fmt.setFontWeight(QFont.Bold)

        for date_edit in date_edits:
            if date_edit is None:
                continue
            cal = date_edit.calendarWidget()
            if cal is None:
                continue

            cal.setStyleSheet("""
                QCalendarWidget QWidget {
                    background-color: #FFFFFF;
                    color: #2F2A24;
                }
                QCalendarWidget QWidget#qt_calendar_navigationbar {
                    background-color: #F6F1E8;
                    border-bottom: 1px solid #E2D8C8;
                    min-height: 32px;
                }
                QCalendarWidget QToolButton {
                    color: #2C3E50;
                    background: transparent;
                    border: none;
                    font-size: 18px;
                    font-weight: 700;
                    padding: 4px 8px;
                }
                QCalendarWidget QToolButton:hover {
                    background-color: #EFE5D7;
                    border-radius: 6px;
                }
                QCalendarWidget QMenu {
                    background-color: #FFFFFF;
                    color: #2F2A24;
                    border: 1px solid #D8CCBA;
                }
                QCalendarWidget QSpinBox {
                    background: #FFFFFF;
                    color: #2F2A24;
                    border: 1px solid #D8CCBA;
                    border-radius: 4px;
                    selection-background-color: #D9C3A4;
                    selection-color: #2F2A24;
                }
            """)
            for weekday in (Qt.Monday, Qt.Tuesday, Qt.Wednesday, Qt.Thursday, Qt.Friday, Qt.Saturday, Qt.Sunday):
                cal.setWeekdayTextFormat(weekday, weekday_fmt)
            if hasattr(cal, "setAllowedDateRange"):
                cal.setAllowedDateRange(min_date, max_date)
            cal.updateCells()

    def _on_yield_calendar_page_changed(self, view_key: str, *_):
        """日历翻页后刷新显示。"""
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return
        for date_edit_key in ("date_start", "date_end"):
            date_edit = refs.get(date_edit_key)
            if date_edit is None:
                continue
            cal = date_edit.calendarWidget()
            if cal is not None:
                cal.updateCells()

    def _sync_yield_date_controls(self, view_key: str, reset_selection: bool = False):
        """将良率页日期控件同步到当前数据源的可选范围。

        - 内存模式（双击导入）：日期控件显示导入数据的完整时间范围，仅作参考，不参与过滤。
        - 数据库模式：日期控件默认自动定到数据库中最新一天（而非今天实际日期）。
        """

        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return

        start_edit = refs.get("date_start")
        end_edit = refs.get("date_end")
        if start_edit is None or end_edit is None:
            return

        module_name, category, product_name = self._ensure_yield_scope_state()
        stats_mode = str(getattr(self, "_yield_stats_mode", "db_latest_day")).strip().lower()

        min_date, max_date = self._resolve_yield_date_range(module_name=module_name, category=category, product_name=None)

        start_edit.blockSignals(True)
        end_edit.blockSignals(True)
        try:
            start_edit.setMinimumDate(min_date)
            start_edit.setMaximumDate(max_date)
            end_edit.setMinimumDate(min_date)
            end_edit.setMaximumDate(max_date)

            def _clamp_dates_to_range(start_qd, end_qd):
                s, e = start_qd, end_qd
                if s < min_date:
                    s = min_date
                if e > max_date:
                    e = max_date
                if s > e:
                    s, e = min_date, max_date
                return s, e

            if reset_selection:
                if stats_mode == "memory":
                    # 内存模式：显示完整导入数据时间范围
                    start_edit.setDate(min_date)
                    end_edit.setDate(max_date)
                elif stats_mode == "db_latest_day":
                    # 数据库模式：默认定到数据库最新一天
                    start_edit.setDate(max_date)
                    end_edit.setDate(max_date)
                else:
                    # 自定义时间范围：保留用户已选区间，仅在越界时收敛
                    s, e = _clamp_dates_to_range(start_edit.date(), end_edit.date())
                    start_edit.setDate(s)
                    end_edit.setDate(e)
            else:
                current_start = start_edit.date()
                current_end = end_edit.date()
                out_of_range = (
                    current_start < min_date
                    or current_start > max_date
                    or current_end < min_date
                    or current_end > max_date
                    or current_start > current_end
                )
                if out_of_range:
                    if stats_mode == "memory":
                        start_edit.setDate(min_date)
                        end_edit.setDate(max_date)
                    elif stats_mode == "db_latest_day":
                        start_edit.setDate(max_date)
                        end_edit.setDate(max_date)
                    else:
                        s, e = _clamp_dates_to_range(current_start, current_end)
                        start_edit.setDate(s)
                        end_edit.setDate(e)
        finally:
            start_edit.blockSignals(False)
            end_edit.blockSignals(False)

        self._apply_yield_calendar_formats(view_key, min_date, max_date)
        refs["date_needs_reset"] = False

    def _resolve_latest_yield_date(
        self,
        module_name: str | None = None,
        category: str | None = None,
        product_name: str | None = None,
    ):
        """获取当前作用域下最新一笔检测数据对应的日期。"""
        from PyQt5.QtCore import QDate

        latest_date_str = ""
        if hasattr(self, "_ort_db") and self._ort_db is not None:
            latest_date_str = self._ort_db.get_latest_test_date(
                module_name=self._normalize_module_name(module_name) or None,
                category=str(category or "").strip() or None,
                product_name=str(product_name or "").strip() or None,
            )
        if latest_date_str:
            qd = QDate.fromString(latest_date_str, "yyyy-MM-dd")
            if qd.isValid():
                return qd
        _min_date, max_date = self._resolve_yield_date_range(module_name=module_name, category=category, product_name=product_name)
        return max_date

    def _on_yield_category_clicked(self, view_key: str, category: str):
        """切换良率页当前大类（产品列表随映射模板树刷新）。"""
        if view_key == "yield_menu" and hasattr(self, "ort_global_type_btn"):
            self.ort_global_type_btn.setText(str(category or "").strip())
            self._sync_ort_global_date_range_by_type(clamp_dates=True)
        self._set_yield_scope(category=category, product_name=None, refresh_views=True, refresh_view_key=view_key)

    def _on_yield_product_clicked(self, view_key: str, product_name: str | None = None, *_):
        """切换良率页当前产品（同一大类下可切换 X2689 / X3476 等）。"""
        product_val = str(product_name or "").strip()
        if not product_val:
            return
        self._set_yield_scope(product_name=product_val, refresh_views=True, refresh_view_key=view_key)
        self._sync_global_product_selector_to_scope(product_val)

    def _yield_category_button_stylesheet(self) -> str:
        return f"""
            QPushButton {{
                background-color: #FFFFFF;
                color: #3A5A7A;
                border: 1px solid #B8D4E8;
                border-radius: 8px;
                padding: 2px 10px;
                font-size: {int(11*self._s)}px;
                font-weight: 700;
            }}
            QPushButton:hover {{
                background-color: #F5F9FF;
                border-color: #A8C8E0;
            }}
            QPushButton:checked {{
                background-color: #5B9BD5;
                color: #FFFFFF;
                border-color: #5B9BD5;
            }}
        """

    def _rebuild_yield_category_buttons(self, view_key: str, category: str):
        """按模板树重建大类按钮（页面创建时模板可能尚未加载）。"""
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return
        scope_top_row = refs.get("scope_top_row")
        scope_wrap = refs.get("scope_wrap")
        if scope_top_row is None or scope_wrap is None:
            return

        module_name = self.DEFAULT_MODULE_NAME
        compact = bool(refs.get("compact"))
        groups = self._category_names_for_module(module_name)

        while scope_top_row.count():
            item = scope_top_row.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()

        category_btn_group = QButtonGroup(scope_wrap)
        category_btn_group.setExclusive(True)
        category_buttons: dict[str, QPushButton] = {}
        btn_ss = self._yield_category_button_stylesheet()
        for group in groups:
            btn = QPushButton(group)
            btn.setCheckable(True)
            btn.setCursor(QCursor(Qt.PointingHandCursor))
            btn.setMinimumHeight(int(24 * self._s))
            btn.setMinimumWidth(int((72 if compact else 88) * self._s))
            btn.setMaximumWidth(int(200 * self._s))
            btn.setStyleSheet(btn_ss)
            category_btn_group.addButton(btn)
            category_buttons[group] = btn
            scope_top_row.addWidget(btn, 0, Qt.AlignLeft | Qt.AlignVCenter)
        if category in category_buttons:
            category_buttons[category].setChecked(True)
        category_btn_group.buttonClicked.connect(
            lambda btn, key=view_key: self._on_yield_category_clicked(key, btn.text())
        )
        scope_top_row.addStretch(1)
        refs["category_buttons"] = category_buttons
        refs["category_btn_group"] = category_btn_group

    def _sync_yield_scope_widgets(self, view_key: str):
        """同步单个良率页面的导航控件到当前作用域。"""
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return

        scope_wrap = refs.get("scope_wrap")
        category_row_host = refs.get("category_row_host")
        if scope_wrap is not None:
            scope_wrap.setVisible(True)
        if category_row_host is not None:
            category_row_host.setVisible(True)

        if view_key == "yield_menu" and hasattr(self, "ort_global_type_btn"):
            global_cat = self._get_current_global_type()
            if global_cat:
                self._yield_scope_state["category"] = global_cat

        module_name, category, product_name = self._ensure_yield_scope_state()
        category_map = self._get_yield_category_product_map()

        self._rebuild_yield_category_buttons(view_key, category)

        product_buttons_layout = refs.get("product_buttons_layout")
        if product_buttons_layout is not None:
            self._clear_layout_widgets(product_buttons_layout)
            products = category_map.get(module_name, {}).get(category, [])
            product_panel = product_buttons_layout.parentWidget()
            product_btn_group = QButtonGroup(product_panel) if product_panel is not None else QButtonGroup()
            product_btn_group.setExclusive(True)
            refs["product_btn_group"] = product_btn_group
            if products:
                for name in products:
                    btn = QPushButton(str(name))
                    btn.setObjectName("yield_product_chip")
                    btn.setCheckable(True)
                    btn.setCursor(QCursor(Qt.PointingHandCursor))
                    btn.setMinimumHeight(int(30 * self._s))
                    btn.setMaximumHeight(int(30 * self._s))
                    btn.setMinimumWidth(int(88 * self._s))
                    is_sel = str(name) == product_name
                    btn.setChecked(is_sel)
                    # 优化产品按钮样式
                    btn.setStyleSheet(f"""
                        QPushButton {{
                            background-color: {'#5B9BD5' if is_sel else '#FFFFFF'};
                            color: {'#FFFFFF' if is_sel else '#3A5A7A'};
                            border: 2px solid {'#5B9BD5' if is_sel else '#B8D4E8'};
                            border-radius: 8px;
                            padding: 4px 12px;
                            font-size: {int(11*self._s)}px;
                            font-weight: {'700' if is_sel else '600'};
                        }}
                        QPushButton:hover {{
                            background-color: #F5F9FF;
                            border-color: #A8C8E0;
                        }}
                    """)
                    product_btn_group.addButton(btn)
                    product_buttons_layout.addWidget(btn, 0)
                product_btn_group.buttonClicked.connect(
                    lambda btn, key=view_key: self._on_yield_product_clicked(key, btn.text())
                )
                product_buttons_layout.addStretch(1)
            else:
                empty_lbl = QLabel("当前大类下暂无产品")
                empty_lbl.setObjectName("yield_product_empty")
                empty_lbl.setStyleSheet(f"color: #5A7A99; font-size: {int(11*self._s)}px; padding: 6px 0;")
                product_buttons_layout.addWidget(empty_lbl, 0, Qt.AlignLeft | Qt.AlignVCenter)
                product_buttons_layout.addStretch(1)

        scope_label = refs.get("scope_summary")
        if scope_label is not None:
            if product_name:
                scope_label.setText(f"📍 {module_name} · {category} · {product_name}")
                scope_label.setStyleSheet(f"""
                    QLabel {{
                        color: #3A5A7A;
                        font-size: {int(12*self._s)}px;
                        font-weight: 600;
                        padding: 6px 14px;
                        background-color: #F5F9FF;
                        border: 1px solid #C5D9E8;
                        border-radius: 8px;
                    }}
                """)
            else:
                scope_label.setText(f"📍 {module_name} · {category}")
                scope_label.setStyleSheet(f"""
                    QLabel {{
                        color: #8E7F6E;
                        font-size: {int(12*self._s)}px;
                        font-weight: 600;
                        padding: 6px 14px;
                        background-color: #FAF8F4;
                        border: 1px solid #E8E0D4;
                        border-radius: 8px;
                    }}
                """)

        self._apply_yield_stand_layout_mode(view_key)

    @staticmethod
    def _yield_splitter_fill(splitter, widgets: list):
        """清空 splitter 后按顺序放入子控件（用于 Stand/DH 布局切换）。"""
        if splitter is None:
            return
        while splitter.count() > 0:
            splitter.widget(0).setParent(None)
        for widget in widgets:
            if widget is not None:
                splitter.addWidget(widget)

    def _ensure_yield_right_panel_visible(self, view_key: str):
        """Stand 四宫格不使用 right_panel；DH/FATP 保持右侧 NG+趋势面板可见。"""
        _, category, _ = self._ensure_yield_scope_state()
        if self._is_stand_yield_category(category):
            return
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key) or {}
        right_panel = refs.get("right_panel")
        if right_panel is not None and not right_panel.isVisible():
            right_panel.setVisible(True)

    def _apply_yield_stand_layout_mode(self, view_key: str):
        """Stand：红线下四宫格（上 1/3 下 2/3，左右各半）；DH/FATP：左良率 + 右 NG/趋势。"""
        refs = (getattr(self, "_yield_views", {}) or {}).get(view_key)
        if not refs:
            return
        _, category, _ = self._ensure_yield_scope_state()
        is_stand = self._is_stand_yield_category(category)

        grid = refs.get("yield_content_grid")
        bars = refs.get("yield_bars_scroll")
        ng_wrap = refs.get("top_ng_wrap")
        ng_trend = refs.get("ng_trend_splitter")
        right_panel = refs.get("right_panel")
        box_wrap = refs.get("stand_boxplot_wrap")
        serial_wrap = refs.get("stand_serial_wrap")
        bottom_stack = refs.get("right_bottom_stack")
        if grid is None:
            return

        while grid.count():
            grid.takeAt(0)

        if is_stand:
            if box_wrap is not None:
                box_wrap.setVisible(True)
            if serial_wrap is not None:
                serial_wrap.setVisible(True)
            if right_panel is not None:
                right_panel.setVisible(False)
            bottom_trend = refs.get("bottom_trend_wrap")
            if bottom_trend is not None:
                bottom_trend.setVisible(False)
            if bars is not None:
                grid.addWidget(bars, 0, 0)
            if ng_wrap is not None:
                grid.addWidget(ng_wrap, 0, 1)
            if box_wrap is not None:
                grid.addWidget(box_wrap, 1, 0)
            if serial_wrap is not None:
                grid.addWidget(serial_wrap, 1, 1)
            grid.setRowStretch(0, 1)
            grid.setRowStretch(1, 2)
            grid.setColumnStretch(0, 1)
            grid.setColumnStretch(1, 1)
            grid.setColumnMinimumWidth(0, int(200 * self._s))
            grid.setColumnMinimumWidth(1, int(220 * self._s))
            if refs.get("stand_uploaded_serials"):
                self._refresh_stand_serial_history_panel(view_key)
            return

        refs["stand_uploaded_serials"] = []
        self._display_stand_serial_history_table(view_key, pd.DataFrame())
        if box_wrap is not None:
            box_wrap.setVisible(False)
        if serial_wrap is not None:
            serial_wrap.setVisible(False)
        if bottom_stack is not None:
            bottom_stack.setCurrentIndex(0)
            if serial_wrap is not None and bottom_stack.indexOf(serial_wrap) < 0:
                bottom_stack.insertWidget(1, serial_wrap)
        bottom_trend = refs.get("bottom_trend_wrap")
        if bottom_trend is not None:
            bottom_trend.setVisible(True)
        if ng_trend is not None:
            self._yield_splitter_fill(ng_trend, [ng_wrap, bottom_stack])
        if right_panel is not None:
            right_panel.setVisible(True)
            rdet_lay = right_panel.layout()
            if rdet_lay is not None and ng_trend is not None:
                ng_in_panel = False
                for idx in range(rdet_lay.count()):
                    item = rdet_lay.itemAt(idx)
                    if item is not None and item.widget() is ng_trend:
                        ng_in_panel = True
                        break
                if not ng_in_panel:
                    rdet_lay.addWidget(ng_trend, 1)
        if bars is not None:
            grid.addWidget(bars, 0, 0, 2, 1)
        if right_panel is not None:
            grid.addWidget(right_panel, 0, 1, 2, 1)
        grid.setRowStretch(0, 1)
        grid.setRowStretch(1, 0)
        grid.setColumnStretch(0, 1)
        grid.setColumnStretch(1, 1)
        if ng_trend is not None and ng_trend.height() > 80:
            h = ng_trend.height()
            ng_trend.setSizes([
                max(int(h * 0.38), int(120 * self._s)),
                max(int(h * 0.62), int(180 * self._s)),
            ])

    def _create_yield_dashboard_page(
        self,
        view_key: str = "yield_main",
        compact: bool = False,
        header_layout: QHBoxLayout | None = None,
        page_title: str | None = None,
        toolbar_footer_left: bool = False,
    ):
        """创建 ORT 良率监控页面（支持首页嵌入与独立页面复用）"""
        from PyQt5.QtCore import QDate

        page = QWidget()
        page.setObjectName("content_page")
        if not compact:
            page.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        page_lay = QVBoxLayout(page)
        if compact:
            page_lay.setContentsMargins(0, 0, 0, 0)
            page_lay.setSpacing(12)
        else:
            # 适配外层白色大卡片
            # 压缩内页边距
            page_lay.setContentsMargins(int(10 * self._s), int(6 * self._s), int(10 * self._s), int(10 * self._s))
            page_lay.setSpacing(int(10 * self._s))

        # 日期控件仅作内部状态（与 ORT 顶部全局「开始/结束」同步），不单独展示第二行工具栏
        date_start = QDateEdit(page)
        date_start.setCalendarPopup(True)
        date_start.setCalendarWidget(YieldRangeCalendar(date_start))
        date_start.setDate(QDate.currentDate())
        date_start.hide()
        date_end = QDateEdit(page)
        date_end.setCalendarPopup(True)
        date_end.setCalendarWidget(YieldRangeCalendar(date_end))
        date_end.setDate(QDate.currentDate())
        date_end.hide()
        date_start.calendarWidget().currentPageChanged.connect(
            lambda *_args, key=view_key: self._on_yield_calendar_page_changed(key)
        )
        date_end.calendarWidget().currentPageChanged.connect(
            lambda *_args, key=view_key: self._on_yield_calendar_page_changed(key)
        )

        scope_wrap = QFrame()
        scope_wrap.setObjectName("yield_scope_wrap")
        scope_wrap.setStyleSheet(f"""
            QFrame#yield_scope_wrap {{
                background-color: transparent;
                border: none;
            }}
            QLabel#yield_scope_summary {{
                color: #5A7A99;
                font-size: {int(11*self._s)}px;
                font-weight: 600;
            }}
            QScrollArea#yield_product_scroll {{
                background: transparent;
                border: none;
            }}
            QWidget#yield_product_panel {{
                background: transparent;
            }}
            QPushButton#yield_product_chip {{
                background-color: #FFFFFF;
                color: #3A5A7A;
                border: 1px solid #B8D4E8;
                border-radius: 8px;
                padding: 3px 10px;
                font-size: {int(11*self._s)}px;
                font-weight: 600;
            }}
            QPushButton#yield_product_chip:hover {{
                background-color: #F5F9FF;
                border-color: #A8C8E0;
            }}
            QPushButton#yield_product_chip:checked {{
                background-color: #5B9BD5;
                color: #FFFFFF;
                border: 1px solid #5B9BD5;
                font-weight: 700;
            }}
            QLabel#yield_product_empty {{
                color: #6B8299;
                font-size: {int(11*self._s)}px;
                padding: 2px 0;
            }}
        """)
        scope_wrap_lay = QVBoxLayout(scope_wrap)
        scope_wrap_lay.setContentsMargins(0, 0, 0, 0)
        scope_wrap_lay.setSpacing(int(6 * self._s))

        _scope_cat_h = int(32 * self._s)
        _product_row_h = int(36 * self._s)
        _product_btn_h = int(30 * self._s)
        category_row_host = QWidget()
        category_row_host.setObjectName("yield_category_row")
        category_row_host.setFixedHeight(_scope_cat_h)
        category_row_host.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        scope_top_row = QHBoxLayout(category_row_host)
        scope_top_row.setContentsMargins(0, 0, 0, 0)
        scope_top_row.setSpacing(int(8 * self._s))

        _module_name, category_name, _product_name = self._ensure_yield_scope_state()
        category_buttons = {}
        category_btn_group = QButtonGroup(scope_wrap)
        category_btn_group.setExclusive(True)
        for group in self._category_names_for_module(_module_name):
            btn = QPushButton(group)
            btn.setCheckable(True)
            btn.setCursor(QCursor(Qt.PointingHandCursor))
            btn.setMinimumHeight(int(24 * self._s))
            btn.setMinimumWidth(int((72 if compact else 88) * self._s))
            btn.setMaximumWidth(int(200 * self._s))
            btn.setStyleSheet(f"""
                QPushButton {{
                    background-color: #FFFFFF;
                    color: #3A5A7A;
                    border: 1px solid #B8D4E8;
                    border-radius: 8px;
                    padding: 2px 10px;
                    font-size: {int(11*self._s)}px;
                    font-weight: 700;
                }}
                QPushButton:hover {{
                    background-color: #F5F9FF;
                    border-color: #A8C8E0;
                }}
                QPushButton:checked {{
                    background-color: #5B9BD5;
                    color: #FFFFFF;
                    border-color: #5B9BD5;
                }}
            """)
            category_btn_group.addButton(btn)
            category_buttons[group] = btn
            scope_top_row.addWidget(btn, 0, Qt.AlignLeft | Qt.AlignVCenter)
        if category_name in category_buttons:
            category_buttons[category_name].setChecked(True)
        category_btn_group.buttonClicked.connect(
            lambda btn, key=view_key: self._on_yield_category_clicked(key, btn.text())
        )
        scope_top_row.addStretch(1)

        product_row_host = QWidget()
        product_row_host.setObjectName("yield_product_row")
        product_row_host.setFixedHeight(_product_row_h)
        product_row_host.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        product_buttons_layout = QHBoxLayout(product_row_host)
        product_buttons_layout.setContentsMargins(0, 0, 0, 0)
        product_buttons_layout.setSpacing(int(8 * self._s))
        scope_wrap.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        scope_wrap.setMinimumWidth(0)
        scope_wrap.setFixedHeight(_product_row_h)
        scope_wrap_lay.addWidget(product_row_host)

        # 当前版本不显示第三排“当前选择”标签，但保留占位供同步逻辑兼容。
        scope_summary = None

        if header_layout is not None:
            scope_stack = QWidget()
            scope_stack.setObjectName("yield_scope_stack")
            scope_stack_lay = QVBoxLayout(scope_stack)
            scope_stack_lay.setContentsMargins(0, 0, 0, 0)
            scope_stack_lay.setSpacing(int(6 * self._s))
            scope_stack_lay.addWidget(category_row_host)
            scope_stack_lay.addWidget(scope_wrap)
            insert_idx = max(0, header_layout.count() - 1)
            header_layout.insertWidget(insert_idx, scope_stack, 0, Qt.AlignLeft | Qt.AlignTop)
