    def _open_path_config_sub_hub(self, parent_dlg: QDialog | None = None):
        """路径配置：PowerPoint / JMP 程序路径（全局共用）。"""
        if parent_dlg is not None:
            parent_dlg.accept()

        cfg_dlg = PptJmpPathDialog(self)
        if cfg_dlg.exec_() == QDialog.Accepted:
            QMessageBox.information(self, "提示", "路径已保存，导出 PPT / 使用 JMP 时将自动调用。")
        self._open_database_management_hub()

    def _open_stand_yield_spec_dialog(self, parent_dlg: QDialog | None = None):
        """Stand 良率核心参数规格设置。"""
        if parent_dlg is not None:
            parent_dlg.accept()
        dlg = StandYieldSpecDialog(self)
        if dlg.exec_() == QDialog.Accepted:
            try:
                self._refresh_yield_dashboard("yield_home")
                self._refresh_yield_dashboard("yield_menu")
            except Exception:
                pass
            QMessageBox.information(self, "提示", "Stand 核心参数规格已保存。")
        self._open_database_management_hub()

