    def _open_ort_db_table_info_dialog(self, on_back=None):
        """ORT 数据库数据表列名信息。"""
        dlg = QDialog(self)
        dlg.setWindowTitle("ORT 数据库数据表信息")
        dlg.resize(int(780 * self._s), int(520 * self._s))
        self._apply_standalone_dialog_theme(dlg)
        lay = QVBoxLayout(dlg)
        lay.setContentsMargins(int(20 * self._s), int(18 * self._s), int(20 * self._s), int(18 * self._s))
        lay.setSpacing(int(12 * self._s))

        title = QLabel("📊 ORT 映射模板 — 数据库列名对照表")
        title.setStyleSheet(
            f"font-size: {int(15 * self._s)}px; font-weight: 800; color: #2C3E50; "
            "background: transparent;"
        )
        lay.addWidget(title)

        desc = QLabel("ORT 数据入库后，数据库表采用固定 19 个标准字段。")
        desc.setStyleSheet(f"font-size: {int(12 * self._s)}px; color: #6B8299; background: transparent;")
        desc.setWordWrap(True)
        lay.addWidget(desc)

        table = QTableWidget()
        table.setColumnCount(3)
        table.setHorizontalHeaderLabels(["列名", "类型", "说明"])
        ort_data = [
            ("module_name", "TEXT", "模块名（固定为 ORT）"),
            ("category", "TEXT", "大类（如 DH / Stand / FATP）"),
            ("product_name", "TEXT", "产品名称（如 X2689 DH）"),
            ("project", "TEXT", "项目"),
            ("model", "TEXT", "机种"),
            ("component", "TEXT", "组件"),
            ("subpart", "TEXT", "小件"),
            ("recipe", "TEXT", "配方"),
            ("barcode", "TEXT", "二维码 / SN"),
            ("test_time", "TEXT", "检测时间"),
            ("point_name", "TEXT", "测点名称（如 B1, SPK1）"),
            ("value", "REAL", "测量值"),
            ("usl", "REAL", "上规格限"),
            ("lsl", "REAL", "下规格限"),
            ("line", "TEXT", "线别"),
            ("result", "TEXT", "检测结果"),
            ("shift", "TEXT", "班别"),
            ("test_position", "TEXT", "检测位次 / 工位"),
            ("material_category", "TEXT", "物料类别"),
        ]
        table.setRowCount(len(ort_data))
        for i, (col, typ, desc) in enumerate(ort_data):
            table.setItem(i, 0, QTableWidgetItem(col))
            table.setItem(i, 1, QTableWidgetItem(typ))
            table.setItem(i, 2, QTableWidgetItem(desc))
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        table.verticalHeader().setVisible(False)
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setStyleSheet(f"""
            QTableWidget {{
                border: 1px solid #C5D9E8;
                background: #FFFFFF;
                font-size: {int(12 * self._s)}px;
            }}
            QHeaderView::section {{
                background: #D5E3F0;
                color: #2C3E50;
                font-weight: 700;
                padding: {int(6 * self._s)}px;
                border: 1px solid #B8D4E8;
            }}
            QTableWidget::item {{
                padding: {int(4 * self._s)}px {int(8 * self._s)}px;
            }}
        """)
        lay.addWidget(table)

        back_fn = on_back if on_back is not None else (lambda: self._open_template_sub_hub())
        lay.addLayout(self._db_mgmt_footer_buttons(dlg, back_callback=back_fn, object_name_prefix="btn_ort_tbl"))

        dlg.exec_()

    def _open_db_violation_dashboard(self, on_back=None):
        df = self._ort_db.query_violations_under_lsl()
        if df.empty:
            QMessageBox.information(
                self,
                "历史超规",
                "数据库中暂无「测量值低于 LSL」的记录。\n请先完成映射与「一键作图」以写入长表，或确认确实存在超规样本。",
            )
            return
        dlg = QDialog(self)
        dlg.setWindowTitle("数据库 · 历史超规记录（无需导入 Excel）")
        dlg.resize(int(980 * self._s), int(620 * self._s))
        self._apply_standalone_dialog_theme(dlg)
        lay = QVBoxLayout(dlg)

        lbl = QLabel(f"数据源：{getattr(self._ort_db, 'db_path', os.path.join(_app_config_dir(), 'QualityAnalyseSystem_Storage.db'))}  ·  共 {len(df)} 行")
        lbl.setStyleSheet(f"font-size: {int(12*self._s)}px; color:#2C3E50; font-weight:700;")
        lbl.setWordWrap(True)
        lay.addWidget(lbl)

        view = QTableView()
        view.setModel(PandasModel(df))
        view.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeToContents)
        lay.addWidget(view)

        def _export_violations_excel():
            default_name = f"ORT_历史超规_{datetime.now().strftime('%Y%m%d_%H%M')}.xlsx"
            start_dir = self._get_desktop_dir()
            default_path = os.path.join(start_dir, default_name)
            path, _ = QFileDialog.getSaveFileName(
                dlg,
                "导出历史超规记录",
                default_path,
                "Excel 工作簿 (*.xlsx);;所有文件 (*.*)",
            )
            if not path:
                return
            if not str(path).lower().endswith(".xlsx"):
                path = str(path) + ".xlsx"
            try:
                df.to_excel(path, index=False, engine="openpyxl")
                QMessageBox.information(dlg, "导出完成", f"已保存：\n{path}")
            except Exception as ex:
                QMessageBox.critical(dlg, "导出失败", str(ex))

        hb = QHBoxLayout()
        btn_export = QPushButton("导出 Excel…")
        btn_export.setMinimumWidth(int(128 * self._s))
        btn_export.setCursor(QCursor(Qt.PointingHandCursor))
        btn_export.clicked.connect(_export_violations_excel)
        hb.addWidget(btn_export)
        lay.addLayout(hb)

        back_fn = on_back if on_back is not None else (lambda: self._open_database_sub_hub())
        lay.addLayout(self._db_mgmt_footer_buttons(dlg, back_callback=back_fn, object_name_prefix="btn_violation"))

        dlg.exec_()

