    def _open_db_recipe_trend_dialog(self):
        cur_module, cur_category, cur_product = self._current_data_scope()
        recipes = self._ort_db.list_distinct_recipes(
            module_name=cur_module or None,
            category=cur_category or None,
            product_name=cur_product or None,
        )
        if not recipes:
            QMessageBox.information(
                self,
                "配方趋势",
                "数据库中暂无配方维度数据。\n请先完成数据分析并「一键作图」，将当前筛选后的报表沉淀到本地数据库。",
            )
            return

        dlg = QDialog(self)
        dlg.setWindowTitle("数据库 · 配方长期趋势（单值序）")
        dlg.resize(int(920 * self._s), int(620 * self._s))
        self._apply_standalone_dialog_theme(dlg)
        lay = QVBoxLayout(dlg)

        ctl = QHBoxLayout()
        ctl.addWidget(QLabel("配方 Recipe:"))

        combo_r = QComboBox()
        combo_r.addItems(recipes)

        ctl.addWidget(combo_r, 2)
        ctl.addWidget(QLabel("点位:"))

        combo_p = QComboBox()
        ctl.addWidget(combo_p, 2)

        btn_go = QPushButton("绘图")
        btn_go.setMinimumWidth(int(100 * self._s))
        ctl.addWidget(btn_go)
        ctl.addStretch(1)

        lay.addLayout(ctl)

        fig_holder = Figure(figsize=(7.8, 3.9), dpi=100)
        canvas = FigureCanvas(fig_holder)
        lay.addWidget(canvas, 1)

        def refill_points():
            combo_p.blockSignals(True)
            combo_p.clear()
            pts = self._ort_db.list_distinct_points(
                combo_r.currentText(),
                module_name=cur_module or None,
                category=cur_category or None,
                product_name=cur_product or None,
            )
            if pts:
                combo_p.addItems(pts)
            combo_p.blockSignals(False)

        def redraw():
            ax = fig_holder.gca()
            ax.clear()
            if combo_p.count() <= 0:
                refill_points()
            rcp = combo_r.currentText()
            pt = combo_p.currentText()
            if not pt:
                ax.text(
                    0.5,
                    0.5,
                    "该配方暂无点位",
                    ha="center",
                    va="center",
                    transform=ax.transAxes,
                )
                canvas.draw()
                return

            ser = self._ort_db.fetch_recipe_point_series(
                rcp,
                pt,
                module_name=cur_module or None,
                category=cur_category or None,
                product_name=cur_product or None,
            )
            if ser.empty:
                ax.text(
                    0.5,
                    0.5,
                    "暂无数据",
                    ha="center",
                    va="center",
                    transform=ax.transAxes,
                )
                canvas.draw()
                return

            y_raw = pd.to_numeric(ser["value"], errors="coerce")
            m_ok = y_raw.notna()
            ys = y_raw.loc[m_ok]
            xv = np.arange(len(ys))
            ax.plot(xv, ys.values, color="#2F80ED", marker="o", linewidth=1.0, markersize=3.2)

            if "lsl" in ser.columns:
                lf = pd.to_numeric(ser.loc[m_ok, "lsl"], errors="coerce")
                ulf = lf.dropna()
                if len(ulf) > 0:
                    uniq = ulf.unique()
                    lh = float(uniq[0]) if len(uniq) == 1 and np.isfinite(uniq[0]) else float(ulf.iloc[-1])
                    if np.isfinite(lh):
                        ax.axhline(lh, color="#B42318", linestyle="--", linewidth=1.0, alpha=0.82)

            ax.set_xlabel("按时间顺序编号（跨批次序号）")
            ax.set_ylabel("测量值")
            ax.grid(True, linestyle="--", linewidth=0.45, alpha=0.35)
            ax.set_title(f"{rcp} · {pt}", fontsize=11, color="#2C3E50")
            fig_holder.tight_layout()
            canvas.draw()

        def on_recipe_changed(*_):
            refill_points()
            redraw()

        combo_r.currentIndexChanged.connect(on_recipe_changed)
        combo_p.currentIndexChanged.connect(redraw)
        btn_go.clicked.connect(redraw)

        refill_points()
        redraw()

        row = QHBoxLayout()

        row.addStretch(1)

        btn_x = QPushButton("关闭")

        btn_x.clicked.connect(dlg.accept)

        row.addWidget(btn_x)

        lay.addLayout(row)

        dlg.exec_()

    def _open_db_maintenance_dialog(self, on_back=None):
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            QMessageBox.warning(self, "错误", "数据库管理器未初始化。")
            return

        tables_meta = mgr._get_all_tables()
        if not tables_meta:
            QMessageBox.information(
                self,
                "数据库维护",
                f"当前库中暂无 ORT 数据表。\n\n数据库路径：\n{mgr.db_path}",
            )
            return

        dlg = QDialog(self)
        dlg.setObjectName("db_maint_dialog")
        dlg.setWindowTitle("数据库 · 数据维护（删除不可恢复）")
        dlg.resize(int(560 * self._s), int(480 * self._s))
        self._apply_standalone_dialog_theme(dlg)
        root = QVBoxLayout(dlg)

        warn = QLabel(
            "以下操作直接从本地 SQLite 删除数据，请谨慎操作；建议重要数据事先自行备份 QualityAnalyseSystem_Storage.db。"
        )
        warn.setWordWrap(True)
        warn.setStyleSheet(f"font-size: {int(12 * self._s)}px; color: #8B2C2C; font-weight: 700;")
        root.addWidget(warn)

        path_lbl = QLabel(f"库文件：{mgr.db_path}")
        path_lbl.setWordWrap(True)
        path_lbl.setStyleSheet(f"font-size: {int(11 * self._s)}px; color: #2C3E50;")
        root.addWidget(path_lbl)

        _sm = max(9, int(10 * self._s))
        _lbl_sm = f"font-size: {_sm}px; color: #4A423A; font-weight: 600; background: transparent;"

        form = QVBoxLayout()
        lbl_tbl = QLabel("选择数据表（按大类/产品）:")
        lbl_tbl.setStyleSheet(_lbl_sm)
        form.addWidget(lbl_tbl)

        combo_tbl = QComboBox()
        combo_tbl.setStyleSheet(
            f"font-size: {_sm}px; min-height: {int(28 * self._s)}px; padding: 2px 8px;"
        )
        for meta in tables_meta:
            cat = str(meta.get("category") or "").strip() or "—"
            prod = str(meta.get("product_name") or "").strip() or "—"
            tn = str(meta.get("table_name") or "").strip()
            mod = str(meta.get("module_name") or "").strip()
            mod_prefix = f"{mod}-" if mod else ""
            leg = " [旧表]" if meta.get("legacy") else ""
            combo_tbl.addItem(f"{mod_prefix}{cat} / {prod}{leg}", tn)
        form.addWidget(combo_tbl)

        count_lbl = QLabel("")
        count_lbl.setStyleSheet(f"font-size: {_sm}px; color: #4A423A;")
        form.addWidget(count_lbl)

        grp_mode = QGroupBox("删除方式")
        grp_mode.setObjectName("db_maint_mode_grp")
        grp_mode.setStyleSheet(
            f"""
            QGroupBox#db_maint_mode_grp {{
                font-size: {_sm}px;
                font-weight: 700;
                color: #2C3E50;
            }}
            QGroupBox#db_maint_mode_grp::title {{
                subcontrol-origin: margin;
                left: 10px;
                padding: 0 4px;
            }}
            QGroupBox#db_maint_mode_grp QRadioButton {{
                font-size: {_sm}px;
                color: #3A5A7A;
                spacing: 6px;
            }}
            """
        )
        mode_lay = QVBoxLayout(grp_mode)
        rb_date = QRadioButton("按检测日期范围删除（date(test_time)，含起止日）")
        rb_clear = QRadioButton("清空该表全部行（保留空表结构）")
        rb_drop = QRadioButton("删除整张数据表（DROP TABLE，表结构一并移除）")
        rb_date.setChecked(True)
        mode_lay.addWidget(rb_date)
        mode_lay.addWidget(rb_clear)
        mode_lay.addWidget(rb_drop)
        form.addWidget(grp_mode)

        date_row = QHBoxLayout()
        lbl_ds = QLabel("开始日期:")
        lbl_ds.setStyleSheet(_lbl_sm)
        date_row.addWidget(lbl_ds)
        de_start = QDateEdit()
        de_start.setCalendarPopup(True)
        de_start.setDisplayFormat("yyyy-MM-dd")
        de_start.setStyleSheet(f"font-size: {_sm}px; padding: 2px 6px; min-height: {int(28 * self._s)}px;")
        date_row.addWidget(de_start)
        lbl_de = QLabel("结束日期:")
        lbl_de.setStyleSheet(_lbl_sm)
        date_row.addWidget(lbl_de)
        de_end = QDateEdit()
        de_end.setCalendarPopup(True)
        de_end.setDisplayFormat("yyyy-MM-dd")
        de_end.setStyleSheet(f"font-size: {_sm}px; padding: 2px 6px; min-height: {int(28 * self._s)}px;")
        date_row.addWidget(de_end)
        date_row.addStretch(1)
        form.addLayout(date_row)

        root.addLayout(form)

        def current_table_name() -> str:
            return str(combo_tbl.currentData() or "").strip()

        def refresh_count():
            tn = current_table_name()
            n = mgr.count_rows_in_table(tn) if tn else 0
            count_lbl.setText(f"当前表约 {n} 行")

        def rebuild_table_combo(select_table: str | None = None):
            combo_tbl.blockSignals(True)
            combo_tbl.clear()
            metas = mgr._get_all_tables()
            for meta in metas:
                cat = str(meta.get("category") or "").strip() or "—"
                prod = str(meta.get("product_name") or "").strip() or "—"
                tn = str(meta.get("table_name") or "").strip()
                mod = str(meta.get("module_name") or "").strip()
                mod_prefix = f"{mod}-" if mod else ""
                leg = " [旧表]" if meta.get("legacy") else ""
                combo_tbl.addItem(f"{mod_prefix}{cat} / {prod}{leg}", tn)
            if select_table:
                idx = combo_tbl.findData(select_table)
                if idx >= 0:
                    combo_tbl.setCurrentIndex(idx)
            combo_tbl.blockSignals(False)
            refresh_count()

        mn, mx = mgr.get_test_date_range()
        if mn:
            de_start.setDate(QDate.fromString(mn, "yyyy-MM-dd"))
        else:
            de_start.setDate(QDate.currentDate())
        if mx:
            de_end.setDate(QDate.fromString(mx, "yyyy-MM-dd"))
        else:
            de_end.setDate(QDate.currentDate())

        def on_mode_toggled():
            use_date = rb_date.isChecked()
            de_start.setEnabled(use_date)
            de_end.setEnabled(use_date)

        rb_date.toggled.connect(lambda *_: on_mode_toggled())
        rb_clear.toggled.connect(lambda *_: on_mode_toggled())
        rb_drop.toggled.connect(lambda *_: on_mode_toggled())
        combo_tbl.currentIndexChanged.connect(lambda *_: refresh_count())

        refresh_count()
        on_mode_toggled()

        def after_mutation():
            self._set_yield_stats_mode("db_latest_day")
            self._mark_yield_date_reset_pending()
            self._refresh_yield_dashboard("yield_home")

        def do_execute():
            tn = current_table_name()
            if not tn:
                return QMessageBox.warning(dlg, "提示", "请选择数据表。")

            if rb_date.isChecked():
                ds = de_start.date().toString("yyyy-MM-dd")
                de = de_end.date().toString("yyyy-MM-dd")
                if de_start.date() > de_end.date():
                    return QMessageBox.warning(dlg, "提示", "开始日期不能晚于结束日期。")
                ok = QMessageBox.question(
                    dlg,
                    "确认删除",
                    f"将删除表「{tn}」中检测日期在 {ds} ～ {de}（含）内的全部行。\n是否继续？",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                if ok != QMessageBox.Yes:
                    return
                n = mgr.delete_rows_date_between(tn, ds, de)
                QMessageBox.information(dlg, "完成", f"已删除 {n} 行。")
                after_mutation()
                refresh_count()
                return

            if rb_clear.isChecked():
                n0 = mgr.count_rows_in_table(tn)
                ok = QMessageBox.question(
                    dlg,
                    "确认清空",
                    f"将删除表「{tn}」中的全部 {n0} 行（表结构保留）。\n是否继续？",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                if ok != QMessageBox.Yes:
                    return
                n = mgr.delete_all_rows_in_table(tn)
                QMessageBox.information(dlg, "完成", f"已删除 {n} 行。")
                after_mutation()
                refresh_count()
                return

            if rb_drop.isChecked():
                disp = combo_tbl.currentText()
                ok = QMessageBox.warning(
                    dlg,
                    "确认删除整张表",
                    f"将永久删除数据表「{tn}」及其全部数据（DROP TABLE）。\n"
                    f"显示名：{disp}\n\n"
                    f"表结构、索引与注册信息将一并移除，且不可恢复。\n是否继续？",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                if ok != QMessageBox.Yes:
                    return
                if not mgr.drop_data_table(tn):
                    QMessageBox.warning(dlg, "失败", f"删除数据表「{tn}」失败，请查看控制台日志。")
                    return
                QMessageBox.information(dlg, "完成", f"已删除整张数据表：\n{tn}")
                after_mutation()
                remaining = mgr._get_all_tables()
                if not remaining:
                    QMessageBox.information(dlg, "提示", "库中已无数据表。")
                    dlg.accept()
                    return
                rebuild_table_combo()
                return

        btn_row = QHBoxLayout()
        btn_run = QPushButton("执行删除…")
        btn_run.setMinimumWidth(int(120 * self._s))
        btn_run.clicked.connect(do_execute)
        btn_row.addWidget(btn_run)
        root.addLayout(btn_row)

        back_fn = on_back if on_back is not None else (lambda: self._open_database_sub_hub())
        root.addLayout(self._db_mgmt_footer_buttons(dlg, back_callback=back_fn, object_name_prefix="btn_db_maint"))

        dlg.exec_()

    def run_ort_analysis(self, scan_only: bool = True):
        """执行ORT分析逻辑"""
        if self.current_df is None or self.current_df.empty:
            return QMessageBox.warning(self, "提示", "请先导入并映射数据，再运行分析。")
        
        # 确保在ORT分析页面（切换到图形分析Tab，索引1）
        self._switch_ort_tab_by_name("图形分析")
        
        try:
            # === 步骤1：解析数据结构 ===
            df = self.current_df.copy()
            print(f"[DEBUG] 数据列数: {len(df.columns)}, 数据行数: {len(df)}")
            
            # 识别核心维度列
            core_cols = {}
            for col in df.columns:
                col_str = str(col).strip()
                matched_key = _match_ort_core_col_key(col_str)
                if matched_key == 'barcode':
                    core_cols.setdefault('barcode', col)
                elif matched_key:
                    core_cols[matched_key] = col
                else:
                    key = col_str.lower()
                    if any(k in key for k in ["barcode", "sn", "条码", "二维码", "條碼"]):
                        core_cols.setdefault('barcode', col)

            self._merge_ort_core_cols_from_mapping_config(df, core_cols)
            
            # 识别点位数据列：(点位名, value列名, spec列名)
            point_cols = []
            for col in df.columns:
                col_str = str(col).strip()
                if not col_str.endswith("_value"):
                    continue
                point_name = col_str[:-6]
                spec_col = f"{point_name}_spec" if f"{point_name}_spec" in df.columns else None
                point_cols.append((point_name, col, spec_col))
            
            print(f"[DEBUG] 识别到的核心列: {core_cols}")
            if not core_cols or len(core_cols) < 4:
                return QMessageBox.warning(self, "提示", "无法识别核心维度列，请检查数据格式。")
            
            # 若当前数据版本已初始化过，只需要触发一次更新即可
            if self._ort_initialized_version == self._data_version and hasattr(self, "_ort_raw_df"):
                self._ort_core_cols = core_cols
                self._ort_point_cols = point_cols
                self._ort_raw_df = df
                self._schedule_ort_update(delay_ms=0)
                return

            # === 步骤2：填充维度下拉框（首次初始化）===
            def get_unique_sorted(series):
                vals = series.dropna().astype(str).unique()
                vals = [v for v in vals if v and v.lower() not in ['nan', 'none', '']]
                return sorted(vals)
            
            # 填充小件列表
            subpart_vals = get_unique_sorted(df[core_cols['subpart']])
            self.ort_list_subpart.clear()
            for val in subpart_vals:
                item = QListWidgetItem(val)
                item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                item.setCheckState(Qt.Checked)  # 默认全部勾选
                self.ort_list_subpart.addItem(item)
            self._update_dropdown_text('subpart', len(subpart_vals), len(subpart_vals))
            
            # 填充配方列表
            recipe_vals = get_unique_sorted(df[core_cols['recipe']])
            self.ort_list_recipe.clear()
            for val in recipe_vals:
                item = QListWidgetItem(val)
                item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                item.setCheckState(Qt.Checked)  # 默认全部勾选
                self.ort_list_recipe.addItem(item)
            self._update_dropdown_text('recipe', len(recipe_vals), len(recipe_vals))
            
            # === 步骤3：保存解析结果到实例变量 ===
            self._ort_core_cols = core_cols
            self._ort_point_cols = point_cols
            self._ort_raw_df = df
            self._ort_initialized_version = self._data_version
            
            # === 步骤4：首次刷新（扫描/更新产品数，不作图）===
            self._render_ort_placeholder('已完成扫描。点击上方「一键作图」生成图表。')
            self._schedule_ort_update(delay_ms=0, do_plot=False)
            
            # === 步骤5：绑定列表项变化事件 ===
            # 解绑旧事件
            try:
                self.ort_list_subpart.itemChanged.disconnect()
                self.ort_list_recipe.itemChanged.disconnect()
            except:
                pass
            # 绑定新事件：仅扫描/更新产品数（不作图）
            self.ort_list_subpart.itemChanged.connect(lambda: self._schedule_ort_update(do_plot=False))
            self.ort_list_recipe.itemChanged.connect(lambda: self._schedule_ort_update(do_plot=False))
            
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "分析失败", f"数据解析错误：{str(e)}\n{traceback.format_exc()}")
    
    def _schedule_ort_update(self, delay_ms: int = 250, do_plot: bool = False):
        """合并多次筛选变化，避免频繁重绘导致界面假死。"""
        self._ort_next_do_plot = bool(do_plot)
        if getattr(self, "_ort_update_busy", False):
            self._ort_update_pending = True
            return
        if self._ort_update_timer is None:
            self._ort_update_timer = QTimer(self)
            self._ort_update_timer.setSingleShot(True)
            self._ort_update_timer.timeout.connect(self._update_ort_analysis)
        self._ort_update_timer.start(max(0, int(delay_ms)))

    def _update_ort_analysis(self):
        """更新ORT分析图表和表格"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            self._update_ort_analysis_from_db()
            return
        if not hasattr(self, '_ort_raw_df') or self._ort_raw_df is None:
            return
        
        try:
            if getattr(self, "_ort_update_busy", False):
                self._ort_update_pending = True
                return
            self._ort_update_busy = True

            # 性能优化：避免每次刷新都对整表 copy（筛选/排序本身会产生新对象）
            df_raw = self._ort_raw_df
            core_cols = self._ort_core_cols
            point_cols = self._ort_point_cols

            # === 步骤1：级联更新候选项（关键修复：前到后是筛选过程）===
            self._cascade_update_ort_filter_lists(df_raw, core_cols)

            # === 步骤2：获取当前勾选并应用筛选 ===
            selected_subparts = self._get_checked_texts(self.ort_list_subpart)
            selected_recipes = self._get_checked_texts(self.ort_list_recipe)

            df = df_raw
            if selected_subparts:
                df = df[df[core_cols['subpart']].astype(str).isin(selected_subparts)]
            else:
                df = df.head(0)
            if selected_recipes:
                df = df[df[core_cols['recipe']].astype(str).isin(selected_recipes)]
            else:
                df = df.head(0)
            
            # 扫描样本数（用于“作图设置”展示）
            # 你这里关注的是“单个配方（机种-项目-小件-配方）下的样本数”，而不是全局总行数。
            total_samples = int(len(df)) if df is not None else 0
            group_cols = [
                core_cols.get('machine_type'),
                core_cols.get('project'),
                core_cols.get('component'),
                core_cols.get('subpart'),
                core_cols.get('recipe'),
            ]
            group_cols = [c for c in group_cols if c and c in df.columns]
            per_recipe_samples = 0
            n_groups = 0
            if total_samples > 0 and group_cols:
                sizes = df.groupby(group_cols, sort=False).size()
                n_groups = int(len(sizes))
                # 用“最常见的样本数”作为默认显示（例如你的示例里常见是 11）
                try:
                    per_recipe_samples = int(sizes.mode().iloc[0])
                except Exception:
                    per_recipe_samples = int(sizes.median()) if len(sizes) else 0
            elif total_samples > 0:
                per_recipe_samples = total_samples

            if hasattr(self, "lbl_ort_product_count"):
                if total_samples <= 0:
                    self.lbl_ort_product_count.setText("样本数: -")
                else:
                    # 显示：单配方样本数（默认） + 总样本数 + 配方组数
                    tail = f" | 总{total_samples}"
                    if n_groups:
                        tail += f" | 组{n_groups}"
                    self.lbl_ort_product_count.setText(f"样本数: {per_recipe_samples}{tail}")

            if per_recipe_samples > 0 and hasattr(self, "spin_ort_points_per_chart"):
                # 首次扫描时把默认值同步成“单配方样本数”（不覆盖用户手动修改过的情况）
                if self.spin_ort_points_per_chart.value() in (0, 1, 11):
                    self.spin_ort_points_per_chart.setValue(max(1, per_recipe_samples))

            # 只有点击「一键作图」后才允许绘图
            if not getattr(self, "_ort_next_do_plot", False):
                # 如果不是绘图请求，检查是否有缓存的图表
                if hasattr(self, '_ort_fig_cache') and self._ort_fig_cache.get('generated'):
                    # 有缓存，不需要重新生成
                    self._ort_update_busy = False
                    return
                self._ort_update_busy = False
                return

            if df.empty:
                self._render_ort_recipe_charts(df, core_cols, point_cols, show_progress=False)
                self._update_ort_report_table(None)
                self._ort_update_busy = False
                return
            
            # === 步骤3：按配方 + 检测时间顺序排序 ===
            time_col = core_cols.get('time')
            sort_cols = [core_cols['recipe']]
            if time_col:
                df['_ort_time_sort'] = self._normalize_ort_time_series(df[time_col])
                sort_cols.append('_ort_time_sort')
            df = df.sort_values(sort_cols, ascending=True, kind='stable', na_position='last').reset_index(drop=True)
            df['_ort_x'] = range(len(df))
            self._ort_filtered_sorted_df = df
            
            # === 步骤4：更新图表（带进度条）===
            self._render_ort_recipe_charts(df, core_cols, point_cols, show_progress=True)
            # 本次绘图完成后回到"非绘图状态"，避免输入框/筛选变动自动重画
            self._ort_next_do_plot = False
            # 标记图表已生成，用于缓存判断
            self._ort_fig_cache['generated'] = True

            # === 步骤5：更新"数据与报告"页数据表 ===
            self._ort_show_df = df
            core_cols_report = dict(core_cols)
            core_cols_report.setdefault("barcode", "barcode")
            report_df = self._build_ort_report_df_from_wide(df, core_cols_report, point_cols)
            self._ort_report_df = report_df
            self._update_ort_report_table(self._ort_report_df)
            
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "更新失败", f"分析更新错误：{str(e)}\n{traceback.format_exc()}")
        finally:
            self._ort_update_busy = False
            if self._ort_update_pending:
                self._ort_update_pending = False
                self._schedule_ort_update(delay_ms=50)

    @staticmethod
    def _allocate_unique_sheet_title(row: pd.Series, used_sheet_names: set) -> tuple[str, str]:
        """返回 (用作 Tab/Sheet 的短标题, 完整配方名用作 ToolTip)。短标题遵循 Excel Sheet 命名规则。"""
        if "配方" in row.index and not pd.isna(row["配方"]) and str(row["配方"]).strip():
            full_recipe = str(row["配方"]).strip()
            title = full_recipe
        else:
            full_recipe = ""
            title = "Sheet"
        title = re.sub(r'[\[\]\:\*\?\/\\]', "_", title).strip() or "Sheet"
        short = title[:31]
        base = short
        suffix = 1
        while short in used_sheet_names:
            suffix_txt = f"_{suffix}"
            short = f"{base[:31 - len(suffix_txt)]}{suffix_txt}"
            suffix += 1
        used_sheet_names.add(short)
        return short, full_recipe

    def _build_ort_export_sheet_frames(self, report_df: pd.DataFrame | None) -> list[tuple[str, pd.DataFrame]]:
        """
        与导出 Excel / 报告页 Tab 相同：按 机种/组件/项目/小件/配方 分组；
        去掉规格列；每组只保留有实测值的点位；检测时间排序；
        测量列表头去掉后缀「_值」，仅保留点位名。
        """
        if report_df is None or report_df.empty:
            return []

        # 维度分组列：用于 Tab/Sheet 拆分。
        # 注意：二维码通常每行唯一，不能参与分组，否则会导致每个二维码被拆成一个 Tab/Sheet（看起来只剩一行）。
        identity_cols = [c for c in ["机种", "组件", "项目", "小件", "配方"] if c in report_df.columns]
        extra_cols = [c for c in ["二维码"] if c in report_df.columns]
        time_col = "检测时间" if "检测时间" in report_df.columns else None
        measurement_cols = [c for c in report_df.columns if str(c).endswith("_值")]
        if not identity_cols or not measurement_cols:
            return []

        # 输出列：在分组维度基础上追加二维码列（不参与分组），再加时间与测量值。
        export_cols = identity_cols + extra_cols + ([time_col] if time_col else []) + measurement_cols
        export_df = report_df[export_cols].copy()
        used_titles = set()
        frames: list[tuple[str, pd.DataFrame]] = []

        for _, group_df in export_df.groupby(identity_cols, sort=False, dropna=False):
            sheet_df = group_df.copy()
            if time_col:
                sheet_df["_ort_time_sort"] = pd.to_datetime(sheet_df[time_col], errors="coerce")
                sheet_df = sheet_df.sort_values("_ort_time_sort", ascending=True, kind="stable", na_position="last")
                sheet_df = sheet_df.drop(columns=["_ort_time_sort"])

            active_measurement_cols = []
            for col in measurement_cols:
                if col not in sheet_df.columns:
                    continue
                values = sheet_df[col]
                has_value = values.notna() & values.astype(str).str.strip().ne("")
                if bool(has_value.any()):
                    active_measurement_cols.append(col)

            sheet_cols = identity_cols + extra_cols + ([time_col] if time_col else []) + active_measurement_cols
            sheet_df = sheet_df[sheet_cols].reset_index(drop=True)
            if sheet_df.empty:
                continue
            rename_map = {}
            for c in sheet_df.columns:
                cs = str(c)
                if cs.endswith("_值"):
                    base = cs[:-2]
                    rename_map[c] = base if base else cs
            if rename_map:
                sheet_df = sheet_df.rename(columns=rename_map)
            short_title, _ = self._allocate_unique_sheet_title(sheet_df.iloc[0], used_titles)
            frames.append((short_title, sheet_df.copy()))
        return frames

    def _populate_ort_report_tabs(self, frames: list[tuple[str, pd.DataFrame]]):
        """在「数据与报告」页按配方 Tab 展示与导出一致的表格。"""
        tabs = getattr(self, "ort_report_tabs", None)
        if tabs is None:
            return

        # 性能优化：如果 frames 内容签名未变，避免重复重建所有 Tab/Table
        try:
            sig = tuple((t, int(getattr(df, "shape", (0, 0))[0]), tuple(getattr(df, "columns", []))) for t, df in (frames or []))
        except Exception:
            sig = None
        if sig is not None and getattr(self, "_ort_report_tabs_sig", None) == sig:
            return
        self._ort_report_tabs_sig = sig

        tabs.blockSignals(True)
        try:
            while tabs.count() > 0:
                tabs.removeTab(0)

            table_style = """
                QTableView {
                    border: none;
                    gridline-color: #B8D4E8;
                    font-size: 13px;
                }
                QHeaderView::section {
                    background-color: #E8F1F8;
                    padding: 10px 8px;
                    border: none;
                    border-bottom: 1px solid #A8C8E0;
                    font-weight: 600;
                    font-size: 14px;
                    min-height: 34px;
                }
            """

            if not frames:
                placeholder = QTableView()
                placeholder.setStyleSheet(table_style)
                placeholder.setModel(None)
                tabs.addTab(placeholder, "无数据")
                return

            for short_title, sheet_df in frames:
                table = QTableView()
                table.setAlternatingRowColors(True)
                table.setSelectionBehavior(QAbstractItemView.SelectRows)
                table.setSelectionMode(QAbstractItemView.ExtendedSelection)
                table.setStyleSheet(table_style)
                table.setMinimumWidth(0)
                table.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Expanding)
                table.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                table.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                # 性能优化：ResizeToContents 在列多时非常卡，改为交互式默认宽度
                table.setUpdatesEnabled(False)
                try:
                    table.setModel(PandasModel(sheet_df))
                    hdr = table.horizontalHeader()
                    hdr.setSectionResizeMode(QHeaderView.Interactive)
                    hdr.setDefaultSectionSize(110)
                    hdr.setStretchLastSection(True)
                finally:
                    table.setUpdatesEnabled(True)
                # 保证列表头有足够行高（不再限制 max，避免挤压标题）
                table.horizontalHeader().setMinimumHeight(36)

                idx = tabs.addTab(table, "")
                tab_lbl = self._create_ort_report_tab_label(short_title)
                tabs.tabBar().setTabButton(idx, QTabBar.LeftSide, tab_lbl)

                if "配方" in sheet_df.columns and len(sheet_df) > 0:
                    fr = sheet_df.iloc[0]["配方"]
                    if not pd.isna(fr) and str(fr).strip():
                        tabs.setTabToolTip(idx, str(fr).strip())
        finally:
            tabs.blockSignals(False)
            self._update_ort_tab_label_styles(tabs.currentIndex())
        QTimer.singleShot(0, self._ensure_ort_report_page_layout)

    def _create_ort_report_tab_label(self, short_title: str) -> QLabel:
        """数据与报告页：配方 Tab 自定义标题（支持两行完整显示）。"""
        tab_lbl = QLabel(str(short_title or ""))
        tab_lbl.setWordWrap(True)
        tab_lbl.setAlignment(Qt.AlignHCenter | Qt.AlignVCenter)
        tab_lbl.setMinimumWidth(int(120 * self._s))
        tab_lbl.setMaximumWidth(int(200 * self._s))
        tab_lbl.setMinimumHeight(int(44 * self._s))
        tab_lbl.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.MinimumExpanding)
        tab_lbl.setAttribute(Qt.WA_TransparentForMouseEvents)
        fs = int(12 * self._s)
        tab_lbl.setStyleSheet(
            f"font-size: {fs}px; font-weight: 700; color: #2C3E50; "
            "background: transparent; border: none; margin: 0; padding: 4px 6px;"
        )
        return tab_lbl

    def _update_ort_tab_label_styles(self, index: int):
        """当 Tab 切换时，更新自定义 Label 的文字颜色。"""
        tabs = self.ort_report_tabs
        bar = tabs.tabBar()
        fs = int(12 * self._s)
        for i in range(tabs.count()):
            btn = bar.tabButton(i, QTabBar.LeftSide)
            if isinstance(btn, QLabel):
                color = "#FFFFFF" if i == index else "#3A5A7A"
                btn.setStyleSheet(
                    f"font-size: {fs}px; font-weight: 700; color: {color}; "
                    "background: transparent; border: none; margin: 0; padding: 4px 6px;"
                )

    def _set_ort_report_stats(self, report_df: pd.DataFrame | None, frames: list | None):
        """刷新「数据与报告」页顶部的配方数、点位总数统计。"""
        r_lbl = getattr(self, "lbl_ort_report_recipe_cnt", None)
        p_lbl = getattr(self, "lbl_ort_report_point_cnt", None)
        if r_lbl is None or p_lbl is None:
            return
        frames = frames if frames is not None else []
        if report_df is None or getattr(report_df, "empty", True) or not frames:
            r_lbl.setText("配方数: —")
            p_lbl.setText("点位总数: —")
            return
        n_recipe = len(frames)
        n_points = sum(1 for c in report_df.columns if str(c).endswith("_值"))
        r_lbl.setText(f"配方数: {n_recipe}")
        p_lbl.setText(f"点位总数: {n_points}")

    def _build_ort_report_df_from_wide(
        self,
        df: pd.DataFrame,
        core_cols: dict,
        point_cols: list,
    ) -> pd.DataFrame:
        """将宽表整理为「数据与报告 / 导出 Excel」用的中文列名表。"""
        if df is None or df.empty or not core_cols or not point_cols:
            return pd.DataFrame()

        recipe_col = core_cols.get("recipe")
        if not recipe_col or recipe_col not in df.columns:
            return pd.DataFrame()

        work = df.copy()
        time_col = core_cols.get("time")
        sort_cols = [recipe_col]
        if time_col and time_col in work.columns:
            work["_ort_time_sort"] = self._normalize_ort_time_series(work[time_col])
            sort_cols.append("_ort_time_sort")
        work = work.sort_values(sort_cols, ascending=True, kind="stable", na_position="last").reset_index(drop=True)

        show_cols: list = []
        proj_col = core_cols.get("project")
        mt_show = core_cols.get("machine_type")
        bc_col = core_cols.get("barcode") or "barcode"
        comp_col = core_cols.get("component")
        sub_col = core_cols.get("subpart")
        if proj_col and proj_col in work.columns:
            show_cols.append(proj_col)
        if mt_show and mt_show in work.columns:
            show_cols.append(mt_show)
        if bc_col in work.columns:
            show_cols.append(bc_col)
        for c in (comp_col, sub_col, recipe_col):
            if c and c in work.columns:
                show_cols.append(c)
        if time_col and time_col in work.columns:
            show_cols.append(time_col)
        for (_point_name, val_col, spec_col) in point_cols:
            if val_col in work.columns:
                show_cols.append(val_col)
            if spec_col and spec_col in work.columns:
                show_cols.append(spec_col)

        show_cols = [c for c in show_cols if c in work.columns]
        if not show_cols:
            return pd.DataFrame()
        show_df = work.loc[:, show_cols].reset_index(drop=True)

        new_col_names: dict = {}
        if proj_col and proj_col in show_df.columns:
            new_col_names[proj_col] = "项目"
        if mt_show and mt_show in show_df.columns:
            new_col_names[mt_show] = "机种"
        if bc_col in show_df.columns:
            new_col_names[bc_col] = "二维码"
        if comp_col and comp_col in show_df.columns:
            new_col_names[comp_col] = "组件"
        if sub_col and sub_col in show_df.columns:
            new_col_names[sub_col] = "小件"
        if recipe_col in show_df.columns:
            new_col_names[recipe_col] = "配方"
        if time_col and time_col in show_df.columns:
            new_col_names[time_col] = "检测时间"
        for (point_name, val_col, spec_col) in point_cols:
            if val_col in show_df.columns:
                new_col_names[val_col] = f"{point_name}_值"
            if spec_col and spec_col in show_df.columns:
                new_col_names[spec_col] = f"{point_name}_规格"
        return show_df.rename(columns=new_col_names)

    def _prepare_ort_report_data_from_db(self, show_errors: bool = False) -> tuple[bool, str]:
        """从数据库加载并生成「数据与报告」页 / Export Data 用的配方分页表。"""
        self._ort_report_tabs_sig = None
        ok, err = self._prepare_spc_data_from_db()
        if not ok:
            self._ort_report_df = None
            self._update_ort_report_table(None)
            if show_errors and err:
                QMessageBox.information(self, "提示", err)
            return False, err

        core_cols = dict(self._ort_core_cols or {})
        core_cols.setdefault("barcode", "barcode")
        report_df = self._build_ort_report_df_from_wide(
            self._ort_raw_df, core_cols, getattr(self, "_ort_point_cols", []) or []
        )
        if report_df is None or report_df.empty:
            err = "查询到数据但无法生成报告表，请检查数据库记录是否完整。"
            self._ort_report_df = None
            self._update_ort_report_table(None)
            if show_errors:
                QMessageBox.information(self, "提示", err)
            return False, err

        start_date, end_date = self._ort_global_date_range_strings()
        category = self._get_current_global_type()
        product_name = self._get_selected_global_product()
        products_note = "、".join(self._get_global_type_products()[:6])
        if len(self._get_global_type_products()) > 6:
            products_note += "…"
        self._spc_data_scope_note = (
            f"{category}"
            + (f"（{products_note}）" if products_note else "")
            + f"  |  {start_date} ~ {end_date}"
        )

        self._ort_report_df = report_df
        lbl = getattr(self, "ort_report_table_label", None)
        if lbl is not None:
            lbl.setText(f"数据预览 · {self._spc_data_scope_note}（按配方分页，与导出 Excel 一致）")
        self._update_ort_report_table(report_df)
        return True, ""

    def _update_ort_report_table(self, report_df: pd.DataFrame | None):
        """刷新「ORT 数据与报告」页：按配方 Tab 预览（与导出 Excel 内容一致）。"""
        if report_df is None or getattr(report_df, "empty", True):
            self._ort_report_sheet_frames = []
            self._set_ort_report_stats(None, [])
            self._populate_ort_report_tabs([])
            return
        self._ort_report_sheet_frames = self._build_ort_export_sheet_frames(report_df)
        self._set_ort_report_stats(report_df, self._ort_report_sheet_frames)
        self._populate_ort_report_tabs(self._ort_report_sheet_frames)
        # 注意：不再自动入库，数据入库请在"数据预览"页面手动点击"数据入库"按钮

    def _call_jmp(self):
        """
        调用 JMP 绘制箱线图。
        流程：JMP路径确认 → 参数配置 → 导出临时CSV → 生成JSL → 启动JMP执行。
        """
        _jmp_call_boxplot(
            parent=self,
            report_df=getattr(self, "_ort_report_df", None),
            sheet_frames=list(getattr(self, "_ort_report_sheet_frames", None) or []),
            core_cols=getattr(self, "_ort_core_cols", {}) or {},
            point_cols=getattr(self, "_ort_point_cols", []) or [],
            spec_map=getattr(self, "_ort_recipe_point_spec_map", {}) or {},
            build_frames_fn=self._build_ort_export_sheet_frames,
        )

    def _export_ort_data(self):
        """导出内容与「数据与报告」页 Tab 预览一致（按配方拆分 Sheet）。"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            ok, err = self._prepare_ort_report_data_from_db(show_errors=True)
            if not ok:
                return
        report_df = getattr(self, "_ort_report_df", None)
        if report_df is None or report_df.empty:
            return QMessageBox.warning(
                self, "提示",
                "当前没有可导出的数据。请先在顶部选择类型/产品/时间范围，并确认数据库中有记录。",
            )

        frames = list(getattr(self, "_ort_report_sheet_frames", None) or [])
        if not frames:
            frames = self._build_ort_export_sheet_frames(report_df)
        if not frames:
            return QMessageBox.warning(self, "提示", "当前数据缺少配方维度或点位测量值，无法导出。")

        # 获取保存路径
        file_path, _ = QFileDialog.getSaveFileName(
            self,
            "导出 ORT 数据",
            os.path.join(self.current_workspace_dir, f"ORT_Data_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"),
            "Excel 文件 (*.xlsx)"
        )
        if not file_path:
            return

        try:
            # 若用户未指定扩展名，自动补 .xlsx
            if not file_path.lower().endswith(".xlsx"):
                file_path += ".xlsx"

            # 使用 openpyxl 写入并设置样式
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side

            # 计算总步骤数：1(单值图sheet) + len(frames)(数据sheets)
            total_steps = 1 + len(frames)
            progress = NiceProgressDialog("导出 Excel", "正在生成数据...", total_steps, self)
            progress.show()
            QApplication.processEvents()

            wb = Workbook()
            wb.remove(wb.active)

            # 表头样式（略增大字号；不自动换行 + 固定行高压扁表头，避免预览/导出观感过高）
            header_font = Font(name="Microsoft YaHei", bold=True, size=13, color="FFFFFF")
            header_fill = PatternFill(start_color="8B7355", end_color="8B7355", fill_type="solid")
            header_align = Alignment(horizontal="center", vertical="center", wrap_text=False)
            thin_border = Border(
                left=Side(style="thin", color="D4C4A8"),
                right=Side(style="thin", color="D4C4A8"),
                top=Side(style="thin", color="D4C4A8"),
                bottom=Side(style="thin", color="D4C4A8")
            )
            cell_align = Alignment(horizontal="center", vertical="center")

            def _write_dataframe_to_sheet(ws, sheet_df: pd.DataFrame):
                # 写入表头
                for col_idx, col_name in enumerate(sheet_df.columns, start=1):
                    cell = ws.cell(row=1, column=col_idx, value=col_name)
                    cell.font = header_font
                    cell.fill = header_fill
                    cell.alignment = header_align
                    cell.border = thin_border

                ws.row_dimensions[1].height = 28

                # 写入数据行
                for row_idx, row in enumerate(sheet_df.values, start=2):
                    for col_idx, val in enumerate(row, start=1):
                        cell = ws.cell(row=row_idx, column=col_idx)
                        cell.value = "" if pd.isna(val) else val
                        cell.alignment = cell_align
                        cell.border = thin_border
                        if row_idx % 2 == 0:
                            cell.fill = PatternFill(start_color="F8F4EC", end_color="F8F4EC", fill_type="solid")

                # 自适应列宽
                for col_idx, col_name in enumerate(sheet_df.columns, start=1):
                    max_len = max(len(str(col_name)), 10)
                    for row_idx in range(2, min(len(sheet_df) + 2, 100)):
                        cell_val = ws.cell(row=row_idx, column=col_idx).value
                        if cell_val:
                            max_len = max(max_len, min(len(str(cell_val)), 40))
                    ws.column_dimensions[ws.cell(row=1, column=col_idx).column_letter].width = max_len + 2

                ws.freeze_panes = "A2"

            # 创建"单值图"sheet并插入图表（放在第一个位置）
            progress.setValue(0)
            progress.bar.setFormat("正在生成单值图... %p%")
            QApplication.processEvents()
            chart_ws = wb.create_sheet("单值图", 0)
            self._add_charts_to_excel_sheet(chart_ws, frames)

            # 写入数据sheets
            for idx, (sheet_title, sheet_df) in enumerate(frames, start=1):
                if progress.wasCanceled():
                    return
                progress.setValue(idx)
                progress.bar.setFormat(f"正在导出 {sheet_title}... %p%")
                QApplication.processEvents()
                ws = wb.create_sheet(sheet_title)
                _write_dataframe_to_sheet(ws, sheet_df)

            progress.setValue(total_steps)
            QApplication.processEvents()
            progress.close()
            progress.deleteLater()

            wb.save(file_path)
            QMessageBox.information(self, "导出成功", f"数据已按配方拆分导出到：\n{file_path}")
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "导出失败", f"导出 Excel 时发生错误：\n{str(e)}\n{traceback.format_exc()}")

    def _add_charts_to_excel_sheet(self, ws, frames: list[tuple[str, pd.DataFrame]]):
        """在 Excel「单值图」Sheet 中插入趋势图：与主页一致——A 列为结构名（纵向合并居中），B 起横向排列，列宽/行高避免重叠。"""
        from openpyxl.drawing.image import Image as OpenpyxlImage
        from io import BytesIO
        import matplotlib.pyplot as plt
        from collections import defaultdict

        if not frames:
            ws.cell(row=1, column=1, value="暂无数据")
            ws.cell(row=1, column=1).font = Font(name="Microsoft YaHei", size=14, color="5D4E37")
            return

        charts_per_row = 6
        chart_width = 2.5
        chart_height = 1.6
        img_width_px = 240
        img_height_px = 150
        # 每一「横行」图共用一行锚点，行高用 row_pt 撑开；下一横行锚点紧挨下一 Excel 行（避免大块空白）
        row_stride = 1
        label_col = 1
        first_chart_col = 2
        last_chart_col = first_chart_col + charts_per_row - 1
        # Excel 列宽约等于像素/7（Calibri 11 下经验值），略放大防止横向挤压重叠
        chart_col_width = max(14.0, min(56.0, (img_width_px + 24) / 6.5))

        ws.column_dimensions[self._get_excel_col_letter(label_col)].width = 10.5
        for ci in range(first_chart_col, last_chart_col + 1):
            ws.column_dimensions[self._get_excel_col_letter(ci)].width = chart_col_width

        row_pt = img_height_px * 72.0 / 96.0 + 10.0

        current_row = 1

        for sheet_title, sheet_df in frames:
            if sheet_df is None or sheet_df.empty:
                continue

            recipe_name = sheet_title
            sample_count = len(sheet_df)

            # 导出用 sheet 与「数据与报告」一致：维度列 + 时间 + 测量列；测量列已去掉「_值」后缀（见 _build_ort_export_sheet_frames）
            dim_cols = {"机种", "機種", "组件", "組件", "项目", "項目", "小件", "配方"}
            time_col = None
            for col in sheet_df.columns:
                if _is_ort_time_col(col):
                    time_col = col
                    break
            point_cols = [
                col
                for col in sheet_df.columns
                if str(col) not in dim_cols and col is not time_col and not _is_ort_time_col(col)
            ]
            # 兼容未改名的宽表列（仍为 xxx_值）
            if not point_cols:
                point_cols = [
                    col
                    for col in sheet_df.columns
                    if str(col).endswith("_值") and str(col) not in dim_cols and not _is_ort_time_col(col)
                ]
            if not point_cols:
                current_row += 2
                continue

            n_plottable = 0
            for pc in point_cols:
                if pd.to_numeric(sheet_df[pc], errors="coerce").notna().any():
                    n_plottable += 1

            ws.merge_cells(
                start_row=current_row,
                start_column=label_col,
                end_row=current_row,
                end_column=last_chart_col,
            )
            hdr = ws.cell(
                row=current_row,
                column=label_col,
                value=f"配方：{recipe_name}    样本数：{sample_count}    总图数：{n_plottable}",
            )
            hdr.font = Font(name="Microsoft YaHei", bold=True, size=12, color="5D4E37")
            hdr.alignment = Alignment(horizontal="left", vertical="center")
            current_row += 2

            buckets: dict[str, list] = defaultdict(list)
            for point_col in point_cols:
                prefix = self._ort_point_structure_prefix(point_col)
                buckets[prefix].append(point_col)

            recipe_order_text = str(sheet_df.iloc[0]["配方"]) if "配方" in sheet_df.columns else recipe_name
            ordered_prefs = sorted(
                buckets.keys(),
                key=lambda p: (
                    self._ort_prefix_first_pos_in_recipe(recipe_order_text, p),
                    tuple(self._natural_sort_key(str(p))),
                ),
            )

            for pref in ordered_prefs:
                group_point_cols = sorted(
                    buckets[pref], key=lambda x: tuple(self._natural_sort_key(str(x)))
                )
                plot_cols = [
                    pc for pc in group_point_cols
                    if pd.to_numeric(sheet_df[pc], errors="coerce").notna().any()
                ]
                if not plot_cols:
                    continue

                n_chart_rows = (len(plot_cols) + charts_per_row - 1) // charts_per_row
                group_start_row = current_row
                # A 列合并范围 = 实际占用行数（与右侧图行一致），勿再乘以过大的 row_stride
                merge_end_row = group_start_row + n_chart_rows - 1

                ws.merge_cells(
                    start_row=group_start_row,
                    start_column=label_col,
                    end_row=merge_end_row,
                    end_column=label_col,
                )
                struct_cell = ws.cell(row=group_start_row, column=label_col, value=str(pref))
                struct_cell.font = Font(name="Microsoft YaHei", bold=True, size=11, color="6B5344")
                struct_cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

                valid_charts = 0
                seen_anchor_rows: set[int] = set()

                for point_col in plot_cols:
                    try:
                        fig = self._build_excel_point_figure_small(
                            sheet_df, point_col, time_col, chart_width, chart_height
                        )
                        if fig is None:
                            continue

                        img_buffer = BytesIO()
                        fig.savefig(
                            img_buffer,
                            format="png",
                            dpi=100,
                            bbox_inches="tight",
                            facecolor="white",
                            edgecolor="none",
                        )
                        img_buffer.seek(0)

                        chart_idx = valid_charts
                        row_in_group = chart_idx // charts_per_row
                        col_in_row = chart_idx % charts_per_row
                        target_row = group_start_row + row_in_group * row_stride
                        col_letter = self._get_excel_col_letter(first_chart_col + col_in_row)

                        img = OpenpyxlImage(img_buffer)
                        img.width = img_width_px
                        img.height = img_height_px
                        ws.add_image(img, f"{col_letter}{target_row}")

                        if target_row not in seen_anchor_rows:
                            seen_anchor_rows.add(target_row)
                            ws.row_dimensions[target_row].height = row_pt

                        valid_charts += 1
                        plt.close(fig)
                    except Exception as e:
                        print(f"[DEBUG] 生成图表失败 {point_col}: {e}")
                        continue

                current_row = merge_end_row + 2

            current_row += 2

    def _get_excel_col_letter(self, col_num: int) -> str:
        """将列数字转换为Excel列字母（1=A, 2=B, ...）"""
        result = ""
        while col_num > 0:
            col_num, remainder = divmod(col_num - 1, 26)
            result = chr(65 + remainder) + result
        return result

    def _build_excel_point_figure(self, sheet_df: pd.DataFrame, point_col: str, time_col: str | None):
        """构建Excel用的单个点位趋势图 Figure。"""
        values = pd.to_numeric(sheet_df[point_col], errors="coerce")
        valid_df = sheet_df.loc[values.notna()].copy()
        if valid_df.empty:
            return None

        y_values = pd.to_numeric(valid_df[point_col], errors="coerce").to_numpy()
        x_values = np.arange(1, len(valid_df) + 1)

        fig = Figure(figsize=(6, 3.5), dpi=120)
        fig.patch.set_facecolor("#FFFFFF")
        ax = fig.add_subplot(111)
        ax.set_facecolor("#FFFFFF")

        point_name = str(point_col).replace("_值", "")
        ax.plot(x_values, y_values, color="#2F80ED", marker="o", linewidth=1.5, markersize=4)
        ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.28)
        ax.set_title(point_name, fontsize=10, color="#2C3E50", pad=6)
        ax.set_xlabel("样本顺序", fontsize=8)
        ax.set_ylabel("测量值", fontsize=8)
        ax.tick_params(axis="both", labelsize=7)

        if time_col and time_col in valid_df.columns:
            time_labels = [self._format_chart_time_label(v) for v in valid_df[time_col]]
            if len(time_labels) <= 5:
                tick_positions = x_values
            else:
                tick_positions = np.linspace(1, len(time_labels), num=5, dtype=int)
                tick_positions = np.unique(tick_positions)
            tick_labels = [time_labels[pos - 1] for pos in tick_positions]
            ax.set_xticks(tick_positions)
            ax.set_xticklabels(tick_labels, fontsize=6, rotation=35, ha="right")
        else:
            ax.set_xticks(x_values)
            ax.tick_params(axis="x", labelsize=6)

        y_min = np.nanmin(y_values) if len(y_values) else np.nan
        y_max = np.nanmax(y_values) if len(y_values) else np.nan
        if np.isfinite(y_min) and np.isfinite(y_max):
            if y_min == y_max:
                y_margin = max(abs(y_min) * 0.05, 0.5)
                ax.set_ylim(y_min - y_margin, y_max + y_margin)
            else:
                pad = (y_max - y_min) * 0.08
                ax.set_ylim(y_min - pad, y_max + pad)

        fig.tight_layout(pad=1.0)
        return fig

    def _build_excel_point_figure_small(self, sheet_df: pd.DataFrame, point_col: str, time_col: str | None, width: float = 2.5, height: float = 1.6):
        """构建Excel用的小尺寸单个点位趋势图 Figure。"""
        values = pd.to_numeric(sheet_df[point_col], errors="coerce")
        valid_df = sheet_df.loc[values.notna()].copy()
        if valid_df.empty:
            return None

        y_values = pd.to_numeric(valid_df[point_col], errors="coerce").to_numpy()
        x_values = np.arange(1, len(valid_df) + 1)

        fig = Figure(figsize=(width, height), dpi=100)
        fig.patch.set_facecolor("#FFFFFF")
        ax = fig.add_subplot(111)
        ax.set_facecolor("#FFFFFF")

        point_name = str(point_col).replace("_值", "")
        ax.plot(x_values, y_values, color="#2F80ED", marker="o", linewidth=1.0, markersize=2.5)
        ax.grid(True, linestyle="--", linewidth=0.4, alpha=0.25)
        ax.set_title(point_name, fontsize=7, color="#2C3E50", pad=3)
        ax.tick_params(axis="both", labelsize=5)

        # 简化X轴标签
        if time_col and time_col in valid_df.columns:
            time_labels = [self._format_chart_time_label(v) for v in valid_df[time_col]]
            if len(time_labels) <= 3:
                tick_positions = x_values
            else:
                tick_positions = np.linspace(1, len(time_labels), num=3, dtype=int)
                tick_positions = np.unique(tick_positions)
            tick_labels = [time_labels[pos - 1] for pos in tick_positions]
            ax.set_xticks(tick_positions)
            ax.set_xticklabels(tick_labels, fontsize=4, rotation=30, ha="right")
        else:
            # 只显示首尾标签
            ax.set_xticks([1, len(x_values)])
            ax.set_xticklabels(["1", str(len(x_values))], fontsize=5)

        y_min = np.nanmin(y_values) if len(y_values) else np.nan
        y_max = np.nanmax(y_values) if len(y_values) else np.nan
        if np.isfinite(y_min) and np.isfinite(y_max):
            if y_min == y_max:
                y_margin = max(abs(y_min) * 0.05, 0.5)
                ax.set_ylim(y_min - y_margin, y_max + y_margin)
            else:
                pad = (y_max - y_min) * 0.1
                ax.set_ylim(y_min - pad, y_max + pad)

        fig.tight_layout(pad=0.5)
        return fig

    def _choose_ppt_export_action(self):
        """导出前选择导出类型：single=单值图，jmp=JMP 箱线图，False=取消。"""
        while True:
            msg = QMessageBox(self)
            msg.setWindowTitle("选择导出类型")
            msg.setText("请选择本次导出的内容。")
            
            # 添加标准按钮和自定义按钮
            btn_single = msg.addButton("单值图", QMessageBox.AcceptRole)
            btn_jmp = msg.addButton("JMP箱线图", QMessageBox.ActionRole)
            btn_cfg = msg.addButton("配置路径", QMessageBox.ActionRole)
            
            # 添加一个隐藏的取消按钮，使关闭按钮可用
            btn_cancel = msg.addButton(QMessageBox.Cancel)
            btn_cancel.setVisible(False)
            
            msg.setDefaultButton(btn_single)

            # 按钮字体与尺寸：比默认更紧凑（考虑 DPI 缩放）
            try:
                btn_font_px = max(10, int(11 * getattr(self, "_s", 1.0)))
                btn_h = max(30, int(34 * getattr(self, "_s", 1.0)))
                msg.setStyleSheet(f"""
                    QLabel {{
                        font-size: {max(12, int(13 * getattr(self, "_s", 1.0)))}px;
                        color: #2C3E50;
                    }}
                    QPushButton {{
                        font-size: {btn_font_px}px;
                        font-weight: 600;
                        padding: 6px 12px;
                        min-height: {btn_h}px;
                        border-radius: 8px;
                        background-color: #5B9BD5;
                        color: white;
                    }}
                    QPushButton:hover {{ background-color: #4A8BC4; }}
                """)
            except Exception:
                pass

            result = msg.exec_()
            
            # 检查点击的是哪个按钮
            clicked = msg.clickedButton()
            
            # 如果点击了取消按钮、关闭窗口，或者没有点击任何按钮，返回None
            if clicked is None or clicked == btn_cancel or result == QMessageBox.Cancel:
                return None
            if clicked == btn_cfg:
                # 同时配置PPT和JMP路径
                dlg = PptJmpPathDialog(self)
                if dlg.exec_() == QDialog.Accepted:
                    QMessageBox.information(self, "提示", "PPT 和 JMP 路径已更新")
                continue
            if clicked == btn_jmp:
                return "jmp"
            return "single"

    def _get_ppt_blank_layout(self, prs):
        """尽量选择空白版式；若模板没有标准空白版式，选占位符最少的版式。"""
        try:
            return min(prs.slide_layouts, key=lambda layout: len(layout.placeholders))
        except Exception:
            return prs.slide_layouts[0]

    def _natural_sort_key(self, text):
        return [int(part) if part.isdigit() else part.lower() for part in re.split(r"(\d+)", str(text))]

    def _build_ppt_point_figure(self, sheet_df: pd.DataFrame, point_col: str, time_col: str | None):
        """构建 PPT 用的单个点位趋势图 Figure。"""
        values = pd.to_numeric(sheet_df[point_col], errors="coerce")
        valid_df = sheet_df.loc[values.notna()].copy()
        if valid_df.empty:
            return None

        y_values = pd.to_numeric(valid_df[point_col], errors="coerce").to_numpy()
        x_values = np.arange(1, len(valid_df) + 1)

        fig = Figure(figsize=(3.2, 1.95), dpi=160)
        fig.patch.set_facecolor("#FFFFFF")
        ax = fig.add_subplot(111)
        ax.set_facecolor("#FFFFFF")
        ax.plot(x_values, y_values, color="#2F80ED", marker="o", linewidth=1.2, markersize=3.2)
        ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.28)
        ppt_point_name = str(point_col).replace("_值", "")
        ax.set_title(ppt_point_name, fontsize=8.5, color="#2C3E50", pad=4)
        ax.set_xlabel("样本顺序", fontsize=7)
        ax.tick_params(axis="y", labelsize=7)

        if time_col and time_col in valid_df.columns:
            time_labels = [self._format_chart_time_label(v) for v in valid_df[time_col]]
            if len(time_labels) <= 5:
                tick_positions = x_values
            else:
                tick_positions = np.linspace(1, len(time_labels), num=5, dtype=int)
                tick_positions = np.unique(tick_positions)
            tick_labels = [time_labels[pos - 1] for pos in tick_positions]
            ax.set_xticks(tick_positions)
            ax.set_xticklabels(tick_labels, fontsize=6, rotation=35, ha="right")
        else:
            ax.set_xticks(x_values)
            ax.tick_params(axis="x", labelsize=6)

        y_min = np.nanmin(y_values) if len(y_values) else np.nan
        y_max = np.nanmax(y_values) if len(y_values) else np.nan
        if np.isfinite(y_min) and np.isfinite(y_max):
            if y_min == y_max:
                y_margin = max(abs(y_min) * 0.05, 0.5)
                ax.set_ylim(y_min - y_margin, y_max + y_margin)
            else:
                pad = (y_max - y_min) * 0.08
                ax.set_ylim(y_min - pad, y_max + pad)

        fig.tight_layout(pad=0.8)
        return fig

    def _add_ppt_title(self, slide, title_text: str, prs):
        from pptx.util import Inches, Pt  # type: ignore[import-not-found]
        from pptx.dml.color import RGBColor  # type: ignore[import-not-found]

        slide_w = prs.slide_width / 914400
        title_box = slide.shapes.add_textbox(Inches(0.45), Inches(0.18), Inches(slide_w - 0.9), Inches(0.55))
        tf = title_box.text_frame
        tf.clear()
        p = tf.paragraphs[0]
        p.text = title_text
        p.font.name = "Microsoft YaHei"
        p.font.size = Pt(22)
        p.font.bold = True
        p.font.color.rgb = RGBColor(61, 54, 48)

    def _add_ppt_chart_grid(self, slide, sheet_df: pd.DataFrame, prs):
        from pptx.util import Inches  # type: ignore[import-not-found]

        time_col = next((c for c in sheet_df.columns if _is_ort_time_col(c)), None)
        meta_cols = {"机种", "機種", "组件", "組件", "项目", "項目", "小件", "配方", "检测时间", "檢測時間", "时间", "時間"}
        point_cols = [c for c in sheet_df.columns if c not in meta_cols]
        point_cols = sorted(point_cols, key=self._natural_sort_key)
        if not point_cols:
            return

        n = len(point_cols)
        if n <= 1:
            cols = 1
        elif n <= 4:
            cols = 2
        elif n <= 9:
            cols = 3
        else:
            cols = 4
        rows = int(np.ceil(n / cols))

        slide_w = prs.slide_width / 914400
        slide_h = prs.slide_height / 914400
        left = 0.42
        right = 0.42
        top = 0.98
        bottom = 0.32
        gap_x = 0.14
        gap_y = 0.16
        chart_w = max((slide_w - left - right - gap_x * (cols - 1)) / cols, 1.0)
        chart_h = max((slide_h - top - bottom - gap_y * (rows - 1)) / rows, 0.72)

        for idx, point_col in enumerate(point_cols):
            fig = self._build_ppt_point_figure(sheet_df, point_col, time_col)
            if fig is None:
                continue
            buf = io.BytesIO()
            fig.savefig(buf, format="png", dpi=160, facecolor="#FFFFFF", bbox_inches="tight")
            plt.close(fig)
            buf.seek(0)

            row = idx // cols
            col = idx % cols
            x = left + col * (chart_w + gap_x)
            y = top + row * (chart_h + gap_y)
            slide.shapes.add_picture(buf, Inches(x), Inches(y), width=Inches(chart_w), height=Inches(chart_h))

    def _build_ppt_chart_layout(self, sheet_df: pd.DataFrame, slide_w: float, slide_h: float):
        time_col = next((c for c in sheet_df.columns if _is_ort_time_col(c)), None)
        meta_cols = {"机种", "機種", "组件", "組件", "项目", "項目", "小件", "配方", "检测时间", "檢測時間", "时间", "時間"}
        point_cols = [c for c in sheet_df.columns if c not in meta_cols]
        point_cols = sorted(point_cols, key=self._natural_sort_key)
        if not point_cols:
            return time_col, []

        n = len(point_cols)
        if n <= 1:
            cols = 1
        elif n <= 4:
            cols = 2
        elif n <= 9:
            cols = 3
        else:
            cols = 4
        rows = int(np.ceil(n / cols))

        left = 0.42
        right = 0.42
        top = 0.98
        bottom = 0.32
        gap_x = 0.14
        gap_y = 0.16
        chart_w = max((slide_w - left - right - gap_x * (cols - 1)) / cols, 1.0)
        chart_h = max((slide_h - top - bottom - gap_y * (rows - 1)) / rows, 0.72)

        layout = []
        for idx, point_col in enumerate(point_cols):
            row = idx // cols
            col = idx % cols
            layout.append({
                "point_col": point_col,
                "x": left + col * (chart_w + gap_x),
                "y": top + row * (chart_h + gap_y),
                "w": chart_w,
                "h": chart_h,
            })
        return time_col, layout

    def _render_ppt_slide_assets(self, sheet_df: pd.DataFrame, temp_dir: str, slide_index: int,
                                 slide_w: float = 13.333, slide_h: float = 7.5):
        time_col, chart_layout = self._build_ppt_chart_layout(sheet_df, slide_w, slide_h)
        pictures = []
        for chart_index, chart in enumerate(chart_layout, start=1):
            fig = self._build_ppt_point_figure(sheet_df, chart["point_col"], time_col)
            if fig is None:
                continue
            image_path = os.path.join(temp_dir, f"slide_{slide_index:03d}_chart_{chart_index:03d}.png")
            fig.savefig(image_path, format="png", dpi=160, facecolor="#FFFFFF", bbox_inches="tight")
            plt.close(fig)
            pictures.append({
                "path": image_path,
                "left": chart["x"] * 72,
                "top": chart["y"] * 72,
                "width": chart["w"] * 72,
                "height": chart["h"] * 72,
            })
        return {
            "title_left": 0.45 * 72,
            "title_top": 0.18 * 72,
            "title_width": max(slide_w - 0.9, 1.0) * 72,
            "title_height": 0.55 * 72,
            "pictures": pictures,
        }

    def _export_ort_ppt_via_powerpoint(self, frames, out_path):
        temp_dir = tempfile.mkdtemp(prefix="ort_ppt_export_")
        progress = None
        try:
            slides_payload = []
            progress = NiceProgressDialog("导出 PPT", "正在调用本机 PowerPoint 生成文件...", len(frames), self)
            progress.show()
            QApplication.processEvents()

            for idx, (sheet_title, sheet_df) in enumerate(frames, start=1):
                if progress.wasCanceled():
                    return
                progress.setValue(idx - 1)
                QApplication.processEvents()

                recipe_name = str(sheet_df.iloc[0]["配方"]).strip() if "配方" in sheet_df.columns else sheet_title
                slide_assets = self._render_ppt_slide_assets(sheet_df, temp_dir, idx)
                slides_payload.append({
                    "title": recipe_name,
                    "title_left": slide_assets["title_left"],
                    "title_top": slide_assets["title_top"],
                    "title_width": slide_assets["title_width"],
                    "title_height": slide_assets["title_height"],
                    "pictures": slide_assets["pictures"],
                })

            progress.setValue(len(frames))
            QApplication.processEvents()
            progress.close()
            progress.deleteLater()
            progress = None

            if not _save_ppt_via_powerpoint_payload(slides_payload, out_path, parent=self):
                return

            QMessageBox.information(self, "导出成功", f"PPT 已导出到：\n{out_path}")
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "导出失败", f"调用本机 PowerPoint 导出时发生错误：\n{str(e)}\n{traceback.format_exc()}")
        finally:
            if progress is not None:
                progress.close()
                progress.deleteLater()
            shutil.rmtree(temp_dir, ignore_errors=True)

    def _export_ort_single_value_ppt(self):
        """按配方导出单值趋势图 PPT。"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            ok, _ = self._prepare_ort_report_data_from_db(show_errors=True)
            if not ok:
                return
        report_df = getattr(self, "_ort_report_df", None)
        if report_df is None or report_df.empty:
            return QMessageBox.warning(
                self, "提示",
                "当前没有可导出的数据。请先在顶部选择类型/产品/时间范围。",
            )

        frames = list(getattr(self, "_ort_report_sheet_frames", None) or [])
        if not frames:
            frames = self._build_ort_export_sheet_frames(report_df)
        if not frames:
            return QMessageBox.warning(self, "提示", "当前数据缺少配方维度或点位测量值，无法导出 PPT。")

        out_path, _ = QFileDialog.getSaveFileName(
            self,
            "导出 ORT PPT",
            os.path.join(self.current_workspace_dir, f"ORT_Report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pptx"),
            "PowerPoint 文件 (*.pptx)"
        )
        if not out_path:
            return
        if not out_path.lower().endswith(".pptx"):
            out_path += ".pptx"

        try:
            from pptx import Presentation  # type: ignore[import-not-found]
            from pptx.util import Inches  # type: ignore[import-not-found]

            prs = Presentation()
            prs.slide_width = Inches(13.333)
            prs.slide_height = Inches(7.5)

            blank_layout = self._get_ppt_blank_layout(prs)
            progress = NiceProgressDialog("导出 PPT", "正在生成配方趋势图页面...", len(frames), self)
            progress.show()
            QApplication.processEvents()

            for idx, (sheet_title, sheet_df) in enumerate(frames, start=1):
                if progress.wasCanceled():
                    return
                progress.setValue(idx - 1)
                QApplication.processEvents()

                slide = prs.slides.add_slide(blank_layout)
                recipe_name = str(sheet_df.iloc[0]["配方"]).strip() if "配方" in sheet_df.columns else sheet_title
                self._add_ppt_title(slide, recipe_name, prs)
                self._add_ppt_chart_grid(slide, sheet_df, prs)

            progress.setValue(len(frames))
            QApplication.processEvents()
            # 进度完成后自动关闭
            progress.close()
            progress.deleteLater()
            prs.save(out_path)
            QMessageBox.information(self, "导出成功", f"PPT 已导出到：\n{out_path}")
        except ImportError:
            self._export_ort_ppt_via_powerpoint(frames, out_path)
        except Exception as e:
            import traceback
            QMessageBox.critical(self, "导出失败", f"导出 PPT 时发生错误：\n{str(e)}\n{traceback.format_exc()}")

    def _export_ort_ppt(self):
        """导出入口：选择导出单值图或 JMP 箱线图。"""
        action = self._choose_ppt_export_action()
        if action is None or action is False:
            return
        if action == "jmp":
            self._call_jmp()
            return
        self._export_ort_single_value_ppt()

    def _update_dropdown_text(self, attr_name, selected_count, total_count):
        dropdown_btn = getattr(self, f"ort_dropdown_{attr_name}", None)
        if not dropdown_btn:
            return
        panel_host = getattr(self, f"_ort_filter_panel_host_{attr_name}", None)
        if selected_count == 0:
            text = "请选择..."
        elif selected_count == total_count and total_count > 0:
            text = f"全选 ({total_count})"
        elif selected_count == total_count:
            text = "全选"
        else:
            text = f"已选 {selected_count}/{total_count}"
        suffix = "▴" if panel_host is not None and panel_host.isVisible() else "▾"
        dropdown_btn.setText(f"{text}  {suffix}")

    def _get_checked_texts(self, list_widget: QListWidget) -> list[str]:
        if list_widget is None:
            return []
        checked = []
        for i in range(list_widget.count()):
            it = list_widget.item(i)
            if it and it.checkState() == Qt.Checked:
                checked.append(it.text())
        return checked

    def _ort_group_dimension_options(self) -> list[tuple[str, str]]:
        return [
            ("不分组", ""),
            ("项目", "project"),
            ("机种", "machine_type"),
            ("组件", "component"),
            ("小件", "subpart"),
            ("配方", "recipe"),
            ("线别", "line"),
            ("结果", "result"),
            ("班别", "shift"),
            ("测试位", "test_position"),
            ("日期", "analysis_date"),
            ("件名", "part_name"),
        ]

    def _ort_group_dimension_label(self, key: str) -> str:
        # 特殊处理点位名称
        if key == "point_name":
            return "点位"
        for label, value in self._ort_group_dimension_options():
            if value == key:
                return label
        return str(key or "")

    def _ort_is_hierarchical_xaxis(self, x_field: str, df: pd.DataFrame) -> bool:
        """X 轴为日期/班次等分组维度且存在多点位时，启用双层标签（点位在上、分组在下）。"""
        if not x_field or x_field == "point_name":
            return False
        if x_field not in df.columns:
            return False
        return "point_name" in df.columns and df["point_name"].nunique() > 1

    def _ort_plot_mean_line_segments(
        self,
        ax,
        items,
        *,
        color="#2F80ED",
        linestyle="--",
        linewidth=1.5,
        marker="o",
        markersize=5,
        alpha=0.8,
        min_points=2,
        break_by_prefix=False,
        break_by_key=None,
    ):
        """按前缀或自定义键分段绘制箱线图均值连线。"""
        import collections
        if not items or len(items) < min_points:
            return
        segments = collections.OrderedDict()
        for pos, mean_val, lbl, seg_key in items:
            if break_by_key and seg_key is not None:
                key = seg_key
            elif break_by_prefix:
                key = _jmp_point_family(str(lbl))
            else:
                key = "_all"
            if key not in segments:
                segments[key] = {"positions": [], "values": []}
            segments[key]["positions"].append(pos)
            segments[key]["values"].append(mean_val)
        for seg in segments.values():
            if len(seg["positions"]) >= min_points:
                ax.plot(
                    seg["positions"], seg["values"],
                    color=color, linestyle=linestyle, linewidth=linewidth,
                    alpha=alpha, marker=marker, markersize=markersize,
                )

    def _ort_point_xtick_style(self, n_ticks: int) -> tuple[int, str]:
        """点位较多时竖排刻度，避免 AC1/USB1 等标签重叠。"""
        if n_ticks > 6:
            return 90, "center"
        return 22, "right"

    def _ort_apply_hierarchical_xlabels(self, ax, fig, group_keys, hierarchical_info):
        """双层 X 轴：上行点位（竖排），下行 X 分组值（日期等）。"""
        date_vals = hierarchical_info["date_vals"]
        x_field_label = hierarchical_info.get("x_field_label", "")

        grp_positions = {}
        for gi, gk in enumerate(group_keys):
            dv, _pt = gk
            grp_positions.setdefault(dv, []).append(gi)

        date_positions, date_labels = [], []
        for date_val in date_vals:
            pos_list = grp_positions.get(date_val) or []
            if pos_list:
                date_positions.append((pos_list[0] + pos_list[-1]) / 2.0)
                date_labels.append(str(date_val))

        point_labels_full = [str(pt) for _dv, pt in group_keys]
        # 层级图点位重复出现，统一竖排避免 AC1/USB1 等重叠
        ax.set_xticklabels(point_labels_full, fontsize=7, rotation=90, ha="center")
        ax.tick_params(axis="x", pad=34)
        use_vertical = True
        ax.set_xlabel("")

        xlim = ax.get_xlim()
        ax_width = xlim[1] - xlim[0] if xlim[1] != xlim[0] else 1.0
        date_y = -0.20 if use_vertical else -0.14
        for pos, label in zip(date_positions, date_labels):
            x_norm = (pos - xlim[0]) / ax_width
            ax.text(
                x_norm, date_y, label,
                fontsize=9, ha="center", va="top",
                transform=ax.transAxes, color="#333333",
            )
        if x_field_label:
            ax.text(
                1.0, date_y, x_field_label,
                fontsize=8, ha="right", va="top",
                transform=ax.transAxes, color="#888888", style="italic",
            )
        bottom = 0.16 if use_vertical else 0.10
        fig.tight_layout(pad=1.2, rect=[0, bottom, 1, 0.92])

    def _ort_db_current_scope(self) -> tuple[str, str, str]:
        module_name = str(getattr(self, "ort_db_combo_module", QComboBox()).currentData() or "").strip()
        category = str(getattr(self, "ort_db_combo_category", QComboBox()).currentData() or "").strip()
        product_name = str(getattr(self, "ort_db_combo_product", QComboBox()).currentData() or "").strip()
        return module_name, category, product_name

    def _ort_db_current_filters(self) -> dict:
        return {
            "subpart": self._get_checked_texts(getattr(self, "ort_list_subpart", None)),
            "recipe": self._get_checked_texts(getattr(self, "ort_list_recipe", None)),
        }

    def _ort_global_date_range_strings(self) -> tuple[str, str]:
        """读取 ORT 顶部全局时间范围（yyyy-MM-dd）。"""
        from PyQt5.QtCore import QDate
        if hasattr(self, "ort_global_date_start") and hasattr(self, "ort_global_date_end"):
            start_date = self.ort_global_date_start.date().toString("yyyy-MM-dd")
            end_date = self.ort_global_date_end.date().toString("yyyy-MM-dd")
        else:
            start_date = QDate.currentDate().toString("yyyy-MM-dd")
            end_date = start_date
        return start_date, end_date

    def _ort_db_partial_filters(self, *exclude_keys: str) -> dict:
        filters = self._ort_db_current_filters()
        skip = {str(k or "").strip() for k in exclude_keys if str(k or "").strip()}
        return {k: v for k, v in filters.items() if k not in skip and v}

    def _resolve_ort_analysis_point_name(self) -> str:
        """图形分析自动解析点位（界面已移除点位选择）。"""
        combo_point = getattr(self, "ort_db_combo_point", None)
        if combo_point is not None:
            current = str(combo_point.currentData() or "").strip()
            if current:
                return current

        mgr = getattr(self, "_ort_db", None)
        module_name, category, product_name = self._ort_db_current_scope()
        if mgr is None or not (module_name and category and product_name):
            return ""

        points = mgr.list_distinct_long_values(
            "point_name",
            module_name=module_name,
            category=category,
            product_name=product_name,
            filters=self._ort_db_partial_filters(),
            limit=8000,
        )
        if not points:
            return ""
        chosen = str(points[0]).strip()
        if combo_point is not None:
            self._fill_combo_items(combo_point, [(p, p) for p in points], chosen)
        return chosen

    def _get_available_points_for_analysis(self, mgr, module_name: str, category: str, product_name: str) -> list[str]:
        """获取可用于分析的点位列表（如AC1~AC6）。"""
        if mgr is None or not (module_name and category and product_name):
            return []
        
        points = mgr.list_distinct_long_values(
            "point_name",
            module_name=module_name,
            category=category,
            product_name=product_name,
            filters=self._ort_db_partial_filters(),
            limit=8000,
        )
        
        # 过滤出类似AC1~AC6的点位
        # 支持格式：AC1, AC2, ..., AC6 或类似命名
        point_list = []
        for p in points:
            p_str = str(p).strip()
            if p_str:
                point_list.append(p_str)
        
        # 按自然顺序排序（如AC1, AC2, ..., AC10）
        def natural_sort_key(s):
            import re
            return [int(text) if text.isdigit() else text.lower() 
                    for text in re.split('([0-9]+)', s)]
        
        return sorted(point_list, key=natural_sort_key)

    def _refresh_ort_db_hidden_point(self):
        combo_point = getattr(self, "ort_db_combo_point", None)
        mgr = getattr(self, "_ort_db", None)
        if combo_point is None or mgr is None:
            return
        module_name, category, product_name = self._ort_db_current_scope()
        current = str(combo_point.currentData() or "").strip()
        if not (module_name and category and product_name):
            self._fill_combo_items(combo_point, [], "")
            return
        points = mgr.list_distinct_long_values(
            "point_name",
            module_name=module_name,
            category=category,
            product_name=product_name,
            filters=self._ort_db_partial_filters(),
            limit=8000,
        )
        keep = current if current in points else (points[0] if points else "")
        self._fill_combo_items(combo_point, [(p, p) for p in points], keep)

    def _on_ort_db_filter_changed(self, *_):
        """核心筛选（小件/配方/班别/线别）变化时级联刷新候选项。"""
        # 获取当前选中的小件，用于级联刷新配方
        sender_list = self.sender()
        if sender_list == self.ort_list_subpart:
            # 小件变化时，需要级联刷新配方
            self._refresh_ort_db_filter_lists()
        else:
            # 其他筛选变化，只更新提示
            self._update_recipe_selection_hint()
        self._schedule_ort_update(delay_ms=120, do_plot=False)

    def _update_recipe_selection_hint(self):
        """更新配方选择状态提示"""
        lbl = getattr(self, "lbl_recipe_selection_hint", None)
        if lbl is None:
            return
        
        selected_recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
        recipe_count = len(selected_recipes)
        
        if recipe_count == 0:
            lbl.setText("⚠️ 请选择至少一个配方")
            lbl.setStyleSheet(f"color: #6B8299; font-size: {int(10*self._s)}px;")
        elif recipe_count == 1:
            lbl.setText(f"✓ 已选配方: {selected_recipes[0]}\n将生成单一图形")
            lbl.setStyleSheet(f"color: #27AE60; font-size: {int(10*self._s)}px;")
        else:
            lbl.setText(f"✓ 已选 {recipe_count} 个配方\n将生成 {recipe_count} 个独立图形（按配方分组）")
            lbl.setStyleSheet(f"color: #6B8299; font-size: {int(10*self._s)}px;")

    def _fill_combo_items(self, combo: QComboBox, items: list[tuple[str, str]], keep_value: str = ""):
        if combo is None:
            return
        combo.blockSignals(True)
        try:
            combo.clear()
            for text, value in items:
                combo.addItem(text, value)
            idx = combo.findData(keep_value)
            if idx < 0:
                idx = 0 if combo.count() > 0 else -1
            if idx >= 0:
                combo.setCurrentIndex(idx)
        finally:
            combo.blockSignals(False)

    def _on_ort_global_scope_inputs_changed(self):
        """顶部全局类型/产品变化时，同步图形分析数据库范围（不影响良率页模板导航）。"""
        if getattr(self, "_ort_chart_mode", "") != "db_grouped":
            return
        tab_idx = getattr(self, "_current_ort_tab_idx", -1)
        if tab_idx == 3:
            self._refresh_ort_report_table()
            return
        if tab_idx != 1:
            return
        if self._sync_ort_db_scope_from_global():
            self._refresh_ort_db_filter_lists()
            self._schedule_ort_update(delay_ms=120, do_plot=False)

    def _set_ort_db_combo_value(self, combo: QComboBox, value: str) -> bool:
        val = str(value or "").strip()
        if combo is None or not val:
            return False
        idx = combo.findData(val)
        if idx < 0:
            for i in range(combo.count()):
                if str(combo.itemData(i) or "").strip().lower() == val.lower():
                    idx = i
                    break
        if idx < 0:
            return False
        combo.setCurrentIndex(idx)
        return True

    def _sync_ort_db_scope_from_global(self) -> bool:
        """将顶部全局「类型」（默认取该类型下首个产品）同步到图形分析的数据库范围下拉框。"""
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            return False

        category = str(self._get_current_global_type() or "").strip()
        if not category:
            return False

        selected_products = self._get_selected_global_products()
        product_name = str(selected_products[0]).strip() if selected_products else ""
        if not product_name:
            _m, _c, product_name = self._ensure_yield_scope_state()
            if not category and _c:
                category = str(_c).strip()
        if not product_name:
            return False
        module_name = ""
        scopes = mgr.list_registered_scopes()
        for mod, cat, prod in scopes:
            if str(cat).strip() == category and str(prod).strip() == product_name:
                module_name = str(mod).strip()
                break
        if not module_name:
            for mod, cat, _prod in scopes:
                if str(cat).strip() == category:
                    module_name = str(mod).strip()
                    break
        if not module_name:
            module_name = self.DEFAULT_MODULE_NAME

        combo_module = getattr(self, "ort_db_combo_module", None)
        combo_category = getattr(self, "ort_db_combo_category", None)
        combo_product = getattr(self, "ort_db_combo_product", None)
        combo_point = getattr(self, "ort_db_combo_point", None)
        if combo_module is None or combo_category is None or combo_product is None:
            return False

        combos = [c for c in (combo_module, combo_category, combo_product, combo_point) if c is not None]
        for combo in combos:
            combo.blockSignals(True)
        try:
            self._refresh_ort_db_scope_controls()
            self._set_ort_db_combo_value(combo_module, module_name)
            self._refresh_ort_db_scope_controls()
            self._set_ort_db_combo_value(combo_category, category)
            self._refresh_ort_db_scope_controls()
            self._set_ort_db_combo_value(combo_product, product_name)
            self._refresh_ort_db_scope_controls()

        finally:
            for combo in combos:
                combo.blockSignals(False)

        self._refresh_ort_db_filter_lists()
        module_name, category, product_name = self._ort_db_current_scope()
        return bool(module_name and category and product_name)

    def _initialize_ort_db_analysis_ui(self, update_placeholder: bool = True):
        if getattr(self, "_ort_db", None) is None:
            return
        self._refresh_ort_db_scope_controls()
        synced = self._sync_ort_db_scope_from_global()
        if not getattr(self, "_ort_db_scope_ready", False):
            self._ort_db_scope_ready = True
        if update_placeholder and not (getattr(self, "_ort_fig_cache", {}) or {}).get("generated"):
            module_name, category, product_name = self._ort_db_current_scope()
            point_name = self._resolve_ort_analysis_point_name()
            if module_name and category and product_name and point_name:
                msg = "将维度字段拖入 X / Y / 颜色，再点击「作图  ◉」。"
            elif synced and module_name and category and product_name:
                msg = "范围已从顶部同步。配置维度后点击「作图  ◉」。"
            elif not synced:
                msg = "请先在顶部选择类型，再进入图形分析。"
            else:
                msg = "请先在顶部选择类型，再点击「作图  ◉」。"
            self._render_ort_placeholder(msg)

    def _refresh_ort_db_scope_controls(self):
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            return
        combo_module = getattr(self, "ort_db_combo_module", None)
        combo_category = getattr(self, "ort_db_combo_category", None)
        combo_product = getattr(self, "ort_db_combo_product", None)
        combo_g1 = getattr(self, "ort_db_combo_group1", None)
        combo_g2 = getattr(self, "ort_db_combo_group2", None)
        combo_g3 = getattr(self, "ort_db_combo_group3", None)
        if combo_module is None or combo_category is None or combo_product is None:
            return

        current_module = str(combo_module.currentData() or "").strip()
        current_category = str(combo_category.currentData() or "").strip()
        current_product = str(combo_product.currentData() or "").strip()

        scopes = mgr.list_registered_scopes()
        modules = sorted({m for m, _, _ in scopes if m}, key=str.lower)
        self._fill_combo_items(combo_module, [("请选择模块...", "")] + [(m, m) for m in modules], current_module)
        chosen_module = str(combo_module.currentData() or "").strip()

        categories = sorted({c for m, c, _ in scopes if c and (not chosen_module or m == chosen_module)}, key=str.lower)
        self._fill_combo_items(combo_category, [("请选择大类...", "")] + [(c, c) for c in categories], current_category)
        chosen_category = str(combo_category.currentData() or "").strip()

        products = sorted(
            {p for m, c, p in scopes if p and (not chosen_module or m == chosen_module) and (not chosen_category or c == chosen_category)},
            key=str.lower
        )
        self._fill_combo_items(combo_product, [("请选择产品...", "")] + [(p, p) for p in products], current_product)

        dim_items = self._ort_group_dimension_options()
        self._fill_combo_items(combo_g1, dim_items, str(combo_g1.currentData() or "shift"))
        self._fill_combo_items(combo_g2, dim_items, str(combo_g2.currentData() or "line"))
        self._fill_combo_items(combo_g3, dim_items, str(combo_g3.currentData() or "recipe"))

    def _refresh_ort_db_filter_lists(self):
        """刷新筛选列表，实现小件-配方级联筛选"""
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            return
        module_name, category, product_name = self._ort_db_current_scope()
        if not (module_name and category and product_name):
            for attr_name in ("subpart", "recipe", "shift", "line"):
                self._rebuild_check_list(getattr(self, f"ort_list_{attr_name}", None), attr_name, [])
            self._refresh_ort_db_hidden_point()
            return
        
        # 1. 先刷新小件列表（不受其他筛选影响）
        subpart_values = mgr.list_distinct_long_values(
            "subpart",
            module_name=module_name,
            category=category,
            product_name=product_name,
            filters={},
            limit=5000,
        )
        self._rebuild_check_list(self.ort_list_subpart, "subpart", subpart_values)
        
        # 2. 根据已选小件刷新配方列表（级联筛选）
        selected_subparts = self._get_checked_texts(self.ort_list_subpart)
        recipe_filters = {"subpart": selected_subparts} if selected_subparts else {}
        recipe_values = mgr.list_distinct_long_values(
            "recipe",
            module_name=module_name,
            category=category,
            product_name=product_name,
            filters=recipe_filters,
            limit=5000,
        )
        self._rebuild_check_list(self.ort_list_recipe, "recipe", recipe_values)
        
        # 3. 刷新其他筛选列表
        for attr_name in ("shift", "line"):
            values = mgr.list_distinct_long_values(
                attr_name,
                module_name=module_name,
                category=category,
                product_name=product_name,
                filters=self._ort_db_partial_filters(attr_name),
                limit=5000,
            )
            self._rebuild_check_list(getattr(self, f"ort_list_{attr_name}", None), attr_name, values)
        
        self._refresh_ort_db_hidden_point()
        self._update_recipe_selection_hint()

    def _rebuild_check_list(self, list_widget: QListWidget, attr_name: str, values: list[str]):
        """
        用 values 重建勾选列表，并尽量保留原勾选状态：
        - 若原来是“全选”，则新列表也全选
        - 否则保留原本勾选的交集；
          - 若用户曾把该维度“清空勾选”（prev_checked 为空），则保持清空
          - 若交集为空且 values 非空（说明原选项不再存在），则默认全选
        """
        prev_all = True
        prev_checked = set()
        prev_total = list_widget.count()
        for i in range(prev_total):
            it = list_widget.item(i)
            if not it:
                continue
            if it.checkState() == Qt.Checked:
                prev_checked.add(it.text())
            else:
                prev_all = False

        values = [str(v) for v in values if str(v).strip() and str(v).lower() not in ("nan", "none")]
        values = sorted(set(values))

        list_widget.blockSignals(True)
        try:
            list_widget.clear()
            if not values:
                self._update_dropdown_text(attr_name, 0, 0)
                return

            # 计算本次应勾选集合
            if prev_total > 0 and prev_all:
                next_checked = set(values)
            else:
                # 用户明确“全取消”时，prev_checked 会为空，此时保持为空，不要自动回填全选
                if prev_total > 0 and (not prev_all) and (len(prev_checked) == 0):
                    next_checked = set()
                else:
                    next_checked = prev_checked.intersection(values)
                    if not next_checked:
                        next_checked = set(values)

            for v in values:
                item = QListWidgetItem(v)
                item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                item.setCheckState(Qt.Checked if v in next_checked else Qt.Unchecked)
                list_widget.addItem(item)
        finally:
            list_widget.blockSignals(False)

        self._update_dropdown_text(attr_name, len(self._get_checked_texts(list_widget)), list_widget.count())

    def _cascade_update_ort_filter_lists(self, df_raw: pd.DataFrame, core_cols: dict):
        """按 小件→配方 的级联关系，更新各维度候选项。"""
        if self._ort_updating_controls:
            return
        self._ort_updating_controls = True
        try:
            # 1) Subpart 候选
            sub_vals = df_raw[core_cols['subpart']].dropna().astype(str).unique().tolist() if core_cols.get('subpart') in df_raw.columns else []
            self._rebuild_check_list(self.ort_list_subpart, 'subpart', sub_vals)
            sel_subs = set(self._get_checked_texts(self.ort_list_subpart))
            df1 = df_raw[df_raw[core_cols['subpart']].astype(str).isin(sel_subs)] if sel_subs else df_raw.head(0)

            # 2) Recipe 候选（依赖小件）
            rec_vals = df1[core_cols['recipe']].dropna().astype(str).unique().tolist() if core_cols.get('recipe') in df1.columns else []
            self._rebuild_check_list(self.ort_list_recipe, 'recipe', rec_vals)
        finally:
            self._ort_updating_controls = False

    def _clear_layout_widgets(self, layout):
        """递归清空布局中的控件。"""
        if layout is None:
            return
        while layout.count():
            item = layout.takeAt(0)
            child_layout = item.layout()
            child_widget = item.widget()
            if child_layout is not None:
                self._clear_layout_widgets(child_layout)
            if child_widget is not None:
                child_widget.deleteLater()

    def _render_ort_placeholder(self, text: str):
        """在图表区域显示占位提示。"""
        if not hasattr(self, "ort_chart_layout") or self.ort_chart_layout is None:
            return
        self._clear_layout_widgets(self.ort_chart_layout)
        lbl = QLabel(text or "")
        lbl.setWordWrap(True)
        lbl.setStyleSheet("font-size: 14px; color: #5A7A99; padding: 22px 10px;")
        self.ort_chart_layout.addWidget(lbl)
        self.ort_chart_layout.addStretch(1)

    def _build_ort_db_grouped_summary(self, raw_df: pd.DataFrame, dim_keys: list[str]) -> tuple[pd.DataFrame, list[str]]:
        df = raw_df.copy()
        df["value"] = pd.to_numeric(df["value"], errors="coerce")
        df["lsl"] = pd.to_numeric(df.get("lsl"), errors="coerce")
        df["usl"] = pd.to_numeric(df.get("usl"), errors="coerce")
        df["analysis_date"] = pd.to_datetime(df.get("test_time"), errors="coerce").dt.strftime("%Y-%m-%d")
        df["machine_type"] = df.get("model")
        df["status_code"] = df.apply(lambda row: _ort_point_status_code(row.get("value"), row.get("lsl"), row.get("usl")), axis=1)
        df["is_ng"] = (df["status_code"] == 0).astype(int)
        df["is_alert"] = (df["status_code"] == 2).astype(int)
        df["is_pass"] = (df["status_code"] == 1).astype(int)

        used_dims: list[str] = []
        actual_cols: list[str] = []
        for dim_key in dim_keys:
            key = str(dim_key or "").strip()
            if not key or key in used_dims:
                continue
            if key not in df.columns:
                continue
            used_dims.append(key)
            actual_cols.append(key)

        if not actual_cols:
            df["_all_groups"] = "全部"
            actual_cols = ["_all_groups"]
            used_dims = []

        grouped = df.groupby(actual_cols, dropna=False, sort=False)
        summary_df = grouped.agg(
            sample_count=("value", "count"),
            mean_value=("value", "mean"),
            median_value=("value", "median"),
            min_value=("value", "min"),
            max_value=("value", "max"),
            ng_count=("is_ng", "sum"),
            alert_count=("is_alert", "sum"),
            pass_count=("is_pass", "sum"),
        ).reset_index()
        summary_df["ng_rate"] = np.where(summary_df["sample_count"] > 0, summary_df["ng_count"] / summary_df["sample_count"] * 100.0, 0.0)
        summary_df["alert_rate"] = np.where(summary_df["sample_count"] > 0, summary_df["alert_count"] / summary_df["sample_count"] * 100.0, 0.0)
        summary_df["pass_rate"] = np.where(summary_df["sample_count"] > 0, summary_df["pass_count"] / summary_df["sample_count"] * 100.0, 0.0)

        def _build_group_label(row):
            parts = []
            for dim in actual_cols:
                val = row.get(dim)
                txt = str(val).strip() if val is not None and not pd.isna(val) else "空"
                parts.append("全部" if dim == "_all_groups" else f"{self._ort_group_dimension_label(dim)}={txt}")
            return " | ".join(parts)

        summary_df["group_label"] = summary_df.apply(_build_group_label, axis=1)
        summary_df = summary_df.sort_values(["sample_count", "group_label"], ascending=[False, True], kind="stable").reset_index(drop=True)
        return summary_df, used_dims

    def _build_ort_grouped_analysis_figure(
        self,
        point_name: str,
        summary_df: pd.DataFrame,
        used_dims: list[str],
        scope_triplet: tuple[str, str, str],
        figsize=(10.6, 6.4),
        dpi=110,
    ):
        plot_df = summary_df.head(24).copy()
        fig = Figure(figsize=figsize, dpi=dpi)
        fig.patch.set_facecolor("#FFFFFF")
        ax1 = fig.add_subplot(311)
        ax2 = fig.add_subplot(312)
        ax3 = fig.add_subplot(313)
        x = np.arange(len(plot_df))
        short_labels = [txt if len(txt) <= 26 else txt[:23] + "..." for txt in plot_df["group_label"].astype(str).tolist()]

        ax1.bar(x, plot_df["sample_count"].to_numpy(), color="#A8C8E0", edgecolor="#5B9BD5", linewidth=0.6)
        ax1.set_ylabel("样本数", fontsize=9)
        ax1.set_title(
            f"{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]} · 点位 {point_name}\n"
            f"三维分组统计图（显示前 {len(plot_df)} 组）",
            fontsize=11,
            color="#2C3E50",
            pad=8,
        )
        ax1.grid(True, axis="y", linestyle="--", linewidth=0.5, alpha=0.22)

        ax2.plot(x, plot_df["mean_value"].to_numpy(), color="#2F80ED", marker="o", linewidth=1.4, markersize=4, label="Mean")
        ax2.plot(x, plot_df["median_value"].to_numpy(), color="#3A5A7A", marker="s", linewidth=1.2, markersize=3.5, label="Median")
        ax2.set_ylabel("测量值", fontsize=9)
        ax2.grid(True, linestyle="--", linewidth=0.5, alpha=0.24)
        ax2.legend(loc="best", fontsize=8, frameon=False)

        ax3.bar(x, plot_df["pass_rate"].to_numpy(), color="#22C55E", label="Pass")
        ax3.bar(x, plot_df["alert_rate"].to_numpy(), bottom=plot_df["pass_rate"].to_numpy(), color="#F59E0B", label="Alert")
        ax3.bar(x, plot_df["ng_rate"].to_numpy(), bottom=(plot_df["pass_rate"] + plot_df["alert_rate"]).to_numpy(), color="#EF4444", label="NG")
        ax3.set_ylabel("占比 %", fontsize=9)
        ax3.set_ylim(0, 100)
        ax3.grid(True, axis="y", linestyle="--", linewidth=0.5, alpha=0.24)
        ax3.legend(loc="best", fontsize=8, frameon=False)

        for ax in (ax1, ax2, ax3):
            ax.set_xticks(x)
            ax.set_xticklabels(short_labels, fontsize=7, rotation=22, ha="right")
            ax.tick_params(axis="y", labelsize=8)
        fig.tight_layout(pad=1.2)
        return fig

    def _render_ort_db_grouped_charts(
        self,
        point_name: str,
        summary_df: pd.DataFrame,
        raw_df: pd.DataFrame,
        used_dims: list[str],
        scope_triplet: tuple[str, str, str],
    ):
        self._clear_layout_widgets(self.ort_chart_layout)
        self.ort_chart_label.setText("数据库多维统计图")

        info_card = QFrame()
        info_card.setStyleSheet("""
            QFrame {
                background-color: #F5F9FF;
                border: 1px solid #C5D9E8;
                border-radius: 14px;
            }
        """)
        info_lay = QVBoxLayout(info_card)
        info_lay.setContentsMargins(16, 14, 16, 14)
        info_lay.setSpacing(8)
        dim_text = " / ".join(self._ort_group_dimension_label(k) for k in used_dims) if used_dims else "整体汇总"
        title_lbl = QLabel(f"点位：{point_name}  ·  分组维度：{dim_text}")
        title_lbl.setStyleSheet("font-size: 14px; font-weight: 800; color: #2C3E50;")
        info_lay.addWidget(title_lbl)
        desc_lbl = QLabel(
            f"数据源：{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]}    "
            f"原始记录 {len(raw_df)} 条，统计分组 {len(summary_df)} 组。"
        )
        desc_lbl.setWordWrap(True)
        desc_lbl.setStyleSheet("font-size: 12px; color: #5A7A99;")
        info_lay.addWidget(desc_lbl)

        chart_card = ClickableFrame()
        chart_card.setStyleSheet("""
            QFrame {
                background-color: #FFFFFF;
                border: 1px solid #C5D9E8;
                border-radius: 12px;
            }
        """)
        chart_lay = QVBoxLayout(chart_card)
        chart_lay.setContentsMargins(12, 12, 12, 12)
        chart_lay.setSpacing(8)
        fig_builder = lambda figsize=(10.6, 6.4), dpi=110: self._build_ort_grouped_analysis_figure(
            point_name=point_name,
            summary_df=summary_df,
            used_dims=used_dims,
            scope_triplet=scope_triplet,
            figsize=figsize,
            dpi=dpi,
        )
        canvas = FigureCanvas(fig_builder(figsize=(9.4, 5.6), dpi=100))
        chart_lay.addWidget(canvas)
        chart_card.clicked.connect(lambda: ChartZoomDialog(f"{point_name} · 数据库统计图", fig_builder, self).exec_())

        self.ort_chart_layout.addWidget(info_card)
        self.ort_chart_layout.addWidget(chart_card)
        self.ort_chart_layout.addStretch(1)

    # ── 互动图形：字段列表填充 & 拖拽区域响应 ──

    def _populate_ort_point_field_list(self):
        """用当前 DB 中可用的点位名填充「测量点位」字段列表。"""
        fl = getattr(self, "_ort_point_field_list", None)
        if fl is None:
            return
        mgr = getattr(self, "_ort_db", None)
        module_name, category, product_name = self._ort_db_current_scope()
        points: list[str] = []
        if mgr and module_name and category and product_name:
            points = mgr.list_distinct_long_values(
                "point_name",
                module_name=module_name,
                category=category,
                product_name=product_name,
                limit=8000,
            )
        fl.blockSignals(True)
        fl.clear()
        for pt in points:
            it = QListWidgetItem(str(pt))
            it.setData(Qt.UserRole, str(pt))
            it.setData(Qt.UserRole + 1, "point")
            fl.addItem(it)
        fl.blockSignals(False)

    def _on_ort_drop_zone_changed(self, zone_id: str, field_key: str, _display: str):
        """放置区变化时同步隐藏的分组 Combo（X→分组1，Y→分组2，颜色→分组3，图形拆分→分组4）。"""
        _zone_combo = {"x": "group1", "y": "group2", "color": "group3", "group": "group4"}
        combo_key = _zone_combo.get(zone_id)
        if combo_key:
            combo = getattr(self, f"ort_db_combo_{combo_key}", None)
            if combo is not None:
                keep = field_key if field_key else str(combo.currentData() or "")
                self._fill_combo_items(
                    combo, self._ort_group_dimension_options(), keep)
        lbl = getattr(self, "lbl_ort_product_count", None)
        if lbl:
            lbl.setText("样本数: - (点击「作图」生成)")

    # ── 箱线图 ──

    def _build_ort_boxplot_figure(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str = "",
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        figsize=(10.6, 5.4),
        dpi=110,
        chart_title_override: str = "",
    ):
        """生成 ORT 分组箱线图（matplotlib）。
        
        Args:
            chart_title_override: 可选，覆盖默认的图表标题"""
        COLORS = ["#2F80ED", "#E63946", "#2DC653", "#F4A261", "#A8DADC",
                  "#457B9D", "#E9C46A", "#264653", "#9B5DE5", "#00B4D8"]

        df = raw_df.copy()
        df["value"] = pd.to_numeric(df.get("value"), errors="coerce")
        df["lsl"]   = pd.to_numeric(df.get("lsl"),   errors="coerce")
        df["usl"]   = pd.to_numeric(df.get("usl"),   errors="coerce")
        df = df.dropna(subset=["value"])

        y_vals = []
        if y_field and y_field in df.columns:
            y_vals = sorted(df[y_field].dropna().unique().tolist(), key=str)

        # ── 创建画布 ──
        fig = Figure(figsize=figsize, dpi=dpi)
        fig.patch.set_facecolor("#FFFFFF")

        if df.empty:
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FAFAFA")
            ax.text(0.5, 0.5, "暂无数据", ha="center", va="center",
                    transform=ax.transAxes, fontsize=14, color="#9A8A78")
            return fig

        # ── 确定 X 轴分组 ──
        has_point_level = "point_name" in df.columns and df["point_name"].nunique() > 1
        use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, df)
        
        if use_hierarchical:
            point_vals = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            date_vals = sorted(df[x_field].dropna().unique().tolist(), key=str)
            
            group_keys = []
            x_labels = []
            for date_val in date_vals:
                for pt in point_vals:
                    subset = df[(df[x_field] == date_val) & (df["point_name"] == pt)]["value"].dropna().tolist()
                    if subset:
                        group_keys.append((date_val, pt))
                        x_labels.append(str(pt))
            
            n_groups = len(group_keys)
            hierarchical_info = {
                'date_vals': date_vals,
                'point_vals': point_vals,
                'x_field_label': self._ort_group_dimension_label(x_field),
            }
        elif x_field and x_field in df.columns:
            group_keys = sorted(df[x_field].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
        elif has_point_level:
            group_keys = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
            x_field = "point_name"
        else:
            group_keys = ["全部"]
            x_labels = ["全部"]
            n_groups = 1
            use_hierarchical = False
            hierarchical_info = None
            x_field = ""

        # ── 颜色分组 ──
        if color_field and color_field in df.columns:
            color_vals = sorted(df[color_field].dropna().unique().tolist(), key=str)
            n_c = len(color_vals)
            width = 0.72 / max(n_c, 1)
            offsets = np.linspace(-(n_c - 1) * width / 2, (n_c - 1) * width / 2, n_c)
        else:
            color_vals = []

        # ── 构建标题 ──
        if chart_title_override:
            chart_title = chart_title_override
        else:
            product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
            subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
            recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
            subpart_str = subparts[0] if len(subparts) == 1 else (f"{len(subparts)}个小件" if subparts else "")
            recipe_str = recipes[0] if len(recipes) == 1 else (f"{len(recipes)}个配方" if recipes else "")
            
            title_parts = [p for p in [product_name, subpart_str, recipe_str] if p]
            chart_title = "-".join(title_parts) + " · 箱线图" if title_parts else f"{product_name} · 箱线图"

        # ── 创建垂直多子图 (JMP 风格) ──
        if y_vals:
            nrows = len(y_vals)
            figsize = (figsize[0], 2.2 * nrows + 1.2)
            fig.set_size_inches(figsize[0], figsize[1])
            axes = fig.subplots(nrows, 1, sharex=True, sharey=True, squeeze=False)
        else:
            nrows = 1
            axes = None

        # ── 遍历子图绘制数据 ──
        for ri in range(nrows):
            if y_vals:
                ax = axes[ri, 0]
                y_val = y_vals[ri]
                sub_df = df[df[y_field] == y_val]
            else:
                ax = fig.add_subplot(111)
                y_val = None
                sub_df = df
            
            ax.set_facecolor("#FAFAFA")
            is_last_row = (ri == nrows - 1)

            if color_vals:
                for ci, (cval, offset) in enumerate(zip(color_vals, offsets)):
                    c_df = sub_df[sub_df[color_field] == cval]
                    c_data = []
                    c_pos  = []
                    for gi, gk in enumerate(group_keys):
                        if use_hierarchical:
                            date_val, pt = gk
                            subset = c_df[(c_df[x_field] == date_val) & (c_df["point_name"] == pt)]["value"].dropna().tolist()
                        else:
                            subset = (c_df[c_df[x_field] == gk]["value"].dropna().tolist()
                                      if x_field else c_df["value"].dropna().tolist())
                        if subset:
                            c_data.append(subset)
                            c_pos.append(gi + offset)
                    if c_data:
                        col = COLORS[ci % len(COLORS)]
                        ax.boxplot(
                            c_data, positions=c_pos, widths=width * 0.86,
                            patch_artist=True, notch=False,
                            boxprops=dict(facecolor=col, alpha=0.72, linewidth=0.9),
                            medianprops=dict(color="#1A1A1A", linewidth=1.8),
                            whiskerprops=dict(linewidth=0.8, color="#666"),
                            capprops=dict(linewidth=0.8, color="#666"),
                            flierprops=dict(marker=".", markersize=3.5, alpha=0.5, color=col),
                        )
                        if ri == 0:
                            ax.plot([], [], color=col, label=str(cval)[:22],
                                    linewidth=8, alpha=0.72)
                        
                        # 均值连线
                        if use_hierarchical:
                            import collections
                            seg_by_group = collections.OrderedDict()
                            for gi, gk in enumerate(group_keys):
                                dv, pt = gk
                                subset = c_df[(c_df[x_field] == dv) & (c_df["point_name"] == pt)]["value"].dropna().tolist()
                                if subset:
                                    if dv not in seg_by_group:
                                        seg_by_group[dv] = {'positions': [], 'values': []}
                                    seg_by_group[dv]['positions'].append(gi + offset)
                                    seg_by_group[dv]['values'].append(np.mean(subset))
                            for dv, seg in seg_by_group.items():
                                if len(seg['positions']) >= 2:
                                    ax.plot(seg['positions'], seg['values'],
                                            color=col, linewidth=1.8, alpha=0.78,
                                            marker="D", markersize=4.5)
                        else:
                            c_mean_items = []
                            for gi, gk in enumerate(group_keys):
                                subset = (c_df[c_df[x_field] == gk]["value"].dropna().tolist()
                                          if x_field else c_df["value"].dropna().tolist())
                                if subset:
                                    c_mean_items.append(
                                        (gi + offset, np.mean(subset), x_labels[gi], None))
                            self._ort_plot_mean_line_segments(
                                ax, c_mean_items, color=col, linestyle="-", linewidth=1.8,
                                marker="D", markersize=4.5, break_by_prefix=True,
                            )
                c_lbl = self._ort_group_dimension_label(color_field)
                if ri == 0:
                    ax.legend(title=c_lbl, loc="best", fontsize=8, frameon=False, title_fontsize=8)
            else:
                data_per_group = []
                valid_pos = []
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = sub_df[(sub_df[x_field] == date_val) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                    else:
                        subset = (sub_df[sub_df[x_field] == gk]["value"].dropna().tolist()
                                  if x_field else sub_df["value"].dropna().tolist())
                    if subset:
                        data_per_group.append(subset)
                        valid_pos.append(gi)
                
                mean_data = []
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = sub_df[(sub_df[x_field] == date_val) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                    else:
                        subset = (sub_df[sub_df[x_field] == gk]["value"].dropna().tolist()
                                  if x_field else sub_df["value"].dropna().tolist())
                    if subset:
                        mean_data.append((gi, np.mean(subset), x_labels[gi]))
                
                if data_per_group:
                    ax.boxplot(
                        data_per_group, positions=valid_pos,
                        widths=max(0.3, min(0.6, 4.0 / max(len(valid_pos), 1))),
                        patch_artist=True, notch=False,
                        boxprops=dict(facecolor="#A8C8E0", alpha=0.82, linewidth=0.9),
                        medianprops=dict(color="#3A5A7A", linewidth=2.0),
                        whiskerprops=dict(linewidth=0.8, color="#5B9BD5"),
                        capprops=dict(linewidth=0.8, color="#5B9BD5"),
                        flierprops=dict(marker=".", markersize=3.5, alpha=0.5, color="#5B9BD5"),
                    )
                
                # 均值连线
                if use_hierarchical:
                    hier_mean_items = []
                    for gi, gk in enumerate(group_keys):
                        dv, pt = gk
                        subset = sub_df[(sub_df[x_field] == dv) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                        if subset:
                            hier_mean_items.append((gi, np.mean(subset), str(pt), dv))
                    self._ort_plot_mean_line_segments(ax, hier_mean_items, break_by_key=True)
                else:
                    flat = [(p, v, lb, None) for p, v, lb in mean_data]
                    self._ort_plot_mean_line_segments(ax, flat, break_by_prefix=True)

            ax.set_xticks(range(n_groups))
            if is_last_row:
                if not use_hierarchical:
                    _rot, _ha = self._ort_point_xtick_style(n_groups)
                    ax.set_xticklabels(
                        x_labels, fontsize=7 if _rot == 90 else 8, rotation=_rot, ha=_ha)
                    if _rot == 90:
                        ax.tick_params(axis="x", pad=12)
            else:
                ax.set_xticklabels([])

            if is_last_row and use_hierarchical and hierarchical_info:
                self._ort_apply_hierarchical_xlabels(ax, fig, group_keys, hierarchical_info)

            # ── LSL / USL 参考线 ──
            lsl_med = df["lsl"].dropna().median() if df["lsl"].notna().any() else None
            usl_med = df["usl"].dropna().median() if df["usl"].notna().any() else None
            if lsl_med is not None and np.isfinite(lsl_med):
                ax.axhline(lsl_med, color="#EF4444", linestyle="--", linewidth=1.0,
                           alpha=0.85, label=f"LSL={lsl_med:.3g}")
            if usl_med is not None and np.isfinite(usl_med):
                ax.axhline(usl_med, color="#F59E0B", linestyle="--", linewidth=1.0,
                           alpha=0.85, label=f"USL={usl_med:.3g}")
            if ri == 0 and (lsl_med is not None or usl_med is not None):
                ax.legend(loc="best", fontsize=8, frameon=False)

            # ── 右侧分组面板标牌 (JMP 风格) ──
            if y_vals:
                ax.text(
                    1.015, 0.5, str(y_val),
                    transform=ax.transAxes,
                    rotation=270,
                    va='center', ha='left',
                    fontsize=9, fontweight='bold', color='#3A5A7A',
                    bbox=dict(boxstyle='square,pad=0.5', facecolor='#E8F1F8', edgecolor='#B8D4E8', alpha=1.0)
                )

            if ri == 0:
                ax.set_title(chart_title, fontsize=12, color="#2C3E50", pad=8)
            
            if is_last_row and not (use_hierarchical and hierarchical_info):
                x_lbl = self._ort_group_dimension_label(x_field) if x_field else "全部"
                ax.set_xlabel(x_lbl if x_field else "", fontsize=10)
            
            ax.set_ylabel(point_name, fontsize=10)
            ax.grid(True, axis="y", linestyle="--", linewidth=0.5, alpha=0.22)
            ax.tick_params(axis="y", labelsize=8)

        # ── 最右侧分类标志 (JMP 风格) ──
        if y_vals:
            y_lbl = self._ort_group_dimension_label(y_field)
            fig.text(
                0.97, 0.5, y_lbl,
                rotation=270,
                va='center', ha='center',
                fontsize=10, fontweight='bold', color='#5B9BD5'
            )

        # ── 调整布局边距 ──
        bottom = 0.16 if use_hierarchical else 0.10
        if y_vals:
            fig.tight_layout(pad=1.2, rect=[0, bottom, 0.90, 0.92])
        else:
            if not (use_hierarchical and hierarchical_info):
                if n_groups > 6:
                    fig.tight_layout(pad=1.2, rect=[0, 0.08, 1, 0.92])
                else:
                    fig.tight_layout(pad=1.2)
        return fig

    # ── 折线图（每笔数据一根线） ──

    def _build_ort_linechart_figure(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str = "",
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        figsize=(10.6, 5.4),
        dpi=110,
        chart_title_override: str = "",
    ):
        """生成 ORT 折线图：每笔数据（每个barcode）一根线
        
        Args:
            chart_title_override: 可选，覆盖默认的图表标题"""
        COLORS = ["#2F80ED", "#E63946", "#2DC653", "#F4A261", "#A8DADC",
                  "#457B9D", "#E9C46A", "#264653", "#9B5DE5", "#00B4D8"]

        df = raw_df.copy()
        df["value"] = pd.to_numeric(df.get("value"), errors="coerce")
        df["lsl"]   = pd.to_numeric(df.get("lsl"),   errors="coerce")
        df["usl"]   = pd.to_numeric(df.get("usl"),   errors="coerce")
        df = df.dropna(subset=["value"])

        y_vals = []
        if y_field and y_field in df.columns:
            y_vals = sorted(df[y_field].dropna().unique().tolist(), key=str)

        # ── 创建画布 ──
        fig = Figure(figsize=figsize, dpi=dpi)
        fig.patch.set_facecolor("#FFFFFF")

        if df.empty:
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FAFAFA")
            ax.text(0.5, 0.5, "暂无数据", ha="center", va="center",
                    transform=ax.transAxes, fontsize=14, color="#9A8A78")
            return fig

        # ── 确定 X 轴分组 ──
        has_point_level = "point_name" in df.columns and df["point_name"].nunique() > 1
        use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, df)
        
        if use_hierarchical:
            point_vals = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            date_vals = sorted(df[x_field].dropna().unique().tolist(), key=str)
            
            group_keys = []
            x_labels = []
            for date_val in date_vals:
                for pt in point_vals:
                    subset = df[(df[x_field] == date_val) & (df["point_name"] == pt)]["value"].dropna().tolist()
                    if subset:
                        group_keys.append((date_val, pt))
                        x_labels.append(str(pt))
            
            n_groups = len(group_keys)
            hierarchical_info = {
                'date_vals': date_vals,
                'point_vals': point_vals,
                'x_field_label': self._ort_group_dimension_label(x_field),
            }
        elif x_field and x_field in df.columns:
            group_keys = sorted(df[x_field].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
        elif has_point_level:
            group_keys = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
            x_field = "point_name"
        else:
            group_keys = ["全部"]
            x_labels = ["全部"]
            n_groups = 1
            use_hierarchical = False
            hierarchical_info = None
            x_field = ""

        x_ticks = list(range(len(group_keys)))
        x_lbl = self._ort_group_dimension_label(x_field) if x_field else "点位"

        # 按 barcode 分组，每笔数据一根线
        MAX_LINES = 50
        barcodes = df.get("barcode", pd.Series()).dropna().unique().tolist()
        if len(barcodes) > MAX_LINES:
            import random
            random.seed(42)
            barcodes = random.sample(barcodes, MAX_LINES)

        # ── 构建标题 ──
        if chart_title_override:
            chart_title = chart_title_override
        else:
            product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
            subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
            recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
            subpart_str = subparts[0] if len(subparts) == 1 else (f"{len(subparts)}个小件" if subparts else "")
            recipe_str = recipes[0] if len(recipes) == 1 else (f"{len(recipes)}个配方" if recipes else "")
            
            title_parts = [p for p in [product_name, subpart_str, recipe_str] if p]
            chart_title = "-".join(title_parts) + " · 折线图" if title_parts else f"{product_name} · 折线图"

        # ── 创建垂直多子图 (JMP 风格) ──
        if y_vals:
            nrows = len(y_vals)
            figsize = (figsize[0], 2.2 * nrows + 1.2)
            fig.set_size_inches(figsize[0], figsize[1])
            axes = fig.subplots(nrows, 1, sharex=True, sharey=True, squeeze=False)
        else:
            nrows = 1
            axes = None

        # ── 遍历子图绘制数据 ──
        for ri in range(nrows):
            if y_vals:
                ax = axes[ri, 0]
                y_val = y_vals[ri]
                sub_df = df[df[y_field] == y_val]
            else:
                ax = fig.add_subplot(111)
                y_val = None
                sub_df = df
            
            ax.set_facecolor("#FAFAFA")
            is_last_row = (ri == nrows - 1)

            # 为每个 barcode 绘制一条线
            import re
            for bi, barcode in enumerate(barcodes[:MAX_LINES]):
                b_df = sub_df[sub_df.get("barcode") == barcode]
                if b_df.empty:
                    continue
                
                current_date = None
                segment_positions = []
                segment_values = []
                
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        group_id = str(date_val)
                    else:
                        match = re.match(r'^([A-Za-z]+)', str(gk))
                        group_id = match.group(1) if match else '其他'
                    
                    if current_date is not None and group_id != current_date:
                        if len(segment_values) >= 2:
                            c = COLORS[bi % len(COLORS)]
                            ax.plot(segment_positions, segment_values, color=c, marker="o", 
                                    linewidth=1.2, markersize=3, alpha=0.6)
                        elif len(segment_values) == 1:
                            c = COLORS[bi % len(COLORS)]
                            ax.plot(segment_positions, segment_values, color=c, marker="o", 
                                    markersize=3, alpha=0.6)
                        segment_positions = []
                        segment_values = []
                    
                    current_date = group_id
                    
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = b_df[(b_df[x_field] == date_val) & (b_df["point_name"] == pt)]["value"].dropna().tolist()
                    elif x_field:
                        subset = b_df[b_df[x_field] == gk]["value"].dropna().tolist()
                    else:
                        subset = b_df["value"].dropna().tolist()
                    if subset:
                        segment_values.append(subset[0])
                        segment_positions.append(gi)
                
                # 绘制最后一段
                if len(segment_values) >= 2:
                    c = COLORS[bi % len(COLORS)]
                    ax.plot(segment_positions, segment_values, color=c, marker="o", 
                            linewidth=1.2, markersize=3, alpha=0.6)
                elif len(segment_values) == 1:
                    c = COLORS[bi % len(COLORS)]
                    ax.plot(segment_positions, segment_values, color=c, marker="o", 
                            markersize=3, alpha=0.6)

            ax.set_xticks(x_ticks)
            if is_last_row:
                if not use_hierarchical:
                    ax.set_xticklabels([str(k)[:24] for k in group_keys],
                                       fontsize=8, rotation=22, ha="right")
                    ax.set_xlabel(x_lbl, fontsize=10)
            else:
                ax.set_xticklabels([])

            # LSL / USL 参考线
            lsl_med = df["lsl"].dropna().median() if df["lsl"].notna().any() else None
            usl_med = df["usl"].dropna().median() if df["usl"].notna().any() else None
            if lsl_med is not None and np.isfinite(lsl_med):
                ax.axhline(lsl_med, color="#EF4444", linestyle="--",
                           linewidth=1.0, alpha=0.85, label=f"LSL={lsl_med:.3g}")
            if usl_med is not None and np.isfinite(usl_med):
                ax.axhline(usl_med, color="#F59E0B", linestyle="--",
                           linewidth=1.0, alpha=0.85, label=f"USL={usl_med:.3g}")
            if ri == 0 and (lsl_med is not None or usl_med is not None):
                ax.legend(loc="best", fontsize=8, frameon=False)

            # ── 右侧分组面板标牌 (JMP 风格) ──
            if y_vals:
                ax.text(
                    1.015, 0.5, str(y_val),
                    transform=ax.transAxes,
                    rotation=270,
                    va='center', ha='left',
                    fontsize=9, fontweight='bold', color='#3A5A7A',
                    bbox=dict(boxstyle='square,pad=0.5', facecolor='#E8F1F8', edgecolor='#B8D4E8', alpha=1.0)
                )

            # ── 层级标签（X分组+点位双层标签）──
            if is_last_row and use_hierarchical and hierarchical_info:
                date_vals = hierarchical_info['date_vals']
                x_field_label = hierarchical_info.get('x_field_label', '')
                
                grp_positions = {}
                for gi, gk in enumerate(group_keys):
                    dv, pt = gk
                    if dv not in grp_positions:
                        grp_positions[dv] = []
                    grp_positions[dv].append(gi)
                
                date_positions = []
                date_labels_list = []
                for date_val in date_vals:
                    if date_val in grp_positions and grp_positions[date_val]:
                        pos_list = grp_positions[date_val]
                        mid_idx = (pos_list[0] + pos_list[-1]) / 2.0
                        date_positions.append(mid_idx)
                        date_labels_list.append(str(date_val))
                
                point_labels_full = [str(pt) for _, pt in group_keys]
                ax.set_xticklabels(point_labels_full, fontsize=8, rotation=90, ha="center")
                ax.tick_params(axis='x', pad=38)
                ax.set_xlabel("")
                
                xlim = ax.get_xlim()
                ax_width = xlim[1] - xlim[0]
                for pos, label in zip(date_positions, date_labels_list):
                    x_norm = (pos - xlim[0]) / ax_width
                    ax.text(x_norm, -0.15, label,
                            fontsize=9, ha='center', va='top',
                            transform=ax.transAxes, color='#333333')
                if x_field_label:
                    ax.text(1.0, -0.15, x_field_label,
                            fontsize=8, ha='right', va='top',
                            transform=ax.transAxes, color='#888888', style='italic')

            ax.set_ylabel(point_name, fontsize=10)
            if ri == 0:
                ax.set_title(chart_title, fontsize=12, color="#2C3E50", pad=8)
            ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.22)
            ax.tick_params(axis="y", labelsize=8)

        # ── 最右侧分类标志 (JMP 风格) ──
        if y_vals:
            y_lbl = self._ort_group_dimension_label(y_field)
            fig.text(
                0.97, 0.5, y_lbl,
                rotation=270,
                va='center', ha='center',
                fontsize=10, fontweight='bold', color='#5B9BD5'
            )

        # ── 调整布局边距 ──
        bottom = 0.16 if use_hierarchical else 0.10
        if y_vals:
            fig.tight_layout(pad=1.2, rect=[0, bottom, 0.90, 0.92])
        else:
            if use_hierarchical and hierarchical_info:
                fig.tight_layout(pad=1.2, rect=[0, 0.08, 1, 0.92])
            else:
                fig.tight_layout(pad=1.2)
        return fig

    def _build_ort_boxplot_figure_single_recipe(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str,
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        single_recipe: str = "",
        figsize=(9.4, 4.8),
        dpi=100,
    ):
        """单配方版本的箱线图生成（用于多配方模式下的每个配方图形）"""
        COLORS = ["#2F80ED", "#E63946", "#2DC653", "#F4A261", "#A8DADC",
                  "#457B9D", "#E9C46A", "#264653", "#9B5DE5", "#00B4D8"]

        df = raw_df.copy()
        df["value"] = pd.to_numeric(df.get("value"), errors="coerce")
        df["lsl"]   = pd.to_numeric(df.get("lsl"),   errors="coerce")
        df["usl"]   = pd.to_numeric(df.get("usl"),   errors="coerce")
        df = df.dropna(subset=["value"])

        y_vals = []
        if y_field and y_field in df.columns:
            y_vals = sorted(df[y_field].dropna().unique().tolist(), key=str)

        # ── 创建画布 ──
        fig = Figure(figsize=figsize, dpi=dpi)
        fig.patch.set_facecolor("#FFFFFF")

        if df.empty:
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FAFAFA")
            ax.text(0.5, 0.5, "暂无数据", ha="center", va="center",
                    transform=ax.transAxes, fontsize=14, color="#9A8A78")
            return fig

        # ── 确定 X 轴分组 ──
        has_point_level = "point_name" in df.columns and df["point_name"].nunique() > 1
        use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, df)
        
        if use_hierarchical:
            point_vals = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            date_vals = sorted(df[x_field].dropna().unique().tolist(), key=str)
            
            group_keys = []
            x_labels = []
            for date_val in date_vals:
                for pt in point_vals:
                    subset = df[(df[x_field] == date_val) & (df["point_name"] == pt)]["value"].dropna().tolist()
                    if subset:
                        group_keys.append((date_val, pt))
                        x_labels.append(str(pt))
            
            n_groups = len(group_keys)
            hierarchical_info = {
                'date_vals': date_vals,
                'point_vals': point_vals,
                'x_field_label': self._ort_group_dimension_label(x_field),
            }
        elif x_field and x_field in df.columns:
            group_keys = sorted(df[x_field].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
        elif has_point_level:
            group_keys = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
            x_field = "point_name"
        else:
            group_keys = ["全部"]
            x_labels = ["全部"]
            n_groups = 1
            use_hierarchical = False
            hierarchical_info = None
            x_field = ""

        # ── 颜色分组 ──
        if color_field and color_field in df.columns:
            color_vals = sorted(df[color_field].dropna().unique().tolist(), key=str)
            n_c = len(color_vals)
            width = 0.72 / max(n_c, 1)
            offsets = np.linspace(-(n_c - 1) * width / 2, (n_c - 1) * width / 2, n_c)
        else:
            color_vals = []

        # ── 构建标题 ──
        product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
        subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
        subpart_str = subparts[0] if len(subparts) == 1 else (f"{len(subparts)}个小件" if subparts else "")
        
        title_parts = [p for p in [product_name, subpart_str, single_recipe] if p]
        chart_title = "-".join(title_parts) + " · 箱线图" if title_parts else f"{product_name} · 箱线图"

        # ── 创建垂直多子图 (JMP 风格) ──
        if y_vals:
            nrows = len(y_vals)
            figsize = (figsize[0], 2.2 * nrows + 1.2)
            fig.set_size_inches(figsize[0], figsize[1])
            axes = fig.subplots(nrows, 1, sharex=True, sharey=True, squeeze=False)
        else:
            nrows = 1
            axes = None

        # ── 遍历子图绘制数据 ──
        for ri in range(nrows):
            if y_vals:
                ax = axes[ri, 0]
                y_val = y_vals[ri]
                sub_df = df[df[y_field] == y_val]
            else:
                ax = fig.add_subplot(111)
                y_val = None
                sub_df = df
            
            ax.set_facecolor("#FAFAFA")
            is_last_row = (ri == nrows - 1)

            if color_vals:
                for ci, (cval, offset) in enumerate(zip(color_vals, offsets)):
                    c_df = sub_df[sub_df[color_field] == cval]
                    c_data = []
                    c_pos  = []
                    for gi, gk in enumerate(group_keys):
                        if use_hierarchical:
                            dv, pt = gk
                            subset = c_df[(c_df[x_field] == dv) & (c_df["point_name"] == pt)]["value"].dropna().tolist()
                        else:
                            subset = (c_df[c_df[x_field] == gk]["value"].dropna().tolist()
                                      if x_field else c_df["value"].dropna().tolist())
                        if subset:
                            c_data.append(subset)
                            c_pos.append(gi + offset)
                    if c_data:
                        col = COLORS[ci % len(COLORS)]
                        ax.boxplot(
                            c_data, positions=c_pos, widths=width * 0.86,
                            patch_artist=True, notch=False,
                            boxprops=dict(facecolor=col, alpha=0.72, linewidth=0.9),
                            medianprops=dict(color="#1A1A1A", linewidth=1.8),
                            whiskerprops=dict(linewidth=0.8, color="#666"),
                            capprops=dict(linewidth=0.8, color="#666"),
                            flierprops=dict(marker=".", markersize=3.5, alpha=0.5, color=col),
                        )
                        if ri == 0:
                            ax.plot([], [], color=col, label=str(cval)[:22],
                                    linewidth=8, alpha=0.72)
                        
                        # 均值连线
                        if use_hierarchical:
                            import collections
                            seg_by_group = collections.OrderedDict()
                            for gi, gk in enumerate(group_keys):
                                dv, pt = gk
                                subset = c_df[(c_df[x_field] == dv) & (c_df["point_name"] == pt)]["value"].dropna().tolist()
                                if subset:
                                    if dv not in seg_by_group:
                                        seg_by_group[dv] = {'positions': [], 'values': []}
                                    seg_by_group[dv]['positions'].append(gi + offset)
                                    seg_by_group[dv]['values'].append(np.mean(subset))
                            for dv, seg in seg_by_group.items():
                                if len(seg['positions']) >= 2:
                                    ax.plot(seg['positions'], seg['values'],
                                            color=col, linewidth=1.8, alpha=0.78,
                                            marker="D", markersize=4.5)
                        else:
                            c_mean_items = []
                            for gi, gk in enumerate(group_keys):
                                subset = (c_df[c_df[x_field] == gk]["value"].dropna().tolist()
                                          if x_field else c_df["value"].dropna().tolist())
                                if subset:
                                    c_mean_items.append(
                                        (gi + offset, np.mean(subset), x_labels[gi], None))
                            self._ort_plot_mean_line_segments(
                                ax, c_mean_items, color=col, linestyle="-", linewidth=1.8,
                                marker="D", markersize=4.5, break_by_prefix=True,
                            )
                c_lbl = self._ort_group_dimension_label(color_field)
                if ri == 0:
                    ax.legend(title=c_lbl, loc="best", fontsize=8, frameon=False, title_fontsize=8)
            else:
                data_per_group = []
                valid_pos = []
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = sub_df[(sub_df[x_field] == date_val) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                    else:
                        subset = (sub_df[sub_df[x_field] == gk]["value"].dropna().tolist()
                                  if x_field else sub_df["value"].dropna().tolist())
                    if subset:
                        data_per_group.append(subset)
                        valid_pos.append(gi)
                
                mean_data = []
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = sub_df[(sub_df[x_field] == date_val) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                    else:
                        subset = (sub_df[sub_df[x_field] == gk]["value"].dropna().tolist()
                                  if x_field else sub_df["value"].dropna().tolist())
                    if subset:
                        mean_data.append((gi, np.mean(subset), x_labels[gi]))
                
                if data_per_group:
                    ax.boxplot(
                        data_per_group, positions=valid_pos,
                        widths=max(0.3, min(0.6, 4.0 / max(len(valid_pos), 1))),
                        patch_artist=True, notch=False,
                        boxprops=dict(facecolor="#A8C8E0", alpha=0.82, linewidth=0.9),
                        medianprops=dict(color="#3A5A7A", linewidth=2.0),
                        whiskerprops=dict(linewidth=0.8, color="#5B9BD5"),
                        capprops=dict(linewidth=0.8, color="#5B9BD5"),
                        flierprops=dict(marker=".", markersize=3.5, alpha=0.5, color="#5B9BD5"),
                    )
                
                # 均值连线
                if use_hierarchical:
                    hier_mean_items = []
                    for gi, gk in enumerate(group_keys):
                        dv, pt = gk
                        subset = sub_df[(sub_df[x_field] == dv) & (sub_df["point_name"] == pt)]["value"].dropna().tolist()
                        if subset:
                            hier_mean_items.append((gi, np.mean(subset), str(pt), dv))
                    self._ort_plot_mean_line_segments(ax, hier_mean_items, break_by_key=True)
                else:
                    flat = [(p, v, lb, None) for p, v, lb in mean_data]
                    self._ort_plot_mean_line_segments(ax, flat, break_by_prefix=True)

            ax.set_xticks(range(n_groups))
            if is_last_row:
                if not use_hierarchical:
                    _rot, _ha = self._ort_point_xtick_style(n_groups)
                    ax.set_xticklabels(
                        x_labels, fontsize=7 if _rot == 90 else 8, rotation=_rot, ha=_ha)
                    if _rot == 90:
                        ax.tick_params(axis="x", pad=12)
            else:
                ax.set_xticklabels([])

            if is_last_row and use_hierarchical and hierarchical_info:
                self._ort_apply_hierarchical_xlabels(ax, fig, group_keys, hierarchical_info)

            # ── LSL / USL 参考线 ──
            lsl_med = df["lsl"].dropna().median() if df["lsl"].notna().any() else None
            usl_med = df["usl"].dropna().median() if df["usl"].notna().any() else None
            if lsl_med is not None and np.isfinite(lsl_med):
                ax.axhline(lsl_med, color="#EF4444", linestyle="--", linewidth=1.0,
                           alpha=0.85, label=f"LSL={lsl_med:.3g}")
            if usl_med is not None and np.isfinite(usl_med):
                ax.axhline(usl_med, color="#F59E0B", linestyle="--", linewidth=1.0,
                           alpha=0.85, label=f"USL={usl_med:.3g}")
            if ri == 0 and (lsl_med is not None or usl_med is not None):
                ax.legend(loc="best", fontsize=8, frameon=False)

            # ── 右侧分组面板标牌 (JMP 风格) ──
            if y_vals:
                ax.text(
                    1.015, 0.5, str(y_val),
                    transform=ax.transAxes,
                    rotation=270,
                    va='center', ha='left',
                    fontsize=9, fontweight='bold', color='#3A5A7A',
                    bbox=dict(boxstyle='square,pad=0.5', facecolor='#E8F1F8', edgecolor='#B8D4E8', alpha=1.0)
                )

            if ri == 0:
                ax.set_title(chart_title, fontsize=12, color="#2C3E50", pad=8)
            
            if is_last_row and not (use_hierarchical and hierarchical_info):
                x_lbl = self._ort_group_dimension_label(x_field) if x_field else "全部"
                ax.set_xlabel(x_lbl if x_field else "", fontsize=10)
            
            ax.set_ylabel(point_name, fontsize=10)
            ax.grid(True, axis="y", linestyle="--", linewidth=0.5, alpha=0.22)
            ax.tick_params(axis="y", labelsize=8)

        # ── 最右侧分类标志 (JMP 风格) ──
        if y_vals:
            y_lbl = self._ort_group_dimension_label(y_field)
            fig.text(
                0.97, 0.5, y_lbl,
                rotation=270,
                va='center', ha='center',
                fontsize=10, fontweight='bold', color='#5B9BD5'
            )

        # ── 调整布局边距 ──
        bottom = 0.16 if use_hierarchical else 0.10
        if y_vals:
            fig.tight_layout(pad=1.2, rect=[0, bottom, 0.90, 0.92])
        else:
            if not (use_hierarchical and hierarchical_info):
                if n_groups > 6:
                    fig.tight_layout(pad=1.2, rect=[0, 0.08, 1, 0.92])
                else:
                    fig.tight_layout(pad=1.2)
        return fig

    def _build_ort_linechart_figure_single_recipe(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str,
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        single_recipe: str = "",
        figsize=(9.4, 4.8),
        dpi=100,
    ):
        """单配方版本的折线图生成（用于多配方模式下的每个配方图形），每笔数据一根线"""
        COLORS = ["#2F80ED", "#E63946", "#2DC653", "#F4A261", "#A8DADC",
                  "#457B9D", "#E9C46A", "#264653", "#9B5DE5", "#00B4D8"]

        df = raw_df.copy()
        df["value"] = pd.to_numeric(df.get("value"), errors="coerce")
        df["lsl"]   = pd.to_numeric(df.get("lsl"),   errors="coerce")
        df["usl"]   = pd.to_numeric(df.get("usl"),   errors="coerce")
        df = df.dropna(subset=["value"])

        y_vals = []
        if y_field and y_field in df.columns:
            y_vals = sorted(df[y_field].dropna().unique().tolist(), key=str)

        # ── 创建画布 ──
        fig = Figure(figsize=figsize, dpi=dpi)
        fig.patch.set_facecolor("#FFFFFF")

        if df.empty:
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FAFAFA")
            ax.text(0.5, 0.5, "暂无数据", ha="center", va="center",
                    transform=ax.transAxes, fontsize=14, color="#9A8A78")
            return fig

        # ── 确定 X 轴分组 ──
        has_point_level = "point_name" in df.columns and df["point_name"].nunique() > 1
        use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, df)
        
        if use_hierarchical:
            point_vals = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            date_vals = sorted(df[x_field].dropna().unique().tolist(), key=str)
            
            group_keys = []
            x_labels = []
            for date_val in date_vals:
                for pt in point_vals:
                    subset = df[(df[x_field] == date_val) & (df["point_name"] == pt)]["value"].dropna().tolist()
                    if subset:
                        group_keys.append((date_val, pt))
                        x_labels.append(str(pt))
            
            n_groups = len(group_keys)
            hierarchical_info = {
                'date_vals': date_vals,
                'point_vals': point_vals,
                'x_field_label': self._ort_group_dimension_label(x_field),
            }
        elif x_field and x_field in df.columns:
            group_keys = sorted(df[x_field].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
        elif has_point_level:
            group_keys = sorted(df["point_name"].dropna().unique().tolist(), key=str)
            x_labels = [str(k)[:24] for k in group_keys]
            n_groups = len(group_keys)
            use_hierarchical = False
            hierarchical_info = None
            x_field = "point_name"
        else:
            group_keys = ["全部"]
            x_labels = ["全部"]
            n_groups = 1
            use_hierarchical = False
            hierarchical_info = None
            x_field = ""

        x_ticks = list(range(len(group_keys)))
        x_lbl = self._ort_group_dimension_label(x_field) if x_field else "点位"

        # 按 barcode 分组，每笔数据一根线
        MAX_LINES = 50
        barcodes = df.get("barcode", pd.Series()).dropna().unique().tolist()
        if len(barcodes) > MAX_LINES:
            import random
            random.seed(42)
            barcodes = random.sample(barcodes, MAX_LINES)

        # ── 构建标题 ──
        product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
        subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
        subpart_str = subparts[0] if len(subparts) == 1 else (f"{len(subparts)}个小件" if subparts else "")
        
        title_parts = [p for p in [product_name, subpart_str, single_recipe] if p]
        chart_title = "-".join(title_parts) + " · 折线图" if title_parts else f"{product_name} · 折线图"

        # ── 创建垂直多子图 (JMP 风格) ──
        if y_vals:
            nrows = len(y_vals)
            figsize = (figsize[0], 2.2 * nrows + 1.2)
            fig.set_size_inches(figsize[0], figsize[1])
            axes = fig.subplots(nrows, 1, sharex=True, sharey=True, squeeze=False)
        else:
            nrows = 1
            axes = None

        # ── 遍历子图绘制数据 ──
        for ri in range(nrows):
            if y_vals:
                ax = axes[ri, 0]
                y_val = y_vals[ri]
                sub_df = df[df[y_field] == y_val]
            else:
                ax = fig.add_subplot(111)
                y_val = None
                sub_df = df
            
            ax.set_facecolor("#FAFAFA")
            is_last_row = (ri == nrows - 1)

            # 为每个 barcode 绘制一条线
            import re
            for bi, barcode in enumerate(barcodes[:MAX_LINES]):
                b_df = sub_df[sub_df.get("barcode") == barcode]
                if b_df.empty:
                    continue
                
                current_date = None
                segment_positions = []
                segment_values = []
                
                for gi, gk in enumerate(group_keys):
                    if use_hierarchical:
                        date_val, pt = gk
                        group_id = str(date_val)
                    else:
                        match = re.match(r'^([A-Za-z]+)', str(gk))
                        group_id = match.group(1) if match else '其他'
                    
                    if current_date is not None and group_id != current_date:
                        if len(segment_values) >= 2:
                            c = COLORS[bi % len(COLORS)]
                            ax.plot(segment_positions, segment_values, color=c, marker="o", 
                                    linewidth=1.2, markersize=3, alpha=0.6)
                        elif len(segment_values) == 1:
                            c = COLORS[bi % len(COLORS)]
                            ax.plot(segment_positions, segment_values, color=c, marker="o", 
                                    markersize=3, alpha=0.6)
                        segment_positions = []
                        segment_values = []
                    
                    current_date = group_id
                    
                    if use_hierarchical:
                        date_val, pt = gk
                        subset = b_df[(b_df[x_field] == date_val) & (b_df["point_name"] == pt)]["value"].dropna().tolist()
                    elif x_field:
                        subset = b_df[b_df[x_field] == gk]["value"].dropna().tolist()
                    else:
                        subset = b_df["value"].dropna().tolist()
                    if subset:
                        segment_values.append(subset[0])
                        segment_positions.append(gi)
                
                # 绘制最后一段
                if len(segment_values) >= 2:
                    c = COLORS[bi % len(COLORS)]
                    ax.plot(segment_positions, segment_values, color=c, marker="o", 
                            linewidth=1.2, markersize=3, alpha=0.6)
                elif len(segment_values) == 1:
                    c = COLORS[bi % len(COLORS)]
                    ax.plot(segment_positions, segment_values, color=c, marker="o", 
                            markersize=3, alpha=0.6)

            ax.set_xticks(x_ticks)
            if is_last_row:
                if not use_hierarchical:
                    ax.set_xticklabels([str(k)[:24] for k in group_keys],
                                       fontsize=8, rotation=22, ha="right")
                    ax.set_xlabel(x_lbl, fontsize=10)
            else:
                ax.set_xticklabels([])

            # LSL / USL 参考线
            lsl_med = df["lsl"].dropna().median() if df["lsl"].notna().any() else None
            usl_med = df["usl"].dropna().median() if df["usl"].notna().any() else None
            if lsl_med is not None and np.isfinite(lsl_med):
                ax.axhline(lsl_med, color="#EF4444", linestyle="--",
                           linewidth=1.0, alpha=0.85, label=f"LSL={lsl_med:.3g}")
            if usl_med is not None and np.isfinite(usl_med):
                ax.axhline(usl_med, color="#F59E0B", linestyle="--",
                           linewidth=1.0, alpha=0.85, label=f"USL={usl_med:.3g}")
            if ri == 0 and (lsl_med is not None or usl_med is not None):
                ax.legend(loc="best", fontsize=8, frameon=False)

            # ── 右侧分组面板标牌 (JMP 风格) ──
            if y_vals:
                ax.text(
                    1.015, 0.5, str(y_val),
                    transform=ax.transAxes,
                    rotation=270,
                    va='center', ha='left',
                    fontsize=9, fontweight='bold', color='#3A5A7A',
                    bbox=dict(boxstyle='square,pad=0.5', facecolor='#E8F1F8', edgecolor='#B8D4E8', alpha=1.0)
                )

            # ── 层级标签（X分组+点位双层标签）──
            if is_last_row and use_hierarchical and hierarchical_info:
                date_vals = hierarchical_info['date_vals']
                x_field_label = hierarchical_info.get('x_field_label', '')
                
                grp_positions = {}
                for gi, gk in enumerate(group_keys):
                    dv, pt = gk
                    if dv not in grp_positions:
                        grp_positions[dv] = []
                    grp_positions[dv].append(gi)
                
                date_positions = []
                date_labels_list = []
                for date_val in date_vals:
                    if date_val in grp_positions and grp_positions[date_val]:
                        pos_list = grp_positions[date_val]
                        mid_idx = (pos_list[0] + pos_list[-1]) / 2.0
                        date_positions.append(mid_idx)
                        date_labels_list.append(str(date_val))
                
                point_labels_full = [str(pt) for _, pt in group_keys]
                ax.set_xticklabels(point_labels_full, fontsize=8, rotation=90, ha="center")
                ax.tick_params(axis='x', pad=38)
                ax.set_xlabel("")
                
                xlim = ax.get_xlim()
                ax_width = xlim[1] - xlim[0]
                for pos, label in zip(date_positions, date_labels_list):
                    x_norm = (pos - xlim[0]) / ax_width
                    ax.text(x_norm, -0.15, label,
                            fontsize=9, ha='center', va='top',
                            transform=ax.transAxes, color='#333333')
                if x_field_label:
                    ax.text(1.0, -0.15, x_field_label,
                            fontsize=8, ha='right', va='top',
                            transform=ax.transAxes, color='#888888', style='italic')

            ax.set_ylabel(point_name, fontsize=10)
            if ri == 0:
                ax.set_title(chart_title, fontsize=12, color="#2C3E50", pad=8)
            ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.22)
            ax.tick_params(axis="y", labelsize=8)

        # ── 最右侧分类标志 (JMP 风格) ──
        if y_vals:
            y_lbl = self._ort_group_dimension_label(y_field)
            fig.text(
                0.97, 0.5, y_lbl,
                rotation=270,
                va='center', ha='center',
                fontsize=10, fontweight='bold', color='#5B9BD5'
            )

        # ── 调整布局边距 ──
        bottom = 0.16 if use_hierarchical else 0.10
        if y_vals:
            fig.tight_layout(pad=1.2, rect=[0, bottom, 0.90, 0.92])
        else:
            if use_hierarchical and hierarchical_info:
                fig.tight_layout(pad=1.2, rect=[0, 0.08, 1, 0.92])
            else:
                fig.tight_layout(pad=1.2)
        return fig

    def _render_ort_interactive_chart(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str,
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        chart_type: str = "boxplot",
    ):
        """将交互图渲染到 ort_chart_layout。"""
        self._clear_layout_widgets(self.ort_chart_layout)

        if raw_df is None or raw_df.empty:
            self._render_ort_placeholder("当前筛选条件下暂无数据库记录可作图。")
            return

        ct_label = "箱线图" if chart_type == "boxplot" else "均值折线图"
        self.ort_chart_label.setText(f"{point_name} · {ct_label}")

        # 信息卡
        info_card = QFrame()
        info_card.setStyleSheet(
            "QFrame { background-color:#F5F9FF; border:1px solid #C5D9E8; border-radius:14px; }"
        )
        info_lay = QVBoxLayout(info_card)
        info_lay.setContentsMargins(16, 14, 16, 14)
        info_lay.setSpacing(6)
        x_lbl = self._ort_group_dimension_label(x_field) if x_field else "不分组"
        y_lbl = self._ort_group_dimension_label(y_field) if y_field else "无"
        c_lbl = self._ort_group_dimension_label(color_field) if color_field else "无"
        title_lbl = QLabel(
            f"点位：{point_name}  ·  X轴分组：{x_lbl}  ·  Y轴分组：{y_lbl}  ·  颜色分组：{c_lbl}"
        )
        title_lbl.setStyleSheet("font-size:14px; font-weight:800; color:#2C3E50;")
        desc_lbl = QLabel(
            f"数据源：{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]}"
        )
        desc_lbl.setWordWrap(True)
        desc_lbl.setStyleSheet("font-size:12px; color:#5A7A99;")
        info_lay.addWidget(title_lbl)
        info_lay.addWidget(desc_lbl)

        # 图表卡
        chart_card = ClickableFrame()
        chart_card.setStyleSheet(
            "QFrame { background-color:#FFFFFF; border:1px solid #C5D9E8; border-radius:12px; }"
        )
        chart_card_lay = QVBoxLayout(chart_card)
        chart_card_lay.setContentsMargins(12, 12, 12, 12)

        if chart_type == "boxplot":
            fig_builder = lambda figsize=(9.4, 3.6), dpi=100: self._build_ort_boxplot_figure(
                point_name, raw_df, x_field, y_field, color_field, scope_triplet, figsize, dpi)
        else:
            fig_builder = lambda figsize=(9.4, 3.6), dpi=100: self._build_ort_linechart_figure(
                point_name, raw_df, x_field, y_field, color_field, scope_triplet, figsize, dpi)

        canvas = FigureCanvas(fig_builder())
        chart_card_lay.addWidget(canvas)
        chart_card.clicked.connect(
            lambda: ChartZoomDialog(f"{point_name} · {ct_label}", fig_builder, self).exec_()
        )

        self.ort_chart_layout.addWidget(info_card)
        self.ort_chart_layout.addWidget(chart_card, 1)
        self.ort_chart_layout.addStretch()

    def _render_ort_split_charts(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str,
        y_field: str,
        group_field: str,
        scope_triplet: tuple,
        chart_type: str = "boxplot",
    ):
        """按图形拆分分组字段将数据拆分为多个独立图形。
        若同时选中了多个配方，则先按配方分行，每行内再按 group_field 横向排列。"""
        self._clear_layout_widgets(self.ort_chart_layout)

        if raw_df is None or raw_df.empty or not group_field:
            self._render_ort_placeholder("当前筛选条件下暂无数据库记录可作图。")
            return

        ct_label = "箱线图" if chart_type == "boxplot" else "均值折线图"

        if group_field not in raw_df.columns:
            self._render_ort_placeholder(f"分组字段「{group_field}」不在数据中。")
            return

        group_vals = sorted(raw_df[group_field].dropna().unique().tolist(), key=str)
        if not group_vals:
            self._render_ort_placeholder("分组字段无有效值。")
            return

        selected_recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
        recipe_count = len(selected_recipes)
        has_multi_recipe = recipe_count > 1

        total_charts = len(group_vals) * (recipe_count if has_multi_recipe else 1)
        self.ort_chart_label.setText(
            f"{point_name} · {ct_label} · {total_charts}个图形"
            f"（{'按配方分行，' if has_multi_recipe else ''}按{self._ort_group_dimension_label(group_field)}拆分）"
        )

        # 信息卡
        info_card = QFrame()
        info_card.setStyleSheet(
            "QFrame { background-color:#F5F9FF; border:1px solid #C5D9E8; border-radius:14px; }"
        )
        info_lay = QVBoxLayout(info_card)
        info_lay.setContentsMargins(16, 14, 16, 14)
        info_lay.setSpacing(6)
        x_lbl = self._ort_group_dimension_label(x_field) if x_field else "点位"
        y_lbl = self._ort_group_dimension_label(y_field) if y_field else "无"
        title_lbl = QLabel(
            f"点位：{point_name}  ·  X轴分组：{x_lbl}  ·  Y轴分组：{y_lbl}  ·  图形拆分：{self._ort_group_dimension_label(group_field)}"
        )
        title_lbl.setStyleSheet("font-size:14px; font-weight:800; color:#2C3E50;")
        if has_multi_recipe:
            desc_lbl = QLabel(
                f"数据源：{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]}\n"
                f"共 {recipe_count} 个配方 × {len(group_vals)} 个{self._ort_group_dimension_label(group_field)} = {total_charts} 个图形，"
                f"按配方分行、每行按{self._ort_group_dimension_label(group_field)}横向排列"
            )
        else:
            desc_lbl = QLabel(
                f"数据源：{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]}\n"
                f"共 {len(group_vals)} 个分组，每个分组生成独立图形并横向排列"
            )
        desc_lbl.setWordWrap(True)
        desc_lbl.setStyleSheet("font-size:12px; color:#5A7A99;")
        info_lay.addWidget(title_lbl)
        info_lay.addWidget(desc_lbl)
        self.ort_chart_layout.addWidget(info_card)

        # ── 多配方时：每行为一个配方，行内横向排列图形拆分分组 ──
        if has_multi_recipe:
            for recipe in selected_recipes:
                recipe_df = raw_df[raw_df.get("recipe") == recipe] if "recipe" in raw_df.columns else raw_df
                if recipe_df.empty:
                    continue

                # 配方行标题
                recipe_title = QLabel(f"配方：{recipe}")
                recipe_title.setStyleSheet(
                    "font-size:13px; font-weight:700; color:#2C3E50; margin-top:8px;"
                )
                self.ort_chart_layout.addWidget(recipe_title)

                # 横向滚动区域：行内按 group_field 拆分
                scroll_area = QScrollArea()
                scroll_area.setWidgetResizable(True)
                scroll_area.setFrameShape(QFrame.NoFrame)
                scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                scroll_area.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
                scroll_area.setStyleSheet("QScrollArea { border: none; background: transparent; }")

                row_container = QWidget()
                row_container.setStyleSheet("background-color: transparent;")
                row_lay = QHBoxLayout(row_container)
                row_lay.setContentsMargins(0, 0, 0, 0)
                row_lay.setSpacing(12)

                for gval in group_vals:
                    g_df = recipe_df[recipe_df[group_field] == gval]
                    if g_df.empty:
                        continue

                    chart_card = ClickableFrame()
                    chart_card.setStyleSheet(
                        "QFrame { background-color:#FFFFFF; border:1px solid #C5D9E8; border-radius:12px; }"
                    )
                    chart_card.setMinimumWidth(int(600 * self._s))
                    chart_card_lay = QVBoxLayout(chart_card)
                    chart_card_lay.setContentsMargins(12, 12, 12, 12)

                    g_title = QLabel(f"{self._ort_group_dimension_label(group_field)}：{gval}")
                    g_title.setStyleSheet("font-size:12px; font-weight:700; color:#2C3E50;")
                    chart_card_lay.addWidget(g_title)

                    # 构建图表标题：产品-小件-配方
                    product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
                    subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
                    subpart_str = subparts[0] if len(subparts) == 1 else ""
                    title_parts = [p for p in [product_name, subpart_str, recipe] if p]
                    chart_title = "-".join(title_parts) + f" · {ct_label}" if title_parts else f"{product_name} · {ct_label}"

                    # 层级标签模式时增加图形宽度以容纳更多点位
                    has_point_level = "point_name" in g_df.columns and g_df["point_name"].nunique() > 1
                    use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, g_df)
                    fig_width = 12.0 if use_hierarchical else 8.0
                    
                    if chart_type == "boxplot":
                        fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=g_df, title=chart_title: self._build_ort_boxplot_figure(
                            point_name, df, x_field, y_field, "", scope_triplet, figsize, dpi, title)
                    else:
                        fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=g_df, title=chart_title: self._build_ort_linechart_figure(
                            point_name, df, x_field, y_field, "", scope_triplet, figsize, dpi, title)

                    canvas = FigureCanvas(fig_builder())
                    chart_card_lay.addWidget(canvas)
                    chart_card.clicked.connect(
                        lambda checked=False, fb=fig_builder, gv=gval: ChartZoomDialog(
                            f"{point_name} · {gv} · {ct_label}", fb, self
                        ).exec_()
                    )
                    row_lay.addWidget(chart_card)

                row_lay.addStretch()
                scroll_area.setWidget(row_container)
                self.ort_chart_layout.addWidget(scroll_area)

            self.ort_chart_layout.addStretch()
            return

        # ── 单配方/无配方时：原来的横向排列方式 ──
        scroll_area = QScrollArea()
        scroll_area.setWidgetResizable(True)
        scroll_area.setFrameShape(QFrame.NoFrame)
        scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        scroll_area.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        scroll_area.setStyleSheet("QScrollArea { border: none; background: transparent; }")

        split_container = QWidget()
        split_container.setStyleSheet("background-color: transparent;")
        split_lay = QHBoxLayout(split_container)
        split_lay.setContentsMargins(0, 0, 0, 0)
        split_lay.setSpacing(12)

        # 获取当前选中的配方（单配方场景）
        selected_recipes_single = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
        single_recipe = selected_recipes_single[0] if len(selected_recipes_single) == 1 else ""
        
        for gval in group_vals:
            g_df = raw_df[raw_df[group_field] == gval]
            if g_df.empty:
                continue

            chart_card = ClickableFrame()
            chart_card.setStyleSheet(
                "QFrame { background-color:#FFFFFF; border:1px solid #C5D9E8; border-radius:12px; }"
            )
            chart_card.setMinimumWidth(int(600 * self._s))
            chart_card_lay = QVBoxLayout(chart_card)
            chart_card_lay.setContentsMargins(12, 12, 12, 12)

            g_title = QLabel(f"{self._ort_group_dimension_label(group_field)}：{gval}")
            g_title.setStyleSheet("font-size:12px; font-weight:700; color:#2C3E50;")
            chart_card_lay.addWidget(g_title)

            # 构建图表标题：产品-小件-配方
            product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
            subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
            subpart_str = subparts[0] if len(subparts) == 1 else ""
            recipe_name = single_recipe if single_recipe else (selected_recipes_single[0] if selected_recipes_single else "")
            title_parts = [p for p in [product_name, subpart_str, recipe_name] if p]
            chart_title = "-".join(title_parts) + f" · {ct_label}" if title_parts else f"{product_name} · {ct_label}"

            # 层级标签模式时增加图形宽度以容纳更多点位
            has_point_level = "point_name" in g_df.columns and g_df["point_name"].nunique() > 1
            use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, g_df)
            fig_width = 12.0 if use_hierarchical else 8.0
            
            if chart_type == "boxplot":
                fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=g_df, title=chart_title: self._build_ort_boxplot_figure(
                    point_name, df, x_field, y_field, "", scope_triplet, figsize, dpi, title)
            else:
                fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=g_df, title=chart_title: self._build_ort_linechart_figure(
                    point_name, df, x_field, y_field, "", scope_triplet, figsize, dpi, title)

            canvas = FigureCanvas(fig_builder())
            chart_card_lay.addWidget(canvas)
            chart_card.clicked.connect(
                lambda checked=False, fb=fig_builder, gv=gval: ChartZoomDialog(
                    f"{point_name} · {gv} · {ct_label}", fb, self
                ).exec_()
            )
            split_lay.addWidget(chart_card)

        split_lay.addStretch()
        scroll_area.setWidget(split_container)
        self.ort_chart_layout.addWidget(scroll_area, 1)
        self.ort_chart_layout.addStretch()

    def _render_ort_multi_recipe_charts(
        self,
        point_name: str,
        raw_df: pd.DataFrame,
        x_field: str,
        y_field: str = "",
        color_field: str = "",
        scope_triplet: tuple = ("", "", ""),
        chart_type: str = "boxplot",
        selected_recipes: list[str] = None,
    ):
        """多配方时，为每个配方生成独立图形"""
        if selected_recipes is None:
            selected_recipes = []
        self._clear_layout_widgets(self.ort_chart_layout)

        if raw_df is None or raw_df.empty:
            self._render_ort_placeholder("当前筛选条件下暂无数据库记录可作图。")
            return

        ct_label = "箱线图" if chart_type == "boxplot" else "均值折线图"
        self.ort_chart_label.setText(f"{point_name} · {ct_label} · {len(selected_recipes)}个配方")

        # 信息卡
        info_card = QFrame()
        info_card.setStyleSheet(
            "QFrame { background-color:#F5F9FF; border:1px solid #C5D9E8; border-radius:14px; }"
        )
        info_lay = QVBoxLayout(info_card)
        info_lay.setContentsMargins(16, 14, 16, 14)
        info_lay.setSpacing(6)
        x_lbl = self._ort_group_dimension_label(x_field) if x_field else "点位"
        y_lbl = self._ort_group_dimension_label(y_field) if y_field else "无"
        c_lbl = self._ort_group_dimension_label(color_field) if color_field else "无"
        title_lbl = QLabel(
            f"点位：{point_name}  ·  X轴分组：{x_lbl}  ·  Y轴分组：{y_lbl}  ·  颜色分组：{c_lbl}"
        )
        title_lbl.setStyleSheet("font-size:14px; font-weight:800; color:#2C3E50;")
        desc_lbl = QLabel(
            f"数据源：{scope_triplet[0]} / {scope_triplet[1]} / {scope_triplet[2]}\n"
            f"共选择 {len(selected_recipes)} 个配方，每个配方生成独立图形"
        )
        desc_lbl.setWordWrap(True)
        desc_lbl.setStyleSheet("font-size:12px; color:#5A7A99;")
        info_lay.addWidget(title_lbl)
        info_lay.addWidget(desc_lbl)
        self.ort_chart_layout.addWidget(info_card)

        # 为每个配方生成独立图表
        for recipe in selected_recipes:
            recipe_df = raw_df[raw_df.get("recipe") == recipe] if "recipe" in raw_df.columns else raw_df
            if recipe_df.empty:
                continue

            # 图表卡
            chart_card = ClickableFrame()
            chart_card.setStyleSheet(
                "QFrame { background-color:#FFFFFF; border:1px solid #C5D9E8; border-radius:12px; }"
            )
            chart_card_lay = QVBoxLayout(chart_card)
            chart_card_lay.setContentsMargins(12, 12, 12, 12)

            # 配方标题：产品-小件-配方
            product_name = scope_triplet[2] if scope_triplet[2] else "未选产品"
            subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
            subpart_str = subparts[0] if len(subparts) == 1 else (f"{len(subparts)}个小件" if subparts else "")
            
            title_parts = [p for p in [product_name, subpart_str, recipe] if p]
            recipe_display_title = "-".join(title_parts)
            
            recipe_title = QLabel(recipe_display_title)
            recipe_title.setStyleSheet("font-size:12px; font-weight:700; color:#2C3E50;")
            chart_card_lay.addWidget(recipe_title)

            # 层级标签模式时增加图形宽度以容纳更多点位
            has_point_level = "point_name" in recipe_df.columns and recipe_df["point_name"].nunique() > 1
            use_hierarchical = self._ort_is_hierarchical_xaxis(x_field, recipe_df)
            fig_width = 14.0 if use_hierarchical else 9.4
            
            if chart_type == "boxplot":
                fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=recipe_df, r=recipe: self._build_ort_boxplot_figure_single_recipe(
                    point_name, df, x_field, y_field, color_field, scope_triplet, r, figsize, dpi)
            else:
                fig_builder = lambda figsize=(fig_width, 3.6), dpi=100, df=recipe_df, r=recipe: self._build_ort_linechart_figure_single_recipe(
                    point_name, df, x_field, y_field, color_field, scope_triplet, r, figsize, dpi)

            canvas = FigureCanvas(fig_builder())
            chart_card_lay.addWidget(canvas)
            chart_card.clicked.connect(
                lambda checked=False, fb=fig_builder, r=recipe: ChartZoomDialog(
                    f"{point_name} · {r} · {ct_label}", fb, self
                ).exec_()
            )

            self.ort_chart_layout.addWidget(chart_card)

        self.ort_chart_layout.addStretch()

    def _update_ort_grouped_report_preview(self, summary_df: pd.DataFrame, raw_df: pd.DataFrame):
        """图形分析完成后，同步「数据与报告」页（按配方分页，与导出一致）。"""
        self._ort_grouped_summary_df = (
            summary_df.copy() if summary_df is not None and not summary_df.empty else pd.DataFrame()
        )
        self._ort_grouped_raw_df = (
            raw_df.copy() if raw_df is not None and not raw_df.empty else pd.DataFrame()
        )
        if raw_df is None or raw_df.empty:
            self._update_ort_report_table(None)
            return
        wide_df, core_cols, point_cols = self._long_df_to_spc_wide(raw_df)
        if wide_df.empty or not point_cols:
            self._update_ort_report_table(None)
            return
        core_cols = dict(core_cols)
        core_cols.setdefault("barcode", "barcode")
        report_df = self._build_ort_report_df_from_wide(wide_df, core_cols, point_cols)
        self._ort_report_df = report_df
        if hasattr(self, "ort_report_table_label"):
            self.ort_report_table_label.setText(
                "数据预览 (按配方分页，与导出 Excel 一致，不含规格列)"
            )
        self._update_ort_report_table(report_df)

    def _update_ort_analysis_from_db(self):
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            return
        if getattr(self, "_ort_update_busy", False):
            self._ort_update_pending = True
            return
        try:
            self._ort_update_busy = True
            self._initialize_ort_db_analysis_ui()
            self._refresh_ort_db_scope_controls()
            module_name, category, product_name = self._ort_db_current_scope()
            if not (module_name and category and product_name):
                self._render_ort_placeholder("请先从数据库中选择 模块 / 大类 / 产品。")
                return

            # ── 从拖拽区域读取维度配置 ──
            zone_y     = getattr(self, "_ort_zone_y",     None)
            zone_x     = getattr(self, "_ort_zone_x",     None)
            zone_color = getattr(self, "_ort_zone_color", None)
            zone_group = getattr(self, "_ort_zone_group", None)
            drag_x     = zone_x.field_key     if zone_x     else ""
            drag_y     = zone_y.field_key     if zone_y     else ""
            drag_color = zone_color.field_key if zone_color else ""
            drag_group = zone_group.field_key if zone_group else ""

            point_name = self._resolve_ort_analysis_point_name()
            if not point_name:
                self._render_ort_placeholder(
                    "当前筛选条件下暂无可用检测点位，请检查数据库是否已导入数据。"
                )
                return

            if not getattr(self, "_ort_next_do_plot", False):
                if drag_x or drag_y or drag_color or drag_group:
                    self._render_ort_placeholder(
                        f"已配置：X轴分组={self._ort_group_dimension_label(drag_x) if drag_x else '—'}  "
                        f"Y轴分组={self._ort_group_dimension_label(drag_y) if drag_y else '—'}  "
                        f"颜色分组={self._ort_group_dimension_label(drag_color) if drag_color else '—'}  "
                        f"图形拆分={self._ort_group_dimension_label(drag_group) if drag_group else '—'}\n"
                        "点击「作图  ◉」生成图表。"
                    )
                else:
                    self._render_ort_placeholder(
                        "将左侧维度字段拖入 X轴 / Y轴 / 图形拆分后点击「作图  ◉」。"
                    )
                return

            self._render_ort_placeholder("正在从数据库加载数据，请稍候…")
            QApplication.processEvents()

            filters = self._ort_db_current_filters()
            start_date, end_date = self._ort_global_date_range_strings()

            # 查询多个点位数据（用于形成基础图形的点位层级）
            point_names = self._get_available_points_for_analysis(mgr, module_name, category, product_name)
            if len(point_names) > 1:
                raw_df = mgr.query_multiple_points_analysis_rows(
                    point_names=point_names,
                    module_name=module_name,
                    category=category,
                    product_name=product_name,
                    filters=filters,
                    start_date=start_date,
                    end_date=end_date,
                )
                # 如果没有指定X轴分组，默认使用点位作为X轴
                if not drag_x:
                    drag_x = "point_name"
            else:
                raw_df = mgr.query_point_analysis_rows(
                    point_name=point_name,
                    module_name=module_name,
                    category=category,
                    product_name=product_name,
                    filters=filters,
                    start_date=start_date,
                    end_date=end_date,
                )
            
            if raw_df is not None and not raw_df.empty:
                import re
                def get_prefix(pt):
                    match = re.match(r'^([A-Za-z]+)', str(pt))
                    return match.group(1) if match else '其他'
                raw_df['part_name'] = raw_df['point_name'].apply(get_prefix)
                # 添加日期列用于分组（从 test_time 提取）
                if 'test_time' in raw_df.columns:
                    raw_df['analysis_date'] = pd.to_datetime(raw_df['test_time'], errors='coerce').dt.strftime('%Y-%m-%d')
                # 确保班别、线别、物料类别等字段为干净的字符串，填充空值以确保分组效果与时间一致
                for col in ['shift', 'line', 'material_category']:
                    if col in raw_df.columns:
                        raw_df[col] = raw_df[col].fillna("").astype(str).str.strip()
                        # 去除浮点数后缀 .0（例如 1.0 -> 1）
                        raw_df[col] = raw_df[col].apply(lambda x: x[:-2] if x.endswith(".0") else x)
                        # 空白转为未知标识
                        if col == 'shift':
                            label_name = "班别"
                        elif col == 'line':
                            label_name = "线别"
                        else:
                            label_name = "物料类别"
                        raw_df[col] = raw_df[col].replace("", f"未知{label_name}")
            
            self._ort_next_do_plot = False
            self._ort_grouped_raw_df = raw_df.copy() if raw_df is not None else pd.DataFrame()

            if raw_df is None or raw_df.empty:
                self._ort_grouped_summary_df = pd.DataFrame()
                if hasattr(self, "lbl_ort_product_count"):
                    self.lbl_ort_product_count.setText("样本数: 0")
                self._render_ort_placeholder("当前筛选条件下暂无数据库记录可作图。")
                self._update_ort_grouped_report_preview(pd.DataFrame(), pd.DataFrame())
                return

            if hasattr(self, "lbl_ort_product_count"):
                self.lbl_ort_product_count.setText(f"样本数: {len(raw_df)}")

            # ── 判断使用交互图还是旧三维统计图 ──
            chart_type = getattr(self, "_ort_current_chart_type", "boxplot")
            scope_triplet = (module_name, category, product_name)

            # 检查配方选择数量，多配方时自动按配方分组
            selected_recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
            recipe_count = len(selected_recipes)
            
            if drag_group:
                self._render_ort_split_charts(
                    point_name=point_name,
                    raw_df=raw_df,
                    x_field=drag_x,
                    y_field=drag_y,
                    group_field=drag_group,
                    scope_triplet=scope_triplet,
                    chart_type=chart_type,
                )
                dim_keys = [k for k in [drag_x, drag_y, drag_group] if k]
                summary_df, _ = self._build_ort_db_grouped_summary(raw_df, dim_keys)
                self._ort_grouped_summary_df = summary_df.copy()
                self._update_ort_grouped_report_preview(summary_df, raw_df)
            elif recipe_count > 1 and "recipe" not in (drag_x, drag_y, drag_group):
                self._render_ort_multi_recipe_charts(
                    point_name=point_name,
                    raw_df=raw_df,
                    x_field=drag_x,
                    y_field=drag_y,
                    color_field="",
                    scope_triplet=scope_triplet,
                    chart_type=chart_type,
                    selected_recipes=selected_recipes,
                )
                dim_keys = [k for k in [drag_x, drag_y, drag_group, "recipe"] if k]
                summary_df, _ = self._build_ort_db_grouped_summary(raw_df, dim_keys)
                self._ort_grouped_summary_df = summary_df.copy()
                self._update_ort_grouped_report_preview(summary_df, raw_df)
            elif drag_x or drag_y:
                self._render_ort_interactive_chart(
                    point_name=point_name,
                    raw_df=raw_df,
                    x_field=drag_x,
                    y_field=drag_y,
                    color_field="",
                    scope_triplet=scope_triplet,
                    chart_type=chart_type,
                )
                dim_keys = [k for k in [drag_x, drag_y, drag_group] if k] or [
                    str(getattr(self, "ort_db_combo_group1", QComboBox()).currentData() or "").strip(),
                ]
                summary_df, _ = self._build_ort_db_grouped_summary(raw_df, dim_keys)
                self._ort_grouped_summary_df = summary_df.copy()
                self._update_ort_grouped_report_preview(summary_df, raw_df)
            else:
                # 旧模式：三维分组统计图
                dim_keys = [
                    str(getattr(self, "ort_db_combo_group1", QComboBox()).currentData() or "").strip(),
                    str(getattr(self, "ort_db_combo_group2", QComboBox()).currentData() or "").strip(),
                    str(getattr(self, "ort_db_combo_group3", QComboBox()).currentData() or "").strip(),
                ]
                summary_df, used_dims = self._build_ort_db_grouped_summary(raw_df, dim_keys)
                self._ort_grouped_summary_df = summary_df.copy()
                if hasattr(self, "lbl_ort_product_count"):
                    self.lbl_ort_product_count.setText(
                        f"样本数: {len(raw_df)} | 组数 {len(summary_df)}")
                self._render_ort_db_grouped_charts(
                    point_name=point_name,
                    summary_df=summary_df,
                    raw_df=raw_df,
                    used_dims=used_dims,
                    scope_triplet=scope_triplet,
                )
                self._update_ort_grouped_report_preview(summary_df, raw_df)

            self._ort_fig_cache["generated"] = True
        finally:
            self._ort_update_busy = False
            if self._ort_update_pending:
                self._ort_update_pending = False
                self._schedule_ort_update(delay_ms=50)

    def _open_recipe_spec_dialog(self):
        """打开规格限设置弹窗（左配方，右点位 LSL/USL）。"""
        if not hasattr(self, "_ort_raw_df") or self._ort_raw_df is None:
            return QMessageBox.information(self, "提示", "请先导入数据并进入 ORT 图形分析进行扫描。")
        if not hasattr(self, "_ort_core_cols") or not hasattr(self, "_ort_point_cols"):
            return QMessageBox.information(self, "提示", "尚未完成数据扫描，请先点击“ORT 图形分析”。")

        dlg = RecipeSpecDialog(
            df_raw=self._ort_raw_df.copy(),
            core_cols=self._ort_core_cols,
            point_cols=self._ort_point_cols,
            recipe_point_spec_map=self._ort_recipe_point_spec_map,
            on_save_template=self._save_spec_template,
            parent=self
        )
        result = dlg.exec_()
        # 如果点击了保存按钮（返回1），则应用修改
        if result == 1:
            self._ort_recipe_point_spec_map = dlg.recipe_point_spec_map
        # 保存完后刷新模板下拉（如果新增了）
        self._refresh_spec_template_combo(keep_current=True)

    def _spec_templates_path(self) -> str:
        return os.path.join(os.getcwd(), "ort_spec_templates.json")

    def _load_spec_templates(self):
        self._ort_spec_templates = {}
        path = self._spec_templates_path()
        if not os.path.exists(path):
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                payload = json.load(f)
            templates = payload.get("templates", {}) if isinstance(payload, dict) else {}
            for name, mapping in (templates or {}).items():
                # mapping: list[[recipe_key, point, lsl, usl]] or dict
                if isinstance(mapping, dict):
                    # 兼容旧格式：直接存 dict
                    self._ort_spec_templates[str(name)] = mapping
                elif isinstance(mapping, list):
                    m = {}
                    for row in mapping:
                        if not isinstance(row, list) or len(row) < 4:
                            continue
                        rk, pt, lsl, usl = row[0], row[1], row[2], row[3]
                        key = (str(rk).strip(), str(pt).strip())
                        m[key] = self._normalize_spec_limits_row({"lsl": lsl, "usl": usl})
                    self._ort_spec_templates[str(name)] = m
        except Exception:
            self._ort_spec_templates = {}

    def _save_spec_templates_to_disk(self):
        path = self._spec_templates_path()
        try:
            payload = {"templates": {}}
            for name, m in (self._ort_spec_templates or {}).items():
                # 序列化为 list，避免 tuple key
                rows = []
                for (rk, pt), v in (m or {}).items():
                    if not isinstance(v, dict):
                        continue
                    rows.append([rk, pt, v.get("lsl"), v.get("usl")])
                payload["templates"][name] = rows
            with open(path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _save_spec_template(self, name: str, recipe_point_spec_map: dict):
        name = str(name or "").strip()
        if not name:
            return
        # 深拷贝一份
        m = {}
        for k, v in (recipe_point_spec_map or {}).items():
            try:
                rk, pt = k
            except Exception:
                continue
            if isinstance(v, dict):
                m[(str(rk), str(pt))] = {"lsl": v.get("lsl"), "usl": v.get("usl")}
        self._ort_spec_templates[name] = m
        self._ort_active_spec_template = name
        self.settings.setValue("ort_last_spec_template", name)
        self._save_spec_templates_to_disk()

    def _refresh_spec_template_combo(self, keep_current: bool = True):
        if not hasattr(self, "combo_spec_template"):
            return
        cur = self._ort_active_spec_template if keep_current else ""
        self.combo_spec_template.blockSignals(True)
        try:
            self.combo_spec_template.clear()
            self.combo_spec_template.addItem("模板", "")
            for name in sorted((self._ort_spec_templates or {}).keys()):
                self.combo_spec_template.addItem(str(name), name)
            
            # restore
            if not cur:
                last = str(self.settings.value("ort_last_spec_template", "") or "")
                if last:
                    cur = last
            
            idx = self.combo_spec_template.findData(cur)
            if idx >= 0:
                self._ort_active_spec_template = cur
                self.combo_spec_template.setCurrentIndex(idx)
            else:
                self._ort_active_spec_template = ""
                self.combo_spec_template.setCurrentIndex(0)
        finally:
            self.combo_spec_template.blockSignals(False)
            # 程序化恢复上次模板时不会触发 currentIndexChanged，需主动灌入映射
            self._sync_live_spec_map_from_spec_template_combo()

    # ------------------------------------------------------------------
    # SPC 分析核心
    # ------------------------------------------------------------------
    def _long_df_to_spc_wide(self, long_df: pd.DataFrame) -> tuple[pd.DataFrame, dict, list]:
        """将数据库长表转为 SPC 分析用的宽表及列映射。"""
        if long_df is None or long_df.empty:
            return pd.DataFrame(), {}, []

        df = long_df.copy()
        if "test_time" in df.columns:
            df["dt"] = pd.to_datetime(df["test_time"], errors="coerce")
            df = df.sort_values(["dt", "recipe", "barcode", "point_name"], kind="stable", na_position="last")

        index_cols = [
            c for c in (
                "module_name", "category", "product_name",
                "project", "model", "component", "subpart",
                "recipe", "barcode", "test_time",
                "line", "shift", "result", "test_position", "material_category",
            )
            if c in df.columns
        ]
        if not index_cols or "point_name" not in df.columns:
            return pd.DataFrame(), {}, []

        dedupe_cols = index_cols + ["point_name"]
        df = df.drop_duplicates(subset=dedupe_cols, keep="last")
        wide = df.pivot_table(
            index=index_cols, columns="point_name", values="value", aggfunc="first"
        )
        wide = wide.reset_index()
        if isinstance(wide.columns, pd.MultiIndex):
            wide.columns = [str(c[-1] if isinstance(c, tuple) else c) for c in wide.columns]

        point_names = sorted(
            {str(c) for c in wide.columns if str(c) not in index_cols and str(c) != "point_name"},
            key=str,
        )
        point_cols = [(p, p, None) for p in point_names]
        core_cols = {
            "recipe": "recipe",
            "project": "project",
            "subpart": "subpart",
            "time": "test_time",
            "machine_type": "model",
            "component": "component",
        }
        return wide, core_cols, point_cols

    def _prepare_spc_data_from_db(self) -> tuple[bool, str]:
        """从数据库加载 SPC 分析数据（时间范围 + 小件/配方筛选与图形分析一致）。"""
        mgr = getattr(self, "_ort_db", None)
        if mgr is None:
            return False, "数据库未初始化。"

        self._initialize_ort_db_analysis_ui(update_placeholder=False)
        module_name, category, product_name = self._ort_db_current_scope()
        if not (module_name and category and product_name):
            return False, "请先在顶部选择「类型」与「产品」，并确认数据库中已有对应数据。"

        start_date, end_date = self._ort_global_date_range_strings()
        if start_date > end_date:
            return False, "开始日期不能晚于结束日期。"

        point_names = self._get_available_points_for_analysis(mgr, module_name, category, product_name)
        if not point_names:
            return False, "当前产品下没有可用点位，请先入库数据。"

        filters = self._ort_db_current_filters()
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            long_df = mgr.query_multiple_points_analysis_rows(
                point_names=point_names,
                module_name=module_name,
                category=category,
                product_name=product_name,
                filters=filters,
                start_date=start_date,
                end_date=end_date,
            )
        finally:
            QApplication.restoreOverrideCursor()

        if long_df is None or long_df.empty:
            return False, (
                f"在 {start_date} 至 {end_date} 范围内未查到数据。\n"
                "请调整时间范围，或检查左侧小件/配方筛选。"
            )

        wide_df, core_cols, point_cols = self._long_df_to_spc_wide(long_df)
        if wide_df.empty or not point_cols:
            return False, "查询到数据但无法生成测点列，请检查数据库记录是否完整。"

        self._ort_spc_long_df = long_df
        self._ort_raw_df = wide_df
        self._ort_core_cols = core_cols
        self._ort_point_cols = point_cols
        self._spc_data_scope_note = f"{category} / {product_name}  |  {start_date} ~ {end_date}"
        return True, ""

    def _run_spc_analysis(self):
        """扫描数据并对各配方各点位执行 SPC 规则检测（默认从数据库读取）。"""
        use_db = getattr(self, "_ort_chart_mode", "") == "db_grouped"
        if use_db:
            ok, err = self._prepare_spc_data_from_db()
            if not ok:
                QMessageBox.information(self, "提示", err)
                return
        elif not hasattr(self, "_ort_raw_df") or self._ort_raw_df is None or self._ort_raw_df.empty:
            QMessageBox.information(self, "提示", "请先导入数据并进行『ORT 图形分析』扫描。")
            return

        if not hasattr(self, "_ort_core_cols") or not hasattr(self, "_ort_point_cols"):
            QMessageBox.information(self, "提示", "尚未完成数据准备，请重试。")
            return

        df = self._ort_raw_df
        core_cols = self._ort_core_cols
        point_cols = self._ort_point_cols
        spec_map = getattr(self, "_ort_recipe_point_spec_map", {}) or {}
        min_n = int(self.spin_spc_min_n.value())

        # 收集启用的规则及其等级
        enabled_rules = {}
        for rule_id, _ in self._spc_rules_def:
            if self._spc_rule_checks[rule_id].isChecked():
                enabled_rules[rule_id] = self._spc_rule_selectors[rule_id].currentText()

        if not enabled_rules:
            QMessageBox.warning(self, "提示", "请至少启用一条 SPC 规则。")
            return

        recipe_col = core_cols.get("recipe", "")
        proj_col   = core_cols.get("project", "")
        sub_col    = core_cols.get("subpart", "")
        time_col   = core_cols.get("time", "")

        group_cols = [c for c in [proj_col, sub_col, recipe_col] if c and c in df.columns]

        # ---- SPC 规则实现（作用于 numpy 数组 y，返回触发位置列表） ----
        def _check_rule(rule_id: str, y: np.ndarray, mean: float, sigma: float) -> list:
            if sigma == 0:
                return []
            n = len(y)
            hits = []
            z = (y - mean) / sigma  # z-score

            if rule_id == "R1":
                for i in range(n):
                    if abs(z[i]) > 3:
                        hits.append(i)

            elif rule_id == "R2":
                for i in range(8, n):
                    seg = z[i-8:i+1]
                    if all(v > 0 for v in seg) or all(v < 0 for v in seg):
                        hits.append(i)

            elif rule_id == "R3":
                for i in range(5, n):
                    seg = y[i-5:i+1]
                    if all(seg[j] < seg[j+1] for j in range(5)) or \
                       all(seg[j] > seg[j+1] for j in range(5)):
                        hits.append(i)

            elif rule_id == "R4":
                for i in range(13, n):
                    seg = y[i-13:i+1]
                    alt = all((seg[j] - seg[j+1]) * (seg[j+1] - seg[j+2]) < 0
                              for j in range(12))
                    if alt:
                        hits.append(i)

            elif rule_id == "R5":
                for i in range(2, n):
                    seg = z[i-2:i+1]
                    pos_cnt = sum(1 for v in seg if v > 2)
                    neg_cnt = sum(1 for v in seg if v < -2)
                    if pos_cnt >= 2 or neg_cnt >= 2:
                        hits.append(i)

            elif rule_id == "R6":
                for i in range(4, n):
                    seg = z[i-4:i+1]
                    pos_cnt = sum(1 for v in seg if v > 1)
                    neg_cnt = sum(1 for v in seg if v < -1)
                    if pos_cnt >= 4 or neg_cnt >= 4:
                        hits.append(i)

            elif rule_id == "R7":
                for i in range(14, n):
                    seg = z[i-14:i+1]
                    if all(abs(v) < 1 for v in seg):
                        hits.append(i)

            elif rule_id == "R8":
                for i in range(7, n):
                    seg = z[i-7:i+1]
                    if all(abs(v) > 1 for v in seg):
                        hits.append(i)

            return hits

        # ---- 主扫描逻辑 ----
        results = []  # list of dict

        if group_cols:
            groups = list(df.groupby(group_cols, sort=False))
        else:
            groups = [(None, df)]

        for group_key, df_g in groups:
            # 保持UI响应，防止卡死
            QApplication.processEvents()

            # 构建配方标签
            if isinstance(group_key, tuple):
                recipe_label = " - ".join([str(x) for x in group_key if str(x).lower() not in ("nan", "none", "")])
            elif group_key is None:
                recipe_label = "全部"
            else:
                recipe_label = str(group_key)

            # spec_key for spec_map lookup
            if proj_col in df_g.columns and sub_col in df_g.columns and recipe_col in df_g.columns and len(df_g) > 0:
                pv = str(df_g.iloc[0][proj_col]) if proj_col else ""
                sv = str(df_g.iloc[0][sub_col]) if sub_col else ""
                rv = str(df_g.iloc[0][recipe_col]) if recipe_col else ""
                spec_key = f"{pv}||{sv}||{rv}"
            else:
                spec_key = ""

            if time_col and time_col in df_g.columns:
                df_g = df_g.sort_values(time_col, kind="stable")

            for point_name, value_col, _ in point_cols:
                if value_col not in df_g.columns:
                    continue
                vals = pd.to_numeric(df_g[value_col], errors="coerce").dropna()
                if len(vals) < min_n:
                    continue

                y = vals.to_numpy()
                mean = float(np.mean(y))
                sigma = float(np.std(y, ddof=1)) if len(y) > 1 else 0.0

                for rule_id, level in enabled_rules.items():
                    hits = _check_rule(rule_id, y, mean, sigma)
                    if hits:
                        rule_desc = next((d for rid, d in self._spc_rules_def if rid == rule_id), rule_id)
                        
                        # 获取最后一次触发的时间
                        last_hit_idx = vals.index[hits[-1]]
                        last_time_val = df_g.loc[last_hit_idx, time_col] if time_col and time_col in df_g.columns else "-"
                        if pd.notna(last_time_val):
                            if isinstance(last_time_val, (pd.Timestamp, datetime)):
                                last_time_str = last_time_val.strftime("%Y-%m-%d %H:%M:%S")
                            else:
                                last_time_str = str(last_time_val)
                        else:
                            last_time_str = "-"

                        results.append({
                            "recipe": recipe_label,
                            "point": str(point_name),
                            "rule": f"{rule_id}: {rule_desc}",
                            "level": level,
                            "count": len(hits),
                            "first_hit": int(hits[0]) + 1,
                            "last_time": last_time_str,
                            "group_key": group_key,
                            "value_col": value_col
                        })

        # ---- 填充结果表（按重要度 L1→L2→L3 排序） ----
        level_order = {"L1": 0, "L2": 1, "L3": 2}
        results.sort(key=lambda r: (level_order.get(r["level"], 9), r["recipe"], r["point"]))

        self.spc_result_table.blockSignals(True)
        self.spc_result_table.setRowCount(0)
        try:
            # 修改 L2 颜色为系统背景的浅蓝色 (#F5F9FF)
            level_colors = {"L1": "#FFCCCC", "L2": "#F5F9FF", "L3": "#E8F4E8"}
            for row_data in results:
                ri = self.spc_result_table.rowCount()
                self.spc_result_table.insertRow(ri)
                bg = QColor(level_colors.get(row_data["level"], "#FFFFFF"))

                cells = [
                    row_data["recipe"],
                    row_data["point"],
                    row_data["rule"],
                    row_data["level"],
                    str(row_data["count"]),
                    f"第 {row_data['first_hit']} 点",
                    row_data["last_time"],
                ]
                for ci, text in enumerate(cells):
                    item = QTableWidgetItem(text)
                    item.setBackground(bg)
                    item.setTextAlignment(Qt.AlignCenter)
                    self.spc_result_table.setItem(ri, ci, item)
        finally:
            self.spc_result_table.blockSignals(False)

        # 汇总统计
        l1 = sum(1 for r in results if r["level"] == "L1")
        l2 = sum(1 for r in results if r["level"] == "L2")
        l3 = sum(1 for r in results if r["level"] == "L3")
        total_combos = len(set((r["recipe"], r["point"]) for r in results))
        scope_note = getattr(self, "_spc_data_scope_note", "")
        scope_prefix = f"{scope_note}  |  " if scope_note else ""
        if results:
            self.lbl_spc_summary.setText(
                f"{scope_prefix}共检出 {len(results)} 条违规 | 涉及 {total_combos} 个点位 | "
                f"L1（高）: {l1}  L2（中）: {l2}  L3（一般）: {l3}")
        else:
            self.lbl_spc_summary.setText(
                f"{scope_prefix}✔ 未检出任何 SPC 违规，数据状态良好。"
            )

        # 统计每个配方的 L1/L2/L3 次数
        recipe_stats = {}
        for group_key, df_g in groups:
            if isinstance(group_key, tuple):
                rec_label = " - ".join([str(x) for x in group_key if str(x).lower() not in ("nan", "none", "")])
            elif group_key is None:
                rec_label = "全部"
            else:
                rec_label = str(group_key)
            if rec_label not in recipe_stats:
                recipe_stats[rec_label] = {"L1": 0, "L2": 0, "L3": 0}

        for r in results:
            rec = r["recipe"]
            lvl = r["level"]
            if rec in recipe_stats and lvl in recipe_stats[rec]:
                recipe_stats[rec][lvl] += 1

        if hasattr(self, "spc_stat_table"):
            self.spc_stat_table.blockSignals(True)
            self.spc_stat_table.setRowCount(0)
            try:
                for rec, counts in recipe_stats.items():
                    ri = self.spc_stat_table.rowCount()
                    self.spc_stat_table.insertRow(ri)

                    c_rec = QTableWidgetItem(rec)
                    c_rec.setTextAlignment(Qt.AlignCenter)
                    c_rec.setToolTip(rec)
                    self.spc_stat_table.setItem(ri, 0, c_rec)

                    for col_idx, lvl in enumerate(["L1", "L2", "L3"], start=1):
                        count = counts[lvl]
                        c_val = QTableWidgetItem(str(count))
                        c_val.setTextAlignment(Qt.AlignCenter)
                        
                        f = c_val.font()
                        if count > 0:
                            f.setBold(True)
                            f.setPointSize(10)
                            if lvl == "L1": c_val.setForeground(QColor("#FF4D4F")) # Red
                            elif lvl == "L2": c_val.setForeground(QColor("#FAAD14")) # Orange
                            elif lvl == "L3": c_val.setForeground(QColor("#52C41A")) # Green
                        else:
                            f.setBold(False)
                            f.setPointSize(9)
                            c_val.setForeground(QColor("#BFBFBF")) # Standard light gray
                        
                        c_val.setFont(f)
                        self.spc_stat_table.setItem(ri, col_idx, c_val)
            finally:
                self.spc_stat_table.blockSignals(False)

        # 保存结果数据供图表显示使用
        self._spc_results_data = results

    def _export_spc_results(self):
        """将 SPC 分析结果导出到 Excel 文件。"""
        if not hasattr(self, "_spc_results_data") or not self._spc_results_data:
            QMessageBox.warning(self, "提示", "当前没有分析结果可以导出。请先点击“开始分析”。")
            return

        # 准备数据
        export_list = []
        for r in self._spc_results_data:
            export_list.append({
                "配方": r["recipe"],
                "点位": r["point"],
                "触发规则": r["rule"],
                "重要度": r["level"],
                "触发次数": r["count"],
                "首次触发位置": f"第 {r['first_hit']} 点",
                "最后触发时间": r["last_time"]
            })

        df_export = pd.DataFrame(export_list)
        
        # 弹出保存对话框
        file_path, _ = QFileDialog.getSaveFileName(
            self, "导出 SPC 分析结果", f"ORT_SPC_Analysis_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx", 
            "Excel Files (*.xlsx)"
        )
        
        if not file_path:
            return

        try:
            with pd.ExcelWriter(file_path, engine='openpyxl') as writer:
                df_export.to_excel(writer, index=False, sheet_name='SPC_Results')
                
                # 自动调整列宽
                worksheet = writer.sheets['SPC_Results']
                for i, col in enumerate(df_export.columns):
                    column_len = df_export[col].astype(str).str.len().max()
                    column_len = max(column_len, len(col)) + 4
                    worksheet.column_dimensions[chr(65 + i)].width = min(column_len, 50)

            QMessageBox.information(self, "成功", f"分析结果已成功导出至：\n{file_path}")
        except Exception as e:
            QMessageBox.critical(self, "错误", f"导出失败：\n{str(e)}")

    # ------------------------------------------------------------------
    # 导出辅助
    # ------------------------------------------------------------------
    @staticmethod
    def _get_desktop_dir() -> str:
        """返回当前用户桌面路径（Windows 优先；其它系统回退到 Home）。"""
        try:
            home = os.path.expanduser("~")
            desktop = os.path.join(home, "Desktop")
            if os.path.isdir(desktop):
                return desktop
            return home
        except Exception:
            return os.getcwd()

    def _export_spc_results_to_path(self, file_path: str) -> bool:
        """导出 SPC 分析结果到指定路径（不弹窗）。"""
        if not hasattr(self, "_spc_results_data") or not self._spc_results_data:
            return False
        try:
            export_list = []
            for r in self._spc_results_data:
                export_list.append({
                    "配方": r.get("recipe", ""),
                    "点位": r.get("point", ""),
                    "触发规则": r.get("rule", ""),
                    "重要度": r.get("level", ""),
                    "触发次数": r.get("count", ""),
                    "首次触发位置": f"第 {r.get('first_hit', '')} 点",
                    "最后触发时间": r.get("last_time", "")
                })
            df_export = pd.DataFrame(export_list)
            if not str(file_path).lower().endswith(".xlsx"):
                file_path = str(file_path) + ".xlsx"
            os.makedirs(os.path.dirname(file_path), exist_ok=True)
            with pd.ExcelWriter(file_path, engine="openpyxl") as writer:
                df_export.to_excel(writer, index=False, sheet_name="SPC_Results")
                worksheet = writer.sheets["SPC_Results"]
                for i, col in enumerate(df_export.columns):
                    column_len = df_export[col].astype(str).str.len().max()
                    column_len = max(column_len, len(col)) + 4
                    worksheet.column_dimensions[chr(65 + i)].width = min(int(column_len), 50)
            return True
        except Exception:
            return False

    def _export_ort_data_to_path(self, file_path: str, show_progress: bool = True) -> bool:
        """导出 ORT Export Data 到指定路径（不弹窗）。"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            report_df = getattr(self, "_ort_report_df", None)
            if report_df is None or getattr(report_df, "empty", True):
                self._prepare_ort_report_data_from_db(show_errors=False)
        report_df = getattr(self, "_ort_report_df", None)
        if report_df is None or getattr(report_df, "empty", True):
            return False
        frames = list(getattr(self, "_ort_report_sheet_frames", None) or [])
        if not frames:
            frames = self._build_ort_export_sheet_frames(report_df)
        if not frames:
            return False
        try:
            if not str(file_path).lower().endswith(".xlsx"):
                file_path = str(file_path) + ".xlsx"
            os.makedirs(os.path.dirname(file_path), exist_ok=True)

            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side

            # 进度条：1(单值图sheet) + len(frames)(数据sheets)
            progress = None
            if show_progress:
                try:
                    total_steps = 1 + len(frames)
                    progress = NiceProgressDialog("导出 Excel", "正在导出 Export Data...", total_steps, self)
                    progress.show()
                    QApplication.processEvents()
                except Exception:
                    progress = None

            wb = Workbook()
            wb.remove(wb.active)

            header_font = Font(name="Microsoft YaHei", bold=True, size=13, color="FFFFFF")
            header_fill = PatternFill(start_color="8B7355", end_color="8B7355", fill_type="solid")
            header_align = Alignment(horizontal="center", vertical="center", wrap_text=False)
            thin_border = Border(
                left=Side(style="thin", color="D4C4A8"),
                right=Side(style="thin", color="D4C4A8"),
                top=Side(style="thin", color="D4C4A8"),
                bottom=Side(style="thin", color="D4C4A8")
            )
            cell_align = Alignment(horizontal="center", vertical="center")

            def _write_dataframe_to_sheet(ws, sheet_df: pd.DataFrame):
                for col_idx, col_name in enumerate(sheet_df.columns, start=1):
                    cell = ws.cell(row=1, column=col_idx, value=col_name)
                    cell.font = header_font
                    cell.fill = header_fill
                    cell.alignment = header_align
                    cell.border = thin_border
                ws.row_dimensions[1].height = 28

                for row_idx, row in enumerate(sheet_df.values, start=2):
                    for col_idx, val in enumerate(row, start=1):
                        cell = ws.cell(row=row_idx, column=col_idx)
                        cell.value = "" if pd.isna(val) else val
                        cell.alignment = cell_align
                        cell.border = thin_border
                        if row_idx % 2 == 0:
                            cell.fill = PatternFill(start_color="F8F4EC", end_color="F8F4EC", fill_type="solid")

                for col_idx, col_name in enumerate(sheet_df.columns, start=1):
                    max_len = max(len(str(col_name)), 10)
                    for row_idx in range(2, min(len(sheet_df) + 2, 100)):
                        cell_val = ws.cell(row=row_idx, column=col_idx).value
                        if cell_val:
                            max_len = max(max_len, min(len(str(cell_val)), 40))
                    ws.column_dimensions[ws.cell(row=1, column=col_idx).column_letter].width = max_len + 2
                ws.freeze_panes = "A2"

            chart_ws = wb.create_sheet("单值图", 0)
            if progress is not None:
                progress.setValue(0)
                progress.bar.setFormat("正在生成 Excel 内嵌单值图... %p%")
                QApplication.processEvents()
            self._add_charts_to_excel_sheet(chart_ws, frames)

            for (sheet_title, sheet_df) in frames:
                if progress is not None and progress.wasCanceled():
                    try:
                        progress.close()
                        progress.deleteLater()
                    except Exception:
                        pass
                    return False
                ws = wb.create_sheet(sheet_title)
                _write_dataframe_to_sheet(ws, sheet_df)
                if progress is not None:
                    # idx 从 1 开始更符合用户预期
                    done = wb.sheetnames.index(sheet_title)  # includes "单值图"
                    progress.setValue(min(done, 1 + len(frames)))
                    progress.bar.setFormat(f"正在写入 {sheet_title}... %p%")
                    QApplication.processEvents()

            wb.save(file_path)
            if progress is not None:
                try:
                    progress.setValue(1 + len(frames))
                    QApplication.processEvents()
                    progress.close()
                    progress.deleteLater()
                except Exception:
                    pass
            return True
        except Exception:
            return False

    def _export_ort_single_value_ppt_to_path(self, out_path: str, show_progress: bool = True) -> bool:
        """导出 ORT 单值图 PPT 到指定路径（不弹窗）。"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            report_df = getattr(self, "_ort_report_df", None)
            if report_df is None or getattr(report_df, "empty", True):
                self._prepare_ort_report_data_from_db(show_errors=False)
        report_df = getattr(self, "_ort_report_df", None)
        if report_df is None or getattr(report_df, "empty", True):
            return False
        frames = list(getattr(self, "_ort_report_sheet_frames", None) or [])
        if not frames:
            frames = self._build_ort_export_sheet_frames(report_df)
        if not frames:
            return False
        try:
            if not str(out_path).lower().endswith(".pptx"):
                out_path = str(out_path) + ".pptx"
            os.makedirs(os.path.dirname(out_path), exist_ok=True)
            try:
                from pptx import Presentation  # type: ignore[import-not-found]
                from pptx.util import Inches  # type: ignore[import-not-found]

                prs = Presentation()
                prs.slide_width = Inches(13.333)
                prs.slide_height = Inches(7.5)
                blank_layout = self._get_ppt_blank_layout(prs)

                progress = None
                if show_progress:
                    try:
                        progress = NiceProgressDialog("导出 PPT", "正在导出单值图...", len(frames), self)
                        progress.show()
                        QApplication.processEvents()
                    except Exception:
                        progress = None

                for idx, (sheet_title, sheet_df) in enumerate(frames, start=1):
                    if progress is not None and progress.wasCanceled():
                        try:
                            progress.close()
                            progress.deleteLater()
                        except Exception:
                            pass
                        return False
                    slide = prs.slides.add_slide(blank_layout)
                    recipe_name = str(sheet_df.iloc[0]["配方"]).strip() if "配方" in sheet_df.columns else sheet_title
                    self._add_ppt_title(slide, recipe_name, prs)
                    self._add_ppt_chart_grid(slide, sheet_df, prs)
                    if progress is not None:
                        progress.setValue(min(idx, len(frames)))
                        QApplication.processEvents()
                prs.save(out_path)
                if progress is not None:
                    try:
                        progress.setValue(len(frames))
                        QApplication.processEvents()
                        progress.close()
                        progress.deleteLater()
                    except Exception:
                        pass
                return True
            except ImportError:
                self._export_ort_ppt_via_powerpoint(frames, out_path)
                return True
        except Exception:
            return False

    def _on_spc_stat_selection_changed(self):
        """左侧配方统计表选中行变化时，过滤右侧的结果表"""
        if not hasattr(self, "spc_result_table") or not hasattr(self, "spc_stat_table"):
            return

        selected_items = self.spc_stat_table.selectedItems()
        if not selected_items:
            # 如果没有选中任何行，显示所有结果
            for row in range(self.spc_result_table.rowCount()):
                self.spc_result_table.setRowHidden(row, False)
            return

        # 获取选中的配方名称（假设配方名在第一列）
        selected_row = selected_items[0].row()
        recipe_item = self.spc_stat_table.item(selected_row, 0)
        if not recipe_item:
            return
            
        selected_recipe = recipe_item.text()

        # 遍历右侧结果表，根据配方名隐藏/显示行
        for row in range(self.spc_result_table.rowCount()):
            result_recipe_item = self.spc_result_table.item(row, 0)
            if result_recipe_item and result_recipe_item.text() == selected_recipe:
                self.spc_result_table.setRowHidden(row, False)
            else:
                self.spc_result_table.setRowHidden(row, True)

    def _on_spc_result_item_clicked(self, item):
        """点击结果列表项时显示对应点位的趋势图。"""
        row = item.row()
        if not hasattr(self, "_spc_results_data") or not self._spc_results_data:
            self.spc_result_chart_label.setText("无分析结果数据")
            return

        # 获取当前行的数据
        if row >= len(self._spc_results_data):
            self.spc_result_chart_label.setText("行号超出范围")
            return

        result_data = self._spc_results_data[row]
        recipe_label = result_data["recipe"]  # 这是组合标签，如 "pull - Boss - X2689 AC/AI"
        point_name = result_data["point"]
        rule_info = result_data["rule"]
        level = result_data["level"]
        group_key = result_data.get("group_key")
        value_col = result_data.get("value_col")

        long_df = getattr(self, "_ort_spc_long_df", None)
        use_long = long_df is not None and not long_df.empty

        if use_long:
            core_cols = getattr(self, "_ort_core_cols", {})
            proj_col = core_cols.get("project", "project")
            sub_col = core_cols.get("subpart", "subpart")
            recipe_col = core_cols.get("recipe", "recipe")
            time_col = core_cols.get("time", "test_time")
            group_cols = [c for c in [proj_col, sub_col, recipe_col] if c in long_df.columns]
            mask = pd.Series([True] * len(long_df), index=long_df.index)
            if isinstance(group_key, tuple):
                for col, val in zip(group_cols, group_key):
                    if col not in long_df.columns:
                        continue
                    if pd.isna(val):
                        mask &= long_df[col].isna()
                    else:
                        mask &= long_df[col].astype(str) == str(val)
            elif group_key is not None and recipe_col in long_df.columns:
                if pd.isna(group_key):
                    mask &= long_df[recipe_col].isna()
                else:
                    mask &= long_df[recipe_col].astype(str) == str(group_key)
            mask &= long_df["point_name"].astype(str) == str(point_name)
            valid_df = long_df.loc[mask].copy()
            if time_col in valid_df.columns:
                valid_df = valid_df.sort_values(time_col, kind="stable")
        else:
            if not hasattr(self, "_ort_raw_df") or self._ort_raw_df is None:
                self.spc_result_chart_label.setText("无原始数据")
                return

            df = self._ort_raw_df
            core_cols = getattr(self, "_ort_core_cols", {})
            recipe_col = core_cols.get("recipe", "")
            time_col = core_cols.get("time", "")
            proj_col = core_cols.get("project", "")
            sub_col = core_cols.get("subpart", "")

            mask = pd.Series([True] * len(df), index=df.index)
            group_cols = [c for c in [proj_col, sub_col, recipe_col] if c and c in df.columns]

            if isinstance(group_key, tuple):
                for col, val in zip(group_cols, group_key):
                    if pd.isna(val):
                        mask &= df[col].isna()
                    else:
                        mask &= df[col] == val
            elif group_key is not None:
                if recipe_col and recipe_col in df.columns:
                    if pd.isna(group_key):
                        mask &= df[recipe_col].isna()
                    else:
                        mask &= df[recipe_col] == group_key

            point_col = value_col
            if point_col is None or point_col not in df.columns:
                for col in df.columns:
                    col_str = str(col)
                    if col_str == point_name or col_str == f"{point_name}_值" or col_str.replace("_值", "") == point_name:
                        point_col = col
                        break

            if point_col is None or point_col not in df.columns:
                available_cols = [str(c) for c in df.columns[:20]]
                self.spc_result_chart_label.setText(
                    f"未找到点位: {point_name}\n可用列: {', '.join(available_cols)}...")
                return

            valid_df = df.loc[mask].copy()
            if time_col and time_col in valid_df.columns:
                valid_df = valid_df.sort_values(time_col, kind="stable")

        if valid_df.empty:
            self.spc_result_chart_label.setText(f"无数据: {recipe_label} - {point_name}")
            return

        # 生成图表
        try:
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_qt5agg import FigureCanvasQTAgg as FigureCanvas
            import numpy as np

            if use_long:
                y_values = pd.to_numeric(valid_df["value"], errors="coerce")
                valid_df = valid_df.loc[y_values.notna()].copy()
                y_values = y_values.dropna().to_numpy()
            else:
                values = pd.to_numeric(valid_df[point_col], errors="coerce")
                valid_df = valid_df.loc[values.notna()].copy()
                y_values = pd.to_numeric(valid_df[point_col], errors="coerce").to_numpy()

            if valid_df.empty or len(y_values) == 0:
                self.spc_result_chart_label.setText(f"无有效数据: {point_name}")
                return

            x_values = np.arange(1, len(valid_df) + 1)

            # 创建图表
            fig = Figure(figsize=(8, 4.5), dpi=100)
            fig.patch.set_facecolor("#FFFFFF")
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FFFFFF")

            # 绘制趋势线
            ax.plot(x_values, y_values, color="#2F80ED", marker="o", linewidth=1.5, markersize=4)
            ax.grid(True, linestyle="--", linewidth=0.5, alpha=0.28)

            # 设置标题
            title_text = f"{recipe_label}\n点位: {point_name}  |  规则: {rule_info}  |  等级: {level}"
            ax.set_title(title_text, fontsize=11, color="#2C3E50", pad=10)
            ax.set_xlabel("样本顺序", fontsize=9)
            ax.set_ylabel("测量值", fontsize=9)
            ax.tick_params(axis="both", labelsize=8)

            # 时间标签
            if time_col and time_col in valid_df.columns:
                time_labels = [self._format_chart_time_label(v) for v in valid_df[time_col]]
                if len(time_labels) <= 5:
                    tick_positions = x_values
                else:
                    tick_positions = np.linspace(1, len(time_labels), num=5, dtype=int)
                    tick_positions = np.unique(tick_positions)
                tick_labels = [time_labels[pos - 1] for pos in tick_positions]
                ax.set_xticks(tick_positions)
                ax.set_xticklabels(tick_labels, fontsize=7, rotation=35, ha="right")

            # Y轴范围
            y_min = np.nanmin(y_values) if len(y_values) else np.nan
            y_max = np.nanmax(y_values) if len(y_values) else np.nan
            if np.isfinite(y_min) and np.isfinite(y_max):
                if y_min == y_max:
                    y_margin = max(abs(y_min) * 0.05, 0.5)
                    ax.set_ylim(y_min - y_margin, y_max + y_margin)
                else:
                    pad = (y_max - y_min) * 0.1
                    ax.set_ylim(y_min - pad, y_max + pad)

            fig.tight_layout(pad=1.5)

            # 创建canvas并替换label
            canvas = FigureCanvas(fig)
            canvas.setStyleSheet("background-color: transparent; border: none;")

            # 获取图表显示区的父布局
            chart_label_parent = self.spc_result_chart_label.parent()
            if chart_label_parent:
                chart_layout = chart_label_parent.layout()
                if chart_layout:
                    # 移除旧的图表
                    if hasattr(self, "_spc_result_chart_canvas") and self._spc_result_chart_canvas:
                        chart_layout.removeWidget(self._spc_result_chart_canvas)
                        self._spc_result_chart_canvas.deleteLater()

                    # 移除label
                    chart_layout.removeWidget(self.spc_result_chart_label)
                    self.spc_result_chart_label.hide()

                    # 添加新图表
                    chart_layout.addWidget(canvas, 1)
                    self._spc_result_chart_canvas = canvas

        except Exception as e:
            print(f"[DEBUG] 生成图表失败: {e}")
            self.spc_result_chart_label.setText(f"图表生成失败: {str(e)}")

    def _normalize_spec_limits_row(self, v: dict) -> dict:
        """将模板/弹窗里的 LSL、USL 规范为可用 float（无法解析的键省略）。"""
        if not isinstance(v, dict):
            return {}
        out = {}
        for key in ("lsl", "usl"):
            raw = v.get(key)
            if raw is None:
                continue
            if isinstance(raw, str):
                s = raw.strip()
                if not s:
                    continue
                raw = s
            num = pd.to_numeric(raw, errors="coerce")
            try:
                xf = float(num)
            except (TypeError, ValueError):
                xf = float("nan")
            if np.isfinite(xf):
                out[key] = xf
        return out

    def _apply_template_mapping_to_live_spec_map(self, tpl: dict) -> None:
        """规格模板字典 → _ort_recipe_point_spec_map（键与数值均规范化）。"""
        if not isinstance(tpl, dict):
            return
        m = {}
        for k, v in tpl.items():
            if not isinstance(v, dict):
                continue
            try:
                rk, pt = k
            except (TypeError, ValueError):
                continue
            nk = (str(rk).strip(), str(pt).strip())
            m[nk] = self._normalize_spec_limits_row(v)
        self._ort_recipe_point_spec_map = m

    def _sync_live_spec_map_from_spec_template_combo(self) -> None:
        """下拉框当前选中的模板同步到运行时规格映射（选「无」则不覆盖现有映射）。"""
        combo = getattr(self, "combo_spec_template", None)
        if combo is None:
            return
        name = str(combo.currentData() or "").strip()
        if not name:
            return
        tpl = (self._ort_spec_templates or {}).get(name)
        if isinstance(tpl, dict):
            self._apply_template_mapping_to_live_spec_map(tpl)

    def _on_refresh_filters_clicked(self):
        """刷新按钮点击处理：同步全局范围并刷新筛选列表"""
        # 同步全局范围到图形分析
        if not self._sync_ort_db_scope_from_global():
            QMessageBox.information(
                self,
                "提示",
                "请先在顶部选择「类型」和至少一个「产品」，再刷新筛选列表。",
            )
            return
        
        # 刷新筛选列表
        self._refresh_ort_db_filter_lists()
        
        # 更新提示
        module_name, category, product_name = self._ort_db_current_scope()
        selected_recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
        recipe_count = len(selected_recipes)
        
        if recipe_count == 0:
            QMessageBox.information(
                self,
                "刷新完成",
                f"范围：{module_name} / {category} / {product_name}\n\n"
                "⚠️ 请至少选择一个配方后再点击「作图」。"
            )
        else:
            QMessageBox.information(
                self,
                "刷新完成",
                f"范围：{module_name} / {category} / {product_name}\n"
                f"已选配方：{recipe_count} 个\n\n"
                "点击「作图  ◉」生成图表。"
            )

    def _on_spec_template_changed(self, *_):
        if not hasattr(self, "combo_spec_template"):
            return
        name = str(self.combo_spec_template.currentData() or "")
        self._ort_active_spec_template = name
        self.settings.setValue("ort_last_spec_template", name)
        self._sync_live_spec_map_from_spec_template_combo()

    def _normalize_ort_time_series(self, series: pd.Series) -> pd.Series:
        """尽量将检测时间解析为可排序的时间序列。"""
        dt_series = pd.to_datetime(series, errors='coerce')
        numeric_series = pd.to_numeric(series, errors='coerce')
        excel_mask = dt_series.isna() & numeric_series.notna()
        if excel_mask.any():
            dt_series.loc[excel_mask] = pd.to_datetime(
                numeric_series.loc[excel_mask],
                unit='D',
                origin='1899-12-30',
                errors='coerce'
            )
        return dt_series

    def _format_chart_time_label(self, value) -> str:
        """格式化图表横轴时间标签，避免过长。"""
        if pd.isna(value):
            return ""
        dt_val = pd.to_datetime(value, errors='coerce')
        if not pd.isna(dt_val):
            return dt_val.strftime("%m-%d\n%H:%M")
        text = str(value).strip()
        return text if len(text) <= 16 else f"{text[:13]}..."

    @staticmethod
    def _pick_finite_spec_value(series) -> float | None:
        s = pd.to_numeric(series, errors="coerce").dropna()
        if s.empty:
            return None
        try:
            return float(s.mode().iloc[0])
        except Exception:
            return float(s.iloc[-1])

    def _resolve_chart_spec_limits(
        self,
        df: pd.DataFrame,
        point_name: str,
        *,
        spec_col=None,
        recipe_title: str | None = None,
        lsl: float | None = None,
        usl: float | None = None,
    ) -> tuple[float | None, float | None]:
        """解析单值图 LSL/USL：规格设置 > 数据列 > spec 列。"""
        if spec_col and spec_col in df.columns and lsl is None:
            lsl = self._pick_finite_spec_value(df[spec_col])

        pn = str(point_name).strip()
        for col in (f"{pn}_LSL", f"{pn}_lsl", "lsl", "LSL"):
            if lsl is None and col in df.columns:
                lsl = self._pick_finite_spec_value(df[col])
        for col in (f"{pn}_USL", f"{pn}_usl", "usl", "USL"):
            if usl is None and col in df.columns:
                usl = self._pick_finite_spec_value(df[col])

        if recipe_title and hasattr(self, "_ort_recipe_point_spec_map") and isinstance(self._ort_recipe_point_spec_map, dict):
            spec = None
            recipe_title_str = str(recipe_title).strip()
            mapping_items = list(self._ort_recipe_point_spec_map.items())
            for (rkey, pname), spec_val in mapping_items:
                if str(pname).strip() != pn:
                    continue
                if str(rkey).strip() == recipe_title_str:
                    spec = spec_val
                    break
            if spec is None:
                for (rkey, pname), spec_val in mapping_items:
                    if str(pname).strip() != pn:
                        continue
                    parts = str(rkey).split("||")
                    stored_recipe = parts[2] if len(parts) == 3 else str(rkey)
                    if recipe_title_str in stored_recipe or stored_recipe in recipe_title_str or stored_recipe == recipe_title_str:
                        spec = spec_val
                        break
            if spec is None:
                rt_parts = [p.strip() for p in recipe_title_str.split("||")]
                if len(rt_parts) >= 3:
                    rs_sub, rs_rec = rt_parts[1], rt_parts[2]
                    for (rkey, pname), spec_val in mapping_items:
                        if str(pname).strip() != pn:
                            continue
                        sp = [x.strip() for x in str(rkey).strip().split("||")]
                        if len(sp) >= 3 and sp[1] == rs_sub and sp[2] == rs_rec:
                            spec = spec_val
                            break
            if isinstance(spec, dict):
                if spec.get("lsl") is not None:
                    lsl = spec.get("lsl")
                if spec.get("usl") is not None:
                    usl = spec.get("usl")
        return lsl, usl

    def _apply_ort_spec_limit_lines(self, ax, lsl=None, usl=None, *, show_legend: bool = False) -> bool:
        """LSL 红色、USL 橙色。"""
        drawn = False
        if lsl is not None and np.isfinite(float(lsl)):
            ax.axhline(float(lsl), color="#DC2626", linestyle="--", linewidth=1.2, alpha=0.85, label="LSL", zorder=2)
            drawn = True
        if usl is not None and np.isfinite(float(usl)):
            ax.axhline(float(usl), color="#F97316", linestyle="--", linewidth=1.2, alpha=0.85, label="USL", zorder=2)
            drawn = True
        if drawn and show_legend:
            ax.legend(loc="best", fontsize=7, frameon=False)
        return drawn

    @staticmethod
    def _extend_chart_ylim_with_spec(y_min, y_max, lsl=None, usl=None):
        for spec in (lsl, usl):
            if spec is not None and np.isfinite(float(spec)):
                sv = float(spec)
                y_min = np.nanmin([y_min, sv]) if np.isfinite(y_min) else sv
                y_max = np.nanmax([y_max, sv]) if np.isfinite(y_max) else sv
        return y_min, y_max

    def _build_single_value_chart(self, df_recipe: pd.DataFrame, point_name: str, value_col, time_col,
                                  spec_col=None, recipe_title: str | None = None, title_suffix: str = ""):
        """构建单个点位的单值图卡片。"""
        values = pd.to_numeric(df_recipe[value_col], errors='coerce')
        valid_df = df_recipe.loc[values.notna()].copy()
        if valid_df.empty:
            return None

        y_values = pd.to_numeric(valid_df[value_col], errors='coerce').to_numpy()
        x_values = np.arange(1, len(valid_df) + 1)

        lsl, usl = self._resolve_chart_spec_limits(
            valid_df, point_name, spec_col=spec_col, recipe_title=recipe_title,
        )

        card = ClickableFrame()
        card.setStyleSheet("""
            QFrame {
                background-color: #FFFFFF;
                border: 1px solid #C5D9E8;
                border-radius: 12px;
            }
        """)
        # 每张图长度增加 1/5：320 -> 384
        card.setFixedWidth(int(384*self._s))
        card_lay = QVBoxLayout(card)
        card_lay.setContentsMargins(12, 12, 12, 12)
        card_lay.setSpacing(8)

        suffix = f" {title_suffix}".rstrip()
        title = QLabel(f"{point_name}{suffix}")
        title.setStyleSheet("font-size: 13px; font-weight: 700; color: #2C3E50;")
        card_lay.addWidget(title)

        def _build_fig(figsize=(3.6, 2.2), dpi=100):
            fig = Figure(figsize=figsize, dpi=dpi)
            fig.patch.set_facecolor("#FFFFFF")
            ax = fig.add_subplot(111)
            ax.set_facecolor("#FFFFFF")
            ax.plot(x_values, y_values, color="#2F80ED", marker="o", linewidth=1.6, markersize=4.5, label="Value")
            self._apply_ort_spec_limit_lines(ax, lsl, usl, show_legend=True)
            ax.grid(True, linestyle="--", linewidth=0.6, alpha=0.28)
            ax.set_title("按检测时间顺序", fontsize=9, color="#6B7280")
            ax.set_xlabel("样本顺序", fontsize=8)
            ax.tick_params(axis='y', labelsize=8)

            if time_col and time_col in valid_df.columns:
                time_labels = [self._format_chart_time_label(v) for v in valid_df[time_col]]
                if len(time_labels) <= 6:
                    tick_positions = x_values
                else:
                    tick_positions = np.linspace(1, len(time_labels), num=6, dtype=int)
                    tick_positions = np.unique(tick_positions)
                tick_labels = [time_labels[pos - 1] for pos in tick_positions]
                ax.set_xticks(tick_positions)
                ax.set_xticklabels(tick_labels, fontsize=7, rotation=35, ha='right')
            else:
                ax.set_xticks(x_values)
                ax.tick_params(axis='x', labelsize=7)

            # y 轴范围：兼容 LSL / USL
            y_min = np.nanmin(y_values) if len(y_values) else np.nan
            y_max = np.nanmax(y_values) if len(y_values) else np.nan
            y_min, y_max = self._extend_chart_ylim_with_spec(y_min, y_max, lsl, usl)
            if np.isfinite(y_min) and np.isfinite(y_max):
                if y_min == y_max:
                    y_margin = max(abs(y_min) * 0.05, 0.5)
                    ax.set_ylim(y_min - y_margin, y_max + y_margin)
                else:
                    pad = (y_max - y_min) * 0.08
                    ax.set_ylim(y_min - pad, y_max + pad)

            fig.tight_layout()
            return fig

        fig = _build_fig(figsize=(3.6, 2.2), dpi=100)
        canvas = FigureCanvas(fig)
        card_lay.addWidget(canvas)

        # 点击放大
        def _open_zoom():
            dlg = ChartZoomDialog(
                title=f"{point_name}{suffix}",
                build_figure_fn=_build_fig,
                parent=self
            )
            dlg.exec_()

        card.clicked.connect(_open_zoom)
        return card

    def _select_table_rows_for_recipe_point(self, recipe_name: str, point_name: str):
        """点击单值图后，在右侧表格中定位并选中对应配方的行，并滚动到点位列。"""
        if not hasattr(self, "_ort_show_df") or self._ort_show_df is None:
            return
        if not hasattr(self, "_ort_core_cols") or self._ort_core_cols is None:
            return

        show_df = self._ort_show_df
        recipe_col = self._ort_core_cols.get("recipe")
        if not recipe_col or recipe_col not in show_df.columns:
            return

        # 行索引（当前表格模型即 show_df 的顺序）
        mask = show_df[recipe_col].astype(str) == str(recipe_name)
        row_indices = list(show_df.index[mask])
        if not row_indices:
            return

        model = self.ort_data_table.model()
        if model is None:
            return

        sel_model = self.ort_data_table.selectionModel()
        if sel_model is None:
            return

        sel_model.clearSelection()

        # 选中这些行的第 0 列（行选择模式下即可高亮整行）
        from PyQt5.QtCore import QItemSelection, QItemSelectionRange
        selection = QItemSelection()
        for r in row_indices:
            if 0 <= r < model.rowCount():
                selection.append(QItemSelectionRange(model.index(r, 0), model.index(r, max(0, model.columnCount() - 1))))
        if not selection.isEmpty():
            sel_model.select(selection, sel_model.Select | sel_model.Rows)

        # 滚动到第一行
        first_row = row_indices[0]
        self.ort_data_table.scrollTo(model.index(first_row, 0), QAbstractItemView.PositionAtTop)

        # 横向滚动到点位值列（使用重命名后的显示列名）
        target_header = f"{point_name}_值"
        target_col = -1
        for c in range(model.columnCount()):
            if str(model.headerData(c, Qt.Horizontal, Qt.DisplayRole)) == target_header:
                target_col = c
                break
        if target_col >= 0:
            idx = model.index(first_row, target_col)
            self.ort_data_table.setCurrentIndex(idx)
            self.ort_data_table.scrollTo(idx, QAbstractItemView.PositionAtCenter)

    def _ort_point_structure_prefix(self, point_name: str) -> str:
        """点位名前缀作为结构名，如 USB1→USB，AC12→AC；无法识别则返回原名前段。"""
        s = str(point_name).strip()
        if not s:
            return "?"
        m = re.match(r"^([A-Za-z]+)", s)
        return m.group(1) if m else s.split("_")[0] if "_" in s else s

    def _ort_prefix_first_pos_in_recipe(self, recipe_text: str, prefix: str) -> int:
        """前缀在配方名中首次出现的字符位置（整词边界），用于结构名从上到下排序。"""
        s = str(recipe_text or "")
        p = str(prefix or "").strip()
        if not p:
            return 10**9
        try:
            pat = re.compile(r"(?<![A-Za-z])" + re.escape(p) + r"(?![A-Za-z])")
            m = pat.search(s)
            if m:
                return m.start()
        except Exception:
            pass
        return 10**9

    def _render_ort_recipe_charts(
        self,
        df: pd.DataFrame,
        core_cols: dict,
        point_cols: list,
        show_progress: bool = False,
        chart_layout=None,
        points_per_chart: int | None = None,
    ):
        """按配方分组渲染点位单值图。chart_layout 默认图形分析区；数据与报告页传入 ort_report_chart_layout。"""
        layout = chart_layout
        if layout is None:
            layout = getattr(self, "ort_chart_layout", None)
        if layout is None:
            return

        self._clear_layout_widgets(layout)
        self._sync_live_spec_map_from_spec_template_combo()

        if df is None or df.empty:
            empty_label = QLabel("当前筛选条件下暂无可绘制的数据。")
            empty_label.setStyleSheet("font-size: 14px; color: #5A7A99; padding: 24px 8px;")
            layout.addWidget(empty_label)
            layout.addStretch(1)
            return

        recipe_col = core_cols.get('recipe')
        time_col = core_cols.get('time')
        machine_type_col = core_cols.get('machine_type')
        component_col = core_cols.get('component')
        project_col = core_cols.get('project')
        subpart_col = core_cols.get('subpart')

        group_cols = [c for c in [machine_type_col, project_col, component_col, subpart_col, recipe_col] if c]
        if not group_cols:
            recipe_groups = [(None, df)]
        else:
            recipe_groups = list(df.groupby(group_cols, sort=False))

        progress = None
        step = 0

        try:
            if show_progress:
                total_steps = max(1, len(recipe_groups) * max(1, len(point_cols)))
                progress = NiceProgressDialog(
                    title="ORT 作图进度",
                    message="正在生成单值图，请稍候…（数据量大时会稍慢）",
                    maximum=total_steps,
                    parent=self
                )
                progress.show()
                QApplication.processEvents()

            for group_key, df_recipe in recipe_groups:
                recipe_frame = QFrame()
                recipe_frame.setStyleSheet("""
                    QFrame {
                        background-color: #F5F9FF;
                        border: 1px solid #C5D9E8;
                        border-radius: 14px;
                    }
                """)
                recipe_lay = QVBoxLayout(recipe_frame)
                recipe_lay.setContentsMargins(16, 16, 16, 16)
                recipe_lay.setSpacing(10)

                # 标题：机种-项目-小件-配方名（展示用）
                if isinstance(group_key, tuple):
                    title_parts = [str(x) for x in group_key]
                elif group_key is None:
                    title_parts = [str(df_recipe.iloc[0][c]) for c in group_cols if c in df_recipe.columns and len(df_recipe) > 0]
                else:
                    title_parts = [str(group_key)]
                title_text = "-".join([p for p in title_parts if p and p.lower() not in ("nan", "none")])

                # 规格设置 key：Project||Subpart||Recipe（用于从弹窗读取 LSL/USL）
                proj_col = core_cols.get("project")
                sub_col = core_cols.get("subpart")
                rec_col = core_cols.get("recipe")
                proj_val = str(df_recipe.iloc[0][proj_col]) if proj_col in df_recipe.columns and len(df_recipe) > 0 else ""
                sub_val = str(df_recipe.iloc[0][sub_col]) if sub_col in df_recipe.columns and len(df_recipe) > 0 else ""
                rec_val = str(df_recipe.iloc[0][rec_col]) if rec_col in df_recipe.columns and len(df_recipe) > 0 else ""
                spec_key = f"{proj_val}||{sub_val}||{rec_val}"

                entries = []
                for point_name, value_col, spec_col in point_cols:
                    if progress is not None:
                        if progress.wasCanceled():
                            return
                        progress.setValue(step)
                        if step % 8 == 0:
                            QApplication.processEvents()
                    step += 1

                    values = pd.to_numeric(df_recipe[value_col], errors="coerce")
                    df_valid = df_recipe.loc[values.notna()].copy()
                    if df_valid.empty:
                        continue

                    if points_per_chart is not None:
                        per_chart = max(1, int(points_per_chart))
                    else:
                        try:
                            per_chart = int(getattr(self, "spin_ort_points_per_chart", None).value()) \
                                if hasattr(self, "spin_ort_points_per_chart") else 0
                        except Exception:
                            per_chart = 0
                        per_chart = max(1, per_chart or 1)
                    per_chart = min(per_chart, len(df_valid))
                    seg_df = df_valid.tail(per_chart).copy()
                    entries.append((point_name, value_col, spec_col, seg_df))

                chart_count = len(entries)
                recipe_order_text = rec_val or title_text

                recipe_title = QLabel(
                    f"配方：{title_text}    样本数：{len(df_recipe)}    总图数：{chart_count}"
                )
                recipe_title.setStyleSheet("font-size: 15px; font-weight: 700; color: #2C3E50;")
                recipe_lay.addWidget(recipe_title)

                def _make_row_scroll(chart_rows: list) -> tuple[QScrollArea, QWidget]:
                    row_scroll_inner = QScrollArea()
                    row_scroll_inner.setWidgetResizable(False)
                    row_scroll_inner.setFrameShape(QFrame.NoFrame)
                    row_scroll_inner.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
                    row_scroll_inner.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                    row_scroll_inner.setStyleSheet("QScrollArea { border: none; background: transparent; }")
                    rw = QWidget()
                    rw.setStyleSheet("background-color: transparent;")
                    rl = QHBoxLayout(rw)
                    rl.setContentsMargins(0, 0, 0, 0)
                    rl.setSpacing(12)
                    for point_name, value_col, spec_col, seg_df in chart_rows:
                        chart_card = self._build_single_value_chart(
                            seg_df, point_name, value_col, time_col,
                            spec_col=spec_col,
                            recipe_title=spec_key
                        )
                        if chart_card is not None:
                            rl.addWidget(chart_card)
                    rl.addStretch(1)
                    rw.adjustSize()
                    rw.setMinimumSize(rw.sizeHint())
                    row_scroll_inner.setWidget(rw)
                    row_scroll_inner.setMinimumHeight(int(320*self._s))
                    return row_scroll_inner, rw

                if chart_count == 0:
                    no_chart = QLabel("这个配方下没有可绘制的点位值。")
                    no_chart.setStyleSheet("font-size: 13px; color: #8A7A64; padding: 12px 4px;")
                    recipe_lay.addWidget(no_chart)
                else:
                    from collections import defaultdict

                    buckets: dict[str, list] = defaultdict(list)
                    for item in entries:
                        point_name = item[0]
                        buckets[self._ort_point_structure_prefix(point_name)].append(item)

                    ordered_prefs = sorted(
                        buckets.keys(),
                        key=lambda p: (
                            self._ort_prefix_first_pos_in_recipe(recipe_order_text, p),
                            tuple(self._natural_sort_key(str(p)))
                        ),
                    )

                    body_outer = QWidget()
                    body_outer.setStyleSheet("background-color: transparent;")
                    body_v = QVBoxLayout(body_outer)
                    body_v.setContentsMargins(0, 10, 0, 8)
                    body_v.setSpacing(14)

                    for pref in ordered_prefs:
                        struct_row_wrap = QWidget()
                        struct_row_wrap.setStyleSheet("background-color: transparent;")
                        struct_h = QHBoxLayout(struct_row_wrap)
                        struct_h.setSpacing(14)
                        struct_h.setContentsMargins(0, 0, 0, 0)

                        group_items = sorted(
                            buckets[pref],
                            key=lambda row: tuple(self._natural_sort_key(str(row[0]))),
                        )
                        row_scroll, _ = _make_row_scroll(group_items)
                        row_h = int(296 * self._s)
                        row_scroll.setMinimumHeight(row_h)

                        slbl = QLabel(str(pref))
                        slbl.setWordWrap(True)
                        slbl.setMinimumWidth(int(60*self._s))
                        slbl.setMaximumWidth(int(100*self._s))
                        slbl.setMinimumHeight(row_h)
                        slbl.setMaximumHeight(row_h)
                        slbl.setAlignment(Qt.AlignCenter)
                        slbl.setStyleSheet(
                            "font-size: 18px; font-weight: 800; color: #3A5A7A;"
                        )
                        struct_h.addWidget(slbl, 0, Qt.AlignVCenter)
                        struct_h.addWidget(row_scroll, 1)

                        body_v.addWidget(struct_row_wrap)

                    recipe_lay.addWidget(body_outer)

                layout.addWidget(recipe_frame)

            layout.addStretch(1)
        finally:
            if progress is not None:
                progress.setValue(progress.maximum())
                QApplication.processEvents()
                # 进度完成后自动关闭
                progress.close()
                progress.deleteLater()

    def _on_select_all_clicked(self, attr_name):
        """全选按钮点击事件"""
        list_widget = getattr(self, f"ort_list_{attr_name}", None)
        if not list_widget:
            return
        total_count = list_widget.count()
        list_widget.blockSignals(True)
        try:
            for i in range(list_widget.count()):
                item = list_widget.item(i)
                item.setCheckState(Qt.Checked)
        finally:
            list_widget.blockSignals(False)
        self._update_dropdown_text(attr_name, total_count, total_count)
        self._schedule_ort_update(delay_ms=50)

    def _on_clear_all_clicked(self, attr_name):
        """取消全选按钮点击事件"""
        list_widget = getattr(self, f"ort_list_{attr_name}", None)
        if not list_widget:
            return
        total_count = list_widget.count()
        list_widget.blockSignals(True)
        try:
            for i in range(list_widget.count()):
                item = list_widget.item(i)
                item.setCheckState(Qt.Unchecked)
        finally:
            list_widget.blockSignals(False)
        self._update_dropdown_text(attr_name, 0, total_count)
        self._schedule_ort_update(delay_ms=50)
    
    def _set_ort_report_view_mode(self, mode: str):
        """数据与报告页：在数据表 / 单值图之间切换。"""
        stack = getattr(self, "ort_report_view_stack", None)
        if stack is None:
            return
        show_chart = (str(mode or "").strip().lower() == "chart")
        stack.setCurrentIndex(1 if show_chart else 0)
        btn_plot = getattr(self, "btn_report_one_click_plot", None)
        btn_back = getattr(self, "btn_report_back_table", None)
        if btn_plot is not None:
            btn_plot.setVisible(not show_chart)
        if btn_back is not None:
            btn_back.setVisible(show_chart)

    def _on_report_back_to_table(self):
        """从单值图视图返回数据表。"""
        self._set_ort_report_view_mode("table")

    def _prepare_ort_df_for_report_charts(
        self, df_raw: pd.DataFrame, core_cols: dict
    ) -> pd.DataFrame:
        """按左侧小件/配方筛选（若有勾选）整理作图用宽表。"""
        if df_raw is None or df_raw.empty or not core_cols:
            return pd.DataFrame()

        df = df_raw.copy()
        sub_col = core_cols.get("subpart")
        rec_col = core_cols.get("recipe")
        selected_subparts = self._get_checked_texts(getattr(self, "ort_list_subpart", None))
        selected_recipes = self._get_checked_texts(getattr(self, "ort_list_recipe", None))
        if selected_subparts and sub_col and sub_col in df.columns:
            df = df[df[sub_col].astype(str).isin(selected_subparts)]
        if selected_recipes and rec_col and rec_col in df.columns:
            df = df[df[rec_col].astype(str).isin(selected_recipes)]

        if df.empty:
            return df

        time_col = core_cols.get("time")
        sort_cols = [c for c in [rec_col] if c and c in df.columns]
        if time_col and time_col in df.columns:
            df["_ort_time_sort"] = self._normalize_ort_time_series(df[time_col])
            sort_cols.append("_ort_time_sort")
        if sort_cols:
            df = df.sort_values(sort_cols, ascending=True, kind="stable", na_position="last")
        return df.reset_index(drop=True)

    def _on_report_one_click_plot(self):
        """数据与报告页：一键生成当前范围内所有配方的单值图，并切换到图形区。"""
        chart_layout = getattr(self, "ort_report_chart_layout", None)
        if chart_layout is None:
            return

        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            self._initialize_ort_db_analysis_ui(update_placeholder=False)
            if not self._sync_ort_db_scope_from_global():
                QMessageBox.information(
                    self,
                    "提示",
                    "请先在顶部选择「类型」和「产品」，并确认数据库中已有数据。",
                )
                return
            ok, err = self._prepare_ort_report_data_from_db(show_errors=True)
            if not ok:
                return
            df_raw = getattr(self, "_ort_raw_df", None)
            core_cols = dict(getattr(self, "_ort_core_cols", {}) or {})
            point_cols = list(getattr(self, "_ort_point_cols", []) or [])
        else:
            if self.current_df is None or getattr(self.current_df, "empty", True):
                QMessageBox.warning(self, "提示", "请先导入并映射数据，再生成图表。")
                return
            if not hasattr(self, "_ort_raw_df") or self._ort_raw_df is None or self._ort_raw_df.empty:
                self._init_ort_data_from_current_df()
            df_raw = getattr(self, "_ort_raw_df", None)
            core_cols = dict(getattr(self, "_ort_core_cols", {}) or {})
            point_cols = list(getattr(self, "_ort_point_cols", []) or [])

        if df_raw is None or df_raw.empty or not point_cols:
            QMessageBox.information(self, "提示", "当前没有可用于作图的数据，请先刷新数据或调整时间范围。")
            return

        df_plot = self._prepare_ort_df_for_report_charts(df_raw, core_cols)
        if df_plot.empty:
            QMessageBox.information(self, "提示", "当前筛选条件下没有可绘制的数据。")
            return

        scope = getattr(self, "_spc_data_scope_note", "")
        lbl = getattr(self, "ort_report_chart_label", None)
        if lbl is not None:
            if scope:
                lbl.setText(f"配方点位单值图 · {scope}")
            else:
                lbl.setText("配方点位单值图（当前时间范围与筛选条件）")

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            self._render_ort_recipe_charts(
                df_plot,
                core_cols,
                point_cols,
                show_progress=True,
                chart_layout=chart_layout,
                points_per_chart=9999,
            )
        finally:
            QApplication.restoreOverrideCursor()

        self._set_ort_report_view_mode("chart")

    def _on_smart_arrange_clicked(self):
        """「一键作图」：切换至图形分析页并按结构名分组绘制单值图。"""
        if getattr(self, "_ort_chart_mode", "") == "db_grouped":
            self._switch_ort_tab_by_name("图形分析")
            self._initialize_ort_db_analysis_ui(update_placeholder=False)
            if not self._sync_ort_db_scope_from_global():
                return QMessageBox.information(
                    self,
                    "提示",
                    "请先在顶部选择「类型」和至少一个「产品」，再点击一键作图。",
                )
            module_name, category, product_name = self._ort_db_current_scope()
            point_name = self._resolve_ort_analysis_point_name()
            if not point_name:
                return QMessageBox.information(
                    self,
                    "提示",
                    f"当前产品「{product_name or '未选'}」在现有筛选下暂无可用检测点位，请检查数据库是否已导入数据。",
                )
            self._ort_fig_cache = {}
            self._schedule_ort_update(delay_ms=0, do_plot=True)
            return
        if self.current_df is None or self.current_df.empty:
            return QMessageBox.warning(self, "提示", "请先导入并映射数据，再生成图表。")
        # 确保 _ort_raw_df 已初始化
        if not hasattr(self, '_ort_raw_df') or self._ort_raw_df is None:
            # 从 current_df 初始化 ORT 数据
            self._init_ort_data_from_current_df()
        # 切换到图形分析Tab（索引1）
        self._switch_ort_tab_by_name("图形分析")
        self._ort_fig_cache = {}
        self._schedule_ort_update(delay_ms=0, do_plot=True)

    def _init_ort_data_from_current_df(self):
        """从 current_df 初始化 ORT 分析所需的数据结构。"""
        if self.current_df is None or self.current_df.empty:
            return

        df = self.current_df.copy()

        # 识别核心维度列（与 run_ort_analysis 使用相同的 _match_ort_core_col_key 逻辑）
        core_cols = {}
        for col in df.columns:
            col_str = str(col).strip()
            matched_key = _match_ort_core_col_key(col_str)
            if matched_key == 'barcode':
                core_cols.setdefault('barcode', col)
            elif matched_key:
                core_cols[matched_key] = col
            else:
                key = col_str.lower()
                if key == 'project' or key == '项目':
                    core_cols.setdefault('project', col)
                elif key in ('machine_type', 'machine type'):
                    core_cols.setdefault('machine_type', col)
                elif key in ('component', '组件', 'product', '产品名称'):
                    core_cols.setdefault('component', col)
                elif key in ('subpart', 'sub_part', '小件', '部件', '零件'):
                    core_cols.setdefault('subpart', col)
                elif key in ('recipe', '配方', 'recipe_name', 'recipename'):
                    core_cols.setdefault('recipe', col)
                elif key in ('time', 'test_time', '测试时间', '检测时间', 'date', '日期', 'datetime'):
                    core_cols.setdefault('time', col)

        # 确保关键维度存在（补全缺失的）
        for key in ['project', 'component', 'subpart', 'recipe']:
            if key not in core_cols:
                for col in df.columns:
                    col_lower = str(col).lower().strip()
                    if key == 'project' and ('project' in col_lower or '项目' in col_lower):
                        core_cols[key] = col
                        break
                    elif key == 'component' and ('component' in col_lower or '组件' in col_lower or '部件' in col_lower):
                        core_cols[key] = col
                        break
                    elif key == 'subpart' and ('subpart' in col_lower or '小件' in col_lower or 'sub_part' in col_lower):
                        core_cols[key] = col
                        break
                    elif key == 'recipe' and ('recipe' in col_lower or '配方' in col_lower):
                        core_cols[key] = col
                        break
            if key not in core_cols:
                core_cols[key] = f"_{key}_"

        if 'time' not in core_cols:
            for col in df.columns:
                col_lower = str(col).lower().strip()
                if 'time' in col_lower or '时间' in col_lower or 'date' in col_lower or '日期' in col_lower:
                    core_cols['time'] = col
                    break
            if 'time' not in core_cols:
                core_cols['time'] = '_time_'

        # 识别测点列（必须与 run_ort_analysis 格式一致：[(point_name, value_col, spec_col), ...]）
        point_cols = []
        for col in df.columns:
            col_str = str(col).strip()
            if not col_str.endswith("_value"):
                continue
            point_name = col_str[:-6]
            spec_col = f"{point_name}_spec" if f"{point_name}_spec" in df.columns else None
            point_cols.append((point_name, col, spec_col))

        # 保存到实例变量
        self._ort_raw_df = df
        self._ort_core_cols = core_cols
        self._ort_point_cols = point_cols
        self._ort_initialized_version = self._data_version

        # 填充下拉框
        def get_unique_sorted(series):
            vals = series.dropna().astype(str).unique()
            vals = [v for v in vals if v and v.lower() not in ['nan', 'none', '']]
            return sorted(vals)

        # 填充小件列表
        if 'subpart' in core_cols and core_cols['subpart'] in df.columns:
            subpart_vals = get_unique_sorted(df[core_cols['subpart']])
            if hasattr(self, 'ort_list_subpart'):
                self.ort_list_subpart.clear()
                for val in subpart_vals:
                    item = QListWidgetItem(val)
                    item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                    item.setCheckState(Qt.Checked)
                    self.ort_list_subpart.addItem(item)
                self._update_dropdown_text('subpart', len(subpart_vals), len(subpart_vals))

        # 填充配方列表
        if 'recipe' in core_cols and core_cols['recipe'] in df.columns:
            recipe_vals = get_unique_sorted(df[core_cols['recipe']])
            if hasattr(self, 'ort_list_recipe'):
                self.ort_list_recipe.clear()
                for val in recipe_vals:
                    item = QListWidgetItem(val)
                    item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                    item.setCheckState(Qt.Checked)
                    self.ort_list_recipe.addItem(item)
                self._update_dropdown_text('recipe', len(recipe_vals), len(recipe_vals))

