    def _apply_material_category_column(self, config: dict, info_col_labels: list[str]) -> None:
        """按映射配置生成「物料类别」列：有值用源列内容，空/空白补 IPQC。"""
        if self.current_df is None or self.current_df.empty:
            return
        mat_idx = _resolve_material_category_col_index(config, info_col_labels)
        if mat_idx < 0:
            return
        config["material_category_col"] = mat_idx
        series = _material_category_series_from_df(self.current_df, mat_idx, info_col_labels)
        self.current_df[_ORT_MATERIAL_CATEGORY_COL] = series

